}

variable "secret_name" {
  description = "Name of the Secrets Manager secret"
  type        = string
  default     = "lambda-auth-credentials"
}

variable "default_username" {
  description = "Default username stored in the secret"
  type        = string
  default     = "techlanches"
}

variable "default_email" {
  description = "Default email stored in the secret"
  type        = string
  default     = "g12.4soat.fiap@outlook.com"
}

variable "default_password" {
  description = "Default password stored in the secret"
  type        = string
  default     = "Test1234@"
  sensitive   = true
}

resource "aws_cognito_user_pool" "user_pool" {
  name                     = "tech-lanches-clientes-pool"
  mfa_configuration        = "OFF"
  username_configuration {
    case_sensitive = false
  }
  auto_verified_attributes = ["email"]
  alias_attributes         = ["email", "preferred_username"]

  tags = {
    Name = "tech_lanches_clientes_pool"
  }
}

resource "aws_cognito_user_pool_client" "user_pool_client" {
  name                                 = "pool-client"
  user_pool_id                         = aws_cognito_user_pool.user_pool.id
  explicit_auth_flows                  = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH"
  ]
}

resource "aws_secretsmanager_secret" "auth_credentials" {
  name                    = var.secret_name
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "auth_credentials_version" {
  secret_id = aws_secretsmanager_secret.auth_credentials.id
  secret_string = jsonencode({
    region     = var.aws_region
    pool_id    = aws_cognito_user_pool.user_pool.id
    client_id  = aws_cognito_user_pool_client.user_pool_client.id
    username   = var.default_username
    email      = var.default_email
    password   = var.default_password
  })
}

output "user_pool_id" {
  value = aws_cognito_user_pool.user_pool.id
}

output "user_pool_client_id" {
  value = aws_cognito_user_pool_client.user_pool_client.id
}

output "secret_arn" {
  value = aws_secretsmanager_secret.auth_credentials.arn
}

