terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "base_bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy" {
  description = "Whether to force destroy the bucket even if it contains objects"
  type        = bool
  default     = true
}

variable "allowed_account_id" {
  description = "AWS account ID granted full S3 access"
  type        = string
  default     = "566373416292"
}

resource "random_integer" "bucket_prefix" {
  min = 1
  max = 50000
}

resource "aws_kms_key" "doc_io_key" {
  description             = "KMS key for doc-io-files S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key_policy" "doc_io_key_policy" {
  key_id = aws_kms_key.doc_io_key.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${var.allowed_account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowUseOfKeyForS3"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${var.allowed_account_id}:root" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "doc_io_files" {
  bucket        = "${random_integer.bucket_prefix.result}-${var.base_bucket_name}"
  force_destroy = var.force_destroy
}

resource "aws_s3_bucket_public_access_block" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.doc_io_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }

  depends_on = [aws_s3_bucket_public_access_block.doc_io_files]
}

data "aws_iam_policy_document" "doc_io_files_policy" {
  statement {
    sid       = "FullAccountAccess"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.doc_io_files.arn,
      "${aws_s3_bucket.doc_io_files.arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id
  policy = data.aws_iam_policy_document.doc_io_files_policy.json

  depends_on = [aws_s3_bucket_public_access_block.doc_io_files]
}

output "bucket_name" {
  description = "Name of the created S3 bucket"
  value       = aws_s3_bucket.doc_io_files.id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encryption"
  value       = aws_kms_key.doc_io_key.arn
}

