terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "identity_pool" {
  name = "identity pool"
}

data "aws_iam_policy_document" "user_group_role_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    effect  = "Allow"

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = ["us-east-1:12345678-dead-beef-cafe-123456790ab"]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "user_group_role" {
  name               = "user-group-role"
  assume_role_policy = data.aws_iam_policy_document.user_group_role_trust.json
}

resource "aws_cognito_user_group" "user_group" {
  name         = "user-group"
  user_pool_id = aws_cognito_user_pool.identity_pool.id
  role_arn     = aws_iam_role.user_group_role.arn
  description  = "Managed by Terraform"
  precedence   = 42
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "alt-tags"
  region = "us-east-1"
}

resource "aws_dynamodb_table" "basic" {
  provider     = aws
  name         = "default-and-alternate-tags-module-basic"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    ManagedBy = "terraform"
  }
}

resource "aws_dynamodb_table" "alternate" {
  provider     = aws.alt-tags
  name         = "default-and-alternate-tags-module-alternate"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    ManagedBy = "terraform"
  }
}

output "basic_table_arn" {
  value = aws_dynamodb_table.basic.arn
}

output "alternate_table_arn" {
  value = aws_dynamodb_table.alternate.arn
}

provider "aws" {
  region = "us-east-1"
}

variable "api_name" {
  description = "Name of the API Gateway REST API"
  type        = string
  default     = "terraform-api-gateway-example"
}

resource "aws_api_gateway_rest_api" "api" {
  name = var.api_name
}

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "movies"
}

resource "aws_api_gateway_method" "movies_get" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "movies_get_mock" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = "200"

  response_parameters = {
    "method.response.header.Content-Type" = true
  }
}

resource "aws_api_gateway_integration_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = aws_api_gateway_method_response.movies_get_200.status_code

  response_parameters = {
    "method.response.header.Content-Type" = "'application/json'"
  }

  response_templates = {
    "application/json" = jsonencode({
      message = "Hello from the movies API!"
    })
  }
}

resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.movies,
      aws_api_gateway_method.movies_get,
      aws_api_gateway_integration.movies_get_mock,
      aws_api_gateway_method_response.movies_get_200,
      aws_api_gateway_integration_response.movies_get_200
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.movies_get_mock,
    aws_api_gateway_integration_response.movies_get_200
  ]
}

resource "aws_api_gateway_stage" "stage" {
  deployment_id = aws_api_gateway_deployment.deployment.id
  rest_api_id   = aws_api_gateway_rest_api.api.id
  stage_name    = "test"
}

output "api_endpoint" {
  description = "URL of the movies GET endpoint"
  value       = "${aws_api_gateway_stage.stage.invoke_url}/movies"
}

