```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "sg-test-vpc"
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow TCP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_tcp"
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow UDP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_udp"
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ICMP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_icmp"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ALL traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_all"
  }
}
