```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for Terraform state"
  type        = string
  default     = "terraform-remote-state-bucket-123456789012"
}

# KMS key for S3 encryption
resource "aws_kms_key" "terraform_state" {
  description             = "KMS key for Terraform state S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# S3 bucket for Terraform state
resource "aws_s3_bucket" "terraform_state" {
  bucket = var.bucket_name

  tags = {
    Name        = "Terraform State Bucket"
    Environment = "shared"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name        = "Terraform Lock Table"
    Environment = "shared"
  }
}

output "state_bucket_name" {
  value = aws_s3_bucket.terraform_state.bucket
}

output "kms_key_arn" {
  value = aws_kms_key.terraform_state.arn
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.terraform_lock.name
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "allowed_regions" {
  description = "List of AWS regions where the policy applies"
  type        = list(string)
  default     = ["*"]
}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

data "aws_iam_policy_document" "powerscale_node_runtime" {
  statement {
    sid       = "PowerScaleNodeRuntime"
    effect    = "Allow"
    actions   = ["ec2:AssignPrivateIpAddresses"]
    resources = ["arn:aws:ec2:*:${local.account_id}:network-interface/*"]

    condition {
      test     = "StringEquals"
      variable = "ec2:Region"
      values   = var.allowed_regions
    }
  }
}

resource "aws_iam_policy" "powerscale_node_runtime" {
  name        = "${local.account_id}-powerscale-node-runtime-policy"
  description = "Policy for PowerScale node runtime operations"
  policy      = data.aws_iam_policy_document.powerscale_node_runtime.json
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "powerscale_node_runtime" {
  name               = "${local.account_id}-powerscale-node-runtime-role"
  description        = "Role for EC2 instances managing PowerScale node runtime operations"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  role       = aws_iam_role.powerscale_node_runtime.name
  policy_arn = aws_iam_policy.powerscale_node_runtime.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime" {
  name = "${local.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime.name
}

output "policy_name" {
  value = aws_iam_policy.powerscale_node_runtime.name
}

output "role_name" {
  value = aws_iam_role.powerscale_node_runtime.name
}

output "instance_profile_name" {
  value = aws_iam_instance_profile.powerscale_node_runtime.name
}

