terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for EC2 instances"
  type        = string
  default     = "ec2-instance-role"
}

variable "managed_policy_arns" {
  description = "List of managed IAM policy ARNs to attach to the role"
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"]
}

variable "inline_policies" {
  description = "Map of inline policy names to JSON policy documents"
  type        = map(string)
  default = {
    "s3-read-only" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = ["s3:GetObject"]
          Resource = ["arn:aws:s3:::example-bucket/*"]
        }
      ]
    })
  }
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "ec2_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "${var.role_name}-profile"
  role = aws_iam_role.ec2_role.name
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.ec2_role.id
  policy = each.value
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.ec2_role.name
  policy_arn = each.value
}

output "role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.ec2_role.arn
}

output "instance_profile_name" {
  description = "Name of the instance profile"
  value       = aws_iam_instance_profile.ec2_profile.name
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the cluster"
  type        = string
  default     = "Fast-App"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

variable "availability_zones" {
  description = "Availability zones to use"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name    = var.cluster_name
    Cluster = var.cluster_name
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name    = "${var.cluster_name}-public-${count.index + 1}"
    Cluster = var.cluster_name
    Tier    = "public"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name    = "${var.cluster_name}-private-${count.index + 1}"
    Cluster = var.cluster_name
    Tier    = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "${var.cluster_name}-igw"
    Cluster = var.cluster_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "${var.cluster_name}-public-rt"
    Cluster = var.cluster_name
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "monitoring_accounts" {
  description = "List of AWS accounts allowed to assume the Grafana monitoring role"
  type        = list(string)
  default     = ["123456789012"]
}

variable "prometheus_workspace_id" {
  description = "ID of the Amazon Managed Service for Prometheus workspace"
  type        = string
  default     = "ws-00000000000000000000000000000000"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "grafana_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = var.monitoring_accounts
    }

    condition {
      test     = "StringEquals"
      variable = "grafana:WorkspaceName"
      values   = ["Grafana"]
    }
  }
}

data "aws_iam_policy_document" "grafana_monitoring" {
  statement {
    sid    = "PrometheusQuery"
    effect = "Allow"
    actions = [
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace"
    ]
    resources = [
      "arn:aws:aps:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:workspace/${var.prometheus_workspace_id}",
      "arn:aws:aps:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:/workspaces/${var.prometheus_workspace_id}/*"
    ]
  }

  statement {
    sid    = "CloudWatchMetrics"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms"
    ]
    resources = ["*"]
  }
}

data "aws_region" "current" {}

resource "aws_iam_role" "grafana_monitoring" {
  name               = "GrafanaMonitoringRole"
  description        = "Role allowing Grafana workspace 'Grafana' to query Prometheus and CloudWatch metrics"
  assume_role_policy = data.aws_iam_policy_document.grafana_trust.json
}

resource "aws_iam_policy" "grafana_monitoring" {
  name        = "GrafanaMonitoringPolicy"
  description = "Read access to Amazon Managed Prometheus and CloudWatch metrics"
  policy      = data.aws_iam_policy_document.grafana_monitoring.json
}

resource "aws_iam_role_policy_attachment" "grafana_monitoring" {
  role       = aws_iam_role.grafana_monitoring.name
  policy_arn = aws_iam_policy.grafana_monitoring.arn
}

output "role_arn" {
  description = "ARN of the Grafana monitoring role"
  value       = aws_iam_role.grafana_monitoring.arn
}

output "policy_arn" {
  description = "ARN of the Grafana monitoring policy"
  value       = aws_iam_policy.grafana_monitoring.arn
}

