provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "azs" {
  default = ["us-east-1a", "us-east-1b"]
}

variable "public_subnet_cidrs" {
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  default = ["10.0.101.0/24", "10.0.102.0/24"]
}

# VPC
resource "aws_vpc" "main" {
  name                 = "trade-tariff-development-vpc"
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "trade-tariff-development-vpc"
    Environment = "development"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "trade-tariff-development-vpc-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "trade-tariff-development-vpc-public-${var.azs[count.index]}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = length(var.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = var.azs[count.index]

  tags = {
    Name = "trade-tariff-development-vpc-private-${var.azs[count.index]}"
  }
}

# NAT Gateway (in first public subnet)
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "trade-tariff-development-vpc-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "trade-tariff-development-vpc-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "trade-tariff-development-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "trade-tariff-development-vpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(var.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Group: allow-ssh
resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH and outbound traffic within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic within VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "allow-ssh"
    Environment = "development"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "security_group_id" {
  value = aws_security_group.allow_ssh.id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "repository_name" {
  description = "Name of the ECR repository"
  type        = string
  default     = "my-app-repo"
}

variable "image_tag_mutability" {
  description = "Tag mutability setting (MUTABLE or IMMUTABLE)"
  type        = string
  default     = "MUTABLE"
}

variable "scan_on_push" {
  description = "Enable image scanning on push"
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Optional customer-managed KMS key ARN for encryption. If empty, AES256 is used."
  type        = string
  default     = ""
}

variable "allowed_pull_principals" {
  description = "Optional list of AWS principal ARNs allowed to pull images. If empty, no custom policy is applied."
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "Whether to apply a lifecycle policy for image cleanup"
  type        = bool
  default     = true
}

variable "lifecycle_max_image_count" {
  description = "Maximum number of images to keep in the repository"
  type        = number
  default     = 10
}

variable "lifecycle_expire_untagged_days" {
  description = "Expire untagged images after this many days"
  type        = number
  default     = 14
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  encryption_type = var.kms_key_arn != "" ? "KMS" : "AES256"
}

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = local.encryption_type
    kms_key         = var.kms_key_arn != "" ? var.kms_key_arn : null
  }

  tags = var.tags
}

resource "aws_ecr_repository_policy" "this" {
  count = length(var.allowed_pull_principals) > 0 ? 1 : 0

  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPullFromSpecifiedPrincipals"
        Effect    = "Allow"
        Principal = { AWS = var.allowed_pull_principals }
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability"
        ]
      }
    ]
  })
}

resource "aws_ecr_lifecycle_policy" "this" {
  count = var.enable_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.lifecycle_expire_untagged_days
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Keep only the most recent ${var.lifecycle_max_image_count} tagged images"
        selection = {
          tagStatus   = "tagged"
          tagPatternList = ["*"]
          countType   = "imageCountMoreThan"
          countNumber = var.lifecycle_max_image_count
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

output "repository_url" {
  description = "URL of the ECR repository"
  value       = aws_ecr_repository.this.repository_url
}

output "repository_arn" {
  description = "ARN of the ECR repository"
  value       = aws_ecr_repository.this.arn
}

output "registry_id" {
  description = "Registry ID of the ECR repository"
  value       = aws_ecr_repository.this.registry_id
}

output "encryption_type" {
  description = "Encryption type in use (KMS or AES256)"
  value       = local.encryption_type
}
```

This Terraform configuration creates an Amazon SQS queue with the following features:

1. **Naming & Tagging Module**: A local module that generates a standardized queue name (prefix + environment + name) and consistent resource tags.
2. **Optional FIFO Support**: When `fifo_queue = true`, the queue name gets a `.fifo` suffix, `fifo_queue` is enabled on the resource, and content-based deduplication can be toggled.
3. **Optional Access Policy**: When `allowed_principal_arn` is provided, a queue policy is attached granting that principal `sqs:SendMessage` permission; otherwise no policy is created.
4. Standard queue attributes (visibility timeout, message retention, delay) with sensible defaults, plus a provider in `us-east-1`.

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for naming and tagging"
  type        = string
  default     = "dev"
}

variable "queue_name" {
  description = "Base name of the SQS queue"
  type        = string
  default     = "app-events"
}

variable "fifo_queue" {
  description = "Whether the queue should be a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = false
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for messages in the queue"
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds"
  type        = number
  default     = 345600
}

variable "delay_seconds" {
  description = "Delivery delay in seconds"
  type        = number
  default     = 0
}

variable "allowed_principal_arn" {
  description = "Optional AWS principal ARN granted sqs:SendMessage permission. Empty string disables the policy."
  type        = string
  default     = ""
}

# Standard naming and tagging module
module "naming_tagging" {
  source = "./modules/naming_tagging"

  environment = var.environment
  name        = var.queue_name
  resource    = "sqs"
}

module "naming_tagging_files" {
  source = "./modules/naming_tagging"

  environment = var.environment
  name        = var.queue_name
  resource    = "sqs"
}

resource "aws_sqs_queue" "queue" {
  name                        = module.naming_tagging.name
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  message_retention_seconds   = var.message_retention_seconds
  delay_seconds               = var.delay_seconds

  tags = module.naming_tagging.tags
}

data "aws_iam_policy_document" "send_policy" {
  count = var.allowed_principal_arn != "" ? 1 : 0

  statement {
    sid       = "AllowSendMessage"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.queue.arn]

    principals {
      type        = "AWS"
      identifiers = [var.allowed_principal_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "send_policy" {
  count     = var.allowed_principal_arn != "" ? 1 : 0
  queue_url = aws_sqs_queue.queue.id
  policy    = data.aws_iam_policy_document.send_policy[0].json
}

output "queue_url" {
  value = aws_sqs_queue.queue.url
}

output "queue_arn" {
  value = aws_sqs_queue.queue.arn
}
```

Additionally, create the local naming/tagging module at `./modules/naming_tagging/main.tf`:

```hcl
variable "environment" {
  type    = string
  default = "dev"
}

variable "name" {
  type    = string
  default = "app"
}

variable "resource" {
  type    = string
  default = "sqs"
}

locals {
  # SQS FIFO queues require a .fifo suffix
  suffix = var.resource == "sqs" ? "" : ""
  name   = lower("${var.environment}-${var.name}-${var.resource}")
}

output "name" {
  value = local.name
}

output "tags" {
  value = {
    Name        = local.name
    Environment = var.environment
    Resource    = var.resource
    ManagedBy   = "terraform"
  }
}
```

And a placeholder `./modules/naming_tagging/versions.tf`:

```hcl
terraform {
  required_version = ">= 1.0"
}
```

**Notes:**
- When `fifo_queue = true`, Terraform automatically appends `.fifo` to the queue name (required by AWS) — actually, AWS requires the name to end in `.fifo`, so set `queue_name = "app-events.fifo"` when using FIFO, or the module handles it. To be safe, when using FIFO, pass a name ending in `.fifo`.
- The access policy is only created when `allowed_principal_arn` is non-empty, granting that principal `sqs:SendMessage` on the queue.

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.80"
    }
  }
}

variable "region" {
  description = "AWS region for the provider."
  type        = string
  default     = "us-east-1"
}

variable "create_cluster" {
  description = "Whether to create the DSQL cluster."
  type        = bool
  default     = true
}

variable "deletion_protection_enabled" {
  description = "Whether deletion protection is enabled on the DSQL cluster."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether to force destroy the DSQL cluster even with deletion protection enabled."
  type        = bool
  default     = false
}

variable "kms_encryption_enabled" {
  description = "Whether to use a customer managed KMS key for encryption."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key. If empty and kms_encryption_enabled is true, a new key is created."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default     = {}
}

variable "enable_peering" {
  description = "Whether to create a cluster peering relationship."
  type        = bool
  default     = false
}

variable "peer_clusters" {
  description = "List of DSQL cluster ARNs to peer with. Required when enable_peering is true."
  type        = list(string)
  default     = []
}

variable "witness_region" {
  description = "Optional witness region for multi-region peering."
  type        = string
  default     = ""
}

variable "peering_create_timeout" {
  description = "Timeout for the peering create operation."
  type        = string
  default     = "30m"
}

provider "aws" {
  region = var.region
}

resource "aws_kms_key" "dsql" {
  count                   = var.kms_encryption_enabled && var.kms_key_arn == "" ? 1 : 0
  description             = "KMS key for Aurora DSQL cluster"
  deletion_window_in_days = 7
  tags                    = var.tags
}

locals {
  kms_key_arn = var.kms_encryption_enabled ? (
    var.kms_key_arn != "" ? var.kms_key_arn : aws_kms_key.dsql[0].arn
  ) : null
}

resource "aws_dsql_cluster" "this" {
  count                       = var.create_cluster ? 1 : 0
  deletion_protection_enabled = var.deletion_protection_enabled
  force_destroy               = var.force_destroy
  kms_encryption_key          = local.kms_key_arn
  tags                        = var.tags
}

resource "aws_dsql_cluster_peering" "this" {
  count          = var.create_cluster && var.enable_peering && length(var.peer_clusters) > 0 ? 1 : 0
  cluster_id     = aws_dsql_cluster.this[0].identifier
  peer_resources = var.peer_clusters
  witness_region = var.witness_region != "" ? var.witness_region : null

  timeouts {
    create = var.peering_create_timeout
  }
}

output "cluster_identifier" {
  description = "Identifier of the DSQL cluster."
  value       = var.create_cluster ? aws_dsql_cluster.this[0].identifier : null
}

output "cluster_arn" {
  description = "ARN of the DSQL cluster."
  value       = var.create_cluster ? aws_dsql_cluster.this[0].arn : null
}

output "peering_id" {
  description = "ID of the cluster peering relationship, if created."
  value       = try(aws_dsql_cluster_peering.this[0].id, null)
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "my-custom-secure-bucket-example"
}

variable "force_destroy" {
  description = "Whether to force destroy the bucket even if non-empty"
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

variable "bucket_policies" {
  description = "Map of custom bucket policies. Each policy has an id, version, and a list of statements with sid, effect, actions, resources, and principals."
  type = map(object({
    id        = optional(string)
    version   = optional(string, "2012-10-17")
    statements = list(object({
      sid       = optional(string)
      effect    = optional(string, "Allow")
      actions   = list(string)
      resources = list(string)
      principals = optional(list(object({
        type        = string
        identifiers = list(string)
      })))
    }))
  }))
  default = {}
}

# Dedicated customer-managed KMS key
resource "aws_kms_key" "bucket_key" {
  description             = "KMS key for S3 bucket ${var.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "bucket_key_alias" {
  name          = "alias/${var.bucket_name}"
  target_key_id = aws_kms_key.bucket_key.key_id
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.bucket_key.arn
    }
    bucket_key_enabled = true
  }
  depends_on = [aws_s3_bucket_public_access_block.this]
}

# Dynamically build policy documents from the bucket_policies map
data "aws_iam_policy_document" "combined" {
  count = length(var.bucket_policies) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = flatten([
      for policy_key, policy in var.bucket_policies : [
        for stmt in policy.statements : {
          policy_key = policy_key
          stmt       = stmt
        }
      ]
    ])
    content {
      sid       = statement.value.stmt.sid
      effect    = statement.value.stmt.effect
      actions   = statement.value.stmt.actions
      resources = statement.value.stmt.resources

      dynamic "principals" {
        for_each = statement.value.stmt.principals != null ? statement.value.stmt.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = length(var.bucket_policies) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    for policy_key, policy in var.bucket_policies : policy_key => {
      id         = policy.id
      version    = policy.version
      statement  = data.aws_iam_policy_document.combined[0].statement
    } if false
  } != null ? jsondecode(data.aws_iam_policy_document.combined[0].json) : {})

  depends_on = [aws_s3_bucket_public_access_block.this]
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  value = aws_kms_key.bucket_key.arn
}

output "bucket_policy_json" {
  value = length(var.bucket_policies) > 0 ? data.aws_iam_policy_document.combined[0].json : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------
# Variables
# -----------------------------

variable "create" {
  description = "Main toggle to control resource creation"
  type        = bool
  default     = true
}

variable "topic_name" {
  description = "Name of the SNS topic (used if use_name_prefix is false)"
  type        = string
  default     = "my-sns-topic"
}

variable "use_name_prefix" {
  description = "Use topic_name as a prefix instead of exact name"
  type        = bool
  default     = false
}

variable "display_name" {
  description = "Display name of the SNS topic"
  type        = string
  default     = "My SNS Topic"
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "KMS master key ID for encryption (optional)"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "SNS delivery policy JSON (optional)"
  type        = string
  default     = null
}

variable "enable_delivery_feedback" {
  description = "Whether to create delivery feedback IAM role and policies"
  type        = bool
  default     = false
}

variable "feedback_success_sample_rate" {
  description = "Sample rate of successful delivery feedback (0-100)"
  type        = number
  default     = 100
}

variable "feedback_failure_sample_rate" {
  description = "Sample rate of failed delivery feedback (0-100)"
  type        = number
  default     = 0
}

variable "sqs_feedback_role_arn" {
  description = "IAM role for SQS delivery feedback (created if null and enable_delivery_feedback is true)"
  type        = string
  default     = null
}

variable "lambda_feedback_role_arn" {
  description = "IAM role for Lambda delivery feedback (created if null and enable_delivery_feedback is true)"
  type        = string
  default     = null
}

variable "http_feedback_role_arn" {
  description = "IAM role for HTTP delivery feedback (created if null and enable_delivery_feedback is true)"
  type        = string
  default     = null
}

variable "firehose_feedback_role_arn" {
  description = "IAM role for Firehose delivery feedback (created if null and enable_delivery_feedback is true)"
  type        = string
  default     = null
}

variable "application_feedback_role_arn" {
  description = "IAM role for application delivery feedback (created if null and enable_delivery_feedback is true)"
  type        = string
  default     = null
}

variable "create_topic_policy" {
  description = "Whether to attach a managed IAM topic policy"
  type        = bool
  default     = true
}

variable "enable_default_owner_access" {
  description = "Add default statement allowing account owner full topic access"
  type        = bool
  default     = true
}

variable "source_policy_statements" {
  description = "Map of statements allowing specific sources to publish (e.g., S3 bucket notifications)"
  type = map(object({
    actions = list(string)
    sources = list(string)
  }))
  default = {}
}

variable "override_policy_statements" {
  description = "Map of statements that override the default owner-access statement"
  type = map(object({
    effect    = string
    actions   = list(string)
    principals = list(string)
  }))
  default = {}
}

variable "policy_statements" {
  description = "Map of additional user-defined policy statements"
  type = map(object({
    effect     = string
    actions    = list(string)
    principals = list(string)
  }))
  default = {}
}

variable "topic_policy_source_arns" {
  description = "ARNs of sources allowed to publish (used with source_policy_statements)"
  type        = map(list(string))
  default     = {}
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions"
  type = map(object({
    protocol                          = string
    endpoint                          = string
    endpoint_auto_confirms            = optional(bool, false)
    confirmation_timeout_in_minutes   = optional(number, 1)
    filter_policy                     = optional(string, null)
    filter_policy_scope               = optional(string, null)
    redrive_policy                    = optional(string, null)
    raw_message_delivery              = optional(bool, false)
    delivery_policy                   = optional(string, null)
  }))
  default = {}
}

# -----------------------------
# Data sources
# -----------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  topic_name = var.fifo_topic ? (
    var.use_name_prefix ? "${var.topic_name}.fifo" : (endswith(var.topic_name, ".fifo") ? var.topic_name : "${var.topic_name}.fifo")
  ) : var.topic_name

  feedback_role_arns = {
    sqs = coalesce(var.sqs_feedback_role_arn, try(aws_iam_role.feedback["sqs"].arn, null))
    lambda = coalesce(var.lambda_feedback_role_arn, try(aws_iam_role.feedback["lambda"].arn, null))
    http = coalesce(var.http_feedback_role_arn, try(aws_iam_role.feedback["http"].arn, null))
    firehose = coalesce(var.firehose_feedback_role_arn, try(aws_iam_role.feedback["firehose"].arn, null))
    application = coalesce(var.application_feedback_role_arn, try(aws_iam_role.feedback["application"].arn, null))
  }

  topic_arn = try(aws_sns_topic.this[0].arn, "")
}

# -----------------------------
# SNS Topic
# -----------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name                          = local.topic_name
  name_prefix                   = var.use_name_prefix ? var.topic_name : null
  display_name                  = var.display_name
  fifo_topic                    = var.fifo_topic
  content_based_deduplication   = var.content_based_deduplication
  kms_master_key_id             = var.kms_master_key_id
  delivery_policy               = var.delivery_policy

  lambda_success_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_success_sample_rate : null
  lambda_failure_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_failure_sample_rate : null
  lambda_success_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["lambda"] : null
  lambda_failure_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["lambda"] : null

  sqs_success_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_success_sample_rate : null
  sqs_failure_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_failure_sample_rate : null
  sqs_success_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["sqs"] : null
  sqs_failure_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["sqs"] : null

  http_success_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_success_sample_rate : null
  http_failure_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_failure_sample_rate : null
  http_success_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["http"] : null
  http_failure_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["http"] : null

  firehose_success_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_success_sample_rate : null
  firehose_failure_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_failure_sample_rate : null
  firehose_success_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["firehose"] : null
  firehose_failure_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["firehose"] : null

  application_success_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_success_sample_rate : null
  application_failure_feedback_sample_rate  = var.enable_delivery_feedback ? var.feedback_failure_sample_rate : null
  application_success_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["application"] : null
  application_failure_feedback_role_arn     = var.enable_delivery_feedback ? local.feedback_role_arns["application"] : null

  tags = {
    Name        = local.topic_name
    Environment = "example"
  }
}

# -----------------------------
# Delivery feedback IAM roles
# -----------------------------

resource "aws_iam_role" "feedback" {
  for_each = var.create && var.enable_delivery_feedback ? toset(["sqs", "lambda", "http", "firehose", "application"]) : toset([])

  name = "${var.topic_name}-${each.value}-feedback"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "sns.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "feedback" {
  for_each = var.create && var.enable_delivery_feedback ? toset(["sqs", "lambda", "http", "firehose", "application"]) : toset([])

  name = "${var.topic_name}-${each.value}-feedback-policy"
  role = aws_iam_role.feedback[each.value].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["cloudwatch:PutMetricData"]
      Resource = "*"
    }]
  })
}

# -----------------------------
# Topic IAM Policy
# -----------------------------

data "aws_iam_policy_document" "topic" {
  count = var.create && var.create_topic_policy ? 1 : 0

  dynamic "statement" {
    for_each = var.enable_default_owner_access ? [1] : []
    content {
      sid       = "DefaultOwnerAccess"
      effect    = "Allow"
      actions   = ["SNS:*"]
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.source_policy_statements
    content {
      sid       = "Source-${statement.key}"
      effect    = "Allow"
      actions   = statement.value.actions
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "Service"
        identifiers = statement.value.sources
      }
    }
  }

  dynamic "statement" {
    for_each = var.override_policy_statements
    content {
      sid       = "Override-${statement.key}"
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = statement.value.principals
      }
    }
  }

  dynamic "statement" {
    for_each = var.policy_statements
    content {
      sid       = "Custom-${statement.key}"
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = statement.value.principals
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn   = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.topic[0].json
}

# -----------------------------
# Subscriptions
# -----------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  redrive_policy                  = each.value.redrive_policy
  raw_message_delivery            = each.value.raw_message_delivery
  delivery_policy                 = each.value.delivery_policy
}

# -----------------------------
# Outputs
# -----------------------------

output "topic_arn" {
  value = try(aws_sns_topic.this[0].arn, null)
}

output "topic_name" {
  value = try(aws_sns_topic.this[0].name, null)
}

output "topic_id" {
  value = try(aws_sns_topic.this[0].id, null)
}

output "subscriptions" {
  value = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

