```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

variable "create_transit_gateway" {
  description = "Whether to create a new Transit Gateway (true) or attach to an existing one (false)"
  type        = bool
  default     = true
}

variable "existing_transit_gateway_id" {
  description = "ID of an existing Transit Gateway to attach to (used when create_transit_gateway is false)"
  type        = string
  default     = ""
}

variable "transit_gateway_name" {
  description = "Name tag for the Transit Gateway"
  type        = string
  default     = "central-tgw"
}

variable "transit_gateway_asn" {
  description = "Private ASN for the Transit Gateway"
  type        = number
  default     = 64512
}

variable "vpc_attachments" {
  description = "Map of VPC attachments. Key is an arbitrary name; value contains vpc_id, subnet_id, and route_table_id."
  type = map(object({
    vpc_id         = string
    subnet_id      = string
    route_table_id = string
  }))
  default = {
    "vpc-a" = {
      vpc_id         = "vpc-0123456789abcdef0"
      subnet_id      = "subnet-0123456789abcdef0"
      route_table_id = "rtb-0123456789abcdef0"
    }
    "vpc-b" = {
      vpc_id         = "vpc-0fedcba9876543210"
      subnet_id      = "subnet-0fedcba9876543210"
      route_table_id = "rtb-0fedcba9876543210"
    }
  }
}

variable "tgw_route_table_name" {
  description = "Name tag for the Transit Gateway route table"
  type        = string
  default     = "central-tgw-rt"
}

# Transit Gateway (created only if create_transit_gateway is true)
resource "aws_ec2_transit_gateway" "this" {
  count                                = var.create_transit_gateway ? 1 : 0
  description                          = "Central Transit Gateway for inter-VPC routing"
  amazon_side_asn                      = var.transit_gateway_asn
  default_route_table_association      = false
  default_route_table_propagation      = false
  auto_accept_shared_attachments       = "disable"
  enable_default_route_table_association = false

  tags = {
    Name = var.transit_gateway_name
  }
}

# Resolve the Transit Gateway ID (created or existing)
locals {
  transit_gateway_id = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].id : var.existing_transit_gateway_id
}

# Transit Gateway route table for centralized routing
resource "aws_ec2_transit_gateway_route_table" "this" {
  transit_gateway_id = local.transit_gateway_id

  tags = {
    Name = var.tgw_route_table_name
  }
}

# VPC attachments, one per entry in the vpc_attachments map
resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each           = var.vpc_attachments
  transit_gateway_id = local.transit_gateway_id
  vpc_id             = each.value.vpc_id
  subnet_ids         = [each.value.subnet_id]

  transit_gateway_default_route_table_association = false
  transit_gateway_default_route_table_propagation = false

  tags = {
    Name = "tgw-attach-${each.key}"
  }
}

# Associate each attachment with the central TGW route table
resource "aws_ec2_transit_gateway_route_table_association" "this" {
  for_each                       = var.vpc_attachments
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.this.id
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_vpc_attachment.this[each.key].id
}

# Propagate each attachment's routes into the central TGW route table
resource "aws_ec2_transit_gateway_route_table_propagation" "this" {
  for_each                       = var.vpc_attachments
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.this.id
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_vpc_attachment.this[each.key].id
}

output "transit_gateway_id" {
  description = "ID of the Transit Gateway"
  value       = local.transit_gateway_id
}

output "transit_gateway_route_table_id" {
  description = "ID of the central Transit Gateway route table"
  value       = aws_ec2_transit_gateway_route_table.this.id
}

output "vpc_attachment_ids" {
  description = "Map of attachment names to Transit Gateway VPC attachment IDs"
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.this : k => v.id }
}
