```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "event-topic"
}

variable "stage_name" {
  description = "API Gateway deployment stage name"
  type        = string
  default     = "prod"
}

# ---------------------------------------------------------------------------
# KMS Key (customer-managed, with rotation)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_iam_role" "apigw_sns_role" {
  name = "apigw-sns-publish-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kms_key" "sns_key" {
  description             = "KMS key for SNS topic ${var.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowSNSUseOfKey"
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowAPIGatewayRoleUseOfKey"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.apigw_sns_role.arn }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/${var.topic_name}-key"
  target_key_id = aws_kms_key.sns_key.key_id
}

# ---------------------------------------------------------------------------
# SNS Topic (encrypted with the KMS key)
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "event_topic" {
  name              = var.topic_name
  kms_master_key_id = aws_kms_key.sns_key.key_id
}

# ---------------------------------------------------------------------------
# IAM policy: allow API Gateway role to publish to the topic
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "apigw_sns_publish" {
  name = "apigw-sns-publish-policy"
  role = aws_iam_role.apigw_sns_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.event_topic.arn
      },
      {
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey*", "kms:Decrypt"]
        Resource = aws_kms_key.sns_key.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# REST API Gateway -> SNS integration
# ---------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "api" {
  name        = "sns-publish-api"
  description = "REST API that publishes POST requests to SNS topic ${var.topic_name}"
}

resource "aws_api_gateway_method" "post" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_rest_api.api.root_resource_id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "sns" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_rest_api.api.root_resource_id
  http_method             = aws_api_gateway_method.post.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:action/Publish"
  credentials             = aws_iam_role.apigw_sns_role.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_rest_api.api.root_resource_id
  http_method = aws_api_gateway_method.post.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_rest_api.api.root_resource_id
  http_method = aws_api_gateway_method.post.http_method
  status_code = aws_api_gateway_method_response.post_200.status_code

  depends_on = [aws_api_gateway_integration.sns]
}

resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_integration.sns,
      aws_api_gateway_method.post,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_api_gateway_integration.sns]
}

resource "aws_api_gateway_stage" "stage" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  deployment_id = aws_api_gateway_deployment.deployment.id
  stage_name    = var.stage_name
}

output "api_invoke_url" {
  description = "Invoke URL for the POST endpoint"
  value       = "${aws_api_gateway_stage.stage.invoke_url}/"
}

output "sns_topic_arn" {
  value = aws_sns_topic.event_topic.arn
}

output "kms_key_arn" {
  value = aws_kms_key.sns_key.arn
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = length(var.public_subnet_cidrs)
  domain = "vpc"

  tags = {
    Name = "terraform-aws-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = length(var.public_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "terraform-aws-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "terraform-aws-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "terraform-aws-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.10.0.0/16"
}

resource "aws_vpc" "ntier_primary" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ntier primary"
  }
}

resource "aws_internet_gateway" "ntier_igw" {
  vpc_id = aws_vpc.ntier_primary.id

  tags = {
    Name = "ntier primary igw"
  }
}

# Subnets
resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "ntier primary web"
    Tier = "web"
  }
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.2.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "ntier primary app"
    Tier = "app"
  }
}

resource "aws_subnet" "database" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.3.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "ntier primary database"
    Tier = "database"
  }
}

resource "aws_subnet" "management" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.4.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "ntier primary management"
    Tier = "management"
  }
}

resource "aws_subnet" "web2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.5.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "ntier primary web 2"
    Tier = "web"
  }
}

resource "aws_subnet" "app2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.6.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "ntier primary app 2"
    Tier = "app"
  }
}

resource "aws_subnet" "database2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.7.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "ntier primary database 2"
    Tier = "database"
  }
}

# Route tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier_igw.id
  }

  tags = {
    Name = "ntier primary public"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier_igw.id
  }

  tags = {
    Name = "ntier primary private"
  }
}

# Public associations: web, management, web2
resource "aws_route_table_association" "web_public" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "management_public" {
  subnet_id      = aws_subnet.management.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web2_public" {
  subnet_id      = aws_subnet.web2.id
  route_table_id = aws_route_table.public.id
}

# Private associations: app, database, app2, database2
resource "aws_route_table_association" "app_private" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database_private" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app2_private" {
  subnet_id      = aws_subnet.app2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database2_private" {
  subnet_id      = aws_subnet.database2.id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the ntier primary VPC"
  value       = aws_vpc.ntier_primary.id
}

output "internet_gateway_id" {
  description = "ID of the attached internet gateway"
  value       = aws_internet_gateway.ntier_igw.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table"
  value       = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "deletion_window_in_days" {
  description = "Waiting period before key deletion"
  type        = number
  default     = 30
}

variable "enable_key_rotation" {
  description = "Enable annual key rotation (standard keys only)"
  type        = bool
  default     = false
}

variable "multi_region" {
  description = "Create a multi-region primary key"
  type        = bool
  default     = false
}

variable "create_external" {
  description = "Create external key with imported key material"
  type        = bool
  default     = false
}

variable "create_replica" {
  description = "Create a replica key"
  type        = bool
  default     = false
}

variable "create_replica_external" {
  description = "Create a replica external key"
  type        = bool
  default     = false
}

variable "primary_key_arn" {
  description = "ARN of the primary key for replicas"
  type        = string
  default     = null
}

variable "key_material_base64" {
  description = "Base64-encoded 256-bit key material for external keys"
  type        = string
  default     = null
}

variable "description" {
  type    = string
  default = "Managed by Terraform"
}

variable "key_owners" {
  type    = list(string)
  default = []
}

variable "key_administrators" {
  type    = list(string)
  default = []
}

variable "key_users" {
  type    = list(string)
  default = []
}

variable "key_service_users" {
  type    = list(string)
  default = []
}

variable "key_asymmetric_users" {
  type    = list(string)
  default = []
}

variable "key_symmetric_encryption_users" {
  type    = list(string)
  default = []
}

variable "key_hmac_users" {
  type    = list(string)
  default = []
}

variable "key_sign_verify_users" {
  type    = list(string)
  default = []
}

variable "key_ec2_auto_scaling_roles" {
  type    = list(string)
  default = []
}

variable "enable_route53_dnssec" {
  type    = bool
  default = false
}

variable "custom_policy_statements" {
  type    = any
  default = []
}

variable "key_policy_override" {
  type    = any
  default = null
}

variable "aliases" {
  description = "List of alias names (exact) or prefixes"
  type        = list(string)
  default     = []
}

variable "grants" {
  description = "List of grant maps: name, grantee_principal, operations, retiring_principal, constraints"
  type        = any
  default     = []
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_iam_policy_document" "this" {
  count = var.key_policy_override == null ? 1 : 0

  statement {
    sid       = "DefaultRoot"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid       = "KeyOwners"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*", "kms:Put*", "kms:Update*", "kms:Revoke*", "kms:Disable*", "kms:Get*", "kms:Delete*", "kms:TagResource", "kms:UntagResource", "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion"]

    principals {
      type        = "AWS"
      identifiers = var.key_owners
    }
  }

  statement {
    sid       = "KeyAdministrators"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*", "kms:Put*", "kms:Update*", "kms:Revoke*", "kms:Disable*", "kms:Get*", "kms:Delete*", "kms:TagResource", "kms:UntagResource", "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion"]

    principals {
      type        = "AWS"
      identifiers = var.key_administrators
    }
  }

  statement {
    sid       = "KeyUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]

    principals {
      type        = "AWS"
      identifiers = var.key_users
    }
  }

  statement {
    sid       = "KeyServiceUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey", "kms:GenerateDataKeyWithoutPlaintext", "kms:GenerateDataKeyPair", "kms:GenerateDataKeyPairWithoutPlaintext"]

    principals {
      type        = "AWS"
      identifiers = var.key_service_users
    }
  }

  statement {
    sid       = "KeyEc2AutoScaling"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]

    principals {
      type        = "AWS"
      identifiers = var.key_ec2_auto_scaling_roles
    }
  }

  statement {
    sid       = "KeySymmetricEncryptionUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]

    principals {
      type        = "AWS"
      identifiers = var.key_symmetric_encryption_users
    }
  }

  statement {
    sid       = "KeyHmacUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:DescribeKey", "kms:GenerateMac", "kms:VerifyMac"]

    principals {
      type        = "AWS"
      identifiers = var.key_hmac_users
    }
  }

  statement {
    sid       = "KeyAsymmetricPublicEncryptionUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Encrypt", "kms:DescribeKey", "kms:GetPublicKey"]

    principals {
      type        = "AWS"
      identifiers = var.key_asymmetric_users
    }
  }

  statement {
    sid       = "KeySignVerifyUsers"
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:Sign", "kms:Verify", "kms:DescribeKey", "kms:GetPublicKey"]

    principals {
      type        = "AWS"
      identifiers = var.key_sign_verify_users
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid       = "Route53Dnssec"
      effect    = "Allow"
      resources = ["*"]
      actions   = ["kms:DescribeKey", "kms:GetPublicKey", "kms:Sign"]

      principals {
        type        = "Service"
        identifiers = ["dnssec.route53.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = try(statement.value.sid, null)
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = try(statement.value.resources, ["*"])

      principals {
        type        = try(statement.value.principal_type, "AWS")
        identifiers = statement.value.principals
      }
    }
  }
}

locals {
  creation_mode = coalesce(
    var.create_replica_external ? "replica_external" : null,
    var.create_replica ? "replica" : null,
    var.create_external ? "external" : null,
    "standard"
  )

  key_policy = var.key_policy_override != null ? jsonencode(var.key_policy_override) : data.aws_iam_policy_document.this[0].json
}

resource "aws_kms_key" "this" {
  count = local.creation_mode == "standard" ? 1 : 0

  description             = var.description
  multi_region            = var.multi_region
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = var.enable_key_rotation
  policy                  = local.key_policy
}

resource "aws_kms_external_key" "this" {
  count = local.creation_mode == "external" ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy
}

resource "aws_kms_replica_key" "this" {
  count = local.creation_mode == "replica" ? 1 : 0

  primary_key_arn         = var.primary_key_arn
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy
}

resource "aws_kms_replica_external_key" "this" {
  count = local.creation_mode == "replica_external" ? 1 : 0

  primary_key_arn         = var.primary_key_arn
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy
}

locals {
  key_arn = coalesce(
    local.creation_mode == "standard" ? try(aws_kms_key.this[0].arn, null) : null,
    local.creation_mode == "external" ? try(aws_kms_external_key.this[0].arn, null) : null,
    local.creation_mode == "replica" ? try(aws_kms_replica_key.this[0].arn, null) : null,
    local.creation_mode == "replica_external" ? try(aws_kms_replica_external_key.this[0].arn, null) : null
  )
}

resource "aws_kms_alias" "this" {
  for_each = toset(var.aliases)

  name          = "alias/${each.value}"
  target_key_id = local.key_arn
}

resource "aws_kms_grant" "this" {
  for_each = { for g in var.grants : g.name => g }

  name              = each.value.name
  key_id            = local.key_arn
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations
  retiring_principal = try(each.value.retiring_principal, null)

  dynamic "constraints" {
    for_each = try([each.value.constraints], [])
    content {
      encryption_context_equals = try(constraints.value.encryption_context_equals, null)
      encryption_context_subset = try(constraints.value.encryption_context_subset, null)
    }
  }
}

output "key_arn" {
  value = local.key_arn
}

output "key_id" {
  value = try(
    aws_kms_key.this[0].key_id,
    aws_kms_external_key.this[0].key_id,
    aws_kms_replica_key.this[0].key_id,
    aws_kms_replica_external_key.this[0].key_id,
    null
  )
}

output "aliases" {
  value = { for k, v in aws_kms_alias.this : k => v.arn }
}

output "grant_ids" {
  value = { for k, v in aws_kms_grant.this : k => v.grant_id }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key"
  type        = bool
  default     = true
}

variable "kms_master_key_arn" {
  description = "Existing KMS master key ARN to use for encryption"
  type        = string
  default     = null
}

variable "kms_key_deletion_window" {
  description = "KMS key deletion window in days"
  type        = number
  default     = 7
}

variable "topic_policy_json" {
  description = "Custom topic policy JSON"
  type        = string
  default     = null
}

variable "application_feedback_role_arn" {
  type    = string
  default = null
}

variable "application_success_sample_rate" {
  type    = number
  default = null
}

variable "application_failure_sample_rate" {
  type    = number
  default = 0
}

variable "http_feedback_role_arn" {
  type    = string
  default = null
}

variable "http_success_sample_rate" {
  type    = number
  default = null
}

variable "http_failure_sample_rate" {
  type    = number
  default = 0
}

variable "lambda_feedback_role_arn" {
  type    = string
  default = null
}

variable "lambda_success_sample_rate" {
  type    = number
  default = null
}

variable "lambda_failure_sample_rate" {
  type    = number
  default = 0
}

variable "sqs_feedback_role_arn" {
  type    = string
  default = null
}

variable "sqs_success_sample_rate" {
  type    = number
  default = null
}

variable "sqs_failure_sample_rate" {
  type    = number
  default = 0
}

variable "firehose_feedback_role_arn" {
  type    = string
  default = null
}

variable "firehose_success_sample_rate" {
  type    = number
  default = null
}

variable "firehose_failure_sample_rate" {
  type    = number
  default = 0
}

variable "subscriptions" {
  description = "Map of SNS subscriptions"
  type = map(object({
    endpoint                       = string
    protocol                       = string
    endpoint_auto_confirms         = optional(bool, false)
    raw_message_delivery           = optional(bool, false)
    filter_policy                  = optional(string, null)
    redrive_policy_target_arn      = optional(string, null)
    confirmation_timeout_in_minutes = optional(number, 1)
  }))
  default = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# Dedicated KMS key
resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "KMS key for SNS topic ${var.topic_name}"
  deletion_window_in_days = var.kms_key_deletion_window
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RootAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "CloudWatchLogsEncryption"
        Effect    = "Allow"
        Principal = { Service = "logs.${data.aws_partition.current.partition}.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${var.topic_name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

locals {
  kms_key_arn = var.create_kms_key ? aws_kms_key.sns[0].arn : (var.kms_master_key_arn != null ? var.kms_master_key_arn : "alias/aws/sns")
}

resource "aws_sns_topic" "this" {
  name                        = var.fifo_topic ? "${var.topic_name}.fifo" : var.topic_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication

  kms_master_key_id = local.kms_key_arn

  policy = var.topic_policy_json

  application_feedback = var.application_feedback_role_arn != null ? {
    role_arn           = var.application_feedback_role_arn
    success_sample_rate = coalesce(var.application_success_sample_rate, 100)
    failure_sample_rate = var.application_failure_sample_rate
  } : null

  http_feedback = var.http_feedback_role_arn != null ? {
    role_arn           = var.http_feedback_role_arn
    success_sample_rate = coalesce(var.http_success_sample_rate, 100)
    failure_sample_rate = var.http_failure_sample_rate
  } : null

  lambda_feedback = var.lambda_feedback_role_arn != null ? {
    role_arn           = var.lambda_feedback_role_arn
    success_sample_rate = coalesce(var.lambda_success_sample_rate, 100)
    failure_sample_rate = var.lambda_failure_sample_rate
  } : null

  sqs_feedback = var.sqs_feedback_role_arn != null ? {
    role_arn           = var.sqs_feedback_role_arn
    success_sample_rate = coalesce(var.sqs_success_sample_rate, 100)
    failure_sample_rate = var.sqs_failure_sample_rate
  } : null

  firehose_feedback = var.firehose_feedback_role_arn != null ? {
    role_arn           = var.firehose_feedback_role_arn
    success_sample_rate = coalesce(var.firehose_success_sample_rate, 100)
    failure_sample_rate = var.firehose_failure_sample_rate
  } : null
}

resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn                       = aws_sns_topic.this.arn
  endpoint                        = each.value.endpoint
  protocol                        = each.value.protocol
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy

  redrive_policy = each.value.redrive_policy_target_arn != null ? jsonencode({
    deadLetterTargetArn = each.value.redrive_policy_target_arn
  }) : null
}

output "topic_arn" {
  value = aws_sns_topic.this.arn
}

output "kms_key_arn" {
  value = local.kms_key_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_iam_group" {
  description = "Whether to create the IAM developer group"
  type        = bool
  default     = true
}

variable "create_iam_read_only_and_s3_policy" {
  description = "Whether to create the IAM read-only and S3 read/write access policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Whether to attach the policy to the group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Whether to create IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_policy" {
  description = "Whether to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Whether to attach the EC2 screenshot policy to users"
  type        = bool
  default     = true
}

variable "create_group_memberships" {
  description = "Whether to add users to the group"
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Whether to create the EC2 instance role"
  type        = bool
  default     = true
}

variable "group_name" {
  description = "Name of the IAM developer group"
  type        = string
  default     = "developers"
}

variable "iam_users" {
  description = "List of IAM users to create"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "user_tags" {
  description = "Tags applied to IAM users"
  type        = map(string)
  default = {
    "user_created_by" = "terraform"
  }
}

variable "iam_read_only_and_s3_policy_name" {
  description = "Name of the IAM read-only and S3 access policy"
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "ec2_screenshot_policy_name" {
  description = "Name of the EC2 console screenshot policy"
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "instance_role_name" {
  description = "Name of the EC2 instance role"
  type        = string
  default     = "instance_role"
}

variable "instance_role_policy_arn" {
  description = "AWS-managed policy ARN attached to the instance role"
  type        = string
  default     = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# IAM Group
resource "aws_iam_group" "developers" {
  count = var.create_iam_group ? 1 : 0
  name  = var.group_name
}

# IAM read-only and S3 read/write policy
resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count  = var.create_iam_read_only_and_s3_policy ? 1 : 0
  name   = var.iam_read_only_and_s3_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "IAMReadOnlyActions"
        Effect = "Allow"
        Action = [
          "iam:GetPolicy",
          "iam:GetPolicyVersion",
          "iam:GetRole",
          "iam:GetRolePolicy",
          "iam:GetUser",
          "iam:GetUserPolicy",
          "iam:ListGroups",
          "iam:ListPolicies",
          "iam:ListRoles",
          "iam:ListUsers",
          "iam:ListAttachedGroupPolicies",
          "iam:ListAttachedUserPolicies",
          "iam:ListAttachedRolePolicies",
          "iam:ListGroupPolicies",
          "iam:ListUserPolicies",
          "iam:ListRolePolicies"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::*/*"
      }
    ]
  })
}

# Attach policy to group
resource "aws_iam_group_policy_attachment" "developers_policy_attachment" {
  count      = var.create_group_policy_attachment ? 1 : 0
  group      = var.create_iam_group ? aws_iam_group.developers[0].name : var.group_name
  policy_arn = var.create_iam_read_only_and_s3_policy ? aws_iam_policy.iam_read_only_and_s3_full_access[0].arn : "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# IAM Users
resource "aws_iam_user" "users" {
  count = var.create_iam_users ? length(var.iam_users) : 0
  name  = var.iam_users[count.index]

  tags = var.user_tags
}

# EC2 console screenshot policy
resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count  = var.create_ec2_screenshot_policy ? 1 : 0
  name   = var.ec2_screenshot_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2GetConsoleScreenshot"
        Effect   = "Allow"
        Action   = ["ec2:GetConsoleScreenshot"]
        Resource = "*"
      }
    ]
  })
}

# Attach EC2 screenshot policy to each user
resource "aws_iam_user_policy_attachment" "ec2_screenshot_attachment" {
  count      = var.create_user_policy_attachments ? length(var.iam_users) : 0
  user       = var.create_iam_users ? aws_iam_user.users[count.index].name : var.iam_users[count.index]
  policy_arn = var.create_ec2_screenshot_policy ? aws_iam_policy.ec2_get_console_screenshot[0].arn : "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# Group memberships
resource "aws_iam_user_group_membership" "users_in_developers" {
  count  = var.create_group_memberships ? length(var.iam_users) : 0
  user   = var.create_iam_users ? aws_iam_user.users[count.index].name : var.iam_users[count.index]
  groups = [var.create_iam_group ? aws_iam_group.developers[0].name : var.group_name]
}

# EC2 instance role
resource "aws_iam_role" "instance_role" {
  count = var.create_ec2_instance_role ? 1 : 0
  name  = var.instance_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid     = "EC2AssumeRole"
        Effect  = "Allow"
        Action  = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "instance_role_read_only" {
  count      = var.create_ec2_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = var.instance_role_policy_arn
}

resource "aws_iam_instance_profile" "instance_profile" {
  count = var.create_ec2_instance_role ? 1 : 0
  name  = "${var.instance_role_name}_profile"
  role  = aws_iam_role.instance_role[0].name
}

# Outputs
output "group_name" {
  value = var.create_iam_group ? aws_iam_group.developers[0].name : null
}

output "iam_read_only_and_s3_policy_arn" {
  value = var.create_iam_read_only_and_s3_policy ? aws_iam_policy.iam_read_only_and_s3_full_access[0].arn : null
}

output "ec2_screenshot_policy_arn" {
  value = var.create_ec2_screenshot_policy ? aws_iam_policy.ec2_get_console_screenshot[0].arn : null
}

output "instance_role_arn" {
  value = var.create_ec2_instance_role ? aws_iam_role.instance_role[0].arn : null
}

output "instance_profile_name" {
  value = var.create_ec2_instance_role ? aws_iam_instance_profile.instance_profile[0].name : null
}

```hcl
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "multi-cluster-networking-vpc"
}

locals {
  vpc_name = var.vpc_name

  tags = {
    Blueprint  = local.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.vpc_name
  cidr = "10.0.0.0/16"

  azs = ["us-west-2a", "us-west-2b", "us-west-2c"]

  private_subnets = [cidrsubnet("10.0.0.0/16", 4, 0), cidrsubnet("10.0.0.0/16", 4, 1), cidrsubnet("10.0.0.0/16", 4, 2)]
  public_subnets  = [cidrsubnet("10.0.0.0/16", 8, 48), cidrsubnet("10.0.0.0/16", 8, 49), cidrsubnet("10.0.0.0/16", 8, 50)]

  enable_nat_gateway   = true
  single_nat_gateway   = true
  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 - allows all traffic from cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster1_additional_sg"
  })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 - allows all traffic from cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster2_additional_sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols from cluster2 security group"
}

resource "aws_vpc_security_group_egress_rule" "cluster1_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols to cluster2 security group"
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols from cluster1 security group"
}

resource "aws_vpc_security_group_egress_rule" "cluster2_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols to cluster1 security group"
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = module.vpc.vpc_id
}

output "private_subnets" {
  description = "List of private subnet IDs"
  value       = module.vpc.private_subnets
}

output "public_subnets" {
  description = "List of public subnet IDs"
  value       = module.vpc.public_subnets
}

output "cluster1_additional_sg_id" {
  description = "ID of the cluster1 additional security group"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "ID of the cluster2 additional security group"
  value       = aws_security_group.cluster2_additional_sg.id
}
