terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for this user pool"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "MFA configuration: OFF, ON, or OPTIONAL"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template by link"
  type = object({
    default_email_option  = string
    email_message_by_link = optional(string)
    email_subject_by_link = optional(string)
  })
  default = {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_message_by_link = "Please click the link below to verify your email address. {##Verify Email##} "
    email_subject_by_link = "Some subject"
  }
}

variable "sms_configuration" {
  description = "SMS configuration map"
  type = object({
    external_id    = string
    sns_caller_arn = string
  })
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  description = "Recovery mechanisms"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

variable "invite_message_template" {
  description = "Invite message templates"
  type = object({
    email_message = string
    email_subject = string
    sms_message   = string
  })
  default = {
    email_message = "Your username is {username} and temporary password is {####}. "
    email_subject = "Your temporary password"
    sms_message   = "Your username is {username} and temporary password is {####}. "
  }
}

variable "admin_create_user_only" {
  description = "Set to true to only allow admin user creation"
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "case_sensitivity" {
  description = "Username case sensitivity: CaseSensitive or CaseInsensitive. null uses default"
  type        = string
  default     = null
}

variable "device_configuration" {
  description = "Device configuration parameters"
  type = object({
    challenge_required_on_new_device      = bool
    device_only_remembered_on_user_prompt = bool
  })
  default = null
}

variable "lambda_config" {
  description = "Lambda trigger configuration map"
  type        = map(string)
  default     = {}
}

variable "custom_email_sender_lambda" {
  description = "Custom email sender Lambda configuration"
  type = object({
    lambda_arn     = string
    lambda_version = string
  })
  default = null
}

variable "schema" {
  description = "Custom schema definitions"
  type = list(object({
    name                     = string
    attribute_data_type      = string
    required                 = bool
    mutable                  = bool
    string_attribute_min_len = optional(number)
    string_attribute_max_len = optional(number)
  }))
  default = [
    {
      name                     = "email"
      attribute_data_type      = "String"
      required                 = true
      mutable                  = true
      string_attribute_min_len = null
      string_attribute_max_len = null
    }
  ]
}

variable "client_app_names" {
  description = "List of client app names to create"
  type        = list(string)
  default     = []
}

variable "generate_secret" {
  description = "Generate app client secret"
  type        = bool
  default     = false
}

variable "access_token_validity" {
  description = "Access token validity"
  type        = number
  default     = 120
}

variable "id_token_validity" {
  description = "ID token validity"
  type        = number
  default     = 120
}

variable "refresh_token_validity" {
  description = "Refresh token validity"
  type        = number
  default     = 7
}

variable "token_validity_units" {
  description = "Token validity units"
  type = object({
    access_token  = string
    id_token      = string
    refresh_token = string
  })
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "allowed_oauth_user_pool_client" {
  description = "Whether the client is allowed to use OAuth"
  type        = bool
  default     = false
}

variable "enable_token_revocation" {
  description = "Enable token revocation"
  type        = bool
  default     = true
}

variable "explicit_auth_flows" {
  description = "Explicit auth flows"
  type        = list(string)
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "prevent_user_existence_errors" {
  description = "Prevent user existence errors setting"
  type        = string
  default     = "LEGACY"
}

variable "read_attributes" {
  description = "Read attributes for clients"
  type        = list(string)
  default     = null
}

variable "write_attributes" {
  description = "Write attributes for clients"
  type        = list(string)
  default     = null
}

variable "callback_urls" {
  description = "Callback URLs for clients"
  type        = list(string)
  default     = null
}

variable "logout_urls" {
  description = "Logout URLs for clients"
  type        = list(string)
  default     = null
}

variable "allowed_oauth_flows" {
  description = "Allowed OAuth flows"
  type        = list(string)
  default     = null
}

variable "allowed_oauth_scopes" {
  description = "Allowed OAuth scopes"
  type        = list(string)
  default     = null
}

variable "supported_identity_providers" {
  description = "Supported identity providers"
  type        = list(string)
  default     = null
}

variable "group_name" {
  description = "Name of the Cognito user group to create (empty to skip)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the user group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "IAM role ARN for the user group"
  type        = string
  default     = null
}

variable "domain" {
  description = "Domain string for the Cognito User Pool domain (empty to skip)"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "ACM certificate ARN for the custom domain"
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias A record for the domain"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID"
  type        = string
  default     = ""
}

# ---------------- User Pool ----------------

resource "aws_cognito_user_pool" "this" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject

  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  mfa_configuration = var.mfa_configuration

  username_configuration {
    case_sensitive = var.case_sensitivity != null ? var.case_sensitivity == "CaseSensitive" : true
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only
    invite_message_template {
      email_message = var.invite_message_template.email_message
      email_subject = var.invite_message_template.email_subject
      sms_message   = var.invite_message_template.sms_message
    }
  }

  verification_message_template {
    default_email_option  = var.verification_message_template.default_email_option
    email_message_by_link = try(var.verification_message_template.email_message_by_link, null)
    email_subject_by_link = try(var.verification_message_template.email_subject_by_link, null)
  }

  dynamic "sms_configuration" {
    for_each = var.sms_configuration.external_id != "" && var.sms_configuration.sns_caller_arn != "" ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [1] : []
    content {
      challenge_required_on_new_device      = var.device_configuration.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_configuration.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_config) > 0 ? [1] : []
    content {
      create_auth_challenge          = try(var.lambda_config["create_auth_challenge"], null)
      custom_message                 = try(var.lambda_config["custom_message"], null)
      define_auth_challenge          = try(var.lambda_config["define_auth_challenge"], null)
      post_authentication            = try(var.lambda_config["post_authentication"], null)
      post_confirmation              = try(var.lambda_config["post_confirmation"], null)
      pre_authentication             = try(var.lambda_config["pre_authentication"], null)
      pre_sign_up                    = try(var.lambda_config["pre_sign_up"], null)
      pre_token_generation           = try(var.lambda_config["pre_token_generation"], null)
      user_migration                 = try(var.lambda_config["user_migration"], null)
      verify_auth_challenge_response = try(var.lambda_config["verify_auth_challenge_response"], null)
    }
  }

  dynamic "custom_email_sender" {
    for_each = var.custom_email_sender_lambda != null ? [1] : []
    content {
      lambda_arn     = var.custom_email_sender_lambda.lambda_arn
      lambda_version = var.custom_email_sender_lambda.lambda_version
    }
  }

  dynamic "schema" {
    for_each = var.schema
    content {
      name                = schema.value.name
      attribute_data_type = schema.value.attribute_data_type
      required            = schema.value.required
      mutable             = schema.value.mutable

      string_attribute_constraints = schema.value.string_attribute_min_len != null || schema.value.string_attribute_max_len != null ? [{
        min_length = schema.value.string_attribute_min_len != null ? schema.value.string_attribute_min_len : 0
        max_length = schema.value.string_attribute_max_len != null ? schema.value.string_attribute_max_len : 2048
      }] : null
    }
  }

  lifecycle {
    ignore_changes = [estimated_number_of_users]
  }
}

# ---------------- User Pool Clients ----------------

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = var.generate_secret

  access_token_validity  = var.access_token_validity
  id_token_validity      = var.id_token_validity
  refresh_token_validity = var.refresh_token_validity

  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }

  allowed_oauth_flows_user_pool_client = var.allowed_oauth_user_pool_client
  enable_token_revocation              = var.enable_token_revocation
  explicit_auth_flows                  = var.explicit_auth_flows
  prevent_user_existence_errors        = var.prevent_user_existence_errors

  read_attributes              = var.read_attributes
  write_attributes             = var.write_attributes
  callback_urls                = var.callback_urls
  logout_urls                  = var.logout_urls
  allowed_oauth_flows          = var.allowed_oauth_flows
  allowed_oauth_scopes         = var.allowed_oauth_scopes
  supported_identity_providers = var.supported_identity_providers
}

# ---------------- User Group ----------------

resource "aws_cognito_user_group" "this" {
  count = var.group_name != "" ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn
}

# ---------------- Domain ----------------

resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.domain_certificate_arn
}

# ---------------- Route 53 Record ----------------

resource "aws_route53_record" "domain_alias" {
  count = var.create_route53_record && var.domain != "" && var.route53_zone_id != "" ? 1 : 0

  name    = var.domain
  type    = "A"
  zone_id = var.route53_zone_id

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

# ---------------- Outputs ----------------

output "user_pool_id" {
  value = aws_cognito_user_pool.this.id
}

output "user_pool_arn" {
  value = aws_cognito_user_pool.this.arn
}

output "client_ids" {
  value = { for k, v in aws_cognito_user_pool_client.this : k => v.id }
}

output "domain_cloudfront_distribution_arn" {
  value = var.domain != "" ? aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name of the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name of the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_name" {
  description = "Identifier name for the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gw_name" {
  description = "Name of the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 address pool for the Elastic IP"
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_a_az" {
  description = "Availability zone for Subnet A"
  type        = string
  default     = "us-east-1a"
}

variable "subnet_b_az" {
  description = "Availability zone for Subnet B"
  type        = string
  default     = "us-east-1b"
}

variable "subnet_c_az" {
  description = "Availability zone for Subnet C"
  type        = string
  default     = "us-east-1c"
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

variable "map_public_ip_on_launch" {
  description = "Whether to assign public IPs on launch in subnets"
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = var.subnet_a_az != "" ? var.subnet_a_az : data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = var.subnet_b_az != "" ? var.subnet_b_az : data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = var.subnet_c_az != "" ? var.subnet_c_az : data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat_eip" {
  domain     = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gw_name
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_security_group" "default_sg" {
  name        = "DefaultSecurityGroup"
  description = "Permits outbound egress traffic only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Egress within VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  description = "Public IP of the NAT Gateway"
  value       = aws_eip.nat_eip.public_ip
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "backup_vault_name" {
  description = "Name of the AWS Backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "backup_tag_key" {
  description = "Tag key used to select resources for backup"
  type        = string
  default     = "backup"
}

variable "resource_tags" {
  description = "Optional tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "daily_cron_schedule" {
  description = "Cron schedule for daily backups"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "daily_delete_after_days" {
  description = "Days after which daily backups are deleted"
  type        = number
  default     = 7
}

variable "daily_enable_continuous_backup" {
  description = "Enable continuous backup for daily plan"
  type        = bool
  default     = false
}

variable "weekly_cron_schedule" {
  description = "Cron schedule for weekly backups"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "weekly_delete_after_days" {
  description = "Days after which weekly backups are deleted"
  type        = number
  default     = 31
}

variable "monthly_cron_schedule" {
  description = "Cron schedule for monthly backups"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "monthly_delete_after_days" {
  description = "Days after which monthly backups are deleted"
  type        = number
  default     = 366
}

variable "enable_backup_notifications" {
  description = "Whether to enable backup vault notifications"
  type        = bool
  default     = false
}

variable "backup_notification_sns_topic_arn" {
  description = "SNS topic ARN for backup notifications"
  type        = string
  default     = ""
}

variable "backup_notification_events" {
  description = "List of backup vault events to be notified about"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

# KMS key for backup vault encryption
resource "aws_kms_key" "backup_vault_key" {
  description             = "KMS key for AWS Backup vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(
    {
      Name = "${var.backup_vault_name}-kms-key"
    },
    var.resource_tags
  )
}

resource "aws_kms_alias" "backup_vault_key_alias" {
  name          = "alias/${var.backup_vault_name}-kms-key"
  target_key_id = aws_kms_key.backup_vault_key.key_id
}

# Backup vault
resource "aws_backup_vault" "backup_vault" {
  name        = var.backup_vault_name
  kms_key_arn = aws_kms_key.backup_vault_key.arn

  tags = merge(
    {
      Name = var.backup_vault_name
    },
    var.resource_tags
  )
}

# IAM role for AWS Backup
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "${var.backup_vault_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = var.resource_tags
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Daily backup plan
resource "aws_backup_plan" "daily" {
  name = "${var.backup_vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.backup_vault.name
    schedule                 = var.daily_cron_schedule
    enable_continuous_backup = var.daily_enable_continuous_backup

    lifecycle {
      delete_after_days = var.daily_delete_after_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup_policy]
}

resource "aws_backup_selection" "daily" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id

  selection_tag {
    type  = "STRINGLIKE"
    key   = var.backup_tag_key
    value = "daily*"
  }
}

# Weekly backup plan
resource "aws_backup_plan" "weekly" {
  name = "${var.backup_vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = var.weekly_cron_schedule

    lifecycle {
      delete_after_days = var.weekly_delete_after_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup_policy]
}

resource "aws_backup_selection" "weekly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id

  selection_tag {
    type  = "STRINGLIKE"
    key   = var.backup_tag_key
    value = "weekly*"
  }
}

# Monthly backup plan
resource "aws_backup_plan" "monthly" {
  name = "${var.backup_vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = var.monthly_cron_schedule

    lifecycle {
      delete_after_days = var.monthly_delete_after_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup_policy]
}

resource "aws_backup_selection" "monthly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id

  selection_tag {
    type  = "STRINGLIKE"
    key   = var.backup_tag_key
    value = "monthly*"
  }
}

# Optional backup vault notifications
resource "aws_backup_vault_notifications" "notifications" {
  count = var.enable_backup_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.backup_vault.name
  sns_topic_arn       = var.backup_notification_sns_topic_arn
  backup_vault_events = var.backup_notification_events
}

output "backup_vault_arn" {
  description = "ARN of the backup vault"
  value       = aws_backup_vault.backup_vault.arn
}

output "backup_vault_kms_key_arn" {
  description = "ARN of the KMS key used for vault encryption"
  value       = aws_kms_key.backup_vault_key.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup"
  value       = aws_iam_role.backup_role.arn
}

output "daily_backup_plan_arn" {
  description = "ARN of the daily backup plan"
  value       = aws_backup_plan.daily.arn
}

output "weekly_backup_plan_arn" {
  description = "ARN of the weekly backup plan"
  value       = aws_backup_plan.weekly.arn
}

output "monthly_backup_plan_arn" {
  description = "ARN of the monthly backup plan"
  value       = aws_backup_plan.monthly.arn
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.common_tags,
    {
      Name    = "${var.env}-vpc"
      Region  = var.region
      "env"   = var.env
    }
  )
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index}"
    }
  )
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index}"
    }
  )
}

resource "aws_nat_gateway" "this" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.this[*].id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_eks" {
  description = "Whether to create the EKS cluster"
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version of the EKS cluster"
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster"
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "control_plane_subnet_ids" {
  description = "List of subnet IDs for the EKS control plane"
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "Fallback list of subnet IDs for the EKS cluster"
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name                                   = var.cluster_name
  version                                = var.cluster_version
  role_arn                               = aws_iam_role.eks_cluster.arn
  bootstrap_cluster_creator_admin_permissions = true

  access_config {
    authentication_mode = var.authentication_mode
  }

  vpc_config {
    subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]
}

