terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  users = {
    dev  = "DevUser-rwwise.dev"
    test = "TestUser-rwwise.dev"
    prod = "ProdUser-rwwise.dev"
  }

  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    Account    = data.aws_caller_identity.current.account_id
    User       = data.aws_caller_identity.current.user_id
  }

  cicd_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCodeCommitCloudWatchReadOnly"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGet*",
          "codebuild:List*",
          "codebuild:Describe*",
          "codecommit:BatchGet*",
          "codecommit:Get*",
          "codecommit:List*",
          "codecommit:Describe*",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
          "cloudwatch:DescribeAlarms",
          "events:DescribeRule",
          "events:ListRules",
          "events:ListTargetsByRule",
          "logs:GetLogEvents",
          "logs:FilterLogEvents",
          "logs:DescribeLogStreams",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      },
      {
        Sid      = "CodeStarConnectionsUserAccess"
        Effect   = "Allow"
        Action   = ["codestar-connections:GetConnection", "codestar-connections:ListConnections"]
        Resource = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid      = "CodeStarNotificationsPowerUserAccess"
        Effect   = "Allow"
        Action   = ["codestar-notifications:DescribeRule"]
        Resource = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid    = "CodeStarNotificationsListAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:ListRule",
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user" "cicd" {
  for_each = local.users

  name = each.value
  path = "/system/"

  tags = merge(local.common_tags, {
    Environment = each.key
  })
}

resource "aws_iam_access_key" "cicd" {
  for_each = local.users
  user     = aws_iam_user.cicd[each.key].name
}

resource "aws_iam_user_policy" "cicd" {
  for_each = local.users
  name     = "${each.key}_cicd_user_policy"
  user     = aws_iam_user.cicd[each.key].name

  policy = local.cicd_policy
}

output "access_key_ids" {
  value = { for k, v in aws_iam_access_key.cicd : k => v.id }
}

output "secret_access_keys" {
  value     = { for k, v in aws_iam_access_key.cicd : k => v.secret }
  sensitive = true
}
