terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  description = "Name of the module. Defaults to 'default' if null or empty."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Event bus configuration. Supports optional event_source_name."
  type        = map(string)
  default     = {}

  validation {
    condition     = var.bus != null
    error_message = "The bus variable must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create."
  type = list(object({
    name                = string
    description         = optional(string)
    event_pattern       = optional(string)
    schedule_expression = optional(string)
  }))
  default = []

  validation {
    condition     = var.rules != null
    error_message = "The rules variable must not be null."
  }
}

variable "targets" {
  description = "List of EventBridge targets to create."
  type = list(object({
    name = string
    rule = string
    arn  = string
  }))
  default = []

  validation {
    condition     = var.targets != null
    error_message = "The targets variable must not be null."
  }
}

locals {
  module_name = coalesce(var.name != null && trimspace(var.name) != "" ? var.name : null, "default")
  create_bus  = local.module_name != "default"
  bus_name    = local.create_bus ? local.module_name : "default"
}

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_bus ? 1 : 0

  name = local.module_name
  tags = var.tags
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for r in var.rules : r.name => r }

  name                = each.key
  description         = try(each.value.description, null)
  event_pattern       = try(each.value.event_pattern, null)
  schedule_expression = try(each.value.schedule_expression, null)
  event_bus_name      = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
  tags                = var.tags
}

data "aws_iam_policy_document" "assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

data "aws_partition" "current" {}

resource "aws_iam_role" "invoke" {
  name               = "${local.module_name}-invoke"
  assume_role_policy = data.aws_iam_policy_document.assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.module_name}-invoke-targets"
  role = aws_iam_role.invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction", "states:StartExecution"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for t in var.targets : t.name => t }

  name          = each.key
  rule          = each.value.rule
  arn           = each.value.arn
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
  role_arn      = strcontains(each.value.arn, "stateMachine") ? aws_iam_role.invoke.arn : null

  depends_on = [aws_cloudwatch_event_rule.this]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  description = "Name used to build resource names"
  type        = string
  default     = "example"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for the backup vault"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON access policy document for the vault"
  type        = string
  default     = ""
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for vault notifications"
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "Backup vault events to subscribe to"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule" {
  description = "Cron schedule for the backup rule"
  type        = string
  default     = "cron(0 12 * * ? *)"
}

variable "start_window" {
  description = "Start window in minutes"
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Completion window in minutes"
  type        = number
  default     = 120
}

variable "cold_storage_after" {
  description = "Days before transition to cold storage"
  type        = number
  default     = 30
}

variable "delete_after" {
  description = "Days before deletion"
  type        = number
  default     = 120
}

variable "copy_action_vaults" {
  description = "Map of copy action names to destination vault ARNs"
  type        = map(string)
  default     = {}
}

variable "selection_tag_operation" {
  description = "Tag condition operation"
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "Tag key for selection"
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value for selection"
  type        = string
  default     = "true"
}

locals {
  job_tag = "${var.name}-backup"
}

# IAM role for AWS Backup
data "aws_iam_policy_document" "backup_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "aws-backup-${var.name}"
  assume_role_policy = data.aws_iam_policy_document.backup_assume.json

  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup vault
resource "aws_backup_vault" "this" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_vault_policy" "this" {
  count          = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.this.name
  policy         = var.vault_policy
}

resource "aws_backup_vault_notifications" "this" {
  count              = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name  = aws_backup_vault.this.name
  sns_topic_arn      = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

# Backup plan
resource "aws_backup_plan" "this" {
  name = "plan-${var.name}-backup"

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.copy_action_vaults
      content {
        destination_vault_arn = copy_action.value
      }
    }

    recovery_point_tags = {
      Job = local.job_tag
    }
  }

  tags = {
    Job = local.job_tag
  }
}

# Backup selection
resource "aws_backup_selection" "this" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "selection-${var.name}-backup"
  plan_id      = aws_backup_plan.this.id

  condition {
    string_equals {
      key   = var.selection_tag_key
      value = var.selection_tag_value
    }
  }

  selection_tag {
    type = var.selection_tag_operation
    key  = var.selection_tag_key
    value = var.selection_tag_value
  }
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources in."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the Transit Gateway (and fallback names)."
  type        = string
  default     = "central-hub-tgw"
}

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create = false."
  type        = string
  default     = null
}

variable "filter_by_name" {
  description = "Name tag of an existing Transit Gateway to look up when create = false and id is null."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachments are automatically accepted."
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "Whether DNS support is enabled."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether VPN ECMP support is enabled."
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4/IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks :
      can(cidrhost(cidr, 0)) || can(cidrnetmask(cidr))
    ])
    error_message = "All transit_gateway_cidr_blocks entries must be valid IPv4 or IPv6 CIDRs."
  }
}

variable "tags" {
  description = "Global tags applied to all resources."
  type        = map(string)
  default     = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables. Key = name. Set create=false to look up existing."
  type = map(object({
    create    = optional(bool, true)
    tags      = optional(map(string), {})
    local_tags = optional(map(string), {})
  }))
  default = {
    "main" = {
      create     = true
      tags       = {}
      local_tags = {}
    }
  }
}

variable "shared_principals" {
  description = "Map of principals to share the Transit Gateway with via RAM. Key = principal identifier."
  type = map(object({
    type = optional(string, "ACCOUNT")
  }))
  default = {}
}

variable "ram_resource_share_name" {
  description = "Name of the RAM resource share. Falls back to the main resource name."
  type        = string
  default     = null
}

variable "ram_allow_external_principals" {
  description = "Whether the RAM share permits external principals."
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# Transit Gateway: create or look up
# -----------------------------------------------------------------------------
resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                     = var.name
  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, {
    Name = var.name
  })
}

data "aws_ec2_transit_gateway" "existing" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null && var.filter_by_name != null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.filter_by_name]
    }
  }
}

locals {
  transit_gateway_id = var.create ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? var.id : data.aws_ec2_transit_gateway.existing[0].id
  )
  ram_share_name = coalesce(var.ram_resource_share_name, var.name)
}

# -----------------------------------------------------------------------------
# Transit Gateway Route Tables: create or look up
# -----------------------------------------------------------------------------
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    each.value.tags,
    each.value.local_tags,
    {
      Name = try(each.value.tags["Name"], each.value.local_tags["Name"], each.key, var.name)
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  transit_gateway_id = local.transit_gateway_id

  filter {
    name   = "tag:Name"
    values = [each.key]
  }
}

locals {
  route_table_ids = merge(
    { for k, rt in aws_ec2_transit_gateway_route_table.this : k => rt.id },
    { for k, rt in data.aws_ec2_transit_gateway_route_table.existing : k => rt.id }
  )
}

# -----------------------------------------------------------------------------
# RAM Resource Share (only if shared_principals is non-empty)
# -----------------------------------------------------------------------------
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = var.ram_allow_external_principals

  tags = merge(var.tags, {
    Name = local.ram_share_name
  })
}

resource "aws_ram_resource_association" "tgw" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.existing[0].arn
  resource_share_arn = aws_ram_resource_share.this[0].id
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  resource_share_arn = aws_ram_resource_share.this[0].id
  principal          = each.key
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Shared KMS key for all backup vaults
resource "aws_kms_key" "backup_key" {
  description             = "Shared KMS key for tiered backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/backup-vault-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

# IAM role for AWS Backup
resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ---------------- Bronze Tier ----------------
resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

# ---------------- Silver Tier ----------------
resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

# ---------------- Gold Tier ----------------
resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

# ---------------- Premium Tier ----------------
resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}
