terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Module: s3_bucket
# ---------------------------------------------------------------------------
module "s3_bucket" {
  source = "./modules/s3_bucket"

  bucket_name          = null
  prefix               = false
  request_payer        = "BucketOwner"
  encryption           = true
  kms_key              = ""
  versioning           = false
  mfa_delete           = false
  force_destroy        = false
  acl                  = "private"
  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
  transfer_acceleration = false

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  cors_rule {
    allowed_methods = ["GET", "HEAD"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }

  lifecycle_rule {
    id     = "expire-old-objects"
    status = "Enabled"
    expiration {
      days = 365
    }
    noncurrent_version_expiration {
      days = 90
    }
  }

  object_lock_configuration {
    object_lock_enabled = true
    rule {
      default_retention {
        mode = "COMPLIANCE"
        days = 30
      }
    }
  }

  replication_rules = [
    {
      id     = "replicate-all"
      status = "Enabled"
      filter = {}
      destination = {
        bucket        = "arn:aws:s3:::corebucket-destination-example"
        storage_class = "STANDARD"
      }
    }
  ]
  # replication_role = "" # leave unset to auto-create IAM role
}

output "bucket_id" {
  value = module.s3_bucket.bucket_id
}

output "bucket_arn" {
  value = module.s3_bucket.bucket_arn
}

output "bucket_regional_domain_name" {
  value = module.s3_bucket.bucket_regional_domain_name
}

output "kms_key_arn" {
  value = module.s3_bucket.kms_key_arn
}

output "replication_role_arn" {
  value = module.s3_bucket.replication_role_arn
}

output "website_endpoint" {
  value = module.s3_bucket.website_endpoint
}
```

```hcl
# modules/s3_bucket/variables.tf
variable "bucket_name" {
  description = "Optional bucket name. Falls back to corebucket-<random4hex>."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, append an extra random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Who pays for requests: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Enable SSE encryption (always aws:kms when true)."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "Optional external KMS key ARN. If empty, module creates its own rotating KMS key."
  type        = string
  default     = ""
}

variable "versioning" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "mfa" {
  description = "MFA device ARN and code, required when mfa_delete is true."
  type        = string
  default     = null
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "acl" {
  type    = string
  default = "private"
}

variable "policy" {
  description = "Optional JSON bucket policy document."
  type        = string
  default     = null
}

variable "grants" {
  description = "Optional list of ACL grants."
  type = list(object({
    type        = string
    id          = optional(string)
    uri         = optional(string)
    permissions = list(string)
  }))
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "transfer_acceleration" {
  type    = bool
  default = false
}

variable "logging" {
  description = "Optional logging target."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "website" {
  description = "Website configuration: index/error docs or redirect_all_requests."
  type = object({
    index_document       = optional(string)
    error_document       = optional(string)
    redirect_all_requests_to = optional(object({
      host_name = string
      protocol  = optional(string)
    }))
    routing_rules = optional(string)
  })
  default = null
}

variable "cors_rule" {
  description = "List of CORS rules."
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string))
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rules."
  type = list(object({
    id     = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    expiration = optional(object({
      days = optional(number)
      date = optional(string)
    }))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Optional object lock configuration."
  type = object({
    object_lock_enabled = optional(bool, true)
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

variable "replication_rules" {
  description = "Optional replication configuration rules."
  type = list(object({
    id     = optional(string)
    status = string
    filter = optional(map(any), {})
    destination = object({
      bucket        = string
      storage_class = optional(string)
      account_id    = optional(string)
    })
  }))
  default = []
}

variable "replication_role" {
  description = "Optional external IAM role ARN for replication. If empty, module creates one."
  type        = string
  default     = ""
}
```

```hcl
# modules/s3_bucket/main.tf
locals {
  base_name = coalesce(var.bucket_name, "corebucket-${random_id.suffix.hex}")
  resolved_name = var.prefix ? "${local.base_name}-${random_id.extra_suffix.hex}" : local.base_name

  kms_key_arn = var.encryption ? (var.kms_key != "" ? var.kms_key : aws_kms_key.this[0].arn) : ""
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_id" "extra_suffix" {
  byte_length = 4
}

# Rotating customer-managed KMS key when none supplied
resource "aws_kms_key" "this" {
  count                   = var.encryption && var.kms_key == "" ? 1 : 0
  description             = "KMS key for bucket ${local.resolved_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_s3_bucket" "this" {
  bucket        = local.resolved_name
  force_destroy = var.force_destroy

  tags = var.tags
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.versioning || var.mfa_delete ? 1 : 0

  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count   = var.transfer_acceleration ? 1 : 0
  bucket  = aws_s3_bucket.this.id
  status  = "Enabled"
}

resource "aws_s3_bucket_acl" "this" {
  count  = length(var.grants) == 0 && var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_acl" "grants" {
  count  = length(var.grants) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "grant" {
    for_each = var.grants
    content {
      type        = grant.value.type
      id          = try(grant.value.id, null)
      uri         = try(grant.value.uri, null)
      permissions = grant.value.permissions
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : [], [])
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "index_document" {
    for_each = try(var.website.redirect_all_requests_to == null && var.website.index_document != null ? [var.website.index_document] : [], [])
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.redirect_all_requests_to == null && var.website.error_document != null ? [var.website.error_document] : [], [])
    content {
      key = error_document.value
    }
  }

  dynamic "routing_rules" {
    for_each = try(var.website.routing_rules != null ? [var.website.routing_rules] : [], [])
    content {
      dynamic "condition" {
        for_each = [jsondecode(routing_rules.value)[0]["Condition"]]
        content {
          key_prefix_equals = try(condition.value["KeyPrefixEquals"], null)
        }
      }
      dynamic "redirect" {
        for_each = [jsondecode(routing_rules.value)[0]["Redirect"]]
        content {
          replace_key_prefix_with = try(redirect.value["ReplaceKeyPrefixWith"], null)
          http_redirect_code      = try(redirect.value["HttpRedirectCode"], null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = try(rule.value.filter != null ? [rule.value.filter] : [], [])
        content {
          prefix = try(filter.value.prefix, null)
          dynamic "tag" {
            for_each = try(filter.value.tags != null ? filter.value.tags : {}, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition != null ? rule.value.transition : [], [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration != null ? [rule.value.expiration] : [], [])
        content {
          days = try(expiration.value.days, null)
          date = try(expiration.value.date, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : [], [])
        content {
          days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : [], [])
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    dynamic "default_retention" {
      for_each = try(var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule.default_retention] : [], [])
      content {
        mode  = default_retention.value.mode
        days  = try(default_retention.value.days, null)
        years = try(default_retention.value.years, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ---------------------------------------------------------------------------
# Replication
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  count  = length(var.replication_rules) > 0 && var.replication_role == "" ? 1 : 0
  name   = "CoreS3ReplicationRole_${local.resolved_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role == "" ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.resolved_name}"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectRetention",
          "s3:GetObjectLegalHold"
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = [for r in var.replication_rules : "${r.destination.bucket}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  # Replication requires versioning on source and destination
  depends_on = [aws_s3_bucket_versioning.this]

  role = var.replication_role != "" ? var.replication_role : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id     = try(rule.value.id, null)
      status = rule.value.status

      dynamic "filter" {
        for_each = [rule.value.filter]
        content {
          prefix = try(filter.value["prefix"], null)
          dynamic "tag" {
            for_each = try(filter.value["tags"] != null ? filter.value["tags"] : {}, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account_id    = try(rule.value.destination.account_id, null)

        dynamic "encryption_configuration" {
          for_each = local.kms_key_arn != "" ? [1] : []
          content {
            replica_kms_key_id = local.kms_key_arn
          }
        }
      }
    }
  }
}
```

