terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "suffix_length" {
  description = "Length of the random suffix"
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name of the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name" {
  description = "Base name of the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name of the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload the image file to S3"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local image file to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "S3 folder prefix for the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prefix the S3 key with the folder"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user and related resources"
  type        = bool
  default     = true
}

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.suffix_length
  special = false
  upper   = false
}

locals {
  suffix          = var.random_suffix ? random_string.suffix[0].result : ""
  bucket_name     = "${var.bucket_name}${local.suffix}"
  iam_user_name   = "${var.iam_user_name}${local.suffix}"
  iam_policy_name = "${var.iam_policy_name}${local.suffix}"
  s3_key          = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_kms_key" "bucket_key" {
  description             = "KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "image_bucket" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "image_bucket_encryption" {
  bucket = aws_s3_bucket.image_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.bucket_key.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "image_bucket_pab" {
  bucket = aws_s3_bucket.image_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "image" {
  count  = var.upload_image ? 1 : 0
  bucket = aws_s3_bucket.image_bucket.id
  key    = local.s3_key
  source = var.image_filename

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.image_bucket_encryption]
}

resource "aws_iam_user" "s3_user" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.iam_user_name
  path          = "/"
  force_destroy = true
}

resource "aws_iam_access_key" "s3_user_key" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_user[0].name
}

resource "aws_iam_policy" "s3_read_policy" {
  count  = var.create_iam_user ? 1 : 0
  name   = local.iam_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowReadBucketObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.image_bucket.arn}/*"
      },
      {
        Sid      = "AllowListBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.image_bucket.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "s3_user_policy" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_user[0].name
  policy_arn = aws_iam_policy.s3_read_policy[0].arn
}

output "bucket_name" {
  value = aws_s3_bucket.image_bucket.id
}

output "kms_key_arn" {
  value = aws_kms_key.bucket_key.arn
}

output "iam_user_name" {
  value = var.create_iam_user ? aws_iam_user.s3_user[0].name : null
}

output "iam_access_key_id" {
  value = var.create_iam_user ? aws_iam_access_key.s3_user_key[0].id : null
}

output "iam_access_key_secret" {
  value     = var.create_iam_user ? aws_iam_access_key.s3_user_key[0].secret : null
  sensitive = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "tf-eks-jofo"
      Owner       = "Jovan Zelincevic"
      Compliance  = "Nothing"
      Environment = "dev"
      Provider    = "Terraform"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.14.0.0/16"
}

locals {
  project     = "tf-eks-jofo"
  environment = "dev"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.project}-${local.environment}-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.project}-${local.environment}-igw"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.project}-${local.environment}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index + 3)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.project}-${local.environment}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.project}-${local.environment}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.project}-${local.environment}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.project}-${local.environment}-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.project}-${local.environment}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. Conflicts with bucket_prefix."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for the bucket name. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "acceleration_status" {
  description = "Sets acceleration status of the bucket. Valid values: Enabled, Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who pays for the request. Valid values: BucketOwner, Requester."
  type        = string
  default     = null
}

variable "control_object_ownership" {
  type    = bool
  default = true
}

variable "object_ownership" {
  type    = string
  default = "ObjectWriter"
}

variable "website" {
  description = "Map of static website hosting configuration"
  type        = any
  default     = null
}

variable "cors_rule" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map of versioning configuration (enabled, mfa_delete)"
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map of access logging configuration (target_bucket, target_prefix)"
  type        = map(string)
  default     = {}
}

variable "grant" {
  description = "List of ACL policy grant maps"
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map of cross-region replication configuration"
  type        = any
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Map of server-side encryption configuration. If null, a customer-managed KMS key is created."
  type        = any
  default     = null
}

variable "object_lock_configuration" {
  description = "Map of object lock configuration"
  type        = any
  default     = null
}

variable "attach_elb_log_delivery_policy" {
  type    = bool
  default = false
}

variable "attach_lb_log_delivery_policy" {
  type    = bool
  default = false
}

variable "attach_deny_insecure_transport_policy" {
  type    = bool
  default = false
}

variable "attach_policy" {
  type    = bool
  default = false
}

variable "policy" {
  description = "Custom policy document (JSON string) to attach"
  type        = string
  default     = null
}

variable "attach_public_policy" {
  type    = bool
  default = true
}

variable "block_public_acls" {
  type    = bool
  default = true
}

variable "block_public_policy" {
  type    = bool
  default = true
}

variable "ignore_public_acls" {
  type    = bool
  default = true
}

variable "restrict_public_buckets" {
  type    = bool
  default = true
}

variable "kms_key_deletion_window_in_days" {
  type    = number
  default = 7
}

variable "expected_bucket_owner" {
  type    = string
  default = null
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  create_bucket = var.create_bucket
  bucket_name   = var.bucket != null ? var.bucket : (var.bucket_prefix != null ? null : null)
  account_id    = data.aws_caller_identity.current.account_id
  partition     = data.aws_partition.current.partition
  region        = data.aws_region.current.name
}

# -----------------------------------------------------------------------------
# KMS key (created only when no SSE configuration is supplied)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count                           = local.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0
  description                     = "Customer-managed KMS key for S3 bucket ${coalesce(var.bucket, var.bucket_prefix, "default")}"
  deletion_window_in_days         = var.kms_key_deletion_window_in_days
  enable_key_rotation             = true
}

resource "aws_kms_alias" "this" {
  count         = local.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0
  name          = "alias/s3-${coalesce(var.bucket, var.bucket_prefix, "default")}"
  target_key_id = aws_kms_key.this[0].key_id
}

# -----------------------------------------------------------------------------
# S3 bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix

  acl           = var.acl
  force_destroy = var.force_destroy

  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer

  tags = var.tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try([var.website["index_document"]], [])
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website["error_document"]], [])
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try([var.website["redirect_all_requests_to"]], [])
    content {
      host_name = redirect_all_requests_to.value["host_name"]
      protocol  = try(redirect_all_requests_to.value["protocol"], null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website["routing_rules"], [])
    content {
      dynamic "condition" {
        for_each = try([routing_rule.value["condition"]], [])
        content {
          http_error_code_returned_equals = try(condition.value["http_error_code_returned_equals"], null)
          key_prefix_equals               = try(condition.value["key_prefix_equals"], null)
        }
      }
      dynamic "redirect" {
        for_each = try([routing_rule.value["redirect"]], [])
        content {
          host_name               = try(redirect.value["host_name"], null)
          http_redirect_code      = try(redirect.value["http_redirect_code"], null)
          protocol                = try(redirect.value["protocol"], null)
          replace_key_prefix_with = try(redirect.value["replace_key_prefix_with"], null)
          replace_key_with        = try(redirect.value["replace_key_with"], null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = try(cors_rule.value["id"], null)
      allowed_methods = cors_rule.value["allowed_methods"]
      allowed_origins = cors_rule.value["allowed_origins"]
      allowed_headers = try(cors_rule.value["allowed_headers"], null)
      expose_headers  = try(cors_rule.value["expose_headers"], null)
      max_age_seconds = try(cors_rule.value["max_age_seconds"], null)
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(var.versioning) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning["enabled"], false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning["mfa_delete"], null)
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(var.logging) > 0 ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = var.logging["target_bucket"]
  target_prefix = try(var.logging["target_prefix"], null)
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket && length(var.grant) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "grant" {
    for_each = var.grant
    content {
      permissions = grant.value["permissions"]
      type        = grant.value["type"]
      id          = try(grant.value["id"], null)
      uri         = try(grant.value["uri"], null)
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = try(rule.value["id"], null)
      status = try(rule.value["enabled"], true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = try([rule.value["filter"]], [])
        content {
          prefix = try(filter.value["prefix"], null)
          dynamic "tag" {
            for_each = try(filter.value["tags"], {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try([rule.value["expiration"]], [])
        content {
          date                         = try(expiration.value["date"], null)
          days                         = try(expiration.value["days"], null)
          expired_object_delete_marker = try(expiration.value["expired_object_delete_marker"], null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try([rule.value["noncurrent_version_expiration"]], [])
        content {
          noncurrent_days = try(noncurrent_version_expiration.value["noncurrent_days"], null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try([rule.value["abort_incomplete_multipart_upload"]], [])
        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value["days_after_initiation"], null)
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Cross-region replication
# -----------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  count = local.create_bucket && var.replication_configuration != null ? 1 : 0

  name = "${coalesce(var.bucket, var.bucket_prefix, "s3-replication")}-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_bucket && var.replication_configuration != null ? 1 : 0

  name = "${coalesce(var.bucket, var.bucket_prefix, "s3-replication")}-replication"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.this[0].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = ["${aws_s3_bucket.this[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          for rule in try(var.replication_configuration["rules"], []) : rule["destination"]["bucket_arn"]
        ]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id     = try(rule.value["id"], null)
      status = try(rule.value["status"], "Enabled")

      filter {
        prefix = try(rule.value["filter"]["prefix"], null)
      }

      delete_marker_replication {
        status = try(rule.value["delete_marker_replication_status"], "Disabled")
      }

      destination {
        bucket        = rule.value["destination"]["bucket_arn"]
        storage_class = try(rule.value["destination"]["storage_class"], null)

        dynamic "replication_time" {
          for_each = try([rule.value["destination"]["replication_time"]], [])
          content {
            status  = replication_time.value["status"]
            minutes = replication_time.value["minutes"]
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Server-side encryption
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.server_side_encryption_configuration != null ? [var.server_side_encryption_configuration] : [{}]
    content {
      bucket_key_enabled = try(rule.value["bucket_key_enabled"], null)

      dynamic "apply_server_side_encryption_by_default" {
        for_each = var.server_side_encryption_configuration != null ? [try(rule.value["apply_server_side_encryption_by_default"], {})] : [{}]
        content {
          sse_algorithm     = var.server_side_encryption_configuration != null ? try(apply_server_side_encryption_by_default.value["sse_algorithm"], "AES256") : "aws:kms"
          kms_master_key_id = var.server_side_encryption_configuration != null ? try(apply_server_side_encryption_by_default.value["kms_master_key_id"], null) : aws_kms_key.this[0].arn
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Object lock
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration["rule"]["default_retention"]["mode"]
      days  = try(var.object_lock_configuration["rule"]["default_retention"]["days"], null)
      years = try(var.object_lock_configuration["rule"]["default_retention"]["years"], null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Bucket policy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "combined" {
  count = local.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy) ? 1 : 0

  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid       = "ELBLogDelivery"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "Service"
        identifiers = ["elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "LBLogDeliveryToBucket"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${local.account_id}/*"]

      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "LBLogDeliveryAclCheck"
      effect    = "Allow"
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.this[0].arn]

      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid     = "DenyInsecureTransport"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }

      principals {
        type        = "*"
        identifiers = ["*"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_policy && var.policy != null ? [1] : []
    content {
      sid       = "CustomPolicy"
      effect    = "Allow"
      actions   = ["s3:GetObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "AWS"
        identifiers = [local.account_id]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = local.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = var.attach_policy && var.policy != null ? var.policy : data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket && var.attach_public_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

output "bucket_id" {
  value = try(aws_s3_bucket.this[0].id, null)
}

output "bucket_arn" {
  value = try(aws_s3_bucket.this[0].arn, null)
}

output "kms_key_arn" {
  value = try(aws_kms_key.this[0].arn, null)
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion
}

variable "projectPrefix" {
  type    = string
  default = "f5-dcec"
}

variable "resourceOwner" {
  type    = string
  default = "f5-user"
}

variable "buildSuffix" {
  type    = string
  default = "YY"
}

variable "awsRegion" {
  type    = string
  default = "us-east-1"
}

variable "awsAz1" {
  type    = string
  default = null
}

variable "awsAz2" {
  type    = string
  default = null
}

variable "map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "vpcMainCidr" {
  type    = string
  default = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  type    = string
  default = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  type    = string
  default = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  type    = string
  default = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  type    = string
  default = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  type    = string
  default = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  type    = string
  default = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(var.awsAz2, try(coalesce(var.awsAz1, data.aws_availability_zones.available.names[1]), data.aws_availability_zones.available.names[1]))

  common_tags = {
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-main-${var.buildSuffix}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-main-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-pub-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-pub-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-priv-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-priv-b-${var.buildSuffix}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "az1" {
  value = local.az1
}

output "az2" {
  value = local.az2
}

output "subnet_ids" {
  value = {
    public_a  = aws_subnet.public_a.id
    public_b  = aws_subnet.public_b.id
    mgmt_a    = aws_subnet.mgmt_a.id
    mgmt_b    = aws_subnet.mgmt_b.id
    private_a = aws_subnet.private_a.id
    private_b = aws_subnet.private_b.id
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "resource_name" {
  description = "Name prefix for all resources"
  type        = string
  default     = "benchmark"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create"
  type        = number
  default     = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "benchmark" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_subnet" "benchmark" {
  count                   = 2
  vpc_id                  = aws_vpc.benchmark.id
  cidr_block              = cidrsubnet(aws_vpc.benchmark.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.resource_name}-subnet-${count.index}"
  }
}

resource "aws_security_group" "benchmark" {
  name        = var.resource_name
  description = "Allow all traffic within the VPC"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "All traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = {
    Name = var.resource_name
  }
}

resource "tls_private_key" "benchmark" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "benchmark" {
  private_key_pem = tls_private_key.benchmark.private_key_pem

  subject {
    common_name  = "${var.resource_name}.internal"
    organization = "TerraformAI"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "benchmark" {
  private_key      = tls_private_key.benchmark.private_key_pem
  certificate_body = tls_self_signed_cert.benchmark.cert_pem

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_target_group" "benchmark" {
  name     = var.resource_name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.benchmark.id

  health_check {
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb" "benchmark" {
  name                       = var.resource_name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.benchmark.id]
  subnets                    = aws_subnet.benchmark[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_listener" "benchmark" {
  load_balancer_arn = aws_lb.benchmark.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "TLS13"
  certificate_arn   = aws_acm_certificate.benchmark.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_listener_rule" "benchmark" {
  count        = var.listener_rule_count
  listener_arn = aws_lb_listener.benchmark.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.resource_name}-rule-${count.index}"
  }
}

output "alb_dns_name" {
  value = aws_lb.benchmark.dns_name
}

output "vpc_id" {
  value = aws_vpc.benchmark.id
}

output "target_group_arn" {
  value = aws_lb_target_group.benchmark.arn
}

provider "aws" {
  region = "us-east-1"
}

variable "trail_name" {
  default = "management_trail"
}

variable "is_organization_trail" {
  type    = bool
  default = false
}

variable "log_group_name" {
  default = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  type    = bool
  default = true
}

variable "kms_key_alias" {
  default = "alias/cloudtrail_key"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 6
  keepers = {
    regenerate = timestamp()
  }
}

locals {
  bucket_name = "cloudtrail-bucket-${random_id.bucket_suffix.hex}"
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
}

resource "aws_kms_key" "cloudtrail" {
  count                   = var.enable_kms_encryption ? 1 : 0
  description             = "KMS key for CloudTrail and log bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAdminPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCallerIdentityAdministration"
        Effect    = "Allow"
        Principal = { AWS = data.aws_caller_identity.current.arn }
        Action = [
          "kms:CreateKey",
          "kms:DescribeKey",
          "kms:ListKeys",
          "kms:ListAliases",
          "kms:TagResource",
          "kms:PutKeyPolicy",
          "kms:GetKeyPolicy",
          "kms:EnableKeyRotation",
          "kms:ScheduleKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudTrailGenerateDataKeys"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${local.partition}:trail/${var.trail_name}"
          }
        }
      },
      {
        Sid       = "AllowS3UseOfKeyForBucketEncryption"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowAccountDecryptLogs"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action = [
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail" {
  count         = var.enable_kms_encryption ? 1 : 0
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket                  = aws_s3_bucket.cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailAclCheck"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.cloudtrail.arn
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = "arn:${local.partition}:trail/${var.trail_name}"
          }
        }
      },
      {
        Sid       = "AWSCloudTrailWrite"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"      = "bucket-owner-full-control"
            "AWS:SourceArn"     = "arn:${local.partition}:trail/${var.trail_name}"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "cloudtrail_cw" {
  name = "CloudTrailRoleForCloudWatchLogs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cw" {
  name = "allow-access-to-cw-logs"
  role = aws_iam_role.cloudtrail_cw.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.log_group_name
  retention_in_days = 0
}

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cw.arn
  kms_key_id                    = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  advanced_event_selector {
    name = "Management events"
    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }
    field_selector {
      field  = "readOnly"
      equals = ["true", "false"]
    }
  }

  depends_on = [aws_s3_bucket_policy.cloudtrail]
}

