terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  description = "Optional namespace for the repository name"
  type        = string
  default     = ""
}

variable "repository_name" {
  description = "Repository name; petname generated if null or empty"
  type        = string
  default     = "ecr"
}

variable "image_tag_mutability" {
  description = "Image tag mutability setting"
  type        = string
  default     = "IMMUTABLE"
}

variable "image_scan_on_push" {
  description = "Scan images on push"
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "Optional lifecycle policy JSON string"
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "Additional AWS account IDs allowed read access"
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

# Frigga-style petname generation when name is null or empty
resource "random_pet" "repo" {
  count = var.repository_name == null || var.repository_name == "" ? 1 : 0
}

locals {
  generated_name = var.repository_name == null || var.repository_name == "" ? random_pet.repo[0].id : var.repository_name
  name           = var.namespace == null || var.namespace == "" ? local.generated_name : "${var.namespace}/${local.generated_name}"
}

resource "aws_ecr_repository" "this" {
  name                 = local.name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.image_scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.name
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy == null ? 0 : 1
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "read" {
  statement {
    sid       = "ECRRead"
    effect    = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "read" {
  name   = "${local.name}-ecr-read"
  policy = data.aws_iam_policy_document.read.json
}

data "aws_iam_policy_document" "write" {
  statement {
    sid       = "ECRWrite"
    effect    = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload",
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "write" {
  name   = "${local.name}-ecr-write"
  policy = data.aws_iam_policy_document.write.json
}

data "aws_iam_policy_document" "repo" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = concat(["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"], [for acct in var.trusted_accounts : "arn:aws:iam::${acct}:root"])
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repo.json
}

output "repository_arn" {
  value = aws_ecr_repository.this.arn
}

output "repository_url" {
  value = aws_ecr_repository.this.repository_url
}

output "repository_name" {
  value = local.name
}
