terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 2
}

variable "enable_public_subnets" {
  description = "Enable public subnet tier"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Enable NAT subnet tier"
  type        = bool
  default     = false
}

variable "enable_private_subnets" {
  description = "Enable private subnet tier"
  type        = bool
  default     = false
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.availability_zone_count)

  public_enabled  = var.enable_public_subnets ? 1 : 0
  nat_enabled     = var.enable_nat_subnets ? 1 : 0
  private_enabled = var.enable_private_subnets ? 1 : 0

  total_subnets = (local.public_enabled + local.nat_enabled + local.private_enabled) * var.availability_zone_count

  # Bitwise log-based splitting: newbits = ceil(log2(total_subnets)), min 1
  newbits = max(ceil(log(local.total_subnets, 2)), 1)

  public_offset  = 0
  nat_offset     = local.public_enabled * var.availability_zone_count
  private_offset = (local.public_enabled + local.nat_enabled) * var.availability_zone_count
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dynamic-multi-tier-vpc"
  }
}

# ---------------- Public Tier ----------------

resource "aws_internet_gateway" "main" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dynamic-igw"
  }
}

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.public_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
    Tier = "public"
  }
}

resource "aws_security_group" "public_egress" {
  count  = var.enable_public_subnets ? 1 : 0
  name   = "public-egress-all"
  vpc_id = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-egress-all"
  }
}

resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = aws_vpc.main.cidr_block
    gateway_id = "local"
  }

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ---------------- NAT Tier ----------------

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.availability_zone_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, local.nat_offset + count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "nat-subnet-${count.index}"
    Tier = "nat"
  }
}

# ---------------- Private Tier ----------------

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.availability_zone_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, local.private_offset + count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-subnet-${count.index}"
    Tier = "private"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_cidrs" {
  value = [for s in aws_subnet.public : s.cidr_block]
}

output "nat_subnet_cidrs" {
  value = [for s in aws_subnet.nat : s.cidr_block]
}

output "private_subnet_cidrs" {
  value = [for s in aws_subnet.private : s.cidr_block]
}

output "newbits_used" {
  value = local.newbits
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------- Variables ----------------

variable "project" {
  description = "Project name"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "Primary VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "availability_zones" {
  description = "Availability zones for subnets"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

variable "key_name" {
  description = "EC2 key pair name for bastion SSH access"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "Bastion host instance type"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Enable EBS optimization on bastion"
  type        = bool
  default     = false
}

variable "common_tags" {
  description = "Common resource tags"
  type        = map(string)
  default = {
    Project     = "demo"
    Environment = "poc"
    ManagedBy   = "terraform"
  }
}

variable "vpc_tags" {
  description = "Additional VPC tags"
  type        = map(string)
  default = {
    Name = "demo-dataflow"
  }
}

# ---------------- Data Sources ----------------

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_vpc" "default" {
  default = true
}

# ---------------- Networking ----------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.common_tags,
    var.vpc_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    { Name = "demogwInternet" }
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    { Name = "${var.vpc_name}-public-${count.index + 1}" }
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(
    var.common_tags,
    { Name = "${var.vpc_name}-private-${count.index + 1}" }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(
    var.common_tags,
    { Name = "demoPublicRouteTable" }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- Bastion Host ----------------

resource "aws_security_group" "bastion" {
  name        = "${var.vpc_name}-bastion-sg"
  description = "Allow SSH to bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    var.common_tags,
    { Name = "${var.vpc_name}-bastion-sg" }
  )
}

resource "aws_iam_role" "bastion" {
  name = "${var.vpc_name}-bastion-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "bastion_ssm" {
  role       = aws_iam_role.bastion.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "bastion" {
  name = "${var.vpc_name}-bastion-profile"
  role = aws_iam_role.bastion.name
}

resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = var.bastion_instance_type
  subnet_id                   = aws_subnet.public[0].id
  key_name                    = var.key_name
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  associate_public_ip_address = true
  ebs_optimized               = var.ebs_optimized
  iam_instance_profile        = aws_iam_instance_profile.bastion.name

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
  }

  tags = merge(
    var.common_tags,
    { Name = "${var.vpc_name}-bastion" }
  )
}

# ---------------- Outputs ----------------

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "bastion_public_ip" {
  value = aws_instance.bastion.public_ip
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "primary_region" {
  type    = string
  default = "us-east-1"
}

variable "secondary_region" {
  type    = string
  default = "us-west-2"
}

variable "create_daily_plan" {
  type    = bool
  default = true
}

variable "excluded_rds_arns" {
  type    = list(string)
  default = []
}

variable "enable_cross_account_copy" {
  type    = bool
  default = true
}

variable "cross_account_id" {
  type    = string
  default = "433568766270"
}

variable "cross_account_vault_name" {
  type    = string
  default = "cross-account-backup-vault"
}

# ---------------- IAM ----------------

data "aws_iam_policy_document" "backup_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  name               = "aws-backup-rds-service-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume.json
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForS3Restore"
}

# ---------------- KMS keys ----------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for primary backup vault"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key for cross-region backup vault"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------- Vaults ----------------

resource "aws_backup_vault" "daily" {
  name        = "rds-daily-vault"
  kms_key_arn = aws_kms_key.primary.arn
}

resource "aws_backup_vault" "weekly" {
  name        = "rds-weekly-vault"
  kms_key_arn = aws_kms_key.primary.arn
}

resource "aws_backup_vault" "monthly" {
  name        = "rds-monthly-vault"
  kms_key_arn = aws_kms_key.primary.arn
}

resource "aws_backup_vault" "yearly" {
  name        = "rds-yearly-vault"
  kms_key_arn = aws_kms_key.primary.arn
}

resource "aws_backup_vault" "cross_region" {
  provider    = aws.secondary
  name        = "rds-cross-region-vault"
  kms_key_arn = aws_kms_key.secondary.arn
}

# ---------------- Copy destinations ----------------

locals {
  cross_region_dest_arn = aws_backup_vault.cross_region.arn
  cross_account_dest_arn = "arn:aws:backup:${var.secondary_region}:${var.cross_account_id}:backup-vault:${var.cross_account_vault_name}"
}

# ---------------- Backup plans ----------------

resource "aws_backup_plan" "daily" {
  count = var.create_daily_plan ? 1 : 0
  name  = "rds-daily-backup-plan"

  rule {
    rule_name         = "daily"
    target_vault_name = aws_backup_vault.daily.name
    schedule          = "cron(0 2 * * ? *)"

    lifecycle {
      delete_after = 7
    }

    copy_action {
      destination_vault_arn = local.cross_region_dest_arn
      lifecycle {
        delete_after = 7
      }
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.cross_account_dest_arn
        lifecycle {
          delete_after = 7
        }
      }
    }
  }
}

resource "aws_backup_plan" "weekly" {
  name = "rds-weekly-backup-plan"

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.weekly.name
    schedule          = "cron(0 2 ? * SAT *)"

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = local.cross_region_dest_arn
      lifecycle {
        delete_after = 30
      }
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.cross_account_dest_arn
        lifecycle {
          delete_after = 30
        }
      }
    }
  }
}

resource "aws_backup_plan" "monthly" {
  name = "rds-monthly-backup-plan"

  rule {
    rule_name         = "monthly"
    target_vault_name = aws_backup_vault.monthly.name
    schedule          = "cron(0 3 1 * ? *)"

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = local.cross_region_dest_arn
      lifecycle {
        delete_after = 365
      }
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.cross_account_dest_arn
        lifecycle {
          delete_after = 365
        }
      }
    }
  }
}

resource "aws_backup_plan" "yearly" {
  name = "rds-yearly-backup-plan"

  rule {
    rule_name         = "yearly"
    target_vault_name = aws_backup_vault.yearly.name
    schedule          = "cron(0 4 1 1 ? *)"

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = local.cross_region_dest_arn
      lifecycle {
        delete_after = 2555
      }
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.cross_account_dest_arn
        lifecycle {
          delete_after = 2555
        }
      }
    }
  }
}

# ---------------- Selection (all RDS, with exclusions) ----------------

resource "aws_backup_selection" "rds" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "select-all-rds"

  resources     = ["*"]
  not_resources = var.excluded_rds_arns
}

# Attach all plans to the selection
resource "aws_backup_selection" "rds_daily" {
  count        = var.create_daily_plan ? 1 : 0
  iam_role_arn = aws_iam_role.backup.arn
  name         = "select-all-rds-daily"
  plan_id      = aws_backup_plan.daily[0].id

  resources     = ["*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "rds_weekly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "select-all-rds-weekly"
  plan_id      = aws_backup_plan.weekly.id

  resources     = ["*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "rds_monthly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "select-all-rds-monthly"
  plan_id      = aws_backup_plan.monthly.id

  resources     = ["*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "rds_yearly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "select-all-rds-yearly"
  plan_id      = aws_backup_plan.yearly.id

  resources     = ["*"]
  not_resources = var.excluded_rds_arns
}

output "backup_plan_arns" {
  value = {
    daily   = var.create_daily_plan ? aws_backup_plan.daily[0].arn : null
    weekly  = aws_backup_plan.weekly.arn
    monthly = aws_backup_plan.monthly.arn
    yearly  = aws_backup_plan.yearly.arn
  }
}

output "cross_region_vault_arn" {
  value = aws_backup_vault.cross_region.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allow_users_to_change_password" {
  description = "Whether IAM users can change their own passwords"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after expiry"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Maximum number of days a password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum password length"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that cannot be reused"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  type    = bool
  default = true
}

variable "require_uppercase_characters" {
  type    = bool
  default = true
}

variable "require_numbers" {
  type    = bool
  default = true
}

variable "require_symbols" {
  type    = bool
  default = true
}

resource "aws_iam_account_password_policy" "baseline" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# IAM Groups
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

# Policies
resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Full EC2 and RDS access on dev-tagged resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullEc2RdsOnDev"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Full EC2 and RDS access on preprod/prod-tagged resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullEc2RdsOnPreprodProd"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad access excluding IAM/Organizations/Account actions unless security != high, with explicit exceptions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "BroadAccessExceptSensitiveServices"
        Effect    = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid    = "ExplicitSensitiveServiceExceptions"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      }
    ]
  })
}

# Group policy attachments
resource "aws_iam_group_policy_attachment" "administrators_attach" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers_attach" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_attach" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "VPC instance tenancy"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "Main VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound network ACL rules"
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [{
    rule_number = 100
    rule_action = "allow"
    from_port   = 1024
    to_port     = 65535
    protocol    = "tcp"
    cidr_block  = "0.0.0.0/0"
  }]
}

variable "public_outbound_acl_rules" {
  description = "Outbound network ACL rules"
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [{
    rule_number = 100
    rule_action = "allow"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_block  = "0.0.0.0/0"
  }]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name_prefix}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.name_prefix}-s3-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.this.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_number = ingress.value.rule_number
      rule_action = ingress.value.rule_action
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_block  = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_number = egress.value.rule_number
      rule_action = egress.value.rule_action
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      cidr_block  = egress.value.cidr_block
    }
  }

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_association" "private" {
  count = length(var.private_subnets)

  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}
