terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

provider "null" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-2"
}

# Cloud Posse null-label context conventions
variable "namespace" {
  type    = string
  default = "cp"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "stage" {
  type    = string
  default = "base"
}

variable "name" {
  type    = string
  default = "vpc"
}

variable "delimiter" {
  type    = string
  default = "-"
}

variable "attributes" {
  type    = list(string)
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "label_order" {
  type    = list(string)
  default = null
}

variable "regex_replace_chars" {
  type    = string
  default = "/[^a-zA-Z0-9-]/"
}

variable "id_length_limit" {
  type    = number
  default = 0
}

# VPC core
variable "cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "11.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "Optional IPAM pool ID for primary IPv4 allocation. If set, overrides cidr_block."
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Optional netmask length for IPv4 IPAM allocation"
  type        = number
  default     = null
}

variable "instance_tenancy" {
  type    = string
  default = "default"
}

variable "enable_dns_hostnames" {
  type    = bool
  default = true
}

variable "enable_dns_support" {
  type    = bool
  default = true
}

variable "assign_generated_ipv6_cidr_block" {
  type    = bool
  default = true
}

variable "ipv6_cidr_block" {
  description = "Optional explicit IPv6 CIDR (requires assign_generated_ipv6_cidr_block = false)"
  type        = string
  default     = null
}

variable "ipv6_ipam_pool_id" {
  description = "Optional IPAM pool ID for IPv6 allocation"
  type        = string
  default     = null
}

variable "ipv6_netmask_length" {
  description = "Optional netmask length for IPv6 IPAM allocation"
  type        = number
  default     = null
}

variable "vpc_create_timeout" {
  type    = string
  default = "10m"
}

variable "vpc_delete_timeout" {
  type    = string
  default = "15m"
}

# Additional CIDR associations
variable "additional_ipv4_cidr_blocks" {
  description = "Map of additional IPv4 CIDR associations. Keys: cidr_block, ipv4_ipam_pool_id, ipv4_netmask_length, create_timeout, delete_timeout"
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    create_timeout      = optional(string, "5m")
    delete_timeout      = optional(string, "10m")
  }))
  default = {}
}

variable "additional_ipv6_cidr_blocks" {
  description = "Map of additional IPv6 CIDR associations. Keys: ipv6_cidr_block, ipv6_ipam_pool_id, ipv6_netmask_length, create_timeout, delete_timeout"
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    create_timeout      = optional(string, "5m")
    delete_timeout      = optional(string, "10m")
  }))
  default = {}
}

# Default resource adoption
variable "default_security_group_deny_all" {
  type    = bool
  default = true
}

variable "adopt_default_route_table" {
  type    = bool
  default = false
}

variable "adopt_default_network_acl" {
  type    = bool
  default = false
}

# Gateways
variable "internet_gateway_enabled" {
  type    = bool
  default = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type    = bool
  default = false
}

# -----------------------------------------------------------------------------
# Cloud Posse null-label context (self-contained implementation)
# -----------------------------------------------------------------------------

locals {
  context_tags = merge(
    {
      "Name" = local.id
    },
    var.tags
  )

  normalized_attributes = [
    for a in var.attributes : replace(a, var.regex_replace_chars, "")
  ]

  label_components = compact(
    var.label_order != null ? [
      for c in var.label_order : c == "namespace" ? var.namespace :
      c == "environment" ? var.environment :
      c == "stage" ? var.stage :
      c == "name" ? var.name :
      c == "attributes" ? join(var.delimiter, local.normalized_attributes) : ""
    ] : [var.namespace, var.environment, var.stage, var.name, join(var.delimiter, local.normalized_attributes)]
  )

  full_id = join(var.delimiter, local.label_components)

  id = var.id_length_limit > 0 ? substr(local.full_id, 0, var.id_length_limit) : local.full_id
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "default" {
  # IPv4: either explicit CIDR or IPAM pool allocation
  cidr_block           = var.ipv4_ipam_pool_id == null ? var.cidr_block : null
  ipv4_ipam_pool_id    = var.ipv4_ipam_pool_id
  ipv4_netmask_length  = var.ipv4_netmask_length

  # IPv6: autogenerated, explicit, or IPAM pool allocation
  assign_generated_ipv6_cidr_block = var.ipv6_ipam_pool_id == null && var.ipv6_cidr_block == null ? var.assign_generated_ipv6_cidr_block : null
  ipv6_cidr_block                  = var.ipv6_cidr_block
  ipv6_ipam_pool_id                = var.ipv6_ipam_pool_id
  ipv6_netmask_length              = var.ipv6_netmask_length

  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(local.context_tags, {
    Name = "${local.id}-vpc"
  })

  timeouts {
    create = var.vpc_create_timeout
    delete = var.vpc_delete_timeout
  }
}

# -----------------------------------------------------------------------------
# Additional IPv4 CIDR associations
# -----------------------------------------------------------------------------

resource "aws_vpc_ipv4_cidr_block_association" "additional" {
  for_each = var.additional_ipv4_cidr_blocks

  vpc_id = aws_vpc.default.id

  cidr_block          = each.value.ipv4_ipam_pool_id == null ? each.value.cidr_block : null
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

# -----------------------------------------------------------------------------
# Additional IPv6 CIDR associations
# -----------------------------------------------------------------------------

resource "aws_vpc_ipv6_cidr_block_association" "additional" {
  for_each = var.additional_ipv6_cidr_blocks

  vpc_id = aws_vpc.default.id

  ipv6_cidr_block     = each.value.ipv6_ipam_pool_id == null ? each.value.ipv6_cidr_block : null
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

# -----------------------------------------------------------------------------
# Default security group (deny all)
# -----------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.default.id

  # No ingress/egress blocks defined => all rules removed

  tags = merge(local.context_tags, {
    Name = "${local.id}-default-sg"
  })
}

# -----------------------------------------------------------------------------
# Default route table adoption
# -----------------------------------------------------------------------------

resource "aws_default_route_table" "default" {
  count = var.adopt_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.default.default_route_table_id

  tags = merge(local.context_tags, {
    Name = "${local.id}-default-rt"
  })
}

# -----------------------------------------------------------------------------
# Default network ACL adoption
# -----------------------------------------------------------------------------

resource "aws_default_network_acl" "default" {
  count = var.adopt_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.default.default_network_acl_id

  tags = merge(local.context_tags, {
    Name = "${local.id}-default-nacl"
  })
}

# -----------------------------------------------------------------------------
# Internet gateway (dual-stack)
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "default" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default.id

  tags = merge(local.context_tags, {
    Name = "${local.id}-igw"
  })
}

resource "aws_route" "igw_ipv6" {
  count = var.internet_gateway_enabled && var.assign_generated_ipv6_cidr_block ? 1 : 0

  route_table_id         = aws_vpc.default.default_route_table_id
  destination_ipv6_cidr_block = "::/0"
  gateway_id             = aws_internet_gateway.default[0].id
}

# -----------------------------------------------------------------------------
# Egress-only internet gateway (IPv6)
# -----------------------------------------------------------------------------

resource "aws_egress_only_internet_gateway" "default" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default.id

  tags = merge(local.context_tags, {
    Name = "${local.id}-eigw"
  })
}

# -----------------------------------------------------------------------------
# IAM role for deployment context
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "vpc_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow" {
  name = "${local.id}-vpc-role"

  assume_role_policy = data.aws_iam_policy_document.vpc_assume.json

  tags = local.context_tags
}

resource "aws_iam_role_policy_attachment" "vpc_flow" {
  role       = aws_iam_role.vpc_flow.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonVPCFullAccess"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  value = aws_vpc.default.id
}

output "vpc_cidr_block" {
  value = aws_vpc.default.cidr_block
}

output "vpc_ipv6_cidr_blocks" {
  value = aws_vpc.default.ipv6_cidr_block
}

output "internet_gateway_id" {
  value = var.internet_gateway_enabled ? aws_internet_gateway.default[0].id : null
}

output "egress_only_internet_gateway_id" {
  value = var.ipv6_egress_only_internet_gateway_enabled ? aws_egress_only_internet_gateway.default[0].id : null
}

output "default_security_group_id" {
  value = var.default_security_group_deny_all ? aws_default_security_group.default[0].id : null
}

output "label_id" {
  value = local.id
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "username" {
  description = "Name of the IAM user for infrastructure deployment credentials"
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "Name of the IAM group"
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "Name of the IAM group membership"
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "ProjectTag value applied to user and policies"
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Custom path for all IAM policies"
  default     = "/my_vpn_infra/"
}

# ---------------- IAM User, Group, Membership, Access Key ----------------

resource "aws_iam_user" "infra_user" {
  name          = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_access_key" "infra_user_key" {
  user = aws_iam_user.infra_user.name
}

resource "aws_iam_group" "infra_group" {
  name = var.group_name
}

resource "aws_iam_user_group_membership" "membership" {
  user = aws_iam_user.infra_user.name
  groups = [
    aws_iam_group.infra_group.name,
  ]
  name = var.membership_name
}

# ---------------- Policies ----------------

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Basic STS identity check"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sts:GetCallerIdentity"]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "EC2 resource creation actions"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "Comprehensive EC2 read actions"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeAddresses",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstances",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeLocalGatewayRouteTableVpcAssociations",
          "ec2:DescribeLocalGatewayRouteTables",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribePrefixLists",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcEndpoints",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "EC2 modification and association actions"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AssociateAddress",
          "ec2:AssociateRouteTable",
          "ec2:AssociateSubnetCidrBlock",
          "ec2:AttachInternetGateway",
          "ec2:AttachVolume",
          "ec2:ModifyInstanceMetadataOptions",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyVolume",
          "ec2:ModifyVpcAttribute",
          "ec2:ModifyVpcEndpoint",
          "ec2:ReplaceRoute",
          "ec2:ReplaceIamInstanceProfileAssociation",
          "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
          "ec2:UpdateSecurityGroupRuleDescriptionsIngress",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "EC2 deletion and detachment actions"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteVpc",
          "ec2:DeleteSubnet",
          "ec2:DeleteInternetGateway",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteTags",
          "ec2:DeleteVolume",
          "ec2:DetachInternetGateway",
          "ec2:DetachVolume",
          "ec2:DisassociateAddress",
          "ec2:DisassociateRouteTable",
          "ec2:DisassociateSubnetCidrBlock",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "EC2 instance lifecycle actions"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Terraform backend access for DynamoDB state locking and S3 state storage"

  tags = {
    ProjectTag = var.project_tag
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------- Policy Attachments to Group ----------------

resource "aws_iam_group_policy_attachment" "basic" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

resource "aws_iam_group_policy_attachment" "create" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

resource "aws_iam_group_policy_attachment" "read" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

resource "aws_iam_group_policy_attachment" "update" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

resource "aws_iam_group_policy_attachment" "delete" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_group_policy_attachment" "instance" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

resource "aws_iam_group_policy_attachment" "backend" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

# ---------------- Outputs ----------------

output "iam_user_name" {
  value = aws_iam_user.infra_user.name
}

output "iam_group_name" {
  value = aws_iam_group.infra_group.name
}

output "access_key_id" {
  value = aws_iam_access_key.infra_user_key.id
}

output "access_key_secret" {
  value     = aws_iam_access_key.infra_user_key.secret
  sensitive = true
}
```

provider "aws" {
  region = "us-east-1"
}

variable "existing_vpc_id" {
  description = "Optional existing VPC ID. If empty, a new VPC is created."
  type        = string
  default     = ""
}

variable "environment_prefix" {
  description = "Environment prefix for resource naming."
  type        = string
  default     = "DEV"
}

variable "main_cidr" {
  description = "CIDR block for the new VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "craete_private_subnet" {
  description = "Whether to create private subnets, NAT Gateway, and private route table."
  type        = bool
  default     = false
}

variable "nat_eip_private_ip" {
  description = "Private IP for the NAT Gateway Elastic IP association."
  type        = string
  default     = "10.0.0.5"
}

locals {
  vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main[0].id
  azs    = ["us-east-1a", "us-east-1b"]
}

# VPC (created only when no existing VPC ID is supplied)
resource "aws_vpc" "main" {
  count                 = var.existing_vpc_id == "" ? 1 : 0
  cidr_block           = var.main_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${var.environment_prefix}-vpc"
    Environment = var.environment_prefix
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name        = "${var.environment_prefix}-igw"
    Environment = var.environment_prefix
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = local.vpc_id
  availability_zone       = local.azs[count.index]
  cidr_block              = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment_prefix}-public-subnet-${count.index + 1}"
    Environment = var.environment_prefix
    Tier        = "public"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${var.environment_prefix}-public-rt"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private subnets (conditional)
resource "aws_subnet" "private" {
  count             = var.craete_private_subnet ? 2 : 0
  vpc_id            = local.vpc_id
  availability_zone = local.azs[count.index]
  cidr_block        = count.index == 0 ? "10.0.10.0/24" : "10.0.11.0/24"

  tags = {
    Name        = "${var.environment_prefix}-private-subnet-${count.index + 1}"
    Environment = var.environment_prefix
    Tier        = "private"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count            = var.craete_private_subnet ? 1 : 0
  domain           = "vpc"
  private_ip       = var.nat_eip_private_ip
  depends_on       = [aws_internet_gateway.main]

  tags = {
    Name        = "${var.environment_prefix}-nat-eip"
    Environment = var.environment_prefix
  }
}

# NAT Gateway in the first public subnet
resource "aws_nat_gateway" "main" {
  count         = var.craete_private_subnet ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name        = "${var.environment_prefix}-nat-gw"
    Environment = var.environment_prefix
  }
}

# Private route table
resource "aws_route_table" "private" {
  count  = var.craete_private_subnet ? 1 : 0
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name        = "${var.environment_prefix}-private-rt"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "private" {
  count          = var.craete_private_subnet ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

output "vpc_id" {
  value = local.vpc_id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  value = var.craete_private_subnet ? aws_nat_gateway.main[0].id : null
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the primary SQS queue."
  type        = bool
  default     = true
}

variable "name" {
  description = "Exact name of the queue. Conflicts with name_prefix."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for a generated unique queue name. Conflicts with name."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS key ID/ARN. If omitted, SQS-managed SSE is applied."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds."
  type        = number
  default     = 300
}

variable "visibility_timeout_seconds" {
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  type        = number
  default     = 345600
}

variable "max_message_size" {
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  type        = number
  default     = 0
}

variable "content_based_deduplication" {
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# Queue policy
variable "create_queue_policy" {
  description = "Whether to create and attach a queue policy."
  type        = bool
  default     = false
}

variable "policy_source_json" {
  description = "Source policy document JSON to merge."
  type        = string
  default     = null
}

variable "policy_override_json" {
  description = "Override policy document JSON merged on top of source."
  type        = string
  default     = null
}

variable "policy_statements" {
  description = "Custom policy statements rendered into the queue policy."
  type = list(object({
    sid        = optional(string)
    effect     = optional(string, "Allow")
    actions    = list(string)
    principals = optional(map(list(string)))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

# DLQ
variable "create_dlq" {
  description = "Whether to create a dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Name of the DLQ. Defaults to '<queue-name>-dlq'."
  type        = string
  default     = null
}

variable "dlq_message_retention_seconds" {
  type        = number
  default     = 1209600
}

variable "max_receive_count" {
  description = "Max receive count for the redrive policy."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Attach a redrive allow policy to the DLQ restricting byQueue to the main queue."
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  base_name = coalesce(var.name, var.name_prefix, "default-queue")

  queue_name = var.fifo_queue ? (
    (var.name != null ? var.name : var.name_prefix != null ? "${var.name_prefix}-${random_string.queue_suffix.result}" : "default-queue") != null &&
    (var.name != null ? var.name : "${var.name_prefix}-${random_string.queue_suffix.result}") != null &&
    endswith(coalesce(var.name, try("${var.name_prefix}-${random_string.queue_suffix.result}", null), "default-queue"), ".fifo")
    ? coalesce(var.name, try("${var.name_prefix}-${random_string.queue_suffix.result}", null), "default-queue")
    : "${coalesce(var.name, try("${var.name_prefix}-${random_string.queue_suffix.result}", null), "default-queue")}.fifo"
  ) : coalesce(var.name, try("${var.name_prefix}-${random_string.queue_suffix.result}", null), "default-queue")

  dlq_base_name = coalesce(var.dlq_name, "${local.queue_name}-dlq")

  dlq_name = var.fifo_queue ? (
    endswith(local.dlq_base_name, ".fifo") ? local.dlq_base_name : "${local.dlq_base_name}.fifo"
  ) : local.dlq_base_name

  # SSE: SQS-managed SSE applies automatically when no custom KMS key is given
  effective_sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false

  common_queue_args = {
    visibility_timeout_seconds      = var.visibility_timeout_seconds
    message_retention_seconds       = var.message_retention_seconds
    max_message_size                = var.max_message_size
    delay_seconds                   = var.delay_seconds
    receive_wait_time_seconds       = var.receive_wait_time_seconds
    sqs_managed_sse_enabled         = local.effective_sqs_managed_sse
    kms_master_key_id               = var.kms_master_key_id
    kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
    tags                            = var.tags
  }

  fifo_args = var.fifo_queue ? {
    fifo_queue                  = true
    content_based_deduplication = var.content_based_deduplication
    deduplication_scope         = var.deduplication_scope
    fifo_throughput_limit       = var.fifo_throughput_limit
  } : {}

  # Queue policy document
  policy_statements_rendered = [
    for stmt in var.policy_statements : {
      sid       = try(stmt.sid, null)
      effect    = try(stmt.effect, "Allow")
      action    = stmt.actions
      resource  = try(stmt.resource, null) != null ? stmt.resource : (var.create ? aws_sqs_queue.this[0].arn : null)
      principal = try(stmt.principals, null)
      condition = try(stmt.conditions, null)
    }
  ]

  policy_document = var.create_queue_policy ? jsonencode(
    merge(
      var.policy_source_json != null ? jsondecode(var.policy_source_json) : {},
      var.policy_override_json != null ? jsondecode(var.policy_override_json) : {},
      length(var.policy_statements) > 0 ? {
        Version = "2012-10-17"
        Statement = concat(
          try(jsondecode(coalesce(var.policy_source_json, var.policy_override_json, "{}")).Statement, []),
          local.policy_statements_rendered
        )
      } : {}
    )
  ) : null
}

resource "random_string" "queue_suffix" {
  length  = 6
  special = false
  upper   = false
}

# ------------------------------------------------------------------------------
# Primary queue
# ------------------------------------------------------------------------------

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name                              = local.queue_name
  visibility_timeout_seconds        = local.common_queue_args.visibility_timeout_seconds
  message_retention_seconds         = local.common_queue_args.message_retention_seconds
  max_message_size                  = local.common_queue_args.max_message_size
  delay_seconds                     = local.common_queue_args.delay_seconds
  receive_wait_time_seconds         = local.common_queue_args.receive_wait_time_seconds
  sqs_managed_sse_enabled           = local.common_queue_args.sqs_managed_sse_enabled
  kms_master_key_id                 = local.common_queue_args.kms_master_key_id
  kms_data_key_reuse_period_seconds = local.common_queue_args.kms_data_key_reuse_period_seconds
  tags                              = local.common_queue_args.tags

  fifo_queue                  = try(local.fifo_args.fifo_queue, false)
  content_based_deduplication = try(local.fifo_args.content_based_deduplication, null)
  deduplication_scope         = try(local.fifo_args.deduplication_scope, null)
  fifo_throughput_limit       = try(local.fifo_args.fifo_throughput_limit, null)

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null
}

# ------------------------------------------------------------------------------
# Dead-letter queue
# ------------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name                              = local.dlq_name
  visibility_timeout_seconds        = local.common_queue_args.visibility_timeout_seconds
  message_retention_seconds         = var.dlq_message_retention_seconds
  max_message_size                  = local.common_queue_args.max_message_size
  receive_wait_time_seconds         = local.common_queue_args.receive_wait_time_seconds
  sqs_managed_sse_enabled           = local.common_queue_args.sqs_managed_sse_enabled
  kms_master_key_id                 = local.common_queue_args.kms_master_key_id
  kms_data_key_reuse_period_seconds = local.common_queue_args.kms_data_key_reuse_period_seconds
  tags                              = local.common_queue_args.tags

  fifo_queue                  = try(local.fifo_args.fifo_queue, false)
  content_based_deduplication = try(local.fifo_args.content_based_deduplication, null)
  deduplication_scope         = try(local.fifo_args.deduplication_scope, null)
  fifo_throughput_limit       = try(local.fifo_args.fifo_throughput_limit, null)

  redrive_allow_policy = var.create_dlq_redrive_allow_policy ? jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  }) : null
}

# ------------------------------------------------------------------------------
# Queue policy
# ------------------------------------------------------------------------------

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = local.policy_document
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "queue_arn" {
  description = "ARN of the primary queue."
  value       = var.create ? aws_sqs_queue.this[0].arn : null
}

output "queue_url" {
  description = "URL of the primary queue."
  value       = var.create ? aws_sqs_queue.this[0].url : null
}

output "queue_name" {
  description = "Name of the primary queue."
  value       = var.create ? aws_sqs_queue.this[0].name : null
}

output "dlq_arn" {
  description = "ARN of the dead-letter queue."
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].arn : null
}

output "dlq_url" {
  description = "URL of the dead-letter queue."
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].url : null
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  ec2_describe_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:Describe*"
        Resource = "*"
      }
    ]
  })

  users = {
    "loadbalancer" = ["test", "test2", "test3", "test4"]
    "loadbalancer2" = ["test2", "test22", "test23", "test24"]
    "loadbalancer3" = ["test3", "test32", "test33", "test34"]
  }
}

resource "aws_iam_user" "this" {
  for_each = local.users
  name     = each.key
  path     = "/system/"
}

resource "aws_iam_access_key" "this" {
  for_each = aws_iam_user.this
  user     = each.value.name
}

resource "aws_iam_user_policy" "this" {
  for_each = merge([
    for username, policies in local.users : {
      for policy_name in policies :
      "${username}-${policy_name}" => {
        user        = username
        policy_name = policy_name
      }
    }
  ]...)

  name = each.value.policy_name
  user = each.value.user

  policy = local.ec2_describe_policy
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "backup_name" {
  description = "Name of the backup vault"
  type        = string
}

variable "account_type" {
  description = "Type of account: workload or backup"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for vault encryption"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional backup vault access policy JSON"
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention days for vault lock (optional)"
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention days for vault lock (optional)"
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Days the vault lock is changeable"
  type        = number
  default     = 3
}

variable "enable_aws_backup_vault_notifications" {
  description = "Enable vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for backup notifications"
  type        = string
  default     = null
}

variable "backup_events" {
  description = "Backup events to notify on"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule" {
  description = "Backup rule cron schedule"
  type        = string
  default     = "cron(0 12 * * ? *)"
}

variable "copy_action_region" {
  description = "Destination region for copy action (optional)"
  type        = string
  default     = null
}

variable "copy_action_destination_vault_arn" {
  description = "Destination vault ARN for copy action (optional)"
  type        = string
  default     = null
}

variable "selection_resources" {
  description = "Explicit resource ARNs to include in backup selection"
  type        = list(string)
  default     = []
}

# ---------------- Backup Vault ----------------

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn
}

resource "aws_backup_vault_policy" "this" {
  count          = var.vault_policy != null ? 1 : 0
  backup_vault_name = aws_backup_vault.this.name
  policy         = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count               = var.min_retention_days != null ? 1 : 0
  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count              = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != null ? 1 : 0
  backup_vault_name  = aws_backup_vault.this.name
  sns_topic_arn      = var.sns_topic_arn
  backup_vault_events = var.backup_events
}

# ---------------- Workload account resources ----------------

data "aws_iam_policy_document" "backup_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  count              = var.account_type == "workload" ? 1 : 0
  name               = "aws-backup-${var.backup_name}"
  assume_role_policy = data.aws_iam_policy_document.backup_assume.json
}

resource "aws_iam_role_policy_attachment" "backup" {
  count      = var.account_type == "workload" ? 1 : 0
  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:aws:iam::aws:policy/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "this" {
  count = var.account_type == "workload" ? 1 : 0
  name  = "plan-${var.backup_name}-backup"

  rule {
    rule_name                = "${var.backup_name}-daily"
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.schedule
    start_window             = 60
    completion_window        = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      Backup = "true"
    }

    dynamic "copy_action" {
      for_each = var.copy_action_destination_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.copy_action_destination_vault_arn
        lifecycle {
          cold_storage_after = 30
          delete_after       = 120
        }
      }
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "by_tag" {
  count        = var.account_type == "workload" ? 1 : 0
  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "selection-${var.backup_name}-tag"
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "by_resource" {
  count        = var.account_type == "workload" && length(var.selection_resources) > 0 ? 1 : 0
  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "selection-${var.backup_name}-resources"
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.selection_resources
}

output "backup_vault_arn" {
  value = aws_backup_vault.this.arn
}

output "backup_plan_id" {
  value = var.account_type == "workload" ? aws_backup_plan.this[0].id : null
}

output "backup_role_arn" {
  value = var.account_type == "workload" ? aws_iam_role.backup[0].arn : null
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "role_name" {
  description = "Name for the AWS Config IAM role. Falls back to a petname when null or empty."
  type        = string
  default     = "config"
}

variable "environment" {
  description = "Environment tag value."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  # Naming convention: use provided name, fall back to a petname when null/empty
  config_role_name = coalesce(
    var.role_name != "" && var.role_name != null ? var.role_name : null,
    "config-${random_pet.config_name.id}"
  )

  snapshot_bucket_name = "${local.config_role_name}-config-snapshots-${data.aws_caller_identity.current.account_id}"
  sns_topic_name       = "${local.config_role_name}-config-notifications"
}

resource "random_pet" "config_name" {
  length = 2
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# KMS key for SNS encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "config_sns" {
  description             = "KMS CMK for AWS Config SNS topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "config_sns" {
  name          = "alias/${local.config_role_name}-config-sns"
  target_key_id = aws_kms_key.config_sns.key_id
}

# ---------------------------------------------------------------------------
# SNS Topic
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "config_notifications" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.config_sns.key_id

  tags = {
    "terraform.io" = "true"
    "environment"  = var.environment
  }
}

resource "aws_sns_topic_policy" "config_notifications" {
  arn = aws_sns_topic.config_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowConfigPublish"
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.config_notifications.arn
      },
      {
        Sid       = "AllowKMSUse"
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource  = aws_kms_key.config_sns.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# S3 Snapshot Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "config_snapshots" {
  bucket        = local.snapshot_bucket_name
  force_destroy = true

  tags = {
    "terraform.io" = "true"
    "environment"  = var.environment
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshots" {
  bucket                  = aws_s3_bucket.config_snapshots.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowConfigRoleWrite"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.config_role.arn }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.config_snapshots.arn,
          "${aws_s3_bucket.config_snapshots.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM Role for AWS Config
# ---------------------------------------------------------------------------

data "aws_iam_policy" "aws_config_role" {
  name = "AWS_ConfigRole"
}

resource "aws_iam_role" "config_role" {
  name = local.config_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    "terraform.io" = "true"
    "environment"  = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config_role.name
  policy_arn = data.aws_iam_policy.aws_config_role.arn
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name = "${local.config_role_name}-sns-publish"
  role = aws_iam_role.config_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = aws_sns_topic.config_notifications.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# AWS Config Recorder & Delivery Channel
# ---------------------------------------------------------------------------

resource "aws_config_configuration_recorder" "config_recorder" {
  name     = "${local.config_role_name}-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "config_delivery" {
  name           = "${local.config_role_name}-delivery"
  s3_bucket_name = aws_s3_bucket.config_snapshots.bucket
  s3_kms_key_arn = aws_kms_key.config_sns.arn
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config_notifications.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [aws_config_configuration_recorder.config_recorder]
}

resource "aws_config_configuration_recorder_status" "config_recorder_status" {
  name       = aws_config_configuration_recorder.config_recorder.name
  is_enabled = true
  depends_on = [aws_config_delivery_channel.config_delivery]
}

# ---------------------------------------------------------------------------
# AWS Config Rules
# ---------------------------------------------------------------------------

locals {
  config_rules = {
    cloudtrail_enabled = {
      source_identifier = "CLOUD_TRAIL_ENABLED"
      input_parameters  = null
    }
    iam_pw_policy = {
      source_identifier = "IAM_PASSWORD_POLICY"
      input_parameters  = null
    }
    ec2_vpc = {
      source_identifier = "INSTANCES_IN_VPC"
      input_parameters  = null
    }
    root_mfa_enabled = {
      source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
      input_parameters  = null
    }
    acm_expiration_check = {
      source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
      input_parameters = jsonencode({
        daysToExpiration = 90
      })
    }
    ebs_inuse_check = {
      source_identifier = "EC2_VOLUME_INUSE_CHECK"
      input_parameters  = null
    }
    ec2_imdsv2_check = {
      source_identifier = "EC2_IMDSV2_CHECK"
      input_parameters  = null
    }
    rds_encrypted = {
      source_identifier = "RDS_STORAGE_ENCRYPTED"
      input_parameters  = null
    }
    rds_private = {
      source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
      input_parameters  = null
    }
    rds_private_snapshots = {
      source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
      input_parameters  = null
    }
    required_tags = {
      source_identifier = "REQUIRED_TAGS"
      input_parameters = jsonencode({
        tag1Key = "terraform.io"
        tag2Key = "environment"
      })
    }
  }
}

resource "aws_config_config_rule" "rules" {
  for_each = local.config_rules

  name             = each.key
  input_parameters = each.value.input_parameters

  source {
    owner             = "AWS"
    source_identifier = each.value.source_identifier
  }

  scope {
    compliance_resource_types = each.key == "required_tags" ? ["S3::Bucket"] : []
  }

  maximum_execution_frequency = each.value.input_parameters == null ? null : "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.config_recorder]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "config_role_name" {
  value = aws_iam_role.config_role.name
}

output "snapshot_bucket" {
  value = aws_s3_bucket.config_snapshots.bucket
}

output "sns_topic_arn" {
  value = aws_sns_topic.config_notifications.arn
}

output "kms_key_arn" {
  value = aws_kms_key.config_sns.arn
}
