terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "availability_zones" {
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnet_cidrs" {
  default = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
}

variable "private_subnet_cidrs" {
  default = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name    = "bjit-multi-tier-vpc"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# ---------------- Internet Gateway ----------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-igw"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# ---------------- Public Subnets ----------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "bjit-public-subnet-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# ---------------- Private Subnets ----------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "bjit-private-subnet-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# ---------------- Public Route Table ----------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name    = "bjit-public-rt"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- S3 Gateway VPC Endpoint ----------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_a.id, aws_route_table.private_b.id, aws_route_table.private_c.id]

  tags = {
    Name    = "bjit-s3-endpoint"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# ---------------- Private Route Tables (one per AZ) ----------------
resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-private-rt-a"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-private-rt-b"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_route_table" "private_c" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-private-rt-c"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private[0].id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private[1].id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_route_table_association" "private_c" {
  subnet_id      = aws_subnet.private[2].id
  route_table_id = aws_route_table.private_c.id
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "ALB security group - inbound 80-443 from anywhere, egress limited to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP/HTTPS from anywhere"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name    = "bjit-api-server-ALB-SG"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_security_group" "rds" {
  name        = "bjit-mariaDB-RDS-SG"
