    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name    = "bjit-mariaDB-RDS-SG"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Redis security group - inbound 6379 from VPC, egress limited to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Egress to VPC only"
