```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "base_name" {
  description = "Base name prefix for resources"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "Public subnet CIDRs"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "Private subnet CIDRs (optional)"
  type        = list(string)
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  create_private = var.subnet_private_cidrs != null && length(var.subnet_private_cidrs) > 0
  azs            = data.aws_availability_zones.available.names
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.subnet_public_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = local.azs[count.index + 1]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.base_name}-public-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Optional private subnets
resource "aws_subnet" "private" {
  count             = local.create_private ? length(var.subnet_private_cidrs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = local.azs[count.index + 1]

  tags = {
    Name = "${var.base_name}-private-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = local.create_private ? length(aws_subnet.public) : 0
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.create_private ? length(aws_subnet.public) : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = local.create_private ? length(aws_subnet.public) : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.create_private ? length(aws_subnet.private) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Security group for ECR endpoints
resource "aws_security_group" "ecr_endpoints" {
  name        = "${var.base_name}-ecr-endpoints-sg"
  description = "Security group for ECR interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  dynamic "ingress" {
    for_each = local.create_private ? [1] : []
    content {
      description = "HTTPS from private subnets"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = var.subnet_private_cidrs
    }
  }

  egress {
    description = "Egress within VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.base_name}-ecr-endpoints-sg"
  }
}

# S3 gateway endpoint for public subnets
resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-endpoint-public"
  }
}

# S3 gateway endpoint for private subnets
resource "aws_vpc_endpoint" "s3_private" {
  count             = local.create_private ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-endpoint-private"
  }
}

data "aws_region" "current" {}

# ECR API interface endpoint
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

# ECR Docker interface endpoint
resource "aws_vpc_endpoint" "ecr_docker" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}
