terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "admin_ssh_cidr" {
  type    = string
  default = "203.0.113.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "project_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.project_vpc.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "pvt-sub-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.project_vpc.id

  tags = {
    Name = "T-igw"
  }
}

resource "aws_route_table" "public" {
  count  = 2
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-${count.index + 1}"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[count.index].id
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "nat" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[0].id
  }

  tags = {
    Name = "RT_PVTRT-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_security_group" "public_sg" {
  name        = "allow_tls"
  description = "Public tier security group"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_ssh_cidr]
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_security_group" "private_sg" {
  name        = "pvt-seg"
  description = "Private tier security group"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description     = "HTTP from public SG"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    description     = "HTTPS from public SG"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    description     = "SSH from public SG"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    description     = "PostgreSQL from public SG"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  egress {
    description     = "Egress to public SG only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.public_sg.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- DynamoDB ----------------
resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name            = "PetType-index"
    hash_key        = "PetType"
    projection_type = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity   = 5
    write_capacity  = 5
  }
}

# ---------------- IAM ----------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_iam_role" "apigw_dynamodb_role" {
  name = "apigw-dynamodb-terraform-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb_policy" {
  name = "apigw-dynamodb-terraform-policy"
  role = aws_iam_role.apigw_dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["dynamodb:PutItem", "dynamodb:Query"]
      Resource = [
        aws_dynamodb_table.pets.arn,
        "${aws_dynamodb_table.pets.arn}/index/*"
      ]
    }]
  })
}

# ---------------- CloudWatch Logging ----------------
resource "aws_cloudwatch_log_group" "apigw_logs" {
  name              = "/aws/APIGW/terraform"
  retention_in_days = 7
}

resource "aws_api_gateway_account" "account" {
  cloudwatch_role_arn = aws_iam_role.apigw_cw_role.arn
}

resource "aws_iam_role" "apigw_cw_role" {
  name = "apigw-dynamodb-terraform-cw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cw_policy" {
  role       = aws_iam_role.apigw_cw_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_rest_api" "api" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# ---------------- POST /pets ----------------
resource "aws_api_gateway_method" "post_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.pets.id
  http_method   = "POST"
  authorization = "NONE"
  api_key_required = true
  request_parameters = {
    "method.request.header.x-api-key" = true
  }
}

resource "aws_api_gateway_integration" "post_integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_method.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-amz-json-1.0'"
  }

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "Item": {
    "id": {
      "S": "$context.requestId"
    },
    "PetType": {
      "S": "$input.path('$.PetType')"
    },
    "PetName": {
      "S": "$input.path('$.PetName')"
    },
    "PetPrice": {
      "N": "$input.path('$.PetPrice')"
    },
    "PetBoolean": {
      "BOOL": true
    }
  }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_method.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_method.http_method
  status_code = aws_api_gateway_method_response.post_200.status_code

  response_templates = {
    "application/json" = <<EOF
{
  "message": "Pet added successfully",
  "requestId": "$context.requestId"
}
EOF
  }

  depends_on = [aws_api_gateway_integration.post_integration]
}

# ---------------- GET /pets/{PetType} ----------------
resource "aws_api_gateway_method" "get_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.pet_type.id
  http_method   = "GET"
  authorization = "NONE"
  api_key_required = true
  request_parameters = {
    "method.request.header.x-api-key"      = true
    "method.request.path.PetType"          = true
  }
}

resource "aws_api_gateway_integration" "get_integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_method.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-amz-json-1.0'"
    "integration.request.path.PetType"        = "method.request.path.PetType"
  }

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "IndexName": "PetType-index",
  "KeyConditionExpression": "PetType = :v_pettype",
  "ExpressionAttributeValues": {
    ":v_pettype": {
      "S": "$util.urlDecode('$input.params('PetType')')"
    }
  },
  "ProjectionExpression": "PetName, PetPrice"
}
EOF
  }
}

resource "aws_api_gateway_method_response" "get_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_method.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "get_200" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_method.http_method
  status_code = aws_api_gateway_method_response.get_200.status_code

  response_templates = {
    "application/json" = <<EOF
#set($inputRoot = $input.path('$'))
{
  "pets": [
#foreach($elem in $inputRoot.Items)
    {
      "PetName": "$elem.PetName.S",
      "PetPrice": $elem.PetPrice.N
    }#if($foreach.hasNext),#end
#end
  ]
}
EOF
  }

  depends_on = [aws_api_gateway_integration.get_integration]
}

# ---------------- Deployment & Stage ----------------
resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_integration.post_integration,
      aws_api_gateway_integration.get_integration,
      aws_api_gateway_resource.pets,
      aws_api_gateway_resource.pet_type,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post_integration,
    aws_api_gateway_integration_response.post_200,
    aws_api_gateway_integration.get_integration,
    aws_api_gateway_integration_response.get_200,
  ]
}

resource "aws_api_gateway_stage" "v1" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  deployment_id = aws_api_gateway_deployment.deployment.id
  stage_name    = "v1"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw_logs.arn
    format          = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [aws_api_gateway_account.account]
}

resource "aws_api_gateway_method_settings" "settings" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    logging_level      = "INFO"
    metrics_enabled    = true
    data_trace_enabled = false
  }
}

# ---------------- Log Resource Policy ----------------
resource "aws_api_gateway_rest_api_policy" "log_policy" {
  rest_api_id = aws_api_gateway_rest_api.api.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "delivery.logs.amazonaws.com" }
      Action    = "execute-api:Invoke"
      Resource  = "execute-api:/*"
      Condition = {
        ArnLike = {
          "aws:SourceArn" = "arn:aws:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${aws_api_gateway_rest_api.api.id}/*"
        }
      }
    }]
  })
}

# ---------------- API Key & Usage Plan ----------------
resource "aws_api_gateway_api_key" "api_key" {
  name = "apigw-dynamodb-terraform-api-key"
}

resource "aws_api_gateway_usage_plan" "usage_plan" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.api.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }
}

resource "aws_api_gateway_usage_plan_key" "usage_plan_key" {
  key_id        = aws_api_gateway_api_key.api_key.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.usage_plan.id
}

output "api_invoke_url" {
  value = aws_api_gateway_stage.v1.invoke_url
}

output "api_key_value" {
  value     = aws_api_gateway_api_key.api_key.value
  sensitive = true
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  default = "sadcloud"
}

variable "no_versioning" {
  default = false
}

variable "no_default_encryption" {
  default = false
}

variable "website_enabled" {
  default = false
}

variable "no_logging" {
  default = false
}

variable "bucket_acl" {
  default = "log-delivery-write"
}

variable "allow_cleartext" {
  default = false
}

variable "s3_getobject_only" {
  default = false
}

variable "s3_public" {
  default = false
}

resource "aws_kms_key" "main" {
  description             = "KMS key for ${var.name} bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "logging" {
  description             = "KMS key for ${var.name}-logging bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "main" {
  bucket              = "${var.name}-main"
  force_destroy       = true
  object_lock_enabled = false

  tags = {
    Name = "${var.name}-main"
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_versioning" "main" {
  count = var.no_versioning ? 0 : 1

  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.no_default_encryption ? 0 : 1

  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_policy" "deny_cleartext" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "logging" {
  count = var.no_logging ? 0 : 1

  bucket        = "${var.name}-logging"
  force_destroy = true

  tags = {
    Name = "${var.name}-logging"
  }
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.no_logging ? 0 : 1

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
}

resource "aws_s3_bucket" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket        = "${var.name}-getonly"
  force_destroy = true

  tags = {
    Name = "${var.name}-getonly"
  }
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket" "public" {
  count = var.s3_public ? 1 : 0

  bucket        = "${var.name}-public"
  force_destroy = true

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_s3_bucket_public_access_block" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

output "main_bucket_name" {
  value = aws_s3_bucket.main.id
}

output "logging_bucket_name" {
  value = var.no_logging ? null : aws_s3_bucket.logging[0].id
}

```terraform
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  partition = data.aws_partition.current.partition
  account   = data.aws_caller_identity.current.account_id
}

# ---------------------------------------------------------------
# Trust policies
# ---------------------------------------------------------------
data "aws_iam_policy_document" "drs_agent_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceIdentity"
      values   = ["s-"]
    }
  }
}

data "aws_iam_policy_document" "drs_failback_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceIdentity"
      values   = ["i-"]
    }
  }
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------
# Service roles
# ---------------------------------------------------------------
resource "aws_iam_role" "agent" {
  name                 = "AWSElasticDisasterRecoveryAgentRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.drs_agent_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "failback" {
  name                 = "AWSElasticDisasterRecoveryFailbackRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.drs_failback_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "conversion_server" {
  name                 = "AWSElasticDisasterRecoveryConversionServerRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.ec2_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "recovery_instance" {
  name                 = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.ec2_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "replication_server" {
  name                 = "AWSElasticDisasterRecoveryReplicationServerRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.ec2_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "recovery_instance_launch_actions" {
  name                 = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path                 = "/service-role/"
  assume_role_policy   = data.aws_iam_policy_document.ec2_trust.json
  max_session_duration = 3600
}

# ---------------------------------------------------------------
# Managed policy attachments
# ---------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryAgentPolicy"
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryFailbackPolicy"
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryConversionServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryReplicationServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_launch_actions_drs" {
  role       = aws_iam_role.recovery_instance_launch_actions.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_launch_actions_ssm" {
  role       = aws_iam_role.recovery_instance_launch_actions.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ---------------------------------------------------------------
# Initializer role
# ---------------------------------------------------------------
data "aws_iam_policy_document" "initializer_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account}:user/${data.aws_caller_identity.current.user_id}"]
    }
  }
}

data "aws_iam_policy_document" "initialize_policy" {
  statement {
    sid    = "InitializeService"
    effect = "Allow"
    actions = [
      "drs:InitializeService",
      "drs:CreateRecoveryInstance",
      "drs:DescribeRecoveryInstances",
      "drs:DescribeReplicationConfigurationTemplates",
      "drs:GetLaunchConfiguration",
      "drs:ListTagsForResource",
      "drs:TagResource",
      "drs:UntagResource"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "InstanceProfileCreation"
    effect = "Allow"
    actions = [
      "iam:AddRoleToInstanceProfile",
      "iam:CreateInstanceProfile",
      "iam:TagInstanceProfile"
    ]
    resources = ["arn:${local.partition}:iam::${local.account}:instance-profile/*"]
  }

  statement {
    sid    = "PassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account}:role/service-role/AWSElasticDisasterRecoveryAgentRole",
      "arn:${local.partition}:iam::${local.account}:role/service-role/AWSElasticDisasterRecoveryConversionServerRole",
      "arn:${local.partition}:iam::${local.account}:role/service-role/AWSElasticDisasterRecoveryRecoveryInstanceRole",
      "arn:${local.partition}:iam::${local.account}:role/service-role/AWSElasticDisasterRecoveryReplicationServerRole",
      "arn:${local.partition}:iam::${local.account}:role/service-role/AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
    ]
    condition {
      test     = "StringEqualsIfExists"
      variable = "iam:PassedToService"
      values   = ["ec2.amazonaws.com", "drs.amazonaws.com"]
    }
  }

  statement {
    sid    = "CreateServiceLinkedRole"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = ["arn:${local.partition}:iam::${local.account}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"]
  }

  statement {
    sid    = "EC2FullAccess"
    effect = "Allow"
    actions = [
      "ec2:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AttachDRSPolicies"
    effect = "Allow"
    actions = [
      "iam:AttachRolePolicy",
      "iam:PutRolePolicy"
    ]
    resources = ["arn:${local.partition}:iam::${local.account}:role/service-role/*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PolicyARN"
      values = [
        "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryAgentPolicy",
        "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryFailbackPolicy",
        "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryConversionServerPolicy",
        "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryRecoveryInstancePolicy",
        "arn:${local.partition}:iam::aws:policy/AWSElasticDisasterRecoveryReplicationServerPolicy"
      ]
    }
  }
}

resource "aws_iam_role" "initializer" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  assume_role_policy = data.aws_iam_policy_document.initializer_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "initializer" {
  name   = "InitializePolicy"
  role   = aws_iam_role.initializer.id
  policy = data.aws_iam_policy_document.initialize_policy.json
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  description = "Number of EC2 instances to deploy"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances (default: latest Amazon Linux 2)"
  type        = string
  default     = ""
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  ami_id = var.ami_id != "" ? var.ami_id : data.aws_ami.amazon_linux_2.id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private" {
  count             = length(var.subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name      = "Private_Subnet_${count.index + 1}"
    Terraform = "true"
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP/HTTPS from anywhere, egress to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name      = "allow_ssh_http_https"
    Terraform_SG_HTTP_HTTPS_SSH = "true"
  }
}

resource "aws_instance" "app" {
  count         = var.instance_count
  ami           = local.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp2"
    encrypted   = true
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }

  volume_tags = {
    Terraform_EBS_Volume1 = "true"
  }
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "ecs_task_role_arn" {
  description = "ARN of the ECS task role for CodeDeploy PassRole"
  type        = string
  default     = "" # populated via reference below
}

variable "ecs_exec_task_role_arn" {
  description = "ARN of the ECS execution task role for CodeDeploy PassRole"
  type        = string
  default     = ""
}

locals {
  task_role_arn     = var.ecs_task_role_arn != "" ? var.ecs_task_role_arn : aws_iam_role.ecsTaskRole.arn
  exec_task_role_arn = var.ecs_exec_task_role_arn != "" ? var.ecs_exec_task_role_arn : aws_iam_role.ecsExecTaskRole.arn
}

# ------------------------------------------------------------------
# 1. ecsServiceRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecsServiceRole" {
  name = "ecsServiceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecsTaskRolePolicy" {
  name = "ecsTaskRolePolicy"
  role = aws_iam_role.ecsServiceRole.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:*",
          "ec2:*",
          "ssm:*",
          "secretsmanager:*",
          "kms:*",
          "codedeploy:*",
          "sns:*",
          "cloudwatch:*",
          "lambda:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 2. ecsExecTaskRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecsExecTaskRole" {
  name = "ecsExecTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecsExecRolePolicy" {
  name = "ecsExecRolePolicy"
  role = aws_iam_role.ecsExecTaskRole.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecs:DescribeServices",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
          "secretsmanager:GetSecretValue",
          "kms:Decrypt",
          "ssm:GetParameters",
          "ssm:GetParameter",
          "ssm:GetParametersByPath"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecsExecution_additional" {
  name = "ecsExecution_additional"
  role = aws_iam_role.ecsExecTaskRole.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 3. ecsTaskRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecsTaskRole" {
  name = "ecsTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecsTaskRole_additional" {
  name = "ecsTaskRole_additional"
  role = aws_iam_role.ecsTaskRole.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 4. ecs_autoscale_role
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_autoscale_role" {
  name = "ecs_autoscale_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name = "ecs_autoscale_role_policy"
  role = aws_iam_role.ecs_autoscale_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:UpdateService"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 5. ecs_codedeploy_role
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_codedeploy_role" {
  name = "ecs_codedeploy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name = "ecs_codedeploy_role_policy"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:CreateTaskSet",
          "ecs:UpdateTaskSet",
          "ecs:DeleteTaskSet",
          "ecs:ListServices",
          "ecs:DescribeTaskSets",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:ModifyRule",
          "elasticloadbalancing:SetRulePriorities",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:RegisterTargets",
          "lambda:InvokeFunction",
          "cloudwatch:DescribeAlarms",
          "sns:Publish",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name = "ecs_codedeploy_role_policy_task"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = local.task_role_arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name = "ecs_codedeploy_role_policy_task_exec"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = local.exec_task_role_arn
      }
    ]
  })
}

output "ecs_service_role_arn" {
  value = aws_iam_role.ecsServiceRole.arn
}

output "ecs_exec_task_role_arn" {
  value = aws_iam_role.ecsExecTaskRole.arn
}

output "ecs_task_role_arn" {
  value = aws_iam_role.ecsTaskRole.arn
}

output "ecs_autoscale_role_arn" {
  value = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_codedeploy_role_arn" {
  value = aws_iam_role.ecs_codedeploy_role.arn
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------
# External VPC
# -----------------------------
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external_default_sg" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External Default SG"
    environment = "prod"
  }
}

resource "aws_internet_gateway" "external_igw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    environment = "prod"
  }
}

resource "aws_route_table" "external_main" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_igw.id
  }

  tags = {
    Name        = "External Main Route Table"
    environment = "prod"
  }
}

resource "aws_main_route_table_association" "external_main_assoc" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external_main.id
}

resource "aws_subnet" "external" {
  count             = 4
  vpc_id            = aws_vpc.external.id
  cidr_block        = cidrsubnet("10.41.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "Subnet${count.index}-${element(["1a", "1b", "1c", "1d"], count.index)}"
    environment = "prod"
  }
}

resource "aws_route_table_association" "external" {
  count          = 4
  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external_main.id
}

resource "aws_default_network_acl" "external_default_nacl" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    rule_no    = 100
    protocol   = "icmp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production External Default NACL"
    environment = "prod"
  }
}

# -----------------------------
# Internal VPC
# -----------------------------
resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal_default_sg" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name        = "Production Internal Default SG"
    environment = "prod"
  }
}

resource "aws_subnet" "internal" {
  count             = 4
  vpc_id            = aws_vpc.internal.id
  cidr_block        = cidrsubnet("10.40.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "Subnet${count.index}-${element(["1a", "1b", "1c", "1d"], count.index)}"
    environment = "prod"
  }
}

resource "aws_default_network_acl" "internal_default_nacl" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    rule_no    = 100
    protocol   = "icmp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    protocol   = "icmp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
  }

  tags = {
    Name        = "Production Internal Default NACL"
    environment = "prod"
  }
}

# -----------------------------
# Outputs
# -----------------------------
output "external_vpc_id" {
  value = aws_vpc.external.id
}

output "internal_vpc_id" {
  value = aws_vpc.internal.id
}

output "external_subnet_ids" {
  value = aws_subnet.external[*].id
}

output "internal_subnet_ids" {
  value = aws_subnet.internal[*].id
}
```

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "prefix" {
  description = "Resource prefix"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional existing ACM certificate ARN"
  type        = string
  default     = null
}

variable "url" {
  description = "Optional URL override for webhook"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired task count"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type"
  type        = string
  default     = "FARGATE_SPOT"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
  webhook_url = coalesce(var.url, "https://${aws_lb.main.dns_name}")
}

# ---------------- Networking ----------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = "${var.prefix}-vpc" }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet("10.0.0.0/16", 8, 4 + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags = { Name = "${var.prefix}-public-${count.index}" }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = local.azs[count.index]
  tags = { Name = "${var.prefix}-private-${count.index}" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = { Name = "${var.prefix}-igw" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "${var.prefix}-public-rt" }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- Security groups ----------------
resource "aws_security_group" "alb" {
  name_prefix = "${var.prefix}-alb-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = { Name = "${var.prefix}-alb-sg" }
}

resource "aws_security_group" "ecs" {
  name_prefix = "${var.prefix}-ecs-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = { Name = "${var.prefix}-ecs-sg" }
}

resource "aws_security_group" "efs" {
  name_prefix = "${var.prefix}-efs-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = { Name = "${var.prefix}-efs-sg" }
}

# ---------------- EFS ----------------
resource "aws_efs_file_system" "main" {
  encrypted = true
  creation_token = "${var.prefix}-efs"
  tags = { Name = "${var.prefix}-efs" }
}

resource "aws_efs_mount_target" "main" {
  count           = 3
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id
  root_directory {
    path = "/n8n"
    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "777"
    }
  }
  posix_user {
    gid = 1000
    uid = 1000
  }
  tags = { Name = "${var.prefix}-ap" }
}

# ---------------- Certificate ----------------
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  key_algorithm   = "RSA"
  private_key_pem = tls_private_key.self_signed.private_key_pem
  subject {
    common_name  = "n8n.internal"
    organization = "n8n"
  }
  validity_period_hours = 8760
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
  dns_servers = []
  dns_names   = ["n8n.internal"]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  certificate_body = tls_self_signed_cert.self_signed.cert_pem
  private_key      = tls_private_key.self_signed.private_key_pem
}

locals {
  acm_certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn
}

# ---------------- ALB ----------------
resource "aws_lb" "main" {
  name               = "${var.prefix}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  drop_invalid_header_fields = true
}

resource "aws_lb_target_group" "main" {
  name        = "${var.prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.acm_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ---------------- ECS ----------------
resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"
  setting {
    name  = "containerInsights"
    value = "disabled"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name = aws_ecs_cluster.main.name
  capacity_providers = [
    "FARGATE",
    "FARGATE_SPOT",
  ]
  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name              = "/${var.prefix}-logs"
  retention_in_days = 1
}

resource "aws_iam_role" "execution" {
  name = "${var.prefix}-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "execution_logs" {
  name = "${var.prefix}-execution-logs"
  role = aws_iam_role.execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams"
      ]
      Resource = [
        aws_cloudwatch_log_group.main.arn,
        "${aws_cloudwatch_log_group.main.arn}:*"
      ]
    }]
  })
}

resource "aws_iam_role" "task" {
  name = "${var.prefix}-task-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.prefix}-task-logs"
  role = aws_iam_role.task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams"
      ]
      Resource = [
        aws_cloudwatch_log_group.main.arn,
        "${aws_cloudwatch_log_group.main.arn}:*"
      ]
    }]
  })
}

resource "aws_iam_role_policy_attachment" "execution_ecr" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-data"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      root_directory     = "/"
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 5678
          protocol      = "tcp"
        }
      ]
      environment = [
        { name = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN", value = "true" },
        { name = "WEBHOOK_URL", value = local.webhook_url }
      ]
      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.main.name
          awslogs-region        = "us-east-1"
          awslogs-stream-prefix = "n8n"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "main" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count
  launch_type     = null

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [aws_lb_listener.http]
}

This Terraform configuration deploys an isolated AWS development network named "lambda-rds-dev" with:

- A VPC (10.32.0.0/20) with DNS hostnames, a locked-down default security group, and a default NACL allowing all traffic
- Four subnets across two AZs: two DB subnets, a Lambda subnet, and a bastion subnet (no public IP auto-assign)
- An Internet Gateway attached to a public route table associated with the bastion subnet
- Three security groups: PostgreSQL DB (ingress 5432 from bastion/lambda SGs, egress to VPC CIDR), Lambda functions (egress to VPC CIDR), and bastion host (SSH from VPC CIDR, egress only to the DB SG)

