terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "admin_cidr" {
  description = "Placeholder admin range for bastion SSH access"
  type        = string
  default     = "203.0.113.0/24"
}

# ---------------- VPC ----------------
resource "aws_vpc" "quasar" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Quasar"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

# ---------------- Subnets ----------------
resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name        = "Quasar RDS - 1A"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = "us-east-1e"

  tags = {
    Name        = "Quasar RDS - 1E"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Egress limited to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = {
    Name        = "Quasar-Bastion"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA proxy load balancer security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Egress limited to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = {
    Name        = "Quasar-HA-Proxy"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins UI from HA-Proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Egress limited to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = {
    Name        = "Quasar-Jenkins"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute node security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from Jenkins"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Egress limited to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = {
    Name        = "Quasar-ETL"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from ETL"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Egress limited to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = {
    Name        = "Quasar-PostgreSQL"
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}
