terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the SQS resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable queue name. Any '.fifo' suffix is stripped."
  type        = string
  default     = "my-queue"
}

variable "use_name_prefix" {
  description = "Use name as a prefix instead of the exact queue name."
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope for high throughput FIFO queues."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Throughput limit for high throughput FIFO queues."
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Delay seconds for the queue."
  type        = number
  default     = null
}

variable "max_message_size" {
  description = "Maximum message size in bytes."
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds."
  type        = number
  default     = null
}

variable "receive_wait_time_seconds" {
  description = "Long polling wait time in seconds."
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds."
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS key ID for encryption. Overrides managed SSE."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds."
  type        = number
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create a policy for the main queue."
  type        = bool
  default     = false
}

variable "create_dlq_queue_policy" {
  description = "Whether to create a policy for the DLQ."
  type        = bool
  default     = false
}

variable "override_queue_policy" {
  description = "Custom IAM policy document overriding the main queue policy."
  type        = string
  default     = null
}

variable "override_dlq_policy" {
  description = "Custom IAM policy document overriding the DLQ policy."
  type        = string
  default     = null
}

variable "queue_policy_statements" {
  description = "Additional custom statements merged into the main queue policy."
  type        = any
  default     = []
}

variable "dlq_policy_statements" {
  description = "Additional custom statements merged into the DLQ policy."
  type        = any
  default     = []
}

variable "create_dlq" {
  description = "Whether to provision a dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the queue name for the DLQ."
  type        = string
  default     = "-dlq"
}

variable "dlq_message_retention_seconds" {
  description = "DLQ message retention override."
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "DLQ managed SSE override."
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "DLQ custom KMS key override."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "DLQ KMS data key reuse period override."
  type        = number
  default     = null
}

variable "max_receive_count" {
  description = "Max receive count for the redrive policy."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Attach a redrive allow policy to the DLQ restricting redrive to the source queue."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  enabled = var.create

  base_name = trimsuffix(var.name, ".fifo")

  queue_name = var.fifo_queue ? (
    var.use_name_prefix ? "${local.base_name}.fifo" : "${local.base_name}.fifo"
  ) : local.base_name

  dlq_name = var.fifo_queue ? "${local.base_name}${var.dlq_name_suffix}.fifo" : "${local.base_name}${var.dlq_name_suffix}"

  # Encryption settings for the main queue
  main_sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  main_kms_master_key_id       = var.kms_master_key_id

  # DLQ inherits main queue settings unless overridden
  dlq_sqs_managed_sse_enabled = coalesce(var.dlq_sqs_managed_sse_enabled, var.dlq_kms_master_key_id == null ? var.sqs_managed_sse_enabled : null)
  dlq_kms_master_key_id       = coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id)
  dlq_kms_data_key_reuse      = coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds)

  redrive_policy = var.create_dlq ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "sqs:SendMessage"
        Resource  = "*"
        Condition = {
          ArnNotEquals = {
            "aws:SourceArn" = aws_sqs_queue.dlq[0].arn
          }
        }
      }
    ]
  }) : null

  redrive_allow_policy = (var.create_dlq && var.create_dlq_redrive_allow_policy) ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:RedriveFromQueue"
        Resource  = "*"
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.this[0].arn
          }
        }
      }
    ]
  }) : null

  default_queue_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:SendMessage"
        Resource  = aws_sqs_queue.this[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.this[0].arn
          }
        }
      }
    ]
  })

  default_dlq_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:SendMessage"
        Resource  = aws_sqs_queue.dlq[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.this[0].arn
          }
        }
      }
    ]
  })

  queue_policy = var.override_queue_policy != null ? var.override_queue_policy : jsonencode(
    merge(
      jsondecode(local.default_queue_policy),
      { Statement = concat(jsondecode(local.default_queue_policy).Statement, var.queue_policy_statements) }
    )
  )

  dlq_policy = var.override_dlq_policy != null ? var.override_dlq_policy : jsonencode(
    merge(
      jsondecode(local.default_dlq_policy),
      { Statement = concat(jsondecode(local.default_dlq_policy).Statement, var.dlq_policy_statements) }
    )
  )
}

# ------------------------------------------------------------------------------
# Resources
# ------------------------------------------------------------------------------

resource "aws_sqs_queue" "this" {
  count = local.enabled ? 1 : 0

  name                              = local.queue_name
  fifo_queue                        = var.fifo_queue
  content_based_deduplication       = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope               = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit             = var.fifo_queue ? var.fifo_throughput_limit : null
  delay_seconds                     = var.delay_seconds
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  visibility_timeout_seconds        = var.visibility_timeout_seconds
  sqs_managed_sse_enabled           = local.main_sqs_managed_sse_enabled
  kms_master_key_id                 = local.main_kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  redrive_policy                    = local.redrive_policy

  tags = merge(
    { Name = local.queue_name },
    var.tags
  )
}

resource "aws_sqs_queue" "dlq" {
  count = local.enabled && var.create_dlq ? 1 : 0

  name                              = local.dlq_name
  fifo_queue                        = var.fifo_queue
  content_based_deduplication       = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope               = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit             = var.fifo_queue ? var.fifo_throughput_limit : null
  message_retention_seconds         = var.dlq_message_retention_seconds
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled
  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse
  redrive_allow_policy              = local.redrive_allow_policy

  tags = merge(
    { Name = local.dlq_name },
    var.tags
  )
}

resource "aws_sqs_queue_policy" "this" {
  count = local.enabled && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = local.queue_policy
}

resource "aws_sqs_queue_policy" "dlq" {
  count = local.enabled && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = local.dlq_policy
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "queue_arn" {
  description = "ARN of the main queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "URL of the main queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "Name of the main queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_arn" {
  description = "ARN of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "URL of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "create" {
  description = "Global creation control"
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function to deploy"
  type        = string
  default     = "my-lambda-function"
}

variable "alias_name" {
  description = "Lambda alias name for blue/green traffic shifting"
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Current (blue) Lambda version"
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Target (green) Lambda version"
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional Lambda hook ARN run before traffic shift"
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional Lambda hook ARN run after traffic shift"
  type        = string
  default     = null
}

variable "app_name" {
  description = "CodeDeploy application name"
  type        = string
  default     = "my-lambda-app"
}

variable "create_app" {
  type    = bool
  default = false
}

variable "use_existing_app" {
  type    = bool
  default = false
}

variable "deployment_group_name" {
  type    = string
  default = "my-lambda-deployment-group"
}

variable "create_deployment_group" {
  type    = bool
  default = false
}

variable "use_existing_deployment_group" {
  type    = bool
  default = false
}

variable "deployment_config_name" {
  type    = string
  default = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "deployment_style" {
  type    = string
  default = "WITH_TRAFFIC_CONTROL"
}

variable "deployment_type" {
  type    = string
  default = "BLUE_GREEN"
}

variable "auto_rollback_enabled" {
  type    = bool
  default = true
}

variable "auto_rollback_events" {
  type    = list(string)
  default = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarms" {
  description = "Optional list of CloudWatch alarm names to monitor"
  type        = list(string)
  default     = []
}

variable "alarm_enabled" {
  type    = bool
  default = true
}

variable "trigger_target_arns" {
  description = "Optional SNS topic ARNs for notification triggers"
  type        = list(string)
  default     = []
}

variable "trigger_events" {
  type    = list(string)
  default = ["DeploymentSuccess", "DeploymentFailure"]
}

variable "create_codedeploy_role" {
  type    = bool
  default = true
}

variable "codedeploy_role_name" {
  type    = string
  default = "codedeploy-lambda-role"
}

variable "codedeploy_service_principals" {
  type    = list(string)
  default = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  type    = bool
  default = true
}

variable "attach_triggers_policy" {
  type    = bool
  default = false
}

variable "create_deployment" {
  type    = bool
  default = false
}

variable "aws_cli_command" {
  type    = string
  default = "aws"
}

variable "get_deployment_sleep_timer" {
  type    = number
  default = 5
}

variable "save_deploy_script" {
  type    = bool
  default = false
}

variable "deploy_script_path" {
  type    = string
  default = "./deploy.sh"
}

variable "appspec_path" {
  type    = string
  default = "./appspec.json"
}

variable "run_deployment" {
  type    = bool
  default = false
}

variable "force_deploy" {
  description = "Change this UUID to force a new deployment run"
  type        = string
  default     = "00000000-0000-0000-0000-000000000000"
}

# ---------------- Locals ----------------

locals {
  create_app = var.create && var.create_app && !var.use_existing_app

  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group

  hooks = compact([
    var.before_allow_traffic_hook_arn != null ? var.before_allow_traffic_hook_arn : "",
    var.after_allow_traffic_hook_arn != null ? var.after_allow_traffic_hook_arn : "",
  ])

  appspec = jsonencode({
    version = "0.0"
    Resources = [{
      MyFunction = {
        Type     = "AWS::Lambda::Function"
        Name     = var.function_name
        Alias    = var.alias_name
        CurrentVersion = var.current_version
        TargetVersion  = var.target_version
      }
    }]
    Hooks = length(local.hooks) > 0 ? [
      for h in local.hooks : { Name = h }
    ] : null
  })

  appspec_clean = length(local.hooks) > 0 ? local.appspec : replace(local.appspec, ",\"Hooks\":null", "")

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    AWS_CLI=${var.aws_cli_command}
    APP_NAME=${var.app_name}
    DEPLOYMENT_GROUP=${var.deployment_group_name}
    SLEEP_TIMER=${var.get_deployment_sleep_timer}

    echo "Creating CodeDeploy deployment for ${var.function_name}..."
    DEPLOYMENT_ID=$($AWS_CLI deploy create-deployment \
      --application-name "$APP_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP" \
      --deployment-config-name ${var.deployment_config_name} \
      --description "Blue/Green deployment of ${var.function_name} from ${var.current_version} to ${var.target_version}" \
      --file-exists-behavior OVERWRITE \
      --revision '{"revisionType":"AppSpecContent","appSpecContent":${jsonencode(local.appspec_clean)}}' \
      --query 'deploymentId' --output text)

    echo "Deployment ID: $DEPLOYMENT_ID"

    echo "Waiting for deployment to complete (polling every $SLEEP_TIMER seconds)..."
    while true; do
      STATUS=$($AWS_CLI deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)
      echo "Deployment status: $STATUS"
      if [ "$STATUS" = "Succeeded" ]; then
        echo "Deployment succeeded."
        break
      elif [ "$STATUS" = "Failed" ] || [ "$STATUS" = "Stopped" ]; then
        echo "Deployment $STATUS."
        exit 1
      fi
      sleep "$SLEEP_TIMER"
    done
  EOT
}

# ---------------- IAM Role for CodeDeploy ----------------

data "aws_iam_policy_document" "codedeploy_assume" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name               = var.codedeploy_role_name
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume[0].json
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "hooks_invoke" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hooks) > 0 ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hooks
  }
}

resource "aws_iam_role_policy" "hooks_invoke" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hooks) > 0 ? 1 : 0

  name   = "${var.codedeploy_role_name}-hooks-invoke"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks_invoke[0].json
}

data "aws_iam_policy_document" "triggers_publish" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_target_arns) > 0 ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = var.trigger_target_arns
  }
}

resource "aws_iam_role_policy" "triggers_publish" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_target_arns) > 0 ? 1 : 0

  name   = "${var.codedeploy_role_name}-triggers-publish"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers_publish[0].json
}

# ---------------- CodeDeploy Application ----------------

resource "aws_codedeploy_app" "this" {
  count = local.create_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"
}

data "aws_codedeploy_app" "existing" {
  count = var.create && var.use_existing_app ? 1 : 0

  name = var.app_name
}

locals {
  app_id = local.create_app ? aws_codedeploy_app.this[0].id : (var.use_existing_app ? data.aws_codedeploy_app.existing[0].id : null)
}

# ---------------- CodeDeploy Deployment Group ----------------

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group ? 1 : 0

  app_name              = var.app_name
  deployment_group_name = var.deployment_group_name
  service_role_arn      = var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : null
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = var.deployment_style
    deployment_type   = var.deployment_type
    allow_green_deployments = true
    allow_blue_deployments  = true
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_enabled ? var.auto_rollback_events : []
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarms) > 0 ? [1] : []

    content {
      enabled = var.alarm_enabled
      alarms  = var.alarms
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_target_arns

    content {
      trigger_events       = var.trigger_events
      trigger_name         = "notify-${trigger.key}"
      trigger_target_arn   = trigger.value
    }
  }

  depends_on = [aws_iam_role_policy_attachment.codedeploy_lambda]
}

# ---------------- AppSpec & Deploy Script ----------------

resource "local_file" "appspec" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  content  = local.appspec_clean
  filename = var.appspec_path
}

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  content         = local.deploy_script
  filename        = var.deploy_script_path
  file_permission = "0755"
}

# ---------------- Deployment Provisioner ----------------

resource "null_resource" "deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy    = var.force_deploy
    function_name   = var.function_name
    target_version  = var.target_version
    appspec         = local.appspec_clean
    script          = local.deploy_script
  }

  provisioner "local-exec" {
    command = var.save_deploy_script ? var.deploy_script_path : local.deploy_script
    interpreter = var.save_deploy_script ? ["/bin/bash"] : ["/bin/bash", "-c"]
  }
}

# ---------------- Outputs ----------------

output "codedeploy_role_arn" {
  value = var.create && var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : null
}

output "appspec_json" {
  value = var.create && var.create_deployment ? local.appspec_clean : null
}

output "deploy_script" {
  value = var.create && var.create_deployment ? local.deploy_script : null
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.16.0.0/16"
}

variable "vpc_name_prefix" {
  default = "tf-project"
}

variable "max_subnets" {
  default = 6
}

variable "web_subnet_cidrs" {
  type    = list(string)
  default = ["10.16.1.0/24", "10.16.2.0/24"]
}

variable "app_subnet_cidrs" {
  type    = list(string)
  default = ["10.16.11.0/24", "10.16.12.0/24"]
}

variable "db_subnet_cidrs" {
  type    = list(string)
  default = ["10.16.21.0/24"]
}

variable "reserved_subnet_cidrs" {
  type    = list(string)
  default = ["10.16.31.0/24"]
}

variable "interface_endpoints" {
  type = map(object({
    subnet_ids      = list(string)
    security_groups = list(string)
    private_dns     = bool
  }))
  default = {}
}

variable "gateway_endpoint_service_name" {
  type    = string
  default = ""
}

resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnets, length(data.aws_availability_zones.available.names))
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}"
  }
}

resource "aws_internet_gateway" "this" {
  count  = length(var.web_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-igw"
  }
}

resource "aws_route_table" "public" {
  count  = length(var.web_subnet_cidrs) > 0 ? 1 : 0
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-public"
  }
}

resource "aws_route_table" "private" {
  count  = (length(var.app_subnet_cidrs) + length(var.db_subnet_cidrs) + length(var.reserved_subnet_cidrs)) > 0 ? 1 : 0
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-private"
  }
}

resource "aws_subnet" "web" {
  count             = length(var.web_subnet_cidrs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.web_subnet_cidrs[count.index]
  availability_zone = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-web-${count.index + 1}"
  }
}

resource "aws_subnet" "app" {
  count             = length(var.app_subnet_cidrs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.app_subnet_cidrs[count.index]
  availability_zone = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-app-${count.index + 1}"
  }
}

resource "aws_subnet" "db" {
  count             = length(var.db_subnet_cidrs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.db_subnet_cidrs[count.index]
  availability_zone = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-db-${count.index + 1}"
  }
}

resource "aws_subnet" "reserved" {
  count             = length(var.reserved_subnet_cidrs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.reserved_subnet_cidrs[count.index]
  availability_zone = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-reserved-${count.index + 1}"
  }
}

resource "aws_route_table_association" "web" {
  count          = length(var.web_subnet_cidrs)
  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "app" {
  count          = length(var.app_subnet_cidrs)
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "db" {
  count          = length(var.db_subnet_cidrs)
  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count          = length(var.reserved_subnet_cidrs)
  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_vpc_endpoint" "interface" {
  for_each            = var.interface_endpoints
  vpc_id              = aws_vpc.this.id
  service_name        = each.key
  vpc_endpoint_type   = "Interface"
  subnet_ids          = each.value.subnet_ids
  security_group_ids  = each.value.security_groups
  private_dns_enabled = each.value.private_dns

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-${each.key}"
  }
}

resource "aws_vpc_endpoint" "gateway" {
  count             = var.gateway_endpoint_service_name != "" ? 1 : 0
  vpc_id            = aws_vpc.this.id
  service_name      = var.gateway_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id]

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}-gateway"
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "vpc_name" {
  value = aws_vpc.this.tags["Name"]
}

output "web_subnet_ids" {
  value = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  value = aws_subnet.app[*].id
}

output "db_subnet_ids" {
  value = aws_subnet.db[*].id
}

output "reserved_subnet_ids" {
  value = aws_subnet.reserved[*].id
}

output "azs" {
  value = random_shuffle.azs.result
}
```

This Terraform program creates a complete multi-tier VPC network in AWS:

**Description:**
- **VPC "main"** (10.0.0.0/16) with DNS support/hostnames, an Internet Gateway "ig", DHCP options (domain "internal", resolvers = VPC+2 resolver and 8.8.8.8), and a private Route 53 zone for the internal domain associated with the VPC.
- **Five subnets** (no public IP auto-assign), each with its own route table routing 0.0.0.0/0 to the IGW: reserved, sandbox, web, database, gameserver.
- **Network ACLs**: sandbox (all TCP both ways), web (inbound SSH/HTTP/HTTPS/ephemeral, all TCP out), database (TCP only to/from web & gameserver CIDRs), gameserver (inbound SSH, 27015/27020 TCP+UDP, ephemeral TCP+UDP; all TCP+UDP out).
- **Security groups**: "Home SSH" (SSH from admin CIDRs variable + self, egress VPC only) and "Packer SSH" (SSH from VPC CIDR + self, egress VPC only).

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "internal_domain" {
  description = "Internal domain name for DHCP and private Route53 zone"
  type        = string
  default     = "internal"
}

variable "admin_cidrs" {
  description = "CIDR blocks allowed SSH access for admins"
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

locals {
  vpc_cidr     = "10.0.0.0/16"
  web_cidr     = "10.0.2.0/24"
  db_cidr      = "10.0.3.0/24"
  game_cidr    = "10.0.4.0/22"
  sandbox_cidr = "10.0.1.0/24"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "main" }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = { Name = "ig" }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = ["169.254.169.253", "8.8.8.8"]

  tags = { Name = "main" }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain
  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = { Name = var.internal_domain }
}

# Route tables
resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }
  tags = { Name = "reserved" }
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }
  tags = { Name = "sandbox" }
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }
  tags = { Name = "web" }
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }
  tags = { Name = "database" }
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }
  tags = { Name = "gameserver" }
}

# Subnets
resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false
  route_table_id          = aws_route_table.reserved.id

  tags = { Name = "reserved" }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.sandbox_cidr
  map_public_ip_on_launch = false
  route_table_id          = aws_route_table.sandbox.id

  tags = { Name = "sandbox" }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.web_cidr
  map_public_ip_on_launch = false
  route_table_id          = aws_route_table.web.id

  tags = { Name = "web" }
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.db_cidr
  map_public_ip_on_launch = false
  route_table_id          = aws_route_table.database.id

  tags = { Name = "database" }
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.game_cidr
  map_public_ip_on_launch = false
  route_table_id          = aws_route_table.gameserver.id

  tags = { Name = "gameserver" }
}

# NACLs
resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.sandbox.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = { Name = "sandbox" }
}

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.web.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = { Name = "web" }
}

resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.database.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.web_cidr
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
