  }

  tags = { Name = "gameserver" }
}

# Security groups
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "SSH access for home admins"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.admin_cidrs
    content {
      description = "SSH from admin"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = { Name = "Home SSH" }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "SSH access for Packer builds"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = { Name = "Packer SSH" }
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env" {
  description = "Environment name prefix for resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  description = "CIDR blocks for private application subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "db_subnet_cidrs" {
  description = "CIDR blocks for private database subnets"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}vpc"
  }
}

# ---------------- Internet Gateway ----------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
  }
}

# ---------------- Public Subnets ----------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-${local.azs[count.index]}"
  }
}

# ---------------- Public Route Table ----------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- Elastic IPs & NAT Gateways ----------------
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "nat" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ---------------- Private Application Subnets ----------------
resource "aws_subnet" "private_app" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_app_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.name_prefix}private-app-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "private_app" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}private-app-rt-${local.azs[count.index]}"
  }
}

resource "aws_route" "private_app_nat" {
  count = 3

  route_table_id         = aws_route_table.private_app[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[count.index].id
}

resource "aws_route_table_association" "private_app" {
  count = 3

  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

# ---------------- Database Subnets ----------------
resource "aws_subnet" "db" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.db_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.name_prefix}db-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "db" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}db-rt"
  }
}

resource "aws_route" "db_local" {
  route_table_id         = aws_route_table.db.id
  destination_cidr_block = var.vpc_cidr
  vpc_peering_connection_id = aws_vpc.main.id
}

resource "aws_route_table_association" "db" {
  count = 3

  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.db.id
}

# ---------------- Outputs ----------------
output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_app_subnet_ids" {
  value = aws_subnet.private_app[*].id
}

output "db_subnet_ids" {
  value = aws_subnet.db[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.nat[*].id
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_account_alias" "current" {}

resource "random_string" "suffix" {
  count   = var.use_random_suffix ? 1 : 0
  length  = 8
  special = false
  upper   = false
}

locals {
  bucket_name = coalesce(
    var.use_account_alias_prefix ? "${data.aws_iam_account_alias.current.account_alias}-${var.bucket_name}" : null,
    var.use_random_suffix ? "${var.bucket_name}-${random_string.suffix[0].result}" : null,
    var.bucket_name
  )
}

variable "bucket_name" {
  type    = string
  default = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  type    = bool
  default = false
}

variable "use_random_suffix" {
  type    = bool
  default = false
}

variable "custom_bucket_policy" {
  type    = string
  default = null
}

variable "enable_s3_public_access_block" {
  type    = bool
  default = true
}

variable "kms_master_key_id" {
  type    = string
  default = null
}

variable "bucket_key_enabled" {
  type    = bool
  default = false
}

variable "versioning_status" {
  type    = string
  default = "Enabled"
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "enable_analytics" {
  type    = bool
  default = true
}

variable "enable_bucket_inventory" {
  type    = bool
  default = false
}

variable "logging_bucket" {
  type    = string
  default = null
}

variable "transfer_acceleration" {
  type    = string
  default = null
}

variable "s3_bucket_acl" {
  type    = string
  default = null
}

variable "cors_rules" {
  type = list(map(any))
  default = []
}

resource "aws_s3_bucket" "this" {
  bucket         = local.bucket_name
  force_destroy  = var.force_destroy
}

resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.enable_s3_public_access_block ? 1 : 0
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    bucket_key_enabled = var.bucket_key_enabled

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-expiration"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "analytics-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "inventory-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }
}

resource "aws_s3_bucket_transition_default_minimum_object_size" "this" {
  bucket                = aws_s3_bucket.this.id
  transition_default_minimum_object_size = "all_storage_classes_128K"
}

resource "aws_s3_bucket_analytics_configuration" "this" {
  count  = var.enable_analytics ? 1 : 0
  bucket = aws_s3_bucket.this.id
  name   = "EntireBucket"

  storage_class_analysis {
    export_destination {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "CSV"

      prefix {
        with_prefix = "_AWSBucketAnalytics/"
      }
    }
  }
}

resource "aws_s3_bucket_inventory" "this" {
  count  = var.enable_bucket_inventory ? 1 : 0
  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketDailyInventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "ORC"

      prefix {
        with_prefix = "_AWSBucketInventory/"
      }
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count   = var.transfer_acceleration != null ? 1 : 0
  bucket  = aws_s3_bucket.this.id
  status  = var.transfer_acceleration
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.s3_bucket_acl != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  acl = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      allowed_methods = cors_rule.value["allowed_methods"]
      allowed_origins = cors_rule.value["allowed_origins"]
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

locals {
  secure_transport_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "AllowS3ServicePrincipalWrite"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  final_policy = var.custom_bucket_policy != null ? jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      jsondecode(local.secure_transport_policy).Statement,
      jsondecode(var.custom_bucket_policy).Statement
    )
  }) : local.secure_transport_policy
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = local.final_policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

