terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "Development"
}

variable "extra_tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256, aws:kms, or none"
  type        = string
  default     = "AES256"
}

variable "kms_master_key_id" {
  description = "KMS key ID for aws:kms encryption"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether S3 bucket key is enabled for KMS"
  type        = bool
  default     = true
}

variable "create_public_access_block" {
  description = "Whether to create the public access block"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  type    = bool
  default = true
}

variable "block_public_policy" {
  type    = bool
  default = true
}

variable "ignore_public_acls" {
  type    = bool
  default = true
}

variable "restrict_public_buckets" {
  type    = bool
  default = true
}

variable "acl" {
  description = "Canned ACL"
  type        = string
  default     = "private"
}

variable "grants" {
  description = "JSON-encoded list of grants, e.g. '[{\"type\":\"CanonicalUser\",\"permission\":\"FULL_CONTROL\",\"id\":\"<canonical-id>\"}]'"
  type        = string
  default     = ""
}

variable "control_object_ownership" {
  type    = bool
  default = false
}

variable "object_ownership" {
  type    = string
  default = "ObjectWriter"
}

variable "versioning_enabled" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "mfa" {
  description = "MFA device ARN and code for MFA delete, e.g. 'arn:aws:iam::123456789012:mfa/user 123456'"
  type        = string
  default     = null
}

variable "bucket_logging" {
  type    = bool
  default = false
}

variable "log_bucket_name" {
  type    = string
  default = null
}

variable "log_prefix" {
  type    = string
  default = "logs/"
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}

variable "object_lock_mode" {
  type    = string
  default = "GOVERNANCE"
}

variable "object_lock_days" {
  type    = number
  default = 30
}

variable "website_config" {
  description = "JSON website configuration, e.g. '{\"index_document\":\"index.html\",\"error_document\":\"error.html\"}'"
  type        = string
  default     = ""
}

variable "intelligent_tiering" {
  description = "Map of intelligent tiering configs: name -> {filter_prefix, filter_tags, target_days, target_storage_class}"
  type        = map(any)
  default     = {}
}

variable "metrics" {
  description = "Map of CloudWatch metrics configs: name -> {filter_prefix, filter_tags}"
  type        = map(any)
  default     = {}
}

variable "cors_rules" {
  description = "List of CORS rule maps: allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds"
  type        = any
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps: id, prefix, tags, enabled, abort_incomplete_multipart_upload_days, expiration_days, expiration_date, transition_days, transition_storage_class"
  type        = any
  default     = []
}

data "aws_caller_identity" "current" {}

locals {
  tags = merge(
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    },
    var.extra_tags
  )

  grant_list = var.grants != "" ? jsondecode(var.grants) : []
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  # ACL/grants handled via aws_s3_bucket_acl below
  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_public_access_block ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.sse_algorithm != "none" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.versioning_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
    mfa        = var.mfa_delete ? var.mfa : null
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.bucket_logging && var.log_bucket_name != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.log_bucket_name
  target_prefix = var.log_prefix
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website_config != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = jsondecode(var.website_config)["index_document"]
  }

  dynamic "error_document" {
    for_each = contains(keys(jsondecode(var.website_config)), "error_document") ? [1] : []
    content {
      key = jsondecode(var.website_config)["error_document"]
    }
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = length(local.grant_list) == 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl
}

resource "aws_s3_bucket_acl" "grants" {
  count = length(local.grant_list) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "grant" {
    for_each = local.grant_list
    content {
      permission = grant.value["permission"]
      type       = grant.value["type"]
      id         = grant.value["type"] == "CanonicalUser" ? lookup(grant.value, "id", data.aws_caller_identity.current.id) : null
      uri        = grant.value["type"] == "Group" ? grant.value["uri"] : null
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.intelligent_tiering

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = lookup(each.value, "filter_prefix", null) != null ? [1] : []
    content {
      prefix = each.value["filter_prefix"]
      tags   = lookup(each.value, "filter_tags", {})
    }
  }

  tiering {
    status = "Enabled"
    storage_class = lookup(each.value, "target_storage_class", "INTELLIGENT_TIERING") == "INTELLIGENT_TIERING" ? "INTELLIGENT_TIERING" : each.value["target_storage_class"]
    days          = each.value["target_days"]
  }
}

resource "aws_s3_bucket_metric" "this" {
  for_each = var.metrics

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = lookup(each.value, "filter_prefix", null) != null ? [1] : []
    content {
      prefix = each.value["filter_prefix"]
      tags   = lookup(each.value, "filter_tags", {})
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      allowed_methods = cors_rule.value["allowed_methods"]
      allowed_origins = cors_rule.value["allowed_origins"]
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value["id"]
      status = lookup(rule.value, "enabled", true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = lookup(rule.value, "prefix", null) != null || lookup(rule.value, "tags", null) != null ? [1] : []
        content {
          prefix = lookup(rule.value, "prefix", null)
          tags   = lookup(rule.value, "tags", {})
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = lookup(rule.value, "abort_incomplete_multipart_upload_days", null) != null ? [1] : []
        content {
          days_after_initiation = rule.value["abort_incomplete_multipart_upload_days"]
        }
      }

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration_days", null) != null || lookup(rule.value, "expiration_date", null) != null ? [1] : []
        content {
          days = lookup(rule.value, "expiration_days", null)
          date = lookup(rule.value, "expiration_date", null)
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transition_days", null) != null ? [1] : []
        content {
          days          = rule.value["transition_days"]
          storage_class = rule.value["transition_storage_class"]
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Explicit bucket name (max 63 chars). Conflicts with name_prefix."
  type        = string
  default     = null
  validation {
    condition     = var.name == null || length(var.name) <= 63
    error_message = "name must be at most 63 characters."
  }
}

variable "name_prefix" {
  description = "Bucket name prefix (max 37 chars)."
  type        = string
  default     = null
  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "name_prefix must be at most 37 characters."
  }
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "object_ownership" {
  description = "BucketOwnerEnforced or ObjectWriter"
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be BucketOwnerEnforced or ObjectWriter."
  }
}

variable "acl" {
  description = "Canned ACL, only applied when object_ownership is ObjectWriter"
  type        = string
  default     = "private"
}

variable "block_public_acls" {
  type    = bool
  default = true
}
variable "block_public_policy" {
  type    = bool
  default = true
}
variable "ignore_public_acls" {
  type    = bool
  default = true
}
variable "restrict_public_buckets" {
  type    = bool
  default = true
}

variable "kms_key_arn" {
  type    = string
  default = null
}

variable "versioning_enabled" {
  type    = bool
  default = false
}

variable "custom_bucket_policy" {
  description = "Optional custom policy JSON merged with enforced policies"
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "ARNs of buckets allowed to log into this bucket (enables logging permissions policy)"
  type        = list(string)
  default     = null
}

variable "enable_eventbridge" {
  type    = bool
  default = false
}

variable "server_access_logging_target_bucket" {
  description = "Target bucket for server access logging. Cannot be combined with object lock."
  type        = string
  default     = null
}
variable "server_access_logging_target_prefix" {
  type    = string
  default = "log/"
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}
variable "object_lock_mode" {
  type    = string
  default = null
}
variable "object_lock_days" {
  type    = number
  default = null
}
variable "object_lock_years" {
  type    = number
  default = null
}

variable "replication_rules" {
  description = "List of replication rule maps: id, status, destination_bucket_arn, priority, prefix, delete_marker_replication, storage_class"
  type = list(object({
    id                        = string
    status                    = string
    destination_bucket_arn    = string
    priority                  = number
    prefix                    = optional(string, "")
    delete_marker_replication = optional(bool, true)
    storage_class             = optional(string, null)
  }))
  default = []
}

variable "replication_role_arn" {
  type    = string
  default = null
}

variable "inventory_configs" {
  description = "List of inventory configs: id, destination_bucket_arn, frequency, format (CSV/ORC/PARQUET), sse (AES256 or KMS key id), included_object_versions, prefix"
  type = list(object({
    id                      = string
    destination_bucket_arn  = string
    frequency               = string
    format                  = string
    sse                     = optional(string, "AES256")
    sse_kms_key_id          = optional(string, null)
    included_object_versions = optional(string, "All")
    prefix                  = optional(string, null)
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rule maps"
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string), ["*"])
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number, 3000)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules: id, prefix, tags, expiration_days, transition_days, transition_storage_class, noncurrent_version_expiration_days, noncurrent_version_transition_days, noncurrent_version_transition_storage_class, abort_incomplete_multipart_days"
  type = list(object({
    id                                     = string
    prefix                                 = optional(string, null)
    tags                                   = optional(map(string), null)
    expiration_days                        = optional(number, null)
    transition_days                        = optional(number, null)
    transition_storage_class               = optional(string, null)
    noncurrent_version_expiration_days     = optional(number, null)
    noncurrent_version_transition_days     = optional(number, null)
    noncurrent_version_transition_storage_class = optional(string, null)
    abort_incomplete_multipart_days        = optional(number, null)
  }))
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}

locals {
  bucket_name = var.name != null ? var.name : null
  bucket_prefix = var.name == null && var.name_prefix != null ? var.name_prefix : null

  encryption_algorithm = var.kms_key_arn != null ? "aws:kms" : "AES256"

  ssl_deny_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforcedSSL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })

  logging_permissions_policy = var.logging_source_bucket_arns != null ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogsPolicy"
        Effect    = "Allow"
        Principal = { Service = "logging.s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          ArnLike = { "aws:SourceArn" = var.logging_source_bucket_arns }
        }
      }
    ]
  }) : null

  statements = concat(
    [jsondecode(local.ssl_deny_policy).Statement],
    local.logging_permissions_policy != null ? jsondecode(local.logging_permissions_policy).Statement : [],
    var.custom_bucket_policy != null ? jsondecode(var.custom_bucket_policy).Statement : []
  )

  combined_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.statements
  })
}

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  bucket_prefix       = local.bucket_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.encryption_algorithm
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = var.kms_key_arn != null
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = local.combined_policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.server_access_logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.server_access_logging_target_bucket
  target_prefix = var.server_access_logging_target_prefix
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled && var.object_lock_mode != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }
}

resource "aws_s3_bucket_notification" "this" {
  count  = var.enable_eventbridge ? 1 : 0
  bucket = aws_s3_bucket.this.id

  eventbridge = true
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn != null ? var.replication_role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      filter {
        prefix = rule.value.prefix
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = "Enabled"
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class

        metrics {
          status = "Enabled"
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0
  name  = "${coalesce(var.name, var.name_prefix != null ? var.name_prefix : "s3")}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0
  name  = "replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
      Resource = [aws_s3_bucket.this.arn]
      }, {
      Effect   = "Allow"
      Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging", "s3:GetObjectRetention"]
      Resource = ["${aws_s3_bucket.this.arn}/*"]
      }, {
      Effect   = "Allow"
      Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
      Resource = [for r in var.replication_rules : "${r.destination_bucket_arn}/*"]
    }]
  })
}

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for cfg in var.inventory_configs : cfg.id => cfg }

  bucket = aws_s3_bucket.this.id
  name   = each.value.id

  included_object_versions = each.value.included_object_versions

  schedule {
    frequency = each.value.frequency
  }

  destination {
    bucket {
      bucket_arn = each.value.destination_bucket_arn
      format     = each.value.format

      encryption {
        dynamic "sse_kms" {
          for_each = each.value.sse == "SSE-KMS" ? [1] : []
          content {
            kms_key_id = each.value.sse_kms_key_id
          }
        }
        dynamic "sse_s3" {
          for_each = each.value.sse == "SSE-S3" ? [1] : []
          content {}
        }
      }
    }
  }

  dynamic "filter" {
    for_each = each.value.prefix != null ? [1] : []
    content {
      prefix = each.value.prefix
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = "Enabled"

      filter {
        dynamic "and" {
          for_each = rule.value.prefix != null && rule.value.tags != null ? [1] : []
          content {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
        dynamic "prefix" {
          for_each = rule.value.prefix != null && rule.value.tags == null ? [1] : []
          content {
            prefix = rule.value.prefix
          }
        }
        dynamic "tag" {
          for_each = rule.value.prefix == null && rule.value.tags != null ? rule.value.tags : {}
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [1] : []
        content {
          days = rule.value.expiration_days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition_days != null ? [1] : []
        content {
          days          = rule.value.transition_days
          storage_class = rule.value.transition_storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_transition_days
          storage_class   = rule.value.noncurrent_version_transition_storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_days
        }
      }
    }
  }
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "remote_state_bucket_name" {
  description = "Name of the remote-state S3 bucket to deny access to"
  type        = string
  default     = "my-company-terraform-remote-state"
}

variable "designated_region" {
  description = "Single designated AWS region for S3 bucket creation"
  type        = string
  default     = "us-east-1"
}

# ------------------------------------------------------------------
# Account-wide security baselines
# ------------------------------------------------------------------

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "baseline" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# ------------------------------------------------------------------
# Developer: AWS-managed policy attachments
# ------------------------------------------------------------------

data "aws_iam_policy" "iam_read_only" {
  name = "IAMReadOnlyAccess"
}

data "aws_iam_policy" "iam_user_change_password" {
  name = "IAMUserChangePassword"
}

data "aws_iam_policy" "iam_user_ssh_keys" {
  name = "IAMUserSSHKeys"
}

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_read_only.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_change_password.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_ssh_keys.arn
}

# ------------------------------------------------------------------
# Developer: custom policy - manage personal access keys
# ------------------------------------------------------------------

resource "aws_iam_group_policy" "developer_personal_keys" {
  name  = "${var.group_name_prefix}_developer_personal_access_keys"
  group = aws_iam_group.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:GetAccessKeyLastUsed"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      }
    ]
  })
}

# ------------------------------------------------------------------
# Developer: custom policy - virtual MFA devices (deactivation requires MFA)
# ------------------------------------------------------------------

resource "aws_iam_group_policy" "developer_virtual_mfa" {
  name  = "${var.group_name_prefix}_developer_virtual_mfa"
  group = aws_iam_group.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowVirtualMFADeviceManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = [
          "arn:aws:iam::*:mfa/$${aws:username}",
          "arn:aws:iam::*:user/$${aws:username}"
        ]
      },
      {
        Sid    = "DenyDeactivateMFAWithoutMFA"
        Effect = "Deny"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------
# Developer: custom policy - MFA-gated S3 access
# ------------------------------------------------------------------

resource "aws_iam_group_policy" "developer_s3_mfa" {
  name  = "${var.group_name_prefix}_developer_s3_mfa_gated"
  group = aws_iam_group.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ActionsWithMFA"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyCreateBucketOutsideDesignatedRegion"
        Effect = "Deny"
        Action = "s3:CreateBucket"
        Resource = "arn:aws:s3:::*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.designated_region
          }
        }
      },
      {
        Sid      = "DenyAccessToRemoteStateBucket"
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.remote_state_bucket_name}",
          "arn:aws:s3:::${var.remote_state_bucket_name}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------
# Developer: custom policy - MFA-gated EC2/ELB/CloudWatch/AutoScaling
# ------------------------------------------------------------------

resource "aws_iam_group_policy" "developer_infra_mfa" {
  name  = "${var.group_name_prefix}_developer_infra_mfa_gated"
  group = aws_iam_group.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowInfraActionsWithMFA"
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:RebootInstances",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupEgress",
          "elasticloadbalancing:Describe*",
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:ModifyLoadBalancerAttributes",
          "elasticloadbalancing:ConfigureHealthCheck",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
          "autoscaling:Describe*",
          "autoscaling:CreateLaunchConfiguration",
          "autoscaling:DeleteLaunchConfiguration",
          "autoscaling:CreateAutoScalingGroup",
          "autoscaling:DeleteAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup",
          "autoscaling:SetDesiredCapacity",
          "autoscaling:CreateOrUpdateTags",
          "autoscaling:DeleteTags",
          "autoscaling:AttachLoadBalancers",
          "autoscaling:DetachLoadBalancers",
          "autoscaling:AttachLoadBalancerTargetGroups",
          "autoscaling:DetachLoadBalancerTargetGroups"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowServiceLinkedRolePassAndPermissionsWithMFA"
        Effect = "Allow"
        Action = [
          "iam:PassRole",
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:GetRole",
          "iam:GetServiceLinkedRoleDeletionStatus"
        ]
        Resource = [
          "arn:aws:iam::*:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:aws:iam::*:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing",
          "arn:aws:iam::*:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2"
        ]
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------
# Admin role assumable by root, with MFA-conditioned admin access
# ------------------------------------------------------------------

resource "aws_iam_role" "admin" {
  name = "admin"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::*:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "admin_mfa_conditioned" {
  name = "admin-mfa-conditioned-access"
  role = aws_iam_role.admin.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullAdminAccessWithMFA"
        Effect = "Allow"
        Action = "*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------
# Admin group: allow members to assume the admin role with MFA
# ------------------------------------------------------------------

resource "aws_iam_group_policy" "admin_assume_role" {
  name  = "${var.group_name_prefix}_admin_assume_admin_role"
  group = aws_iam_group.admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAssumeAdminRoleWithMFA"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_definitions" {
  description = "List of 16 subnet definitions: cidr, az, name"
  type = list(object({
    cidr = string
    az   = string
    name = string
  }))
  default = [
    { cidr = "10.0.0.0/24",  az = "us-east-1a", name = "subnet-0" },
    { cidr = "10.0.1.0/24",  az = "us-east-1b", name = "subnet-1" },
    { cidr = "10.0.2.0/24",  az = "us-east-1c", name = "subnet-2" },
    { cidr = "10.0.3.0/24",  az = "us-east-1a", name = "subnet-3" },
    { cidr = "10.0.4.0/24",  az = "us-east-1b", name = "subnet-4" },
    { cidr = "10.0.5.0/24",  az = "us-east-1c", name = "subnet-5" },
    { cidr = "10.0.6.0/24",  az = "us-east-1a", name = "subnet-6" },
    { cidr = "10.0.7.0/24",  az = "us-east-1b", name = "subnet-7" },
    { cidr = "10.0.8.0/24",  az = "us-east-1c", name = "subnet-8" },
    { cidr = "10.0.9.0/24",  az = "us-east-1a", name = "subnet-9" },
    { cidr = "10.0.10.0/24", az = "us-east-1b", name = "subnet-10" },
    { cidr = "10.0.11.0/24", az = "us-east-1c", name = "subnet-11" },
    { cidr = "10.0.12.0/24", az = "us-east-1a", name = "subnet-12" },
    { cidr = "10.0.13.0/24", az = "us-east-1b", name = "subnet-13" },
    { cidr = "10.0.14.0/24", az = "us-east-1c", name = "subnet-14" },
    { cidr = "10.0.15.0/24", az = "us-east-1a", name = "subnet-15" },
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat_eip" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.igw]
}

# First private subnet (subnet-0) hosts the NAT Gateway
resource "aws_subnet" "private_1" {
  count = 4

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_definitions[count.index].cidr
  availability_zone = var.subnet_definitions[count.index].az

  tags = {
    Name = var.subnet_definitions[count.index].name
  }
}

resource "aws_nat_gateway" "natgw" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.private_1[0].id

  tags = {
    Name = "deployme-natgw"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_subnet" "private_2" {
  count = 4

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_definitions[count.index + 4].cidr
  availability_zone = var.subnet_definitions[count.index + 4].az

  tags = {
    Name = var.subnet_definitions[count.index + 4].name
  }
}

resource "aws_subnet" "public" {
  count = 4

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_definitions[count.index + 8].cidr
  availability_zone       = var.subnet_definitions[count.index + 8].az
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_definitions[count.index + 8].name
  }
}

resource "aws_subnet" "spare" {
  count = 4

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_definitions[count.index + 12].cidr
  availability_zone = var.subnet_definitions[count.index + 12].az

  tags = {
    Name = var.subnet_definitions[count.index + 12].name
  }
}

# Main private route table: default route via NAT Gateway
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.natgw.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_1" {
  count = 4

  subnet_id      = aws_subnet.private_1[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  count = 4

  subnet_id      = aws_subnet.private_2[count.index].id
  route_table_id = aws_route_table.private.id
}

# Public route table: IPv4 and IPv6 default routes via IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  count = 4

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Spare route table: IPv4 and IPv6 default routes via IGW
resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  count = 4

  subnet_id      = aws_subnet.spare[count.index].id
  route_table_id = aws_route_table.spare.id
}

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow HTTP/HTTPS from anywhere, SSH from VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Egress to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

output "server_public_ip" {
  description = "Public IP of the NAT Elastic IP"
  value       = aws_eip.nat_eip.public_ip
}
