```hcl
###############################################################################
# Provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################
variable "enable" {
  description = "Flag to control whether the module resources are created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name to be used on all resources as identifier."
  type        = string
  default     = "network-security"
}

variable "environment" {
  description = "Environment, e.g. 'prod', 'staging', 'dev'."
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "Managed by tag value."
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of labels used in tags/id."
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for the repository tag."
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "new_sg" {
  description = "Whether to create a new security group."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID in which the security group will be created."
  type        = string
  default     = "vpc-12345678"
}

variable "existing_sg_id" {
  description = "ID of an existing security group to attach rules to."
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Whether to create a managed prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "External managed prefix list IDs to use instead of creating one."
  type        = list(string)
  default     = []
}

variable "prefix_list_name" {
  description = "Name of the managed prefix list (suffix appended automatically)."
  type        = string
  default     = null
}

variable "prefix_list_address_family" {
  description = "Address family of the prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Max entries of the managed prefix list."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of prefix list entries: { cidr = \"...\", description = \"...\" }."
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []
}

variable "ingress_rules_cidr" {
  description = "Ingress rules targeting CIDR blocks."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
    cidr_blocks = optional(list(string))
    ipv6_cidr_blocks = optional(list(string))
  }))
  default = []
}

variable "ingress_rules_self" {
  description = "Ingress rules with self-referencing source."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = []
}

variable "ingress_rules_sg" {
  description = "Ingress rules targeting source security group IDs."
  type = list(object({
    from_port            = number
    to_port              = number
    protocol             = string
    description          = string
    source_security_group_ids = list(string)
  }))
  default = []
}

variable "ingress_rules_prefix_list" {
  description = "Ingress rules targeting managed prefix list IDs."
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    description     = string
    prefix_list_ids = optional(list(string))
  }))
  default = []
}

variable "egress_rules_cidr" {
  description = "Egress rules targeting CIDR blocks."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
    cidr_blocks = optional(list(string))
    ipv6_cidr_blocks = optional(list(string))
  }))
  default = []
}

variable "egress_rules_self" {
  description = "Egress rules with self-referencing destination."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = []
}

variable "egress_rules_sg" {
  description = "Egress rules targeting destination security group IDs."
  type = list(object({
    from_port            = number
    to_port              = number
    protocol             = string
    description          = string
    source_security_group_ids = list(string)
  }))
  default = []
}

variable "egress_rules_prefix_list" {
  description = "Egress rules targeting managed prefix list IDs."
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    description     = string
    prefix_list_ids = optional(list(string))
  }))
  default = []
}

variable "tags" {
  description = "Additional tags."
  type        = map(string)
  default     = {}
}

###############################################################################
# Labels module (remote git source)
###############################################################################
module "labels" {
  source = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository

  tags = var.tags
}

###############################################################################
# Locals
###############################################################################
locals {
  enabled = var.enable

  # Security group to attach rules to: new SG or existing SG
  target_sg_id = var.new_sg ? aws_security_group.this[0].id : var.existing_sg_id

  # Prefix list IDs: external if supplied, otherwise the created one
  effective_prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : (
    var.prefix_list_enabled ? [aws_ec2_managed_prefix_list.this[0].id] : []
  )

  # Flatten prefix list rules with resolved IDs
  ingress_prefix_list_rules = [
    for rule in var.ingress_rules_prefix_list : {
      from_port       = rule.from_port
      to_port         = rule.to_port
      protocol        = rule.protocol
      description     = rule.description
      prefix_list_ids = length(coalesce(rule.prefix_list_ids, [])) > 0 ? rule.prefix_list_ids : local.effective_prefix_list_ids
    }
    if length(coalesce(rule.prefix_list_ids, [])) > 0 || length(local.effective_prefix_list_ids) > 0
  ]

  egress_prefix_list_rules = [
    for rule in var.egress_rules_prefix_list : {
      from_port       = rule.from_port
      to_port         = rule.to_port
      protocol        = rule.protocol
      description     = rule.description
      prefix_list_ids = length(coalesce(rule.prefix_list_ids, [])) > 0 ? rule.prefix_list_ids : local.effective_prefix_list_ids
    }
    if length(coalesce(rule.prefix_list_ids, [])) > 0 || length(local.effective_prefix_list_ids) > 0
  ]
}

###############################################################################
# Security Group (created when new_sg is true)
###############################################################################
resource "aws_security_group" "this" {
  count       = local.enabled && var.new_sg ? 1 : 0
  name        = "${module.labels.id}-sg"
  description = "Security group managed by Terraform (${module.labels.id})"
  vpc_id      = var.vpc_id

  tags = merge(
    module.labels.tags,
    {
      "Name" = "${module.labels.id}-sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Managed Prefix List (created when enabled and no external IDs supplied)
###############################################################################
resource "aws_ec2_managed_prefix_list" "this" {
  count           = local.enabled && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0
  name            = "${coalesce(var.prefix_list_name, module.labels.id)}-prefix-list"
  address_family  = var.prefix_list_address_family
  max_entries     = var.prefix_list_max_entries
  tags            = merge(module.labels.tags, { "Name" = "${coalesce(var.prefix_list_name, module.labels.id)}-prefix-list" })

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }
}

###############################################################################
# Ingress rules - CIDR blocks (IPv4/IPv6)
###############################################################################
resource "aws_vpc_security_group_ingress_rule" "cidr" {
  for_each = {
    for idx, rule in var.ingress_rules_cidr : idx => rule
    if local.enabled && local.target_sg_id != null
  }

  security_group_id = local.target_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description

  cidr_ipv6 = length(coalesce(each.value.ipv6_cidr_blocks, [])) > 0 ? element(each.value.ipv6_cidr_blocks, 0) : null
  cidr_ipv4 = length(coalesce(each.value.ipv6_cidr_blocks, [])) == 0 && length(coalesce(each.value.cidr_blocks, [])) > 0 ? element(each.value.cidr_blocks, 0) : null
}

###############################################################################
# Ingress rules - Self referencing
###############################################################################
resource "aws_vpc_security_group_ingress_rule" "self" {
  for_each = {
    for idx, rule in var.ingress_rules_self : idx => rule
    if local.enabled && local.target_sg_id != null
  }

  security_group_id = local.target_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
  referenced_security_group_id = local.target_sg_id
}

###############################################################################
# Ingress rules - Source security group IDs
###############################################################################
resource "aws_vpc_security_group_ingress_rule" "sg" {
  for_each = {
    for pair in setproduct(keys({ for idx, _ in var.ingress_rules_sg : idx => true }), []) : join("-", pair) => pair
    if false # placeholder, replaced below
  }

  security_group_id = local.target_sg_id
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
}

###############################################################################
# Ingress rules - Managed prefix list IDs
###############################################################################
resource "aws_vpc_security_group_ingress_rule" "prefix_list" {
  for_each = {
    for entry in flatten([
      for idx, rule in local.ingress_prefix_list_rules : [
        for plid in rule.prefix_list_ids : {
          key         = "${idx}-${plid}"
          from_port   = rule.from_port
          to_port     = rule.to_port
          protocol    = rule.protocol
          description = rule.description
          plid        = plid
        }
      ]
    ]) : entry.key => entry
    if local.enabled && local.target_sg_id != null
  }

  security_group_id        = local.target_sg_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  ip_protocol              = each.value.protocol
  description              = each.value.description
  prefix_list_id           = each.value.plid
}

###############################################################################
# Egress rules - CIDR blocks (IPv4/IPv6)
###############################################################################
resource "aws_vpc_security_group_egress_rule" "cidr" {
  for_each = {
    for idx, rule in var.egress_rules_cidr : idx => rule
    if local.enabled && local.target_sg_id != null
  }

  security_group_id = local.target_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description

  cidr_ipv6 = length(coalesce(each.value.ipv6_cidr_blocks, [])) > 0 ? element(each.value.ipv6_cidr_blocks, 0) : null
  cidr_ipv4 = length(coalesce(each.value.ipv6_cidr_blocks, [])) == 0 && length(coalesce(each.value.cidr_blocks, [])) > 0 ? element(each.value.cidr_blocks, 0) : null
}

###############################################################################
# Egress rules - Self referencing
###############################################################################
resource "aws_vpc_security_group_egress_rule" "self" {
  for_each = {
    for idx, rule in var.egress_rules_self : idx => rule
    if local.enabled && local.target_sg_id != null
  }

  security_group_id = local.target_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
  referenced_security_group_id = local.target_sg_id
}

###############################################################################
# Egress rules - Destination security group IDs
###############################################################################
resource "aws_vpc_security_group_egress_rule" "sg" {
  for_each = {
    for entry in flatten([
      for idx, rule in var.egress_rules_sg : [
        for sgid in rule.source_security_group_ids : {
          key         = "${idx}-${sgid}"
          from_port   = rule.from_port
          to_port     = rule.to_port
          protocol    = rule.protocol
          description = rule.description
          sgid        = sgid
        }
      ]
    ]) : entry.key => entry
    if local.enabled && local.target_sg_id != null
  }

  security_group_id            = local.target_sg_id
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.protocol
  description                  = each.value.description
  referenced_security_group_id = each.value.sgid
}

###############################################################################
# Egress rules - Managed prefix list IDs
###############################################################################
resource "aws_vpc_security_group_egress_rule" "prefix_list" {
  for_each = {
    for entry in flatten([
      for idx, rule in local.egress_prefix_list_rules : [
        for plid in rule.prefix_list_ids : {
          key         = "${idx}-${plid}"
          from_port   = rule.from_port
          to_port     = rule.to_port
          protocol    = rule.protocol
          description = rule.description
          plid        = plid
        }
      ]
    ]) : entry.key => entry
    if local.enabled && local.target_sg_id != null
  }

  security_group_id = local.target_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
  prefix_list_id    = each.value.plid
}

###############################################################################
# Ingress rules - Source security group IDs (flattened, one rule per SG ID)
###############################################################################
resource "aws_vpc_security_group_ingress_rule" "sg_flattened" {
  for_each = {
    for entry in flatten([
      for idx, rule in var.ingress_rules_sg : [
        for sgid in rule.source_security_group_ids : {
          key         = "${idx}-${sgid}"
          from_port   = rule.from_port
          to_port     = rule.to_port
          protocol    = rule.protocol
          description = rule.description
          sgid        = sgid
        }
      ]
    ]) : entry.key => entry
    if local.enabled && local.target_sg_id != null
  }

  security_group_id            = local.target_sg_id
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.protocol
  description                  = each.value.description
  referenced_security_group_id = each.value.sgid
}

###############################################################################
# Outputs
###############################################################################
output "security_group_id" {
  description = "ID of the security group rules are attached to."
  value       = local.target_sg_id
}

output "prefix_list_id" {
  description = "ID of the managed prefix list, if created."
  value       = var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? try(aws_ec2_managed_prefix_list.this[0].id, null) : null
}

output "labels_tags" {
  description = "Standard labels tags applied to resources."
  value       = module.labels.tags
}
