terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used to construct ECS role names"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Account-wide password policy
# ---------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

# ---------------------------------------------------------------------------
# ECS task role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecs-task-role-for-${var.environment}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secretsmanager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy" "ecs_task_ssm_inline" {
  name = "ssm-messages-inline"
  role = aws_iam_role.ecs_task_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["ssmmessages:CreateControlChannel", "ssmmessages:CreateDataChannel", "ssmmessages:OpenControlChannel", "ssmmessages:OpenDataChannel"]
      Resource = "*"
    }]
  })
}

# ---------------------------------------------------------------------------
# ECS execution role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution_role" {
  name = "ecs-execution-role-for-${var.environment}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_exec_task_execution" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_exec_ecs_service" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_exec_inline" {
  name = "secrets-kms-inline"
  role = aws_iam_role.ecs_execution_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ECS events role (assumable by EventBridge)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_events_role" {
  name = "ecs_events_role-for-${var.environment}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "events.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_events_task_execution" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_ecs_service" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerServiceRole"
}

# ---------------------------------------------------------------------------
# Public Lambda role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_public_role" {
  name = "public-lambda-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_public_logs" {
  name = "cloudwatch-logs"
  role = aws_iam_role.lambda_public_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
      Resource = "*"
    }]
  })
}

# ---------------------------------------------------------------------------
# VPC Lambda role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_vpc_role" {
  name = "vpc-lambda-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_vpc_inline" {
  name = "vpc-lambda-permissions"
  role = aws_iam_role.lambda_vpc_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2:CreateNetworkInterface", "ec2:DeleteNetworkInterface", "ec2:DescribeNetworkInterfaces"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Step Functions state machine role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "sfn_state_machine_role" {
  name = "step-functions-state-machine-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "states.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sfn_inline" {
  name = "sfn-permissions"
  role = aws_iam_role.sfn_state_machine_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogDelivery", "logs:GetLogDelivery", "logs:UpdateLogDelivery", "logs:DeleteLogDelivery", "logs:ListLogDeliveries", "logs:PutLogEvents", "logs:CreateLogStream", "logs:DescribeLogGroups"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["states:PutResourcePolicy", "states:DeleteResourcePolicy"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["cloudwatch:DescribeAlarms"]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# EventBridge execution role (Step Functions execution, current account only)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_execution_role" {
  name = "eventbridge-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "events.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "eventbridge_sfn_inline" {
  name = "start-execution-current-account"
  role = aws_iam_role.eventbridge_execution_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "states:StartExecution"
      Resource = "arn:aws:states:*:${data.aws_caller_identity.current.account_id}:stateMachine:*"
    }]
  })
}

# ---------------------------------------------------------------------------
# Developers policy (limited MFA)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developers_policy" {
  name = "developers-policy-limited-mfa"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
        Resource = ["arn:aws:s3:::*", "arn:aws:s3:::*/*"]
      },
      {
        Sid      = "SecretsManagerReadMFA"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret", "secretsmanager:ListSecrets"]
        Resource = "*"
        Condition = {
          Bool = { "aws:MultiFactorAuthPresent" = "true" }
        }
      },
      {
        Sid    = "CloudWatchEcsReadOnlyMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:Describe*", "cloudwatch:Get*", "cloudwatch:List*",
          "ecs:Describe*", "ecs:List*", "ecs:Get*"
        ]
        Resource = "*"
        Condition = {
          Bool = { "aws:MultiFactorAuthPresent" = "true" }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetAccountPasswordPolicy",
          "iam:CreateAccessKey", "iam:DeleteAccessKey", "iam:ListAccessKeys", "iam:UpdateAccessKey",
          "iam:EnableMFADevice", "iam:DeactivateMFADevice", "iam:ListMFADevices", "iam:ResyncMFADevice",
          "iam:CreateVirtualMFADevice", "iam:DeleteVirtualMFADevice",
          "iam:UploadSSHPublicKey", "iam:DeleteSSHPublicKey", "iam:GetSSHPublicKey", "iam:ListSSHPublicKeys", "iam:UpdateSSHPublicKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid      = "MFAEnforcementDeny"
        Effect   = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice", "iam:EnableMFADevice", "iam:ResyncMFADevice", "iam:ListMFADevices",
          "iam:CreateAccessKey", "iam:ListAccessKeys",
          "iam:ListUsers", "iam:GetAccountPasswordPolicy"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = { "aws:MultiFactorAuthPresent" = "false" }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Billing policy (limited MFA)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy" {
  name = "billing-policy-limited-mfa"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling", "aws-portal:ViewPaymentMethods", "aws-portal:ViewAccount",
          "billing:ListBillingViews", "billing:GetBillingData", "billing:GetBillingDetails", "billing:GetBillingDocuments",
          "budgets:ViewBudget", "budgets:DescribeBudgetActions", "budgets:DescribeBudgetNotificationsForAccount",
          "ce:GetCostAndUsage", "ce:GetCostAndUsageWithResources", "ce:GetCostForecast", "ce:GetDimensionValues", "ce:GetReservationCoverage", "ce:GetReservationUtilization", "ce:GetSavingsPlansCoverage", "ce:GetSavingsPlansUtilization", "ce:GetUsageReport",
          "payments:ListPaymentPreferences", "payments:GetPaymentInstrument", "payments:ListPaymentInstruments",
          "tax:GetTaxInheritance", "tax:GetTaxRegistration", "tax:ListTaxRegistrations"
        ]
        Resource = "*"
        Condition = {
          Bool = { "aws:MultiFactorAuthPresent" = "true" }
        }
      },
      {
        Sid    = "SelfServiceMFAAndPassword"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetAccountPasswordPolicy",
          "iam:EnableMFADevice", "iam:DeactivateMFADevice", "iam:ListMFADevices", "iam:ResyncMFADevice",
          "iam:CreateVirtualMFADevice", "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid       = "MFAEnforcementDeny"
        Effect    = "Deny"
        NotAction = ["iam:ChangePassword", "iam:CreateVirtualMFADevice", "iam:EnableMFADevice", "iam:ResyncMFADevice", "iam:ListMFADevices", "iam:GetAccountPasswordPolicy"]
        Resource  = "*"
        Condition = {
          BoolIfExists = { "aws:MultiFactorAuthPresent" = "false" }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "config" {
  type = string
  default = yamlencode({
    create_default_pipeline_role = true
    artifact_bucket_name         = "terraforest-artifacts-example"
    cache_bucket_name            = "terraforest-cache-example"
    connections = [
      { name = "github-conn", provider_type = "GitHub" }
    ]
    pipelines = [
      {
        name            = "example-app"
        role_arn        = null
        source = {
          type           = "CodeCommit"
          repository_name = "example-repo"
          branch         = "main"
          output_format  = "CODEBUILD_CLONE_REF"
        }
        stages = [
          {
            name = "Build"
            actions = [
              {
                name          = "BuildAction"
                type          = "CodeBuild"
                project_name  = "example-app-build"
                input_artifact = "SourceOutput"
                environment = {
                  compute_type = "BUILD_GENERAL1_SMALL"
                  image        = "aws/codebuild/standard:7.0"
                  type         = "LINUX_CONTAINER"
                }
                buildspec = "version: 0.2\nphrases:\n  build:\n    commands:\n      - echo build"
              }
            ]
          },
          {
            name = "Deploy"
            actions = [
              {
                name           = "ManualApproval"
                type           = "Approval"
                input_artifact = null
              },
              {
                name            = "InvokeFunction"
                type            = "Lambda"
                function_name   = "example-deploy-fn"
                input_artifact  = "SourceOutput"
              }
            ]
          }
        ]
        triggers = [
          { type = "CodeCommitBranch", branch = "main" },
          { type = "Schedule", schedule_expression = "rate(1 day)" }
        ]
      }
    ]
  })
}

locals {
  cfg = yamldecode(var.config)

  create_default_role = try(local.cfg.create_default_pipeline_role == true, false)

  artifact_bucket = try(local.cfg.artifact_bucket_name, null)
  cache_bucket    = try(local.cfg.cache_bucket_name, null)

  connections = try(local.cfg.connections, [])

  pipelines = try(local.cfg.pipelines, [])

  # Flatten pipeline actions for CodeBuild project provisioning
  codebuild_actions = flatten([
    for p in local.pipelines : [
      for s in try(p.stages, []) : [
        for a in try(s.actions, []) : {
          pipeline_name  = p.name
          action_name    = a.name
          project_name   = try(a.project_name, "${p.name}-${a.name}")
          buildspec      = try(a.buildspec, null)
          environment    = try(a.environment, {})
          role_arn       = try(a.role_arn, null)
        }
      ] if try(a.type, "") == "CodeBuild"
    ]
  ])
}

# ------------------------------------------------------------------
# S3 buckets
# ------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  count  = local.artifact_bucket != null ? 1 : 0
  bucket = local.artifact_bucket
}

resource "aws_s3_bucket_versioning" "artifacts" {
  count  = local.artifact_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  count  = local.artifact_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  count                   = local.artifact_bucket != null ? 1 : 0
  bucket                  = aws_s3_bucket.artifacts[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "cache" {
  count  = local.cache_bucket != null ? 1 : 0
  bucket = local.cache_bucket
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  count  = local.cache_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.cache[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  count                   = local.cache_bucket != null ? 1 : 0
  bucket                  = aws_s3_bucket.cache[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------
# Default CodePipeline IAM role under /terraforest/
# ------------------------------------------------------------------
data "aws_iam_policy_document" "pipeline_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "default_pipeline" {
  count                = local.create_default_role ? 1 : 0
  name                 = "terraforest-default-pipeline-role"
  path                 = "/terraforest/"
  assume_role_policy   = data.aws_iam_policy_document.pipeline_assume.json
}

data "aws_iam_policy_document" "default_pipeline_perms" {
  statement {
    sid = "CodeCommit"
    actions = [
      "codecommit:GetBranch", "codecommit:GetCommit", "codecommit:UploadArchive",
      "codecommit:GetUploadArchiveStatus", "codecommit:CancelUploadArchive"
    ]
    resources = ["*"]
  }
  statement {
    sid = "S3Artifacts"
    actions   = ["s3:GetObject", "s3:GetObjectVersion", "s3:PutObject", "s3:GetBucketVersioning", "s3:GetBucketLocation", "s3:ListBucket"]
    resources = concat(
      [for b in concat(aws_s3_bucket.artifacts[*].arn, aws_s3_bucket.cache[*].arn) : b],
      [for b in concat(aws_s3_bucket.artifacts[*].arn, aws_s3_bucket.cache[*].arn) : "${b}/*"]
    )
  }
  statement {
    sid = "CodeBuild"
    actions = [
      "codebuild:BatchGetBuilds", "codebuild:StartBuild", "codebuild:StopBuild",
      "codebuild:BatchGetProjects", "codebuild:CreateProject", "codebuild:UpdateProject"
    ]
    resources = ["*"]
  }
  statement {
    sid = "ECR"
    actions = [
      "ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage", "ecr:PutImage",
      "ecr:InitiateLayerUpload", "ecr:UploadLayerPart", "ecr:CompleteLayerUpload",
      "ecr:DescribeRepositories", "ecr:CreateRepository"
    ]
    resources = ["*"]
  }
  statement {
    sid = "LambdaInvoke"
    actions   = ["lambda:InvokeFunction"]
    resources = ["*"]
  }
  statement {
    sid = "PassRole"
    actions   = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["codebuild.amazonaws.com", "lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "default_pipeline" {
  count  = local.create_default_role ? 1 : 0
  name   = "terraforest-default-pipeline-policy"
  role   = aws_iam_role.default_pipeline[0].id
  policy = data.aws_iam_policy_document.default_pipeline_perms.json
}

# ------------------------------------------------------------------
# CodeStar connections
# ------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = { for c in local.connections : c.name => c }
  name          = each.key
  provider_type = each.value.provider_type
}

# ------------------------------------------------------------------
# CodeBuild projects (one per CodeBuild action)
# ------------------------------------------------------------------
data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild" {
  for_each           = { for a in local.codebuild_actions : a.project_name => a }
  name               = "terraforest-cb-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = { for a in local.codebuild_actions : a.project_name => a }
  name     = "codebuild-perms"
  role     = aws_iam_role.codebuild[each.key].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents", "s3:GetObject", "s3:GetObjectVersion", "s3:PutObject", "ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability", "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage", "ecr:PutImage", "ecr:InitiateLayerUpload", "ecr:UploadLayerPart", "ecr:CompleteLayerUpload"]
      Resource = "*"
    }]
  })
}

resource "aws_codebuild_project" "this" {
  for_each     = { for a in local.codebuild_actions : a.project_name => a }
  name         = each.key
  service_role = aws_iam_role.codebuild[each.key].arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type = try(each.value.environment.compute_type, "BUILD_GENERAL1_SMALL")
    image        = try(each.value.environment.image, "aws/codebuild/standard:7.0")
    type         = try(each.value.environment.type, "LINUX_CONTAINER")
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = try(each.value.buildspec, null)
  }
}

# ------------------------------------------------------------------
# Pipelines
# ------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = { for p in local.pipelines : p.name => p }
  name     = each.key
  role_arn = try(each.value.role_arn, null) != null ? each.value.role_arn : (local.create_default_role ? aws_iam_role.default_pipeline[0].arn : aws_iam_role.default_pipeline[0].arn)

  artifact_store {
    location = aws_s3_bucket.artifacts[0].bucket
    type     = "S3"
  }

  # Source stage
  stage {
    name = "Source"

    dynamic "action" {
      for_each = [each.value.source]
      content {
        name             = "Source"
        category         = "Source"
        owner            = action.value.type == "CodeCommit" ? "AWS" : "ThirdParty"
        provider         = action.value.type == "CodeCommit" ? "CodeCommit" : (action.value.type == "S3" ? "S3" : (action.value.type == "ECR" ? "ECR" : "CodeStarSourceConnection"))
        version          = "1"
        output_artifacts = ["SourceOutput"]
        run_order        = 1

        configuration = (
          action.value.type == "CodeCommit" ? {
            RepositoryName       = action.value.repository_name
            BranchName           = try(action.value.branch, "main")
            OutputArtifactFormat = try(action.value.output_format, "CODE_ZIP")
          } : action.value.type == "S3" ? {
            S3Bucket    = action.value.bucket
            S3ObjectKey = action.value.object_key
          } : action.value.type == "ECR" ? {
            RepositoryName = action.value.repository_name
            ImageTag       = try(action.value.image_tag, "latest")
          } : {
            ConnectionArn    = aws_codestarconnections_connection.this[action.value.connection_name].arn
            FullRepositoryId = action.value.full_repository_id
            BranchName       = try(action.value.branch, "main")
          }
        )
      }
    }
  }

  # Dynamic stages
  dynamic "stage" {
    for_each = try(each.value.stages, [])
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])
        content {
          name             = action.value.name
          category         = action.value.type == "Approval" ? "Approval" : (action.value.type == "CodeBuild" ? "Build" : "Invoke")
          owner            = "AWS"
          provider         = action.value.type == "Approval" ? "Manual" : (action.value.type == "CodeBuild" ? "CodeBuild" : "Lambda")
          version          = "1"
          run_order        = action.key + 1
          input_artifacts  = try(action.value.input_artifact, null) != null ? [action.value.input_artifact] : []
          configuration    = action.value.type == "CodeBuild" ? { ProjectName = aws_codebuild_project.this[try(action.value.project_name, "${each.key}-${action.value.name}")].name } : action.value.type == "Lambda" ? { FunctionName = action.value.function_name } : {}
        }
      }
    }
  }
}

# ------------------------------------------------------------------
# EventBridge triggers: terrabits-<pipeline> roles, rules, targets
# ------------------------------------------------------------------
resource "aws_iam_role" "trigger" {
  for_each           = { for p in local.pipelines : p.name => p if length(try(p.triggers, [])) > 0 }
  name               = "terrabits-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.pipeline_assume.json
}

resource "aws_iam_role_policy" "trigger" {
  for_each = { for p in local.pipelines : p.name => p if length(try(p.triggers, [])) > 0 }
  name     = "start-pipeline"
  role     = aws_iam_role.trigger[each.key].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "codepipeline:StartPipelineExecution"
      Resource = aws_codepipeline.this[each.key].arn
    }]
  })
}

resource "aws_cloudwatch_event_rule" "trigger" {
  for_each = merge([
    for p in local.pipelines : {
      for i, t in try(p.triggers, []) : "${p.name}-${i}" => {
        pipeline = p.name
        trigger  = t
      }
    }
  ]...)

  name = "terrabits-${each.value.pipeline}-${each.key}"

  event_pattern = (
    each.value.trigger.type == "CodeCommitBranch" ? jsonencode({
      source      = ["aws.codecommit"]
      detail-type = ["CodeCommit Repository State Change"]
      resources   = ["arn:aws:codecommit:${var.aws_region}:*:${each.value.trigger.repository_name}"]
      detail = {
        event         = ["referenceCreated", "referenceUpdated"]
        referenceType = ["branch"]
        referenceName = [each.value.trigger.branch]
      }
    }) : each.value.trigger.type == "CodeCommitTag" ? jsonencode({
      source      = ["aws.codecommit"]
      detail-type = ["CodeCommit Repository State Change"]
      resources   = ["arn:aws:codecommit:${var.aws_region}:*:${each.value.trigger.repository_name}"]
      detail = {
        event         = ["referenceCreated", "referenceUpdated"]
        referenceType = ["tag"]
        referenceName = [each.value.trigger.tag]
      }
    }) : each.value.trigger.type == "CustomPattern" ? jsonencode(each.value.trigger.event_pattern) : null
  )

  schedule_expression = each.value.trigger.type == "Schedule" ? each.value.trigger.schedule_expression : null
}

resource "aws_cloudwatch_event_target" "trigger" {
  for_each = aws_cloudwatch_event_rule.trigger

  rule     = each.value.name
  arn      = aws_codepipeline.this[each.value.pipeline].arn
  role_arn = aws_iam_role.trigger[each.value.pipeline].arn
}

# ------------------------------------------------------------------
# Lambda function referenced by Lambda actions (module-style inline)
# ------------------------------------------------------------------
resource "aws_iam_role" "lambda" {
  name = "terraforest-pipeline-lambda-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda" {
  name = "lambda-basic"
  role = aws_iam_role.lambda.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
      Resource = "*"
    }]
  })
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_handler.zip"
  source {
    content  = "exports.handler = async (event) => { console.log(event); return { statusCode: 200 }; };"
    filename = "index.js"
  }
}

resource "aws_lambda_function" "this" {
  for_each = toset(distinct(flatten([
    for p in local.pipelines : [
      for s in try(p.stages, []) : [
        for a in try(s.actions, []) : a.function_name
      ] if try(a.type, "") == "Lambda"
    ]
  ])))
  function_name = each.value
  role          = aws_iam_role.lambda.arn
  handler       = "index.handler"
  runtime       = "nodejs20.x"
  filename      = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
}

output "pipeline_names" {
  value = keys(aws_codepipeline.this)
}

output "artifact_bucket" {
  value = try(aws_s3_bucket.artifacts[0].bucket, null)
}

output "codestar_connection_arns" {
  value = { for k, v in aws_codestarconnections_connection.this : k => v.arn }
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  type    = string
  default = ""
}

variable "subnet_ids" {
  type    = list(string)
  default = []
}

variable "efs_performance_mode" {
  type    = string
  default = "generalPurpose"
}

variable "efs_throughput_mode" {
  type    = string
  default = "bursting"
}

variable "kms_key_arn" {
  type    = string
  default = ""
}

variable "create_kms_key" {
  type    = bool
  default = true
}

variable "sftp_server_name" {
  type    = string
  default = "sftp-server"
}

variable "is_public" {
  type    = bool
  default = false
}

variable "logging_enabled" {
  type    = bool
  default = false
}

variable "sftp_users" {
  type = map(object({
    ssh_public_key = string
    uid            = number
    gid            = number
    restricted     = bool
  }))
  default = {}
}

variable "additional_access_points" {
  type = map(object({
    posix_uid = number
    posix_gid = number
  }))
  default = {}
}

variable "user_role_arn" {
  type    = string
  default = ""
}

# --- KMS ---
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "aws_kms_key" "efs" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "KMS key for EFS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

locals {
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : (var.create_kms_key ? aws_kms_key.efs[0].arn : "")
}

# --- Security groups ---
resource "aws_security_group" "sftp" {
  count       = var.vpc_id != "" ? 1 : 0
  name        = "${var.sftp_server_name}-sftp-sg"
  description = "SFTP access"
  vpc_id      = var.vpc_id

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "efs" {
  count       = var.vpc_id != "" ? 1 : 0
  name        = "${var.sftp_server_name}-efs-sg"
  description = "EFS access from SFTP"
  vpc_id      = var.vpc_id

  ingress {
    description     = "NFS from SFTP SG"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.sftp[0].id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# --- EFS ---
resource "aws_efs_file_system" "this" {
  creation_token   = "${var.sftp_server_name}-efs"
  performance_mode = var.efs_performance_mode
  throughput_mode  = var.efs_throughput_mode
  encrypted        = true
  kms_key_id       = local.kms_key_arn != "" ? local.kms_key_arn : null

  tags = {
    Name = "${var.sftp_server_name}-efs"
  }
}

resource "aws_efs_mount_target" "this" {
  count            = length(var.subnet_ids)
  file_system_id   = aws_efs_file_system.this.id
  subnet_id        = var.subnet_ids[count.index]
  security_groups  = var.vpc_id != "" ? [aws_security_group.efs[0].id] : null
}

resource "aws_efs_access_point" "users" {
  for_each        = var.sftp_users
  file_system_id  = aws_efs_file_system.this.id
  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
  root_directory {
    path = "/${each.key}"
    creation_info {
      owner_gid   = each.value.gid
      owner_uid   = each.value.uid
      permissions = "0755"
    }
  }
  tags = { Name = "${var.sftp_server_name}-ap-${each.key}" }
}

resource "aws_efs_access_point" "additional" {
  for_each        = var.additional_access_points
  file_system_id  = aws_efs_file_system.this.id
  posix_user {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }
  root_directory {
    path = "/${each.key}"
    creation_info {
      owner_gid   = each.value.posix_gid
      owner_uid   = each.value.posix_uid
      permissions = "0755"
    }
  }
  tags = { Name = "${var.sftp_server_name}-ap-${each.key}" }
}

# --- IAM ---
resource "aws_iam_role" "transfer" {
  count = var.user_role_arn == "" ? 1 : 0
  name  = "${var.sftp_server_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "transfer.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "transfer_efs" {
  count = var.user_role_arn == "" ? 1 : 0
  name  = "${var.sftp_server_name}-efs-access"
  role  = aws_iam_role.transfer[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["elasticfilesystem:ClientMount", "elasticfilesystem:ClientWrite", "elasticfilesystem:ClientRootAccess"]
        Resource = [aws_efs_file_system.this.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["elasticfilesystem:DescribeMountTargets", "elasticfilesystem:DescribeFileSystems"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.sftp_server_name}-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "transfer.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.sftp_server_name}-logging-policy"
  role  = aws_iam_role.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogStream", "logs:DescribeLogStreams", "logs:CreateLogGroup", "logs:PutLogEvents"]
      Resource = "*"
    }]
  })
}

# --- Transfer Family ---
resource "aws_transfer_server" "this" {
  identity_provider_type = "SERVICE_MANAGED"
  domain                 = "EFS"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = var.vpc_id != "" ? "VPC" : "PUBLIC"

  dynamic "endpoint_details" {
    for_each = var.vpc_id != "" ? [1] : []
    content {
      vpc_id                 = var.vpc_id
      subnet_ids             = var.subnet_ids
      security_group_ids     = [aws_security_group.sftp[0].id]
      address_allocation_ids = var.is_public ? [for eip in aws_eip.sftp : eip.allocation_id] : null
    }
  }

  logging_role = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  tags = {
    Name = var.sftp_server_name
  }
}

resource "aws_eip" "sftp" {
  count  = var.vpc_id != "" && var.is_public ? length(var.subnet_ids) : 0
  domain = "vpc"
}

resource "aws_transfer_user" "users" {
  for_each           = var.sftp_users
  server_id          = aws_transfer_server.this.id
  user_name          = each.key
  role               = var.user_role_arn != "" ? var.user_role_arn : aws_iam_role.transfer[0].arn
  home_directory     = "/${aws_efs_file_system.this.id}/${each.key}"
  home_directory_type = each.value.restricted ? "LOGICAL" : "PATH"

  home_directory_mappings {
    entry  = "/"
    target = "/${aws_efs_file_system.this.id}/${each.key}"
  }

  posix_profile {
    uid            = each.value.uid
    gid            = each.value.gid
    secondary_gids = []
  }

  ssh_public_key_body = each.value.ssh_public_key
}

output "sftp_server_id" {
  value = aws_transfer_server.this.id
}

output "sftp_server_endpoint" {
  value = aws_transfer_server.this.endpoint
}

output "efs_file_system_id" {
  value = aws_efs_file_system.this.id
}
```

# =========================================================
# Root configuration (main.tf)
# =========================================================
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

module "s3_bucket" {
  source = "./s3-bucket-module"

  create_bucket = true
  create_kms_key = true

  tags = {
    Environment = "example"
    ManagedBy   = "terraform"
  }
}

output "bucket_id" {
  value = module.s3_bucket.bucket_id
}

output "bucket_arn" {
  value = module.s3_bucket.bucket_arn
}

output "kms_key_arn" {
  value = module.s3_bucket.kms_key_arn
}

# =========================================================
# Module: s3-bucket-module/variables.tf
# =========================================================
variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Whether to create a customer-managed KMS key (when no caller encryption is supplied)"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Explicit bucket name (conflicts with bucket_prefix)"
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Bucket name prefix"
  type        = string
  default     = null
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}

variable "object_lock_mode" {
  type    = string
  default = null
}

variable "object_lock_days" {
  type    = number
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "acl" {
  description = "Canned ACL"
  type        = string
  default     = null
}

variable "acl_grants" {
  description = "Explicit ACL grants"
  type = list(object({
    type        = string
    permissions = list(string)
    id          = optional(string)
    uri         = optional(string)
  }))
  default = []
}

variable "website" {
  description = "Static website hosting config"
  type = object({
    index_document           = string
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "versioning_enabled" {
  type    = bool
  default = false
}

variable "logging_target_bucket" {
  type    = string
  default = null
}

variable "logging_target_prefix" {
  type    = string
  default = null
}

variable "transfer_acceleration" {
  type    = bool
  default = false
}

variable "requester_pays" {
  type    = bool
  default = false
}

variable "lifecycle_rules" {
  type = list(object({
    id                                     = string
    enabled                                = optional(bool, true)
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    abort_incomplete_multipart_upload_days = optional(number)
    expiration_days                        = optional(number)
    noncurrent_version_expiration_days     = optional(number)
  }))
  default = []
}

variable "replication_configuration" {
  description = "Cross-region replication config"
  type = object({
    role_arn = string
    rules = list(object({
      id                = string
      status            = string
      destination_bucket_arn = string
      storage_class     = optional(string)
    }))
  })
  default = null
}

variable "intelligent_tiering" {
  type = object({
    name   = string
    status = optional(string, "Enabled")
    filter = optional(map(string))
    tierings = list(object({
      days          = number
      access_tier   = string
    }))
  })
  default = null
}

variable "ownership_controls_enabled" {
  type    = bool
  default = false
}

variable "ownership_controls_rule" {
  type    = string
  default = "ObjectWriter"
}

variable "server_side_encryption_configuration" {
  description = "Caller-supplied encryption config; replaces default KMS encryption"
  type = object({
    rule = object({
      bucket_key_enabled = optional(bool)
      apply_server_side_encryption_by_default = object({
        sse_algorithm     = string
        kms_master_key_id = optional(string)
      })
    })
  })
  default = null
}

variable "elb_log_delivery_enabled" {
  description = "Grant classic ELB access log delivery"
  type    = bool
  default = false
}

variable "alb_log_delivery_enabled" {
  description = "Grant ALB/NLB access log delivery"
  type    = bool
  default = false
}

variable "deny_insecure_transport" {
  type    = bool
  default = false
}

variable "deny_tls_older_than_1_2" {
  type    = bool
  default = false
}

variable "attach_policy" {
  type    = bool
  default = true
}

variable "additional_policy_json" {
  type    = string
  default = null
}

# =========================================================
# Module: s3-bucket-module/main.tf
# =========================================================
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  bucket_name = coalesce(var.bucket_name, var.create_bucket && var.bucket_prefix != null ? "${var.bucket_prefix}-${data.aws_caller_identity.current.account_id}" : null)
}

# --- KMS key (default encryption) ---
resource "aws_kms_key" "this" {
  count                   = var.create_bucket && var.create_kms_key && var.server_side_encryption_configuration == null ? 1 : 0
  description             = "S3 bucket default encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# --- Bucket ---
resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket        = local.bucket_name
  bucket_prefix = local.bucket_name == null ? var.bucket_prefix : null
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.create_bucket && var.object_lock_enabled && var.object_lock_mode != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.ownership_controls_enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.ownership_controls_rule
  }

  # Applied after the bucket policy to avoid conflicting S3 operations
  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  # Public access block applied after the bucket policy
  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_acl" "this" {
  count = var.create_bucket && (var.acl != null || length(var.acl_grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  dynamic "grant" {
    for_each = var.acl_grants
    content {
      permissions = grant.value.permissions
      type        = grant.value.type
      id          = grant.value.id
      uri         = grant.value.uri
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.create_bucket && var.versioning_enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.create_bucket && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.website.index_document
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  dynamic "routing_rules" {
    for_each = var.website.routing_rules != null ? [var.website.routing_rules] : []
    content {
      dynamic "condition" {
        for_each = []
        content {}
      }
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.create_bucket && var.logging_target_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.create_bucket && var.transfer_acceleration ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  status = "Enabled"
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.create_bucket && var.requester_pays ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = "Requester"
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || rule.value.tags != null ? [1] : []
        content {
          tags = rule.value.tags != null ? rule.value.tags : {}
          dynamic "prefix" {
            for_each = rule.value.prefix != null ? [rule.value.prefix] : []
            content {
              # prefix is set via object below in provider >= 5
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  role = var.replication_configuration.role_arn

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id     = rule.value.id
      status = rule.value.status

      filter {}

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count = var.create_bucket && var.intelligent_tiering != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  name   = var.intelligent_tiering.name
  status = var.intelligent_tiering.status

  dynamic "filter" {
    for_each = var.intelligent_tiering.filter != null ? [var.intelligent_tiering.filter] : []
    content {
      tags = filter.value
    }
  }

  dynamic "tiering" {
    for_each = var.intelligent_tiering.tierings
    content {
      days          = tiering.value.days
      access_tier   = tiering.value.access_tier
    }
  }
}

# --- Server-side encryption ---
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    bucket_key_enabled = var.server_side_encryption_configuration != null ? try(var.server_side_encryption_configuration.rule.bucket_key_enabled, null) : true

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default.sse_algorithm : "aws:kms"
      kms_master_key_id = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default.kms_master_key_id : (var.create_kms_key ? aws_kms_key.this[0].arn : null)
    }
  }
}

# --- Combined bucket policy ---
data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && var.attach_policy ? 1 : 0

  dynamic "statement" {
    for_each = var.elb_log_delivery_enabled ? [1] : []
    content {
      sid       = "ELBLogDelivery"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::127311923021:root"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.alb_log_delivery_enabled ? [1] : []
    content {
      sid       = "ALBNLBLogDelivery"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.deny_insecure_transport ? [1] : []
    content {
      sid       = "DenyInsecureTransport"
      effect    = "Deny"
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.deny_tls_older_than_1_2 ? [1] : []
    content {
      sid       = "DenyTLSOlderThan1_2"
      effect    = "Deny"
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && var.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      try(data.aws_iam_policy_document.combined[0].statement, []),
      var.additional_policy_json != null ? jsondecode(var.additional_policy_json).Statement : []
    )
  })
}

# =========================================================
# Module: s3-bucket-module/outputs.tf
# =========================================================
output "bucket_id" {
  value = try(aws_s3_bucket.this[0].id, null)
}

output "bucket_arn" {
  value = try(aws_s3_bucket.this[0].arn, null)
}

output "bucket_region" {
  value = data.aws_region.current.name
}

output "kms_key_arn" {
  value = try(aws_kms_key.this[0].arn, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "target_stack" {
  description = "Target stack identifier"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Short git hash of the stack"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Long zero-padded git hash placeholder"
  type        = string
  default     = "benchmark0000000000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "S3 bucket holding stack artifacts"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "Dataset S3 object key"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "Destigmatized dataset S3 object key"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "Genomic dataset S3 object key"
  type        = string
  default     = "genomic_dataset.csv"
}

locals {
  bucket_arn = "arn:aws:s3:::${var.stack_s3_bucket}"

  # Common permissions for all tiers
  common_statements = [
    {
      sid       = "EC2CreateTags"
      effect    = "Allow"
      actions   = ["ec2:CreateTags"]
      resources = ["arn:aws:ec2:*:*:instance/*"]
    },
    {
      sid       = "CloudWatchPutMetricData"
      effect    = "Allow"
      actions   = ["cloudwatch:PutMetricData"]
      resources = ["*"]
    }
  ]

  # Tier-specific S3 prefixes
  tier_prefixes = {
    wildfly = [
      "artifacts/wildfly/",
      "config/wildfly/",
      "ssl/",
      "datasets/${var.dataset_s3_object_key}",
      "datasets/${var.destigmatized_dataset_s3_object_key}",
      "datasets/${var.genomic_dataset_s3_object_key}",
      "security-tools/"
    ]
    httpd = [
      "artifacts/httpd/",
      "config/httpd/",
      "ssl/",
      "security-tools/"
    ]
    auth-hpds = [
      "artifacts/auth-hpds/",
      "config/auth-hpds/",
      "ssl/",
      "datasets/${var.dataset_s3_object_key}",
      "datasets/${var.genomic_dataset_s3_object_key}",
      "security-tools/"
    ]
    open-hpds = [
      "artifacts/open-hpds/",
      "config/open-hpds/",
      "ssl/",
      "datasets/${var.dataset_s3_object_key}",
      "datasets/${var.genomic_dataset_s3_object_key}",
      "security-tools/"
    ]
    dictionary = [
      "artifacts/dictionary/",
      "config/dictionary/",
      "ssl/",
      "datasets/${var.dataset_s3_object_key}",
      "security-tools/"
    ]
  }

  roles = {
    wildfly-deployment-s3     = "wildfly"
    httpd-deployment-s3       = "httpd"
    auth-hpds-deployment-s3   = "auth-hpds"
    open-hpds-deployment-s3   = "open-hpds"
    dictionary-deployment-s3  = "dictionary"
  }
}

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tier" {
  for_each           = local.roles
  name               = "${each.key}-${var.target_stack}-${var.stack_githash}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json

  tags = {
    Stack            = var.target_stack
    GitHash          = var.stack_githash
    GitHashLong      = var.stack_githash_long
    DeploymentPrefix = each.key
  }
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each   = aws_iam_role.tier
  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  for_each   = aws_iam_role.tier
  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy" "inline" {
  for_each = aws_iam_role.tier
  name     = "${each.key}-inline-policy"
  role     = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      local.common_statements,
      [
        {
          sid       = "S3ListBucket"
          effect    = "Allow"
          actions   = ["s3:ListBucket"]
          resources = [local.bucket_arn]
          condition {
            test     = "StringLike"
            variable = "s3:prefix"
            values   = local.tier_prefixes[local.roles[each.key]]
          }
        },
        {
          sid       = "S3GetObjects"
          effect    = "Allow"
          actions   = ["s3:GetObject"]
          resources = [for p in local.tier_prefixes[local.roles[each.key]] : "${local.bucket_arn}/${p}*"]
        }
      ]
    )
  })
}

resource "aws_iam_instance_profile" "tier" {
  for_each = aws_iam_role.tier
  name     = "${each.key}-${var.target_stack}-${var.stack_githash}"
  role     = each.value.name
}

output "role_arns" {
  value = { for k, v in aws_iam_role.tier : k => v.arn }
}

output "instance_profile_names" {
  value = { for k, v in aws_iam_instance_profile.tier : k => v.name }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "create_sg" {
  description = "Master toggle for the module"
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "Whether to create a new security group (true) or use an existing one (false)"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the security group to create"
  type        = string
  default     = "example-sg"
}

variable "description" {
  description = "Description of the security group"
  type        = string
  default     = "Managed by Terraform"
}

variable "vpc_id" {
  description = "VPC ID for the security group"
  type        = string
  default     = "vpc-00000000000000000"
}

variable "existing_sg_id" {
  description = "ID of an existing security group to attach rules to"
  type        = string
  default     = ""
}

variable "create_before_destroy" {
  description = "Create new SG before destroying old one"
  type        = bool
  default     = false
}

variable "revoke_rules_on_delete" {
  description = "Revoke rules inline on security group delete"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply"
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  type    = string
  default = "example-prefix-list"
}

variable "prefix_list_family" {
  description = "Address family: IPv4 or IPv6"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  type    = number
  default = 10
}

variable "prefix_list_entries" {
  description = "List of CIDR entries for the prefix list"
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "existing_prefix_list_ids" {
  description = "Existing prefix list IDs to use instead of creating one"
  type        = list(string)
  default     = []
}

variable "ingress_rules_new_sg" {
  description = "Ingress rules for the new security group"
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
    sg_id       = optional(string)
    prefix_list_id = optional(string)
  }))
  default = [{
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_ipv4   = "0.0.0.0/0"
  }]
}

variable "egress_rules_new_sg" {
  description = "Egress rules for the new security group"
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
    sg_id       = optional(string)
    prefix_list_id = optional(string)
  }))
  default = [{
    description = "Allow all outbound IPv4"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_ipv4   = "0.0.0.0/0"
  }]
}

variable "ingress_rules_existing_sg" {
  description = "Ingress rules for the existing security group"
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
    sg_id       = optional(string)
    prefix_list_id = optional(string)
  }))
  default = []
}

variable "egress_rules_existing_sg" {
  description = "Egress rules for the existing security group"
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
    sg_id       = optional(string)
    prefix_list_id = optional(string)
  }))
  default = []
}

# ---------------- Locals ----------------

locals {
  create_sg     = var.create_sg
  create_new_sg = var.create_sg && var.create_new_sg

  sg_id = local.create_new_sg ? aws_security_group.this[0].id : var.existing_sg_id

  prefix_list_id = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids[0] : (var.create_prefix_list ? aws_ec2_managed_prefix_list.this[0].id : null)

  ingress_rules_new = [for r in var.ingress_rules_new_sg : merge(r, {
    prefix_list_id = coalesce(r.prefix_list_id, local.prefix_list_id)
  })]

  egress_rules_new = [for r in var.egress_rules_new_sg : merge(r, {
    prefix_list_id = coalesce(r.prefix_list_id, local.prefix_list_id)
  })]

  ingress_rules_existing = [for r in var.ingress_rules_existing_sg : merge(r, {
    prefix_list_id = coalesce(r.prefix_list_id, local.prefix_list_id)
  })]

  egress_rules_existing = [for r in var.egress_rules_existing_sg : merge(r, {
    prefix_list_id = coalesce(r.prefix_list_id, local.prefix_list_id)
  })]
}

# ---------------- Prefix List ----------------

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_sg && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr = entry.value
    }
  }

  tags = merge(var.tags, { Name = var.prefix_list_name })
}

# ---------------- Security Group ----------------

resource "aws_security_group" "this" {
  count = local.create_new_sg ? 1 : 0

  name        = var.name
  description = var.description
  vpc_id      = var.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  dynamic "egress" {
    for_each = var.create_before_destroy ? [] : local.egress_rules_new
    content {
      description    = egress.value.description
      from_port      = egress.value.from_port
      to_port        = egress.value.to_port
      protocol       = egress.value.protocol
      cidr_ipv4      = egress.value.cidr_ipv4
      cidr_ipv6      = egress.value.cidr_ipv6
      security_groups = egress.value.sg_id != null ? [egress.value.sg_id] : null
      prefix_list_id = egress.value.prefix_list_id
    }
  }

  tags = merge(var.tags, { Name = var.name })

  lifecycle {
    create_before_destroy = var.create_before_destroy
  }
}

# Inline egress when create_before_destroy is enabled (separate resource to avoid conflicts)
resource "aws_vpc_security_group_egress_rule" "new_cbd" {
  for_each = local.create_new_sg && var.create_before_destroy ? { for idx, r in local.egress_rules_new : idx => r } : {}

  security_group_id = aws_security_group.this[0].id

  description    = each.value.description
  ip_protocol    = each.value.protocol
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  cidr_ipv4      = each.value.cidr_ipv4
  cidr_ipv6      = each.value.cidr_ipv6
  referenced_security_group_id = each.value.sg_id
  prefix_list_id = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null

  tags = var.tags
}

# ---------------- Rules for New SG (standalone resources) ----------------

resource "aws_vpc_security_group_ingress_rule" "new" {
  for_each = local.create_new_sg ? { for idx, r in local.ingress_rules_new : idx => r } : {}

  security_group_id = aws_security_group.this[0].id

  description    = each.value.description
  ip_protocol    = each.value.protocol
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  cidr_ipv4      = each.value.cidr_ipv4
  cidr_ipv6      = each.value.cidr_ipv6
  referenced_security_group_id = each.value.sg_id
  prefix_list_id = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "new" {
  for_each = local.create_new_sg && !var.create_before_destroy ? { for idx, r in local.egress_rules_new : idx => r } : {}

  security_group_id = aws_security_group.this[0].id

  description    = each.value.description
  ip_protocol    = each.value.protocol
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  cidr_ipv4      = each.value.cidr_ipv4
  cidr_ipv6      = each.value.cidr_ipv6
  referenced_security_group_id = each.value.sg_id
  prefix_list_id = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null

  tags = var.tags
}

# ---------------- Rules for Existing SG ----------------

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.create_sg && !local.create_new_sg && var.existing_sg_id != "" ? { for idx, r in local.ingress_rules_existing : idx => r } : {}

  security_group_id = var.existing_sg_id

  description    = each.value.description
  ip_protocol    = each.value.protocol
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  cidr_ipv4      = each.value.cidr_ipv4
  cidr_ipv6      = each.value.cidr_ipv6
  referenced_security_group_id = each.value.sg_id
  prefix_list_id = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.create_sg && !local.create_new_sg && var.existing_sg_id != "" ? { for idx, r in local.egress_rules_existing : idx => r } : {}

  security_group_id = var.existing_sg_id

  description    = each.value.description
  ip_protocol    = each.value.protocol
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  cidr_ipv4      = each.value.cidr_ipv4
  cidr_ipv6      = each.value.cidr_ipv6
  referenced_security_group_id = each.value.sg_id
  prefix_list_id = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null

  tags = var.tags
}

# ---------------- Outputs ----------------

output "security_group_id" {
  description = "ID of the security group in use"
  value       = local.create_sg ? local.sg_id : null
}

output "prefix_list_id" {
  description = "ID of the created prefix list, if any"
  value       = var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? try(aws_ec2_managed_prefix_list.this[0].id, null) : null
}

```hcl
variable "project" {
  description = "Project name prefix"
  type        = string
  default     = "Cv-React-App"
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------
# Trust policies
# ---------------------------------------------------------------
data "aws_iam_policy_document" "ec2_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codedeploy_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codepipeline_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = [
        "ec2.amazonaws.com",
        "codedeploy.amazonaws.com",
        "codebuild.amazonaws.com",
        "codepipeline.amazonaws.com",
        "cloudformation.amazonaws.com",
        "lambda.amazonaws.com",
        "codestar-connections.amazonaws.com",
        "events.amazonaws.com",
        "s3.amazonaws.com"
      ]
    }
  }
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

# ---------------------------------------------------------------
# CodeBuild inline policy
# ---------------------------------------------------------------
data "aws_iam_policy_document" "codebuild_inline" {
  statement {
    sid    = "LoggingPermissions"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject"
    ]
    resources = ["arn:aws:s3:::codepipeline-${var.aws_region}-*"]
  }

  statement {
    sid    = "CodeBuildReports"
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases",
      "codebuild:BatchPutCodeCoverages"
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------
# CodePipeline inline policy
# ---------------------------------------------------------------
data "aws_iam_policy_document" "codepipeline_inline" {
  statement {
    sid    = "FullPipelineActions"
    effect = "Allow"
    actions = [
      "codestar-connections:*",
      "s3:*",
      "codecommit:*",
      "codedeploy:*",
      "lambda:*",
      "codebuild:*",
      "cloudformation:*",
      "iam:PassRole",
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:PutRolePolicy",
      "iam:DeleteRolePolicy",
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListRoles",
      "iam:ListRolePolicies",
      "iam:ListAttachedRolePolicies",
      "ec2:Describe*",
      "events:PutRule",
      "events:DeleteRule",
      "events:DescribeRule",
      "events:PutTargets",
      "events:RemoveTargets",
      "sns:CreateTopic",
      "sns:DeleteTopic",
      "sns:Subscribe",
      "sns:Unsubscribe",
      "sns:Publish",
      "cloudwatch:*",
      "logs:*",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "sts:GetCallerIdentity"
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------
# EC2 CodeDeploy role + instance profile
# ---------------------------------------------------------------
resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleForAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy_profile" {
  name = "${var.project}_ec2_codedeploy_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# ---------------------------------------------------------------
# CodeDeploy service role
# ---------------------------------------------------------------
resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_trust.json
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_codedeploy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_full" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# ---------------------------------------------------------------
# CloudWatch Agent role + instance profile
# ---------------------------------------------------------------
resource "aws_iam_role" "cloudwatch_agent_role" {
  name               = "${var.project}_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_policy" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_full" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "cloudwatch_agent_profile" {
  name = "${var.project}_cloudwatch_agent_profile"
  role = aws_iam_role.cloudwatch_agent_role.name
}

# ---------------------------------------------------------------
# CodeBuild role
# ---------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_trust.json
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name   = "CodeBuildInlinePolicy"
  role   = aws_iam_role.codebuild_role.id
  policy = data.aws_iam_policy_document.codebuild_inline.json
}

# ---------------------------------------------------------------
# CodePipeline role
# ---------------------------------------------------------------
resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_trust.json
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name   = "CodePipelineInlinePolicy"
  role   = aws_iam_role.codepipeline_role.id
  policy = data.aws_iam_policy_document.codepipeline_inline.json
}

# ---------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------
output "ec2_codedeploy_role_arn" {
  value = aws_iam_role.ec2_codedeploy_role.arn
}

output "ec2_codedeploy_instance_profile" {
  value = aws_iam_instance_profile.ec2_codedeploy_profile.name
}

output "codedeploy_service_role_arn" {
