terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
  }
}

resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"
  attribute { name = "appId" type = "S" }
  tags = merge(local.common_tags, { Name = "near-app-actions-mapping" })
  lifecycle { prevent_destroy = true }
}

resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"
