resource "aws_ssm_parameter" "invitations_arn" {
  name  = "/file-service/dynamodb/invitations/arn"
  type  = "String"
  value = aws_dynamodb_table.near_files_invitations.arn
}
resource "aws_ssm_parameter" "invitations_name" {
  name  = "/file-service/dynamodb/invitations/table_name"
  type  = "String"
  value = aws_dynamodb_table.near_files_invitations.name
}
resource "aws_ssm_parameter" "invitations_stream" {
  name  = "/file-service/dynamodb/invitations/stream_arn"
