```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "admin_cidr" {
  type    = string
  default = "203.0.113.0/24"
}

variable "ssh_public_key" {
  type    = string
  default = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQC7examplekeydatafordefaultplaceholder== user@host"
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
}

variable "asg_min" {
  type    = number
  default = 1
}

variable "asg_max" {
  type    = number
  default = 2
}

variable "chaos_tag" {
  type    = string
  default = "chaos-target"
}

data "aws_ssm_parameter" "ecs_ami" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2023/recommended/image_id"
}

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid       = "AllowLogDelivery"
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "aws_kms_key" "fis_logs" {
  description             = "KMS key for FIS experiment log bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json
}

resource "aws_kms_alias" "fis_logs" {
  name          = "alias/fis-logs-key"
  target_key_id = aws_kms_key.fis_logs.key_id
}

# ---------------- Networking ----------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = "chaos-vpc" }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone       = "${var.aws_region}a"
  tags = {
    Name             = "chaos-public-subnet"
    "chaos:target"   = var.chaos_tag
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "chaos-igw" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "chaos-public-rt" }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------- SSH key & security group ----------------
resource "aws_key_pair" "admin" {
  key_name   = "chaos-admin-key"
  public_key = var.ssh_public_key
}

resource "aws_security_group" "ssh" {
  name        = "chaos-ssh-sg"
  description = "SSH access restricted to admin CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "chaos-ssh-sg" }
}

# ---------------- EC2 instance role & profile ----------------
resource "aws_iam_role" "ec2" {
  name = "chaos-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "chaos-ec2-profile"
  role = aws_iam_role.ec2.name
}

# ---------------- Launch template & ASG ----------------
resource "aws_launch_template" "chaos" {
  name          = "chaos-launch-template"
  image_id      = data.aws_ssm_parameter.ecs_ami.value
  instance_type = var.instance_type
  key_name      = aws_key_pair.admin.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2.name
  }

  metadata_options {
    http_tokens                 = "required"
    http_endpoint               = "enabled"
    http_put_response_hop_limit = 2
  }

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.ssh.id]
    delete_on_termination       = true
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name           = "chaos-instance"
      "chaos:target" = var.chaos_tag
    }
  }
}

resource "aws_autoscaling_group" "chaos" {
  name                = "chaos-asg"
  min_size            = var.asg_min
  max_size            = var.asg_max
  desired_capacity    = var.asg_min
  vpc_zone_identifier = [aws_subnet.public.id]
  target_group_arns   = []

  launch_template {
    id      = aws_launch_template.chaos.id
    version = "$Latest"
  }

  tag {
    key                 = "chaos:target"
    value               = var.chaos_tag
    propagate_at_launch = true
  }

  lifecycle {
    ignore_changes = [target_group_arns]
  }
}

# ---------------- FIS logging bucket ----------------
resource "aws_s3_bucket" "fis_logs" {
  bucket        = "chaos-fis-logs-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSLogDeliveryWrite"
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.fis_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid       = "AWSLogDeliveryAclCheck"
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.fis_logs.arn
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "fis" {
  name              = "/aws/fis/chaos-experiments"
  retention_in_days = 30
}

# ---------------- FIS role ----------------
resource "aws_iam_role" "fis" {
  name = "chaos-fis-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "fis.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "fis" {
  name = "chaos-fis-permissions"
  role = aws_iam_role.fis.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeImages"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2:RebootInstances", "ec2:StopInstances", "ec2:TerminateInstances"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2:CreateTags", "ec2:DeleteTags"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2:SendCpuStressFault", "ec2:SendNetworkFault", "ec2:SendDiskFault"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogDelivery", "logs:GetLogDelivery", "logs:UpdateLogDelivery", "logs:DeleteLogDelivery", "logs:ListLogDeliveries"]
        Resource = "*"
      }
    ]
  })
}

# ---------------- FIS experiment templates ----------------
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "API-level internal-error fault on EC2 DescribeImages"
  role_arn    = aws_iam_role.fis.arn

  action {
    name     = "describe-images-internal-error"
    action_id = "aws:fis:inject-api-internal-error"
    parameters = {
      service = "ec2"
      operation = "DescribeImages"
    }
    target = { Targets = { "Resources" = "tagged-instances" } }
  }

  target {
    name   = "tagged-instances"
    resource_type = "aws:ec2:instance"
    resource_tags = { "chaos:target" = var.chaos_tag }
    selection_mode = "ALL"
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2
    cloud_watch_logs_configuration {
      log_group_arn = aws_cloudwatch_log_group.fis.arn
    }
  }

  tags = { Name = "chaos-api-internal-error" }
}

resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "Pause EBS volume I/O"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "pause-volume-io"
    action_id = "aws:fis:pause-volume-io"
    parameters = {
      duration = "60s"
    }
    target = { Targets = { "Volumes" = "tagged-volumes" } }
  }

  target {
    name           = "tagged-volumes"
    resource_type  = "aws:ec2:volume"
    resource_tags  = { "chaos:target" = var.chaos_tag }
    selection_mode = "ALL"
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2
    cloud_watch_logs_configuration {
      log_group_arn = aws_cloudwatch_log_group.fis.arn
    }
  }

  tags = { Name = "chaos-ebs-pause-io" }
}

resource "aws_fis_experiment_template" "cpu_stress" {
  description = "CPU stress on EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "cpu-stress"
    action_id = "aws:fis:inject-cpu-stress"
    parameters = {
      duration = "300s"
    }
    target = { Targets = { "Instances" = "tagged-instances" } }
  }

  target {
    name           = "tagged-instances"
    resource_type  = "aws:ec2:instance"
    resource_tags  = { "chaos:target" = var.chaos_tag }
    selection_mode = "ALL"
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2
    cloud_watch_logs_configuration {
      log_group_arn = aws_cloudwatch_log_group.fis.arn
    }
  }

  tags = { Name = "chaos-cpu-stress" }
}

resource "aws_fis_experiment_template" "instance_termination" {
  description = "Terminate EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  action {
    name       = "terminate-instances"
    action_id  = "aws:fis:terminate-instances"
    target     = { Targets = { "Instances" = "tagged-instances" } }
  }

  target {
    name           = "tagged-instances"
    resource_type  = "aws:ec2:instance"
    resource_tags  = { "chaos:target" = var.chaos_tag }
    selection_mode = "ALL"
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2
    cloud_watch_logs_configuration {
      log_group_arn = aws_cloudwatch_log_group.fis.arn
    }
  }

  tags = { Name = "chaos-instance-termination" }
}

resource "aws_fis_experiment_template" "network_disruption" {
  description = "Network connectivity disruption on subnet"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "network-blackhole"
    action_id = "aws:fis:inject-network-blackhole"
    parameters = {
      duration = "120s"
    }
    target = { Targets = { "Subnets" = "chaos-subnet" } }
  }

  target {
    name           = "chaos-subnet"
    resource_type  = "aws:ec2:subnet"
    resource_ids   = [aws_subnet.public.id]
    selection_mode = "ALL"
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2
    cloud_watch_logs_configuration {
      log_group_arn = aws_cloudwatch_log_group.fis.arn
    }
  }

  tags = { Name = "chaos-network-disruption" }
}

output "fis_experiment_template_ids" {
  value = [
    aws_fis_experiment_template.api_internal_error.id,
    aws_fis_experiment_template.ebs_pause_io.id,
    aws_fis_experiment_template.cpu_stress.id,
    aws_fis_experiment_template.instance_termination.id,
    aws_fis_experiment_template.network_disruption.id
  ]
}

output "log_bucket_name" {
  value = aws_s3_bucket.fis_logs.bucket
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  type    = string
  default = "modular-vpc"
}

variable "create_vpc" {
  type    = bool
  default = true
}

variable "cidr_block" {
  type    = string
  default = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  type    = string
  default = null
}

variable "ipv4_netmask_length" {
  type    = number
  default = null
}

variable "secondary_cidr_blocks" {
  type    = list(string)
  default = []
}

variable "enable_dns_hostnames" {
  type    = bool
  default = true
}

variable "enable_dns_support" {
  type    = bool
  default = true
}

variable "create_igw" {
  type    = bool
  default = true
}

variable "create_egress_only_igw" {
  type    = bool
  default = false
}

variable "public_subnets" {
  description = "Map of public subnets: cidr, az, ipv6_cidr"
  type = map(object({
    cidr       = string
    az         = string
    ipv6_cidr  = optional(string)
  }))
  default = {
    "public-a" = { cidr = "10.0.0.0/20", az = "us-east-1a" }
    "public-b" = { cidr = "10.0.16.0/20", az = "us-east-1b" }
  }
}

variable "private_subnets" {
  description = "Map of private subnets: cidr, az, ipv6_cidr, nat_gateway (bool)"
  type = map(object({
    cidr         = string
    az           = string
    ipv6_cidr    = optional(string)
    nat_gateway  = optional(bool, false)
  }))
  default = {
    "private-a" = { cidr = "10.0.128.0/20", az = "us-east-1a", nat_gateway = true }
    "private-b" = { cidr = "10.0.144.0/20", az = "us-east-1b" }
  }
}

variable "create_dhcp_options" {
  type    = bool
  default = false
}

variable "dhcp_options" {
  type = object({
    domain_name         = optional(string)
    domain_name_servers = optional(list(string), ["AmazonProvidedDNS"])
    ntp_servers         = optional(list(string), [])
    netbios_name_servers = optional(list(string), [])
    netbios_node_type   = optional(string)
  })
  default = {}
}

variable "flow_logs_enabled" {
  type    = bool
  default = false
}

variable "flow_logs_destination" {
  description = "cloud-watch-logs or s3"
  type        = string
  default     = "cloud-watch-logs"
}

variable "flow_logs_retention" {
  type    = number
  default = 30
}

variable "flow_logs_traffic_type" {
  type    = string
  default = "ALL"
}

variable "flow_logs_aggregation_interval" {
  type    = number
  default = 600
}

variable "flow_logs_format" {
  type    = string
  default = "$${version} $${account-id} $${interface-id} $${srcaddr} $${dstaddr} $${srcport} $${dstport} $${protocol} $${packets} $${bytes} $${start} $${end} $${action} $${log-status}"
}

variable "manage_default_security_group" {
  type    = bool
  default = false
}

variable "manage_default_network_acl" {
  type    = bool
  default = false
}

variable "manage_default_route_table" {
  type    = bool
  default = false
}

locals {
  vpc_id = try(aws_vpc.this[0].id, "")
  assign_ipv6 = false
}

# ---------------- VPC ----------------
resource "aws_vpc" "this" {
  count                = var.create_vpc ? 1 : 0
  cidr_block           = var.ipv4_ipam_pool_id == null ? var.cidr_block : null
  ipv4_ipam_pool_id    = var.ipv4_ipam_pool_id
  ipv4_netmask_length  = var.ipv4_netmask_length
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = { Name = "${var.name}-vpc" }
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each   = toset(var.secondary_cidr_blocks)
  count      = var.create_vpc ? 1 : 0
  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

# ---------------- Internet Gateway ----------------
resource "aws_internet_gateway" "this" {
  count  = var.create_vpc && var.create_igw ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  tags   = { Name = "${var.name}-igw" }
}

resource "aws_egress_only_internet_gateway" "this" {
  count  = var.create_vpc && var.create_egress_only_igw ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  tags   = { Name = "${var.name}-eigw" }
}

# ---------------- NAT Gateways ----------------
resource "aws_eip" "nat" {
  for_each = var.create_vpc ? { for k, v in var.private_subnets : k => v if v.nat_gateway } : {}
  domain   = "vpc"
  tags     = { Name = "${var.name}-nat-eip-${each.key}" }
}

resource "aws_nat_gateway" "this" {
  for_each      = var.create_vpc ? { for k, v in var.private_subnets : k => v if v.nat_gateway } : {}
  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id
  depends_on    = [aws_internet_gateway.this]
  tags          = { Name = "${var.name}-nat-${each.key}" }
}

# ---------------- Subnets ----------------
resource "aws_subnet" "public" {
  for_each                = var.create_vpc ? var.public_subnets : {}
  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = true
  ipv6_cidr_block         = try(each.value.ipv6_cidr, null)

  tags = { Name = "${var.name}-public-${each.key}", Tier = "public" }
}

resource "aws_subnet" "private" {
  for_each          = var.create_vpc ? var.private_subnets : {}
  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az
  ipv6_cidr_block   = try(each.value.ipv6_cidr, null)

  tags = { Name = "${var.name}-private-${each.key}", Tier = "private" }
}

# ---------------- Route Tables ----------------
resource "aws_route_table" "public" {
  count  = var.create_vpc && var.create_igw ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  tags   = { Name = "${var.name}-public-rt" }
}

resource "aws_route" "public_internet" {
  count                  = var.create_vpc && var.create_igw ? 1 : 0
  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route" "public_internet_ipv6" {
  count                   = var.create_vpc && var.create_igw ? 1 : 0
  route_table_id          = aws_route_table.public[0].id
  destination_ipv6_cidr_block = "::/0"
  gateway_id              = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each       = var.create_vpc && var.create_igw ? var.public_subnets : {}
  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}
  vpc_id   = aws_vpc.this[0].id
  tags     = { Name = "${var.name}-private-rt-${each.key}" }
}

resource "aws_route" "private_nat" {
  for_each               = var.create_vpc ? { for k, v in var.private_subnets : k => v if v.nat_gateway } : {}
  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.key].id
}

resource "aws_route" "private_eigw" {
  count                       = var.create_vpc && var.create_egress_only_igw ? 1 : 0
  route_table_id              = aws_route_table.private[keys(var.private_subnets)[0]].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  for_each       = var.create_vpc ? var.private_subnets : {}
  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

# ---------------- Network ACLs ----------------
resource "aws_network_acl" "public" {
  count      = var.create_vpc ? 1 : 0
  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [for s in aws_subnet.public : s.id]
  tags       = { Name = "${var.name}-public-nacl" }
}

resource "aws_network_acl_rule" "public_in" {
  for_each        = var.create_vpc ? toset(["80", "443", "1024-65535"]) : toset([])
  network_acl_id  = aws_network_acl.public[0].id
  rule_number     = index(["80", "443", "1024-65535"], each.value) + 100
  egress          = false
  protocol        = "tcp"
  rule_action     = "allow"
  cidr_block      = "0.0.0.0/0"
  from_port       = each.value == "1024-65535" ? 1024 : tonumber(each.value)
  to_port         = each.value == "1024-65535" ? 65535 : tonumber(each.value)
}

resource "aws_network_acl_rule" "public_out" {
  for_each        = var.create_vpc ? toset(["80", "443", "1024-65535"]) : toset([])
  network_acl_id  = aws_network_acl.public[0].id
  rule_number     = index(["80", "443", "1024-65535"], each.value) + 100
  egress          = true
  protocol        = "tcp"
  rule_action     = "allow"
  cidr_block      = "0.0.0.0/0"
  from_port       = each.value == "1024-65535" ? 1024 : tonumber(each.value)
  to_port         = each.value == "1024-65535" ? 65535 : tonumber(each.value)
}

resource "aws_network_acl" "private" {
  for_each   = var.create_vpc ? var.private_subnets : {}
  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [aws_subnet.private[each.key].id]
  tags       = { Name = "${var.name}-private-nacl-${each.key}" }
}

resource "aws_network_acl_rule" "private_in_all" {
  for_each       = var.create_vpc ? var.private_subnets : {}
  network_acl_id = aws_network_acl.private[each.key].id
  rule_number    = 100
  egress         = false
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "private_out_all" {
  for_each       = var.create_vpc ? var.private_subnets : {}
  network_acl_id = aws_network_acl.private[each.key].id
  rule_number    = 100
  egress         = true
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
}

# ---------------- DHCP Options ----------------
resource "aws_vpc_dhcp_options" "this" {
  count                = var.create_vpc && var.create_dhcp_options ? 1 : 0
  domain_name          = try(var.dhcp_options.domain_name, null)
  domain_name_servers  = try(var.dhcp_options.domain_name_servers, ["AmazonProvidedDNS"])
  ntp_servers          = try(var.dhcp_options.ntp_servers, null)
  netbios_name_servers = try(var.dhcp_options.netbios_name_servers, null)
  netbios_node_type    = try(var.dhcp_options.netbios_node_type, null)
  tags                 = { Name = "${var.name}-dhcp" }
}

resource "aws_vpc_dhcp_options_association" "this" {
  count           = var.create_vpc && var.create_dhcp_options ? 1 : 0
  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

# ---------------- Flow Logs ----------------
resource "aws_iam_role" "flow_logs" {
  count = var.create_vpc && var.flow_logs_enabled && var.flow_logs_destination == "cloud-watch-logs" ? 1 : 0
  name  = "${var.name}-flowlogs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "vpc-flow-logs.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  count = length(aws_iam_role.flow_logs) > 0 ? 1 : 0
  name  = "${var.name}-flowlogs-policy"
  role  = aws_iam_role.flow_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
      Resource = "*"
    }]
  })
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count             = var.create_vpc && var.flow_logs_enabled && var.flow_logs_destination == "cloud-watch-logs" ? 1 : 0
  name              = "/aws/vpc/${var.name}-flowlogs"
  retention_in_days = var.flow_logs_retention
}

resource "aws_s3_bucket" "flow_logs" {
  count  = var.create_vpc && var.flow_logs_enabled && var.flow_logs_destination == "s3" ? 1 : 0
  bucket = "${var.name}-vpc-flowlogs-${data.aws_caller_identity.current.account_id}"
}

data "aws_caller_identity" "current" {}

resource "aws_flow_log" "this" {
  count                     = var.create_vpc && var.flow_logs_enabled ? 1 : 0
  vpc_id                    = aws_vpc.this[0].id
  traffic_type              = var.flow_logs_traffic_type
  log_destination_type      = var.flow_logs_destination == "s3" ? "s3" : "cloud-watch-logs"
  log_destination           = var.flow_logs_destination == "s3" ? aws_s3_bucket.flow_logs[0].arn : aws_cloudwatch_log_group.flow_logs[0].arn
  iam_role_arn              = var.flow_logs_destination == "s3" ? null : aws_iam_role.flow_logs[0].arn
  log_format                = var.flow_logs_format
  max_aggregation_interval  = var.flow_logs_aggregation_interval
  tags                      = { Name = "${var.name}-flowlogs" }
}

# ---------------- Default Resource Governance ----------------
resource "aws_default_security_group" "this" {
  count  = var.create_vpc && var.manage_default_security_group ? 1 : 0
  vpc_id = aws_vpc.this[0].id

  tags = { Name = "${var.name}-default-sg" }
}

resource "aws_default_network_acl" "this" {
  count                   = var.create_vpc && var.manage_default_network_acl ? 1 : 0
  default_network_acl_id  = aws_vpc.this[0].default_network_acl_id

  ingress {
    protocol    = "-1"
    rule_no     = 100
    action      = "allow"
    cidr_block  = "0.0.0.0/0"
    from_port   = 0
    to_port     = 0
  }

  ingress {
    protocol            = "-1"
    rule_no             = 101
    action              = "allow"
    ipv6_cidr_block     = "::/0"
    from_port           = 0
    to_port             = 0
  }

  egress {
    protocol    = "-1"
    rule_no     = 100
    action      = "allow"
    cidr_block  = "0.0.0.0/0"
    from_port   = 0
    to_port     = 0
  }

  egress {
    protocol            = "-1"
    rule_no             = 101
    action              = "allow"
    ipv6_cidr_block     = "::/0"
    from_port           = 0
    to_port             = 0
  }

  tags = { Name = "${var.name}-default-nacl" }
}

resource "aws_default_route_table" "this" {
  count                  = var.create_vpc && var.manage_default_route_table ? 1 : 0
  default_route_table_id = aws_vpc.this[0].default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = var.create_igw ? aws_internet_gateway.this[0].id : null
  }

  tags = { Name = "${var.name}-default-rt" }
}

# ---------------- Outputs ----------------
output "vpc_id" {
  value = local.vpc_id
}

output "public_subnet_ids" {
  value = [for s in aws_subnet.public : s.id]
}

output "private_subnet_ids" {
  value = [for s in aws_subnet.private : s.id]
}

output "nat_gateway_ids" {
  value = [for n in aws_nat_gateway.this : n.id]
}

output "igw_id" {
  value = try(aws_internet_gateway.this[0].id, null)
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------
variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "server_name" {
  description = "Explicit server identifier; falls back to random pet name"
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "PUBLIC, VPC, or VPC_ENDPOINT"
  type        = string
  default     = "PUBLIC"
}

variable "protocols" {
  type    = list(string)
  default = ["SFTP"]
}

variable "security_policy_name" {
  type    = string
  default = "TransferSecurityPolicy-2023-05"
}

variable "identity_provider_type" {
  type    = string
  default = "SERVICE_MANAGED"
}

variable "api_gateway_url" {
  type    = string
  default = ""
}

variable "logging_role_arn" {
  type    = string
  default = ""
}

variable "certificate_arn" {
  type    = string
  default = ""
}

variable "pre_authentication_lambda_arn" {
  type    = string
  default = ""
}

variable "host_key" {
  type    = string
  default = ""
}

variable "invocation_role_arn" {
  type    = string
  default = ""
}

variable "custom_login_banner" {
  type    = string
  default = ""
}

variable "display_login_banner" {
  type    = string
  default = ""
}

variable "cloudwatch_logging_role_arn" {
  type    = string
  default = ""
}

variable "structured_log_destinations" {
  type    = list(string)
  default = []
}

variable "s3_storage" {
  type    = string
  default = "S3"
}

variable "vpc_endpoint_id" {
  type    = string
  default = ""
}

variable "address_allocation_ids" {
  description = "Pre-existing EIP allocation IDs for VPC endpoint"
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "Subnets for VPC-hosted server; EIPs auto-created if no allocations supplied"
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Pre-existing security groups; auto-created if empty for VPC mode"
  type        = list(string)
  default     = []
}

variable "vpc_id" {
  description = "VPC ID for auto-created security group"
  type        = string
  default     = ""
}

variable "endpoint_details" {
  description = "Full endpoint details block (overrides individual vars)"
  type = object({
    address_allocation_ids = optional(list(string))
    subnet_ids             = optional(list(string))
    vpc_endpoint_id        = optional(string)
    vpc_id                 = optional(string)
    security_group_ids     = optional(list(string))
  })
  default = {}
}

variable "protocol_details" {
  description = "AS2, passive IP, set-stat options, TLS session resumption"
  type = object({
    as2_transports                          = optional(list(string))
    passive_ip                              = optional(string)
    set_stat_option                         = optional(string)
    tls_session_resumption_mode             = optional(string)
    stream_login_group_initialization_mode  = optional(string)
  })
  default = {}
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

variable "route53_subdomain" {
  type    = string
  default = "sftp"
}

variable "sftp_users" {
  description = "Map of users: home_bucket_path, e.g. { alice = { home_bucket_path = \"my-bucket/home/alice\" } }"
  type = map(object({
    home_bucket_path = string
  }))
  default = {}
}

variable "sftp_user_keys" {
  description = "Map of user -> list of SSH public keys"
  type        = map(list(string))
  default     = {}
}

# ------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------
resource "random_pet" "server" {
  count = var.server_name == "" ? 1 : 0
}

locals {
  server_id = var.server_name != "" ? var.server_name : random_pet.server[0].id

  # Endpoint details: use explicit var.endpoint_details if provided,
  # otherwise build from individual vars (auto EIPs/SG for VPC).
  endpoint_details = length(keys(var.endpoint_details)) > 0 ? var.endpoint_details : (
    var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT" ? {
      address_allocation_ids = var.address_allocation_ids
      subnet_ids             = var.subnet_ids
      vpc_endpoint_id        = var.vpc_endpoint_id
      vpc_id                 = var.vpc_id
      security_group_ids     = var.security_group_ids
    } : {}
  )

  needs_auto_sg = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") &&
    length(lookup(local.endpoint_details, "security_group_ids", [])) == 0

  needs_auto_eips = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") &&
    length(lookup(local.endpoint_details, "address_allocation_ids", [])) == 0 &&
    length(lookup(local.endpoint_details, "subnet_ids", [])) > 0

  final_endpoint_details = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT" ? {
    address_allocation_ids = local.needs_auto_eips ? [for e in aws_eip.transfer[0].allocations : e] : lookup(local.endpoint_details, "address_allocation_ids", null)
    subnet_ids             = lookup(local.endpoint_details, "subnet_ids", null)
    vpc_endpoint_id        = lookup(local.endpoint_details, "vpc_endpoint_id", null)
    vpc_id                 = lookup(local.endpoint_details, "vpc_id", null)
    security_group_ids     = local.needs_auto_sg ? [aws_security_group.transfer[0].id] : lookup(local.endpoint_details, "security_group_ids", null)
  } : null
}

# ------------------------------------------------------------------
# Logging role (unless explicit ARN provided)
# ------------------------------------------------------------------
data "aws_iam_policy_document" "logging_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "logging" {
  count              = var.logging_role_arn == "" ? 1 : 0
  name               = "${local.server_id}-logging-role"
  assume_role_policy = data.aws_iam_policy_document.logging_assume.json
}

resource "aws_iam_role_policy_attachment" "logging" {
  count      = var.logging_role_arn == "" ? 1 : 0
  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/AWSTransferLoggingAccess"
}

locals {
  effective_logging_role = var.logging_role_arn != "" ? var.logging_role_arn : aws_iam_role.logging[0].arn
}

# ------------------------------------------------------------------
# API Gateway auth role (CloudWatch logging permissions)
# ------------------------------------------------------------------
data "aws_iam_policy_document" "apigw_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_auth" {
  count              = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name               = "${local.server_id}-apigw-auth-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume.json
}

resource "aws_iam_role_policy" "apigw_auth_cw" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name  = "${local.server_id}-apigw-cw-logs"
  role  = aws_iam_role.apigw_auth[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
      Resource = "*"
    }]
  })
}

# ------------------------------------------------------------------
# Auto-provisioned VPC networking
# ------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count  = local.needs_auto_sg ? 1 : 0
  name   = "${local.server_id}-sftp-sg"
  vpc_id = lookup(local.endpoint_details, "vpc_id", null) != null ? lookup(local.endpoint_details, "vpc_id") : var.vpc_id

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${local.server_id}-sftp-sg" }
}

resource "aws_eip" "transfer" {
  count = local.needs_auto_eips ? length(lookup(local.endpoint_details, "subnet_ids", [])) : 0
  domain = "vpc"
}

locals {
  auto_allocation_ids = local.needs_auto_eips ? [for e in aws_eip.transfer : e.allocation_id] : []
}

# ------------------------------------------------------------------
# Transfer Server
# ------------------------------------------------------------------
resource "aws_transfer_server" "this" {
  identifier             = local.server_id
  identity_provider_type = var.identity_provider_type
  endpoint_type          = var.endpoint_type
  domain                 = var.s3_storage
  protocols              = var.protocols
  security_policy_name   = var.security_policy_name
  logging_role           = local.effective_logging_role
  pre_authentication_lambda_arn = var.pre_authentication_lambda_arn != "" ? var.pre_authentication_lambda_arn : null
  host_key               = var.host_key != "" ? var.host_key : null
  certificate            = var.certificate_arn != "" ? var.certificate_arn : null
  invocation_role        = var.invocation_role_arn != "" ? var.invocation_role_arn : null
  url                    = var.api_gateway_url != "" ? var.api_gateway_url : null

  dynamic "endpoint_details" {
    for_each = local.final_endpoint_details != null ? [local.final_endpoint_details] : []
    content {
      address_allocation_ids = endpoint_details.value.address_allocation_ids
      subnet_ids             = endpoint_details.value.subnet_ids
      vpc_endpoint_id        = endpoint_details.value.vpc_endpoint_id
      vpc_id                 = endpoint_details.value.vpc_id
      security_group_ids     = endpoint_details.value.security_group_ids
    }
  }

  dynamic "protocol_details" {
    for_each = length(keys(var.protocol_details)) > 0 ? [var.protocol_details] : []
    content {
      as2_transports             = try(protocol_details.value.as2_transports, null)
      passive_ip                 = try(protocol_details.value.passive_ip, null)
      set_stat_option            = try(protocol_details.value.set_stat_option, null)
      tls_session_resumption_mode = try(protocol_details.value.tls_session_resumption_mode, null)
    }
  }

  dynamic "identity_provider_details" {
    for_each = var.identity_provider_type == "API_GATEWAY" ? [1] : []
    content {
      api_gateway_url  = var.api_gateway_url
      invocation_role  = var.invocation_role_arn != "" ? var.invocation_role_arn : aws_iam_role.apigw_auth[0].arn
    }
  }

  pre_authentication_login_banner = var.display_login_banner != "" ? var.display_login_banner : null
  post_authentication_login_banner = var.custom_login_banner != "" ? var.custom_login_banner : null

  dynamic "s3_storage_options" {
    for_each = length(var.structured_log_destinations) > 0 ? [1] : []
    content {}
  }
}

# Structured logging destination (CloudWatch log group + logging role)
resource "aws_cloudwatch_log_group" "transfer" {
  count = length(var.structured_log_destinations) > 0 ? 1 : 0
  name  = "/aws/transfer/${local.server_id}"
}

# ------------------------------------------------------------------
# Route 53 CNAME
# ------------------------------------------------------------------
resource "aws_route53_record" "sftp" {
  count   = var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
  name    = "${var.route53_subdomain}.${var.route53_zone_id != "" ? data.aws_route53_zone.this[0].name : ""}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoints[0]]
}

data "aws_route53_zone" "this" {
  count = var.route53_zone_id != "" ? 1 : 0
  id    = var.route53_zone_id
}

# ------------------------------------------------------------------
# Users
# ------------------------------------------------------------------
data "aws_iam_policy_document" "user_assume" {
  for_each = var.sftp_users
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sftp_user" {
  for_each           = var.sftp_users
  name               = "${local.server_id}-${each.key}-role"
  assume_role_policy = data.aws_iam_policy_document.user_assume[each.key].json
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users
  name     = "${local.server_id}-${each.key}-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListHome"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = "arn:aws:s3:::${split("/", each.value.home_bucket_path)[0]}"
        Condition = {
          StringLike = {
            "s3:prefix" = "${join("/", slice(split("/", each.value.home_bucket_path), 1, length(split("/", each.value.home_bucket_path))))}/*"
          }
        }
      },
      {
        Sid      = "HomeAccess"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:GetObjectTagging", "s3:PutObjectTagging"]
        Resource = "arn:aws:s3:::${each.value.home_bucket_path}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each   = var.sftp_users
  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

resource "aws_transfer_user" "this" {
  for_each          = var.sftp_users
  server_id         = aws_transfer_server.this.id
  user_name         = each.key
  role              = aws_iam_role.sftp_user[each.key].arn
  home_directory    = "/${each.value.home_bucket_path}"
  home_directory_type = "PATH"
}

resource "aws_transfer_ssh_key" "this" {
  for_each = {
    for pair in flatten([
      for user, keys in var.sftp_user_keys : [
        for idx, key in keys : { user = user, idx = idx, key = key }
      ] if lookup(var.sftp_users, user, null) != null
    ]) : "${pair.user}-${pair.idx}" => pair
  }
  server_id = aws_transfer_server.this.id
  user_name = each.value.user
  body      = each.value.key
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "server_id" {
  value = aws_transfer_server.this.id
}

output "server_endpoint" {
  value = aws_transfer_server.this.endpoints
}

output "sftp_dns" {
  value = var.route53_zone_id != "" ? aws_route53_record.sftp[0].fqdn : null
}
```

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  default = "md-k8s"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 3, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name                                        = "${var.cluster_name}-public-${count.index}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 3, count.index + 3)
  map_public_ip_on_launch = false

  tags = {
    Name                                        = "${var.cluster_name}-private-${count.index}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"           = "1"
  }
}

# ---------------- Internet & NAT ----------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.cluster_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "private" {
  name       = "md-k8s-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "md-k8s-private-subnet-group"
  }
}

# ---------------- KMS ----------------
resource "aws_kms_key" "cluster" {
  description             = "KMS key for ${var.cluster_name} secrets envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------- IAM ----------------
resource "aws_iam_role" "cluster" {
  name = "${var.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "ec2_describe" {
  name = "ec2-describe-networking"
  role = aws_iam_role.cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["ec2:DescribeInstances", "ec2:DescribeNetworkInterfaces", "ec2:DescribeSubnets", "ec2:DescribeVpcs", "ec2:DescribeSecurityGroups"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "cloudwatch_publish" {
  name = "cloudwatch-publish-metrics"
  role = aws_iam_role.cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["cloudwatch:PutMetricData"]
      Resource = "*"
    }]
  })
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "cluster" {
  name        = "${var.cluster_name}-cluster-sg"
  description = "EKS control plane security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.cluster_name}-cluster-sg"
  }
}

resource "aws_security_group" "nodes" {
  name        = "${var.cluster_name}-node-sg"
  description = "Shared EKS node security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow node-to-node communication"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    self            = true
  }

  ingress {
    description     = "Allow traffic from cluster security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.cluster.id]
  }

  egress {
    description = "Allow outbound to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name                                        = "${var.cluster_name}-node-sg"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

# ---------------- EKS Cluster ----------------
resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    endpoint_public_access  = false
    endpoint_private_access = true
    security_group_ids      = [aws_security_group.cluster.id]
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.cluster.arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
    aws_iam_role_policy.ec2_describe,
    aws_iam_role_policy.cloudwatch_publish
  ]

  tags = {
    Name = var.cluster_name
  }
}

output "cluster_id" {
  value = aws_eks_cluster.main.id
}

output "cluster_endpoint" {
  value = aws_eks_cluster.main.endpoint
}

output "cluster_ca" {
  value = aws_eks_cluster.main.certificate_authority[0].data
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type    = string
  default = "cp"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "name" {
  type    = string
  default = "app"
}

variable "stage" {
  type    = string
  default = "general"
}

variable "delimiter" {
  type    = string
  default = "-"
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "versioning_enabled" {
  type    = bool
  default = true
}

variable "sse_algorithm" {
  description = "AES256 or aws:kms"
  type        = string
  default     = "aws:kms"
}

variable "kms_master_key_id" {
  description = "Optional existing KMS key ID. If empty and sse_algorithm is aws:kms, a new key is created."
  type        = string
  default     = ""
}

variable "kms_key_deletion_window" {
  type    = number
  default = 30
}

variable "lifecycle_enabled" {
  type    = bool
  default = false
}

variable "transition_to_standard_ia_days" {
  type    = number
  default = 30
}

variable "transition_to_glacier_days" {
  type    = number
  default = 90
}

variable "transition_to_deep_archive_days" {
  type    = number
  default = 180
}

variable "expiration_days" {
  type    = number
  default = 365
}

variable "noncurrent_version_expiration_days" {
  type    = number
  default = 90
}

variable "logging_enabled" {
  type    = bool
  default = false
}

variable "logging_target_bucket" {
  type    = string
  default = ""
}

variable "logging_target_prefix" {
  type    = string
  default = "logs/"
}

variable "website_enabled" {
  type    = bool
  default = false
}

variable "website_index_document" {
  type    = string
  default = "index.html"
}

variable "website_error_document" {
  type    = string
  default = "error.html"
}

variable "website_routing_rules" {
  type    = string
  default = ""
}

variable "cors_enabled" {
  type    = bool
  default = false
}

variable "cors_allowed_headers" {
  type    = list(string)
  default = ["*"]
}

variable "cors_allowed_methods" {
  type    = list(string)
  default = ["GET", "PUT", "POST"]
}

variable "cors_allowed_origins" {
  type    = list(string)
  default = ["*"]
}

variable "cors_max_age_seconds" {
  type    = number
  default = 3000
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}

variable "object_lock_mode" {
  type    = string
  default = "COMPLIANCE"
}

variable "object_lock_days" {
  type    = number
  default = 30
}

variable "bucket_policy_enabled" {
  type    = bool
  default = false
}

variable "bucket_policy_actions" {
  type    = list(string)
  default = ["s3:GetObject"]
}

variable "bucket_policy_principals" {
  type    = list(string)
  default = ["arn:aws:iam::123456789012:root"]
}

variable "acceleration_enabled" {
  type    = bool
  default = false
}

variable "requester_pays_enabled" {
  type    = bool
  default = false
}

variable "canned_acl" {
  type    = string
  default = "private"
}

variable "acl_grants_enabled" {
  type    = bool
  default = false
}

variable "acl_grants" {
  description = "List of maps: type (CanonicalUser/Group), permission, uri or id"
  type = list(object({
    type       = string
    permission = string
    id         = optional(string)
    uri        = optional(string)
  }))
  default = []
}

module "label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  stage      = var.stage
  name       = var.name
  delimiter  = var.delimiter
  tags       = var.tags
}

resource "aws_kms_key" "this" {
  count                           = var.sse_algorithm == "aws:kms" && var.kms_master_key_id == "" ? 1 : 0
  description                     = module.label.id
  enable_key_rotation             = true
  deletion_window_in_days         = var.kms_key_deletion_window
}

locals {
  kms_key_id = var.sse_algorithm == "aws:kms" ? (var.kms_master_key_id != "" ? var.kms_master_key_id : try(aws_kms_key.this[0].arn, null)) : null
}

resource "aws_s3_bucket" "this" {
  bucket         = module.label.id
  force_destroy  = var.force_destroy
  acl            = var.acl_grants_enabled ? null : var.canned_acl
  tags           = module.label.tags

  dynamic "grant" {
    for_each = var.acl_grants_enabled ? var.acl_grants : []
    content {
      type       = grant.value.type
      permission = grant.value.permission
      id         = try(grant.value.id, null)
      uri        = try(grant.value.uri, null)
    }
  }

  dynamic "logging" {
    for_each = var.logging_enabled && var.logging_target_bucket != "" ? [1] : []
    content {
      target_bucket = var.logging_target_bucket
      target_prefix = var.logging_target_prefix
    }
  }

  dynamic "website" {
    for_each = var.website_enabled ? [1] : []
    content {
      index_document = var.website_index_document
      error_document = var.website_error_document
      routing_rules  = var.website_routing_rules != "" ? var.website_routing_rules : null
    }
  }

  dynamic "cors_rule" {
    for_each = var.cors_enabled ? [1] : []
    content {
      allowed_headers = var.cors_allowed_headers
      allowed_methods = var.cors_allowed_methods
      allowed_origins = var.cors_allowed_origins
      max_age_seconds = var.cors_max_age_seconds
    }
  }

  dynamic "lifecycle_rule" {
    for_each = var.lifecycle_enabled ? [1] : []
    content {
      id      = "${module.label.id}-lifecycle"
      enabled = true
      tags    = module.label.tags

      transition {
        days          = var.transition_to_standard_ia_days
        storage_class = "STANDARD_IA"
      }

      transition {
        days          = var.transition_to_glacier_days
        storage_class = "GLACIER"
      }

      transition {
        days          = var.transition_to_deep_archive_days
        storage_class = "DEEP_ARCHIVE"
      }

      expiration {
        days = var.expiration_days
      }

      noncurrent_version_expiration {
        days = var.noncurrent_version_expiration_days
      }
    }
  }

  dynamic "object_lock_configuration" {
    for_each = var.object_lock_enabled ? [1] : []
    content {
      object_lock_enabled = true
      rule {
        default_retention {
          mode = var.object_lock_mode
          days = var.object_lock_days
        }
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.versioning_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.kms_key_id
    }
    bucket_key_enabled = var.sse_algorithm == "aws:kms"
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.requester_pays_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  payer  = "Requester"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = "Enabled"
}

data "aws_iam_policy_document" "this" {
  count = var.bucket_policy_enabled ? 1 : 0
  statement {
    sid       = "GrantSpecifiedActions"
    effect    = "Allow"
    actions   = var.bucket_policy_actions
    resources = [aws_s3_bucket.this.arn, "${aws_s3_bucket.this.arn}/*"]
    principals {
      type        = "AWS"
      identifiers = var.bucket_policy_principals
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.bucket_policy_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this[0].json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  value = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

output "tags" {
  value = module.label.tags
}

output "kms_key_arn" {
  value = var.sse_algorithm == "aws:kms" && var.kms_master_key_id == "" ? aws_kms_key.this[0].arn : null
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of availability zones to use. 0 means all available."
  type        = number
  default     = 0
}

variable "enable_public_subnets" {
  description = "Whether to create public subnets"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Whether to create private subnets"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Whether to create a NAT gateway"
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = var.az_count == 0 ? data.aws_availability_zones.available.names : slice(data.aws_availability_zones.available.names, 0, var.az_count)
  az_count = length(local.azs)
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_network_acl" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "${var.vpc_name}-public-nacl"
  }
}

# NAT gateway
resource "aws_eip" "nat" {
  count  = var.enable_nat_gateway && var.enable_public_subnets ? 1 : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "this" {
  count = var.enable_nat_gateway && var.enable_public_subnets ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat"
  }

  depends_on = [aws_internet_gateway.this]
}

# Private subnets
resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? local.az_count : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index + 8)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "private" {
  count = var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route" "private_nat" {
  count = var.enable_private_subnets && var.enable_nat_gateway && var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  count = var.enable_private_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_network_acl" "private" {
  count = var.enable_private_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "${var.vpc_name}-private-nacl"
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  value = var.enable_nat_gateway && var.enable_public_subnets ? aws_nat_gateway.this[0].id : null
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "is_ipv6_enabled" {
  description = "Enable Amazon-provided IPv6 CIDR block"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "sn_details" {
  description = "List of subnet definitions: name, AZ, public flag"
  type = list(object({
    name   = string
    az     = string
    public = bool
  }))
  default = [
    { name = "web-1",      az = "us-east-1a", public = true },
    { name = "web-2",      az = "us-east-1b", public = true },
    { name = "web-3",      az = "us-east-1c", public = true },
    { name = "app-1",      az = "us-east-1a", public = false },
    { name = "app-2",      az = "us-east-1b", public = false },
    { name = "app-3",      az = "us-east-1c", public = false },
    { name = "database-1", az = "us-east-1a", public = false },
    { name = "database-2", az = "us-east-1b", public = false },
    { name = "database-3", az = "us-east-1c", public = false },
    { name = "reserved-1", az = "us-east-1a", public = false },
    { name = "reserved-2", az = "us-east-1b", public = false },
    { name = "reserved-3", az = "us-east-1c", public = false },
  ]
}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_vpc_ipv6_cidr_block" "main" {
  count  = var.is_ipv6_enabled ? 1 : 0
  vpc_id = aws_vpc.main.id
}

# ---------------- Subnet calculations ----------------
module "ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.vpc_cidr
  networks = [for s in var.sn_details : {
    name     = s.name
    new_bits = 4
  }]
}

module "ipv6_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.is_ipv6_enabled ? aws_vpc_ipv6_cidr_block.main[0].ipv6_cidr_block : "::/64"
  networks = [for s in var.sn_details : {
    name     = s.name
    new_bits = 8
  }]
}

# ---------------- Subnets ----------------
resource "aws_subnet" "subnets" {
  count = length(var.sn_details)

  vpc_id            = aws_vpc.main.id
  cidr_block        = module.ipv4_subnets.networks[count.index].cidr_block
  availability_zone = var.sn_details[count.index].az
  ipv6_cidr_block   = var.is_ipv6_enabled ? module.ipv6_subnets.networks[count.index].cidr_block : null

  tags = {
    Name = var.sn_details[count.index].name
  }
}

# ---------------- Internet Gateway ----------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

# ---------------- Public Route Table ----------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route_table_association" "public" {
  count = length([for s in var.sn_details : s if s.public])

  subnet_id      = [for s in aws_subnet.subnets : s.id][index([for s in var.sn_details : s.public], true) + count.index]
  route_table_id = aws_route_table.public.id
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "web_sg" {
  name   = "web_sg"
  vpc_id = aws_vpc.main.id

  ingress {
    description = "TLS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description                 = "TLS to app tier"
    from_port                   = 443
    to_port                     = 443
    protocol                    = "tcp"
    security_groups             = [aws_security_group.app_sg.id]
  }

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app_sg" {
  name   = "app_sg"
  vpc_id = aws_vpc.main.id

  ingress {
    description     = "TLS from web tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.web_sg.id]
  }

  egress {
    description     = "TLS to db tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.db_sg.id]
  }

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  name   = "db_sg"
  vpc_id = aws_vpc.main.id

  ingress {
    description     = "TLS from app tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }

  tags = {
    Name = "db_sg"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "subnet_ipv4_cidrs" {
  value = [for s in aws_subnet.subnets : s.cidr_block]
}

output "public_subnet_ids" {
  value = [for s, d in zipmap(range(length(var.sn_details)), var.sn_details) : aws_subnet.subnets[s].id if d.public]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "artifact_bucket_name" {
  description = "Name of the S3 bucket for canary artifacts"
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "artifact_bucket_versioning" {
  description = "Enable versioning on the artifact bucket"
  type        = bool
  default     = false
}

variable "kms_enabled" {
  description = "Toggle for custom KMS key usage"
  type        = bool
  default     = true
}

variable "kms_deletion_window" {
  type    = number
  default = 10
}

variable "sns_topic_name" {
  type    = string
  default = "benchmark-canary-topic"
}

variable "alarm_email" {
  type    = string
  default = "nobody@example.com"
}

variable "canary_runtime" {
  type    = string
  default = "syn-nodejs-puppeteer-6.1"
}

variable "canary_timeout" {
  type    = number
  default = 120
}

variable "enable_success_alarm" {
  description = "Enable optional success percent alarm"
  type        = bool
  default     = false
}

variable "vpc_canaries" {
  description = "Map of canary configurations"
  type = map(object({
    name                  = string
    script                = string # inline script content (used if s3_key is null)
    s3_bucket             = optional(string)
    s3_key                = optional(string)
    schedule_expression   = string
    subnet_ids            = list(string)
    security_group_ids    = list(string)
    start_canary          = optional(bool, true)
    success_alarm_enabled = optional(bool, false)
  }))
  default = {
    "internal-health" = {
      name                = "internal-health-check"
      script              = <<-EOT
        var synthetics = require('Synthetics');
        const pageLoad = async function () {
          let URL = "https://example.com";
          let page_title = "Example Domain";
          await synthetics.executeStep('navigate', async function (uri, callback) {
            await synthetics.addResponseValidation();
            let response = await synthetics.page.goto(URL, { waitUntil: 'domcontentloaded', timeout: 30000 });
            await synthetics.takeScreenshot('loaded', 'result');
            let title = await synthetics.page.title();
            if (title !== page_title) throw new Error('Title mismatch: ' + title);
          });
        };
        exports.handler = async () => { await pageLoad(); };
      EOT
      schedule_expression = "rate(5 minutes)"
      subnet_ids          = ["subnet-00000000000000000"]
      security_group_ids  = ["sg-00000000000000000"]
      start_canary        = true
    }
  }
}

# ---------------- Random pet name for IAM role ----------------

resource "random_pet" "lambda_role" {
  length = 2
}

# ---------------- KMS ----------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

resource "aws_kms_key" "canary" {
  count                   = var.kms_enabled ? 1 : 0
  description             = "KMS key for canary artifacts"
  deletion_window_in_days = var.kms_deletion_window
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RootAccess"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "CloudWatchAccess"
        Effect    = "Allow"
        Principal = { Service = "cloudwatch.amazonaws.com" }
        Action = [
          "kms:Decrypt", "kms:GenerateDataKey*", "kms:Encrypt",
          "kms:DescribeKey", "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "canary" {
  count         = var.kms_enabled ? 1 : 0
  name          = "alias/benchmark-canary-key"
  target_key_id = aws_kms_key.canary[0].key_id
}

locals {
  kms_key_id = var.kms_enabled ? aws_kms_key.canary[0].arn : null
}

# ---------------- S3 artifact bucket ----------------

resource "aws_s3_bucket" "artifacts" {
  bucket        = var.artifact_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = var.artifact_bucket_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag", "x-amz-request-id"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_enabled ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_enabled ? aws_kms_key.canary[0].arn : null
    }
  }
}

# ---------------- IAM role for canary Lambda ----------------

resource "aws_iam_role" "canary_execution" {
  name = "${random_pet.lambda_role.id}-canary-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "canary_execution" {
  name = "canary-execution-policy"
  role = aws_iam_role.canary_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Artifacts"
        Effect = "Allow"
        Action = [
          "s3:GetObject", "s3:PutObject", "s3:DeleteObject",
          "s3:GetBucketLocation", "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
      },
      {
        Sid      = "CloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid      = "CloudWatchLogs"
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      },
      {
        Sid    = "EC2ENI"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface", "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface", "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups", "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------- SNS ----------------

resource "aws_sns_topic" "canary_alarms" {
  name              = var.sns_topic_name
  kms_master_key_id = var.kms_enabled ? aws_kms_key.canary[0].arn : null
}

resource "aws_sns_topic_subscription" "email" {
  topic_arn = aws_sns_topic.canary_alarms.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

resource "aws_sns_topic_policy" "canary_alarms" {
  arn = aws_sns_topic.canary_alarms.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "AllowCloudWatchAlarmsPublish"
      Effect    = "Allow"
      Principal = { Service = "cloudwatch.amazonaws.com" }
      Action    = "sns:Publish"
      Resource  = aws_sns_topic.canary_alarms.arn
      Condition = {
        ArnEquals = {
          "AWS:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudwatch:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:alarm:*"
        }
      }
    }]
  })
}

# ---------------- Inline canary scripts (for inline sources) ----------------

resource "aws_synthetics_canary" "vpc" {
  for_each = var.vpc_canaries

  name                 = each.value.name
  artifact_s3_location = "s3://${aws_s3_bucket.artifacts.bucket_name}"
  execution_role_arn   = aws_iam_role.canary_execution.arn
  runtime_version      = var.canary_runtime
  start_canary         = each.value.start_canary
  success_rate         = 90

  schedule {
    expression          = each.value.schedule_expression
    duration_in_seconds = 0
  }

  run_config {
    timeout_in_seconds = var.canary_timeout
    active_tracing     = false
  }

  dynamic "code" {
    for_each = each.value.s3_key == null ? [1] : []
    content {
      script = each.value.script
    }
  }

  dynamic "s3_config" {
    for_each = each.value.s3_key != null ? [1] : []
    content {
      bucket = coalesce(each.value.s3_bucket, aws_s3_bucket.artifacts.bucket_name)
      key    = each.value.s3_key
    }
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  tags = {
    Name = each.value.name
  }
}

# ---------------- Alarms ----------------

resource "aws_cloudwatch_metric_alarm" "canary_failure" {
  for_each = var.vpc_canaries

  alarm_name          = "${each.value.name}-failure-alarm"
  alarm_description   = "Alarm when canary ${each.value.name} fails"
  namespace           = "CloudWatchSynthetics"
  metric_name         = "Failed"
  dimensions          = { CanaryName = each.value.name }
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.canary_alarms.arn]
  ok_actions    = [aws_sns_topic.canary_alarms.arn]

  depends_on = [aws_synthetics_canary.vpc]
}

resource "aws_cloudwatch_metric_alarm" "canary_success" {
  for_each = {
    for k, v in var.vpc_canaries : k => v
    if var.enable_success_alarm || v.success_alarm_enabled
  }

  alarm_name          = "${each.value.name}-success-percent-alarm"
  alarm_description   = "Alarm when canary ${each.value.name} success percent falls below 90"
  namespace           = "CloudWatchSynthetics"
  metric_name         = "SuccessPercent"
  dimensions          = { CanaryName = each.value.name }
  statistic           = "Average"
  period              = 60
  evaluation_periods  = 1
  threshold           = 90
  comparison_operator = "LessThanThreshold"
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.canary_alarms.arn]
  ok_actions    = [aws_sns_topic.canary_alarms.arn]

  depends_on = [aws_synthetics_canary.vpc]
}

# ---------------- Outputs ----------------

output "canary_arns" {
  value = { for k, c in aws_synthetics_canary.vpc : k => c.arn }
}

output "sns_topic_arn" {
  value = aws_sns_topic.canary_alarms.arn
}

output "artifact_bucket" {
  value = aws_s3_bucket.artifacts.bucket
}

output "kms_key_arn" {
  value = var.kms_enabled ? aws_kms_key.canary[0].arn : null
}

output "execution_role_arn" {
  value = aws_iam_role.canary_execution.arn
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "create_vpc" {
  description = "Main creation toggle for the VPC and all resources"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "custom-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "azs" {
  description = "List of availability zone names or IDs to map subnets across"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.0.0/20", "10.0.16.0/20"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.32.0/20", "10.0.48.0/20"]
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for isolated intra subnets"
  type        = list(string)
  default     = ["10.0.64.0/20", "10.0.80.0/20"]
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets (optional)"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets (optional)"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets (optional)"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Name suffix for public subnets"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Name suffix for private subnets"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Name suffix for intra subnets"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Map public IP on launch for public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Create an Internet Gateway"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Create NAT Gateways and EIPs for private subnets"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---------------- Locals ----------------

locals {
  create_vpc = var.create_vpc

  create_public_subnets  = local.create_vpc && length(var.public_subnet_cidrs) > 0
  create_private_subnets = local.create_vpc && length(var.private_subnet_cidrs) > 0
  create_intra_subnets   = local.create_vpc && length(var.intra_subnet_cidrs) > 0

  create_igw = local.create_public_subnets && var.create_igw

  nat_gateway_count = var.enable_nat_gateway ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0
  create_nat        = local.create_public_subnets && local.create_private_subnets && local.nat_gateway_count > 0

  public_subnet_names = length(var.public_subnet_names) > 0 ? var.public_subnet_names : [
    for i in range(length(var.public_subnet_cidrs)) :
    "${var.vpc_name}-${var.public_subnet_suffix}-${element(var.azs, i)}"
  ]

  private_subnet_names = length(var.private_subnet_names) > 0 ? var.private_subnet_names : [
    for i in range(length(var.private_subnet_cidrs)) :
    "${var.vpc_name}-${var.private_subnet_suffix}-${element(var.azs, i)}"
  ]

  intra_subnet_names = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names : [
    for i in range(length(var.intra_subnet_cidrs)) :
    "${var.vpc_name}-${var.intra_subnet_suffix}-${element(var.azs, i)}"
  ]
}

# ---------------- VPC ----------------

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    {
      Name = var.vpc_name
    },
    var.tags
  )
}

# ---------------- Subnets ----------------

resource "aws_subnet" "public" {
  count = local.create_public_subnets ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(var.azs, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    {
      Name = local.public_subnet_names[count.index]
      Tier = var.public_subnet_suffix
    },
    var.tags
  )
}

resource "aws_subnet" "private" {
  count = local.create_private_subnets ? length(var.private_subnet_cidrs) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = element(var.azs, count.index)

  tags = merge(
    {
      Name = local.private_subnet_names[count.index]
      Tier = var.private_subnet_suffix
    },
    var.tags
  )
}

resource "aws_subnet" "intra" {
  count = local.create_intra_subnets ? length(var.intra_subnet_cidrs) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnet_cidrs[count.index]
  availability_zone = element(var.azs, count.index)

  tags = merge(
    {
      Name = local.intra_subnet_names[count.index]
      Tier = var.intra_subnet_suffix
    },
    var.tags
  )
}

# ---------------- Internet Gateway ----------------

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-igw"
    },
    var.tags
  )
}

# ---------------- Public Route Table ----------------

resource "aws_route_table" "public" {
  count = local.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-public"
    },
    var.tags
  )
}

resource "aws_route" "public_internet" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.create_public_subnets ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ---------------- NAT Gateways ----------------

resource "aws_eip" "nat" {
  count = local.create_nat ? local.nat_gateway_count : 0

  domain = "vpc"

  tags = merge(
    {
      Name = "${var.vpc_name}-nat-eip-${count.index + 1}"
    },
    var.tags
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.create_nat ? local.nat_gateway_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    {
      Name = "${var.vpc_name}-nat-${count.index + 1}"
    },
    var.tags
  )

  depends_on = [aws_internet_gateway.this]
}

# ---------------- Private Route Tables ----------------

resource "aws_route_table" "private" {
  count = local.create_nat ? local.nat_gateway_count : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-private-${count.index + 1}"
    },
    var.tags
  )
}

resource "aws_route" "private_nat" {
  count = local.create_nat ? local.nat_gateway_count : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  count = local.create_nat ? min(length(var.private_subnet_cidrs), local.nat_gateway_count) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------- Intra (Isolated) Route Tables ----------------

resource "aws_route_table" "intra" {
  count = local.create_intra_subnets ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-intra"
    },
    var.tags
  )
}

resource "aws_route_table_association" "intra" {
  count = local.create_intra_subnets ? length(var.intra_subnet_cidrs) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

# ---------------- Outputs ----------------

output "vpc_id" {
  description = "ID of the VPC"
  value       = local.create_vpc ? aws_vpc.this[0].id : null
}

output "vpc_cidr" {
  description = "CIDR block of the VPC"
  value       = local.create_vpc ? aws_vpc.this[0].cidr_block : null
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "IDs of the intra subnets"
  value       = aws_subnet.intra[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = local.create_igw ? aws_internet_gateway.this[0].id : null
}

output "nat_gateway_ids" {
  description = "IDs of the NAT Gateways"
  value       = aws_nat_gateway.this[*].id
}

output "nat_eips" {
  description = "Public Elastic IPs of the NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "api_type" {
  description = "Type of API to create: http (v2) or rest (v1)"
  type        = string
  default     = "http"
  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be 'http' or 'rest'."
  }
}

variable "api_name" {
  type    = string
  default = "benchmark-api"
}

variable "environment_name" {
  type    = string
  default = "dev"
}

variable "stage_name" {
  type        = string
  default     = null # computed as environment_name + "-stage"
}

variable "http_routes" {
  description = "Map of route keys to integration URIs for HTTP APIs"
  type = map(object({
    method           = string
    path             = string
    integration_uri  = string
    integration_type = optional(string, "AWS_PROXY")
  }))
  default = {
    default = {
      method           = "ANY"
      path             = "$default"
      integration_uri  = "arn:aws:lambda:us-east-1:123456789012:function:default-handler"
      integration_type = "AWS_PROXY"
    }
  }
}

variable "rest_resources" {
  description = "Map of resource paths to methods for REST APIs"
  type = map(object({
    path = string
    methods = map(object({
      http_method            = string
      integration_uri        = string
      integration_type       = optional(string, "AWS_PROXY")
      path_parameter_override = optional(string, null)
    }))
  }))
  default = {
    root = {
      path = "/"
      methods = {
        proxy = {
          http_method     = "ANY"
          integration_uri = "arn:aws:lambda:us-east-1:123456789012:function:default-handler"
        }
      }
    }
  }
}

variable "custom_domain_name" {
  type    = string
  default = null
}

variable "route53_zone_id" {
  type    = string
  default = null
}

variable "vpc_id" {
  type    = string
  default = null
}

variable "private_subnet_ids" {
  type    = list(string)
  default = []
}

variable "enable_vpc_link" {
  type    = bool
  default = false
}

variable "alb_target_id" {
  description = "ALB ID (e.g. arn suffix id) used as NLB target for REST VPC link"
  type        = string
  default     = null
}

variable "nlb_target_port" {
  type    = number
  default = 443
}

variable "allowed_source_ips" {
  description = "List of CIDR blocks allowed to call the REST API (null = open)"
  type        = list(string)
  default     = null
}

variable "authorizer_functions" {
  description = "Map of authorizer names to source code (Node.js 16.x)"
  type        = map(string)
  default     = {}
}

variable "tags" {
  type    = map(string)
  default = {}
}

locals {
  stage_name = coalesce(var.stage_name, "${var.environment_name}-stage")
  common_tags = merge(var.tags, {
    Environment = var.environment_name
    ApiName     = var.api_name
  })
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------
# HTTP API (v2)
# ------------------------------------------------------------------
resource "aws_apigatewayv2_api" "http" {
  count              = var.api_type == "http" ? 1 : 0
  name               = var.api_name
  protocol_type      = "HTTP"
  tags               = local.common_tags
}

resource "aws_apigatewayv2_integration" "http" {
  for_each               = var.api_type == "http" ? var.http_routes : {}
  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = each.value.integration_type
  integration_uri        = each.value.integration_uri
  payload_format_version = "2.0"
}

resource "aws_apigatewayv2_route" "http" {
  for_each           = var.api_type == "http" ? var.http_routes : {}
  api_id             = aws_apigatewayv2_api.http[0].id
  route_key          = "${upper(each.value.method)} ${each.value.path}"
  target             = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = var.api_type == "http" ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true
  tags        = local.common_tags
}

# HTTP VPC Link
resource "aws_apigatewayv2_vpc_link" "http" {
  count              = var.api_type == "http" && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-http-vpclink"
  security_group_ids = [aws_security_group.vpc_link[0].id]
  subnet_ids         = var.private_subnet_ids
  tags               = local.common_tags
}

resource "aws_security_group" "vpc_link" {
  count       = var.enable_vpc_link && var.vpc_id != null ? 1 : 0
  name_prefix = "${var.api_name}-vpclink-"
  vpc_id      = var.vpc_id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

# Custom domain (HTTP)
resource "aws_apigatewayv2_domain_name" "http" {
  count       = var.api_type == "http" && var.custom_domain_name != null ? 1 : 0
  domain_name = var.custom_domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate.api[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count      = var.api_type == "http" && var.custom_domain_name != null ? 1 : 0
  api_id     = aws_apigatewayv2_api.http[0].id
  stage      = aws_apigatewayv2_stage.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
}

resource "aws_acm_certificate" "api" {
  count             = var.custom_domain_name != null ? 1 : 0
  domain_name       = var.custom_domain_name
  validation_method = "DNS"

  options {
    certificate_transparency_logging_preference = "ENABLED"
  }
  tags = local.common_tags
}

resource "aws_route53_record" "cert_validation" {
  for_each = var.custom_domain_name != null ? {
    for dvo in aws_acm_certificate.api[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.domain_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  zone_id = var.route53_zone_id
  name    = each.value.name
  type    = each.value.type
  ttl     = 60
  records = [each.value.record]
}

resource "aws_acm_certificate_validation" "api" {
  count                   = var.custom_domain_name != null ? 1 : 0
  certificate_arn         = aws_acm_certificate.api[0].arn
  validation_record_fqdns = [for r in aws_route53_record.cert_validation : r.fqdn]
}

resource "aws_route53_record" "api_alias" {
  count   = var.api_type == "http" && var.custom_domain_name != null && var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.custom_domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# ------------------------------------------------------------------
# REST API (v1)
# ------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  name  = var.api_name
  tags  = local.common_tags

  dynamic "policy" {
    for_each = var.allowed_source_ips != null ? [1] : []
    content {
      Version = "2012-10-17"
      Statement = [
        {
          Effect    = "Allow"
          Principal = "*"
          Action    = "execute-api:Invoke"
          Resource  = "*"
        },
        {
          Effect    = "Deny"
          Principal = "*"
          Action    = "execute-api:Invoke"
          Resource  = "*"
          Condition {
            test     = "NotIpAddress"
            variable = "aws:SourceIp"
            values   = var.allowed_source_ips
          }
        }
      ]
    }
  }
}

resource "aws_api_gateway_resource" "rest" {
  for_each    = var.api_type == "rest" ? { for k, v in var.rest_resources : k => v if v.path != "/" } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = element(split("/", trim(each.value.path, "/")), length(split("/", trim(each.value.path, "/"))) - 1)
}

resource "aws_api_gateway_method" "rest" {
  for_each = var.api_type == "rest" ? {
    for pair in flatten([
      for rk, rv in var.rest_resources : [
        for mk, mv in rv.methods : {
          key       = "${rk}-${mk}"
          resource  = rk
          method    = mv
        }
      ]
    ]) : pair.key => pair
  } : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = each.value.resource == "root" || each.value.method.path == "/" ? aws_api_gateway_rest_api.rest[0].root_resource_id : aws_api_gateway_resource.rest[each.value.resource].id
  http_method = each.value.method.http_method
  authorization = length(var.authorizer_functions) > 0 ? "CUSTOM" : "NONE"
  authorizer_id = length(var.authorizer_functions) > 0 ? aws_api_gateway_authorizer.custom[keys(var.authorizer_functions)[0]].id : null
  request_parameters = each.value.method.path_parameter_override != null ? {
    "method.request.path.${each.value.method.path_parameter_override}" = true
  } : {}
}

resource "aws_api_gateway_integration" "rest" {
  for_each = var.api_type == "rest" ? {
    for pair in flatten([
      for rk, rv in var.rest_resources : [
        for mk, mv in rv.methods : {
          key       = "${rk}-${mk}"
          resource  = rk
          method    = mv
        }
      ]
    ]) : pair.key => pair
  } : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = each.value.resource == "root" || each.value.method.path == "/" ? aws_api_gateway_rest_api.rest[0].root_resource_id : aws_api_gateway_resource.rest[each.value.resource].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  type        = each.value.method.integration_type
  integration_http_method = each.value.method.integration_type == "AWS_PROXY" ? "POST" : each.value.method.http_method
  uri         = each.value.method.integration_uri
  request_parameters = each.value.method.path_parameter_override != null ? {
    "integration.request.path.${each.value.method.path_parameter_override}" = "method.request.path.${each.value.method.path_parameter_override}"
  } : {}
}

resource "aws_api_gateway_deployment" "rest" {
  count       = var.api_type == "rest" ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_integration.rest,
      aws_api_gateway_method.rest,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_api_gateway_integration.rest, aws_api_gateway_method.rest]
}

resource "aws_api_gateway_stage" "rest" {
  count        = var.api_type == "rest" ? 1 : 0
  deployment_id = aws_api_gateway_deployment.rest[0].id
  rest_api_id  = aws_api_gateway_rest_api.rest[0].id
  stage_name   = local.stage_name
  tags         = local.common_tags
}

# Custom domain (REST)
resource "aws_api_gateway_domain_name" "rest" {
  count       = var.api_type == "rest" && var.custom_domain_name != null ? 1 : 0
  domain_name = var.custom_domain_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count       = var.api_type == "rest" && var.custom_domain_name != null ? 1 : 0
  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest_alias" {
  count   = var.api_type == "rest" && var.custom_domain_name != null && var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.custom_domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

# Usage plan + API keys + SSM
resource "aws_api_gateway_usage_plan" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  name  = "${var.api_name}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  quota_settings {
    limit  = 1000000
    period = "MONTH"
  }

  throttle_settings {
    rate_limit  = 1000
    burst_limit = 2000
  }
  tags = local.common_tags
}

resource "aws_api_gateway_api_key" "rest" {
  for_each = var.api_type == "rest" ? toset(["default-key"]) : toset([])
  name     = "${var.api_name}-${each.key}"
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  for_each     = var.api_type == "rest" ? toset(["default-key"]) : toset([])
  key_id       = aws_api_gateway_api_key.rest[each.key].id
  key_type     = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  for_each = var.api_type == "rest" ? toset(["default-key"]) : toset([])
  name     = "/${var.api_name}/${var.environment_name}/api-keys/${each.key}"
  type     = "SecureString"
  value    = aws_api_gateway_api_key.rest[each.key].value
  tags     = local.common_tags
}

# Lambda authorizers
resource "aws_iam_role" "authorizer_lambda" {
  for_each = var.api_type == "rest" ? var.authorizer_functions : {}
  name     = "${var.api_name}-${each.key}-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "authorizer_lambda_basic" {
  for_each   = var.api_type == "rest" ? var.authorizer_functions : {}
  role       = aws_iam_role.authorizer_lambda[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  for_each     = var.api_type == "rest" ? var.authorizer_functions : {}
  function_name = "${var.api_name}-${each.key}-authorizer"
  role          = aws_iam_role.authorizer_lambda[each.key].arn
  runtime       = "nodejs16.x"
  handler       = "index.handler"
  filename      = "/tmp/${each.key}-authorizer.zip"
  source_code_hash = sha256(each.value)

  environment {
    variables = { SOURCE_CODE = each.value }
  }
}

# Zip the authorizer source locally
resource "null_resource" "authorizer_zip" {
  for_each = var.api_type == "rest" ? var.authorizer_functions : {}
  triggers = { hash = sha256(each.value) }
  provisioner "local-exec" {
    command = "mkdir -p /tmp/${each.key}-authorizer && echo '${each.value}' > /tmp/${each.key}-authorizer/index.js && cd /tmp/${each.key}-authorizer && zip -q ../${each.key}-authorizer.zip index.js"
  }
}

resource "aws_lambda_permission" "authorizer" {
  for_each    = var.api_type == "rest" ? var.authorizer_functions : {}
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[each.key].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
}

resource "aws_api_gateway_authorizer" "custom" {
  for_each = var.api_type == "rest" ? var.authorizer_functions : {}
  name     = "${each.key}-authorizer"
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  type     = "TOKEN"
  authorizer_uri = aws_lambda_function.authorizer[each.key].invoke_arn
  identity_source = "header.Authorization"
}

# ------------------------------------------------------------------
# REST VPC Link stack: NLB -> target group (ALB) -> listener -> VPC link
# ------------------------------------------------------------------
resource "aws_lb" "internal_nlb" {
  count              = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = var.private_subnet_ids
  tags               = local.common_tags
}

resource "aws_lb_target_group" "alb_target" {
  count    = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0
  name     = "${var.api_name}-tg"
  port     = var.nlb_target_port
  protocol = "TCP"
  vpc_id   = var.vpc_id
  target_type = "alb"

  health_check {
    protocol     = "HTTPS"
    path         = "/"
    port         = "traffic-port"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
    timeout             = 5
  }
  tags = local.common_tags
}

resource "aws_lb_target_group_attachment" "alb" {
  count            = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0
  target_group_arn = aws_lb_target_group.alb_target[0].arn
  target_id        = var.alb_target_id
  port             = var.nlb_target_port
}

resource "aws_lb_listener" "tcp" {
  count             = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.internal_nlb[0].arn
  port              = var.nlb_target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_target[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-rest-vpclink"
  target_arn  = aws_lb.internal_nlb[0].arn
  description = "VPC link for ${var.api_name} REST API"
  tags        = local.common_tags
}

output "http_api_endpoint" {
  value = var.api_type == "http" ? aws_apigatewayv2_stage.http[0].invoke_url : null
}

output "rest_api_endpoint" {
  value = var.api_type == "rest" ? aws_api_gateway_stage.rest[0].invoke_url : null
}

output "api_key_ssm_names" {
  value = var.api_type == "rest" ? [for p in aws_ssm_parameter.api_key : p.name] : []
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------- Variables ----------------

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "org-audit-trail"
}

variable "s3_bucket_name" {
  description = "Optional explicit S3 bucket name; if empty, generated dynamically"
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Force destroy the S3 bucket even if non-empty"
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Enable versioning on the S3 bucket"
  type        = bool
  default     = false
}

variable "kms_deletion_window_in_days" {
  description = "KMS key deletion window"
  type        = number
  default     = 30
}

variable "kms_alias_prefix" {
  description = "Prefix for the KMS alias"
  type        = string
  default     = "alias/cloudtrail-"
}

variable "kms_optional_role_arn" {
  description = "Optional role ARN granted log decryption permissions"
  type        = string
  default     = ""
}

variable "cloudwatch_log_group_name" {
  description = "CloudWatch Log Group name for CloudTrail logs"
  type        = string
  default     = "/aws/cloudtrail/org-audit"
}

variable "cloudwatch_log_retention_in_days" {
  description = "CloudWatch log retention in days"
  type        = number
  default     = 90
}

variable "enable_log_file_validation" {
  description = "Enable CloudTrail log file validation"
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events (IAM, STS, etc.)"
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail is multi-region"
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled on the trail"
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail"
  type        = bool
  default     = false
}

variable "event_selector_read_write_type" {
  description = "Read/write type for event selector: Read, WriteManagement, or All"
  type        = string
  default     = "All"
}

variable "event_selector_include_management_events" {
  description = "Include management events in event selector"
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selector maps (type + values)"
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight selectors (e.g., ApiCallRateInsight)"
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for CloudTrail notifications"
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic if created"
  type        = string
  default     = "cloudtrail-notifications"
}

variable "existing_sns_topic_arn" {
  description = "Optional existing SNS topic ARN to use instead of creating one"
  type        = string
  default     = ""
}

# ---------------- Data sources ----------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------- Random suffix ----------------

resource "random_string" "suffix" {
  length  = 8
  lower   = true
  upper   = false
  special = false
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  s3_bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "cloudtrail-logs-${local.account_id}-${local.region}-${random_string.suffix.result}"

  sns_topic_arn = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].arn : var.existing_sns_topic_arn
}

# ---------------- KMS Key ----------------

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "CloudTrailEncrypt"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:trail:${var.trail_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:trail:${local.account_id}:${var.trail_name}"]
    }
  }

  statement {
    sid       = "CloudWatchLogsEncrypt"
    effect    = "Allow"
    actions   = ["kms:Encrypt*", "kms:Decrypt*", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:Describe*"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${var.cloudwatch_log_group_name}:*"]
    }
  }

  statement {
    sid       = "S3BucketEncrypt"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }

  dynamic "statement" {
    for_each = var.kms_optional_role_arn != "" ? [1] : []
    content {
      sid       = "OptionalRoleDecrypt"
      effect    = "Allow"
      actions   = ["kms:Decrypt", "kms:DescribeKey"]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = [var.kms_optional_role_arn]
      }
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  multi_region            = false
  policy                  = data.aws_iam_policy_document.kms_key.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "${var.kms_alias_prefix}${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# ---------------- S3 Bucket ----------------

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.s3_bucket_name
  force_destroy = var.s3_force_destroy
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket                  = aws_s3_bucket.cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  count = var.s3_versioning_enabled ? 1 : 0

  bucket = aws_s3_bucket.cloudtrail.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "s3_bucket" {
  statement {
    sid       = "CloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.sns_topic_arn != "" ? "arn:${local.partition}:trail:${var.trail_name}" : "arn:${local.partition}:trail:${var.trail_name}"]
    }
  }

  statement {
    sid       = "CloudTrailPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:trail:${var.trail_name}"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.s3_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

# ---------------- CloudWatch Log Group & IAM ----------------

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_retention_in_days
  kms_key_id        = aws_kms_key.cloudtrail.arn
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${local.partition}:trail:${var.trail_name}"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-logs-policy"
  role = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# ---------------- SNS Topic (optional) ----------------

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name         = var.sns_topic_name
  kms_master_key_id = aws_kms_key.cloudtrail.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudTrailPublish"
        Effect    = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = "arn:${local.partition}:sns:${local.region}:${local.account_id}:${var.sns_topic_name}"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${local.partition}:trail:${var.trail_name}"
          }
        }
      }
    ]
  })
}

# ---------------- CloudTrail ----------------

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_kms_key_id                 = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = aws_cloudwatch_log_group.cloudtrail.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_arn != "" ? local.sns_topic_arn : null
  enable_log_file_validation    = var.enable_log_file_validation
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  is_organization_trail         = var.is_organization_trail

  dynamic "event_selector" {
    for_each = length(var.data_resource_selectors) > 0 ? [1] : []
    content {
      read_write_type                  = var.event_selector_read_write_type
      include_management_events        = var.event_selector_include_management_events
      dynamic "data_resource" {
        for_each = var.data_resource_selectors
        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail,
    aws_kms_alias.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch
  ]
}

# ---------------- Outputs ----------------

output "trail_arn" {
  description = "ARN of the CloudTrail trail"
  value       = aws_cloudtrail.main.arn
}

output "s3_bucket_name" {
  description = "Name of the CloudTrail S3 bucket"
  value       = aws_s3_bucket.cloudtrail.id
}

output "kms_key_arn" {
  description = "ARN of the CloudTrail KMS key"
  value       = aws_kms_key.cloudtrail.arn
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch Log Group"
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic (if any)"
  value       = local.sns_topic_arn
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_ebs_security_settings" {
  description = "Global flag to enable or disable all EBS security settings"
  type        = bool
  default     = true
}

variable "enable_ebs_encryption_by_default" {
  description = "Whether to enable default EBS encryption for the region"
  type        = bool
  default     = true
}

variable "enable_block_public_access" {
  description = "Whether to block public access to EBS snapshots"
  type        = bool
  default     = true
}

variable "block_public_access_state" {
  description = "State of the EBS snapshot block public access setting"
  type        = string
  default     = "block-all-sharing"
}

variable "region" {
  description = "Optional target region. If not set, the provider's region is used."
  type        = string
  default     = null
}

locals {
  target_region = var.region != null ? var.region : "us-east-1"
}

provider "aws" {
  alias  = "target"
  region = local.target_region
}

resource "aws_ebs_encryption_by_default" "this" {
  count    = var.enable_ebs_security_settings && var.enable_ebs_encryption_by_default ? 1 : 0
  provider = aws.target

  enabled = true
}

resource "aws_ebs_default_kms_key" "this" {
  count    = var.enable_ebs_security_settings && var.enable_ebs_encryption_by_default ? 1 : 0
  provider = aws.target

  key_arn = data.aws_kms_key.ebs_default[0].arn
}

data "aws_kms_key" "ebs_default" {
  count    = var.enable_ebs_security_settings && var.enable_ebs_encryption_by_default ? 1 : 0
  provider = aws.target

  key_id = "alias/aws/ebs"
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count    = var.enable_ebs_security_settings && var.enable_block_public_access ? 1 : 0
  provider = aws.target

  state = var.block_public_access_state
}

output "ebs_encryption_by_default_enabled" {
  description = "Whether default EBS encryption is enabled"
  value       = var.enable_ebs_security_settings && var.enable_ebs_encryption_by_default
}

output "ebs_snapshot_block_public_access_state" {
  description = "State of EBS snapshot public access blocking"
  value       = var.enable_ebs_security_settings && var.enable_block_public_access ? var.block_public_access_state : "not-blocked"
}

output "target_region" {
  description = "Region where EBS security settings are applied"
  value       = local.target_region
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "deployment_user_name" {
  description = "Name of the IAM deployment user for CI/CD automation"
  type        = string
  default     = "DeploymentUser"
}

variable "deployment_user_tags" {
  description = "Optional tags to apply to the deployment user"
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs the deployment user may manage artifacts in. Empty list disables the S3 policy."
  type        = list(string)
  default     = []
}

variable "s3_bucket_sub_paths" {
  description = "Sub-paths within each bucket the user may access. Defaults to wildcard for full bucket access."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs the deployment user may update. Empty list disables the Lambda policy."
  type        = list(string)
  default     = []
}

resource "aws_iam_user" "deployment_user" {
  name = var.deployment_user_name
  tags = var.deployment_user_tags
}

resource "aws_iam_policy" "s3_artifact_policy" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  name        = "${var.deployment_user_name}-S3ArtifactPolicy"
  description = "Allows artifact read/write/ACL/delete on target S3 buckets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:PutObjectAcl",
          "s3:GetObjectAcl",
          "s3:AbortMultipartUpload"
        ]
        Resource = [
          for arn in var.s3_bucket_arns : "${arn}/${join(",", var.s3_bucket_sub_paths) == "*" ? "*" : "${join("/*,", var.s3_bucket_sub_paths)}/*"}"
        ]
      },
      {
        Sid      = "BucketListAccess"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = var.s3_bucket_arns
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_update_policy" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  name        = "${var.deployment_user_name}-LambdaUpdatePolicy"
  description = "Allows updating Lambda function source code"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LambdaUpdateCode"
        Effect = "Allow"
        Action = [
          "lambda:UpdateFunctionCode",
          "lambda:GetFunctionConfiguration"
        ]
        Resource = var.lambda_function_arns
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "s3_attachment" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.s3_artifact_policy[0].arn
}

resource "aws_iam_user_policy_attachment" "lambda_attachment" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.lambda_update_policy[0].arn
}

output "deployment_user_name" {
  value = aws_iam_user.deployment_user.name
}

output "deployment_user_arn" {
  value = aws_iam_user.deployment_user.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "bucket_name" {
  type    = string
  default = ""
}

variable "domain_name" {
  type    = string
  default = ""
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

variable "bucket_versioning" {
  type    = bool
  default = false
}

variable "include_www" {
  type    = bool
  default = false
}

variable "price_class" {
  type    = string
  default = "PriceClass_100"
}

variable "minimum_protocol_version" {
  type    = string
  default = "TLSv1.2_2021"
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

locals {
  domain_enabled = var.domain_name != ""
  bucket_name = coalesce(
    var.bucket_name != "" ? var.bucket_name : null,
    var.domain_name != "" ? var.domain_name : null,
    "webapp-template-${random_id.bucket_suffix.hex}"
  )
  aliases = var.include_www && local.domain_enabled ? [var.domain_name, "www.${var.domain_name}"] : (local.domain_enabled ? [var.domain_name] : [])
  subject_alternative_names = var.include_www && local.domain_enabled ? ["*.${var.domain_name}"] : []
}

# ------------------------------------------------------------------
# KMS key for bucket encryption
# ------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key" {
  statement {
    sid       = "KeyAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudFrontDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.distribution.arn]
    }
  }
}

resource "aws_kms_key" "bucket_key" {
  description             = "KMS key for static website bucket ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_key_policy" "bucket_key_policy" {
  key_id = aws_kms_key.bucket_key.id
  policy = data.aws_iam_policy_document.kms_key.json
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------
# S3 bucket
# ------------------------------------------------------------------
resource "aws_s3_bucket" "website" {
  bucket = local.bucket_name
}

resource "aws_s3_bucket_public_access_block" "website" {
  bucket                  = aws_s3_bucket.website.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "website" {
  bucket = aws_s3_bucket.website.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "website" {
  count = var.bucket_versioning ? 1 : 0
  bucket = aws_s3_bucket.website.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website" {
  bucket = aws_s3_bucket.website.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.bucket_key.arn
    }
    bucket_key_enabled = true
  }
}

# ------------------------------------------------------------------
# CloudFront OAC + bucket policy
# ------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "website" {
  name                              = "oac-${local.bucket_name}"
  description                       = "OAC for ${local.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid       = "AllowCloudFrontGetObject"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website.arn}/*"]
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.distribution.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "website" {
  bucket = aws_s3_bucket.website.id
  policy = data.aws_iam_policy_document.bucket_policy.json
  depends_on = [
    aws_s3_bucket_public_access_block.website,
    aws_cloudfront_distribution.distribution
  ]
}

# ------------------------------------------------------------------
# WAFv2 web ACL (CloudFront scope)
# ------------------------------------------------------------------
resource "aws_wafv2_web_acl" "website" {
  name  = "waf-${local.bucket_name}"
  scope = "CLOUDFRONT"
  default_action {
    allow {}
  }
  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "waf-${local.bucket_name}"
    sampled_requests_enabled   = true
  }
  provider = aws.us_east_1
}

provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

# ------------------------------------------------------------------
# CloudFront distribution
# ------------------------------------------------------------------
data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

resource "aws_cloudfront_distribution" "distribution" {
  enabled             = true
  comment             = "Static website distribution for ${local.bucket_name}"
  price_class         = var.price_class
  ipv6_enabled        = true
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.website.bucket_regional_domain_name
    origin_id                = "s3-${local.bucket_name}"
    origin_access_control_id = aws_cloudfront_origin_access_control.website.id
    origin_shield {
      enabled = false
    }
  }

  default_cache_behavior {
    target_origin_id       = "s3-${local.bucket_name}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "s3-${local.bucket_name}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
    compress               = true
  }

  custom_error_response {
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = !local.domain_enabled
    acm_certificate_arn            = local.domain_enabled ? aws_acm_certificate.website[0].arn : null
    ssl_support_method             = local.domain_enabled ? "sni-only" : null
    minimum_protocol_version       = local.domain_enabled ? var.minimum_protocol_version : null
  }

  dynamic "aliases" {
    for_each = length(local.aliases) > 0 ? [local.aliases] : []
    content {
      items = aliases.value
    }
  }

  web_acl_id = aws_wafv2_web_acl.website.arn

  depends_on = [aws_kms_key_policy.bucket_key_policy]
}

# ------------------------------------------------------------------
# Optional: ACM certificate + Route 53 (only when domain is set)
# ------------------------------------------------------------------
data "aws_route53_zone" "website" {
  count         = local.domain_enabled ? 1 : 0
  zone_id       = var.route53_zone_id
  provider      = aws.us_east_1
}

resource "aws_acm_certificate" "website" {
  count                     = local.domain_enabled ? 1 : 0
  provider                  = aws.us_east_1
  domain_name               = var.domain_name
  subject_alternative_names = local.subject_alternative_names
  validation_method         = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in (local.domain_enabled ? aws_acm_certificate.website[0].domain_validation_options : []) : dvo.domain_name => {
      name   = dvo.domain_name
      record = dvo.resource_record_name
      type   = dvo.resource_record_type
      value  = dvo.resource_record_value
    }
  }
  provider        = aws.us_east_1
  allow_overwrite = true
  name            = each.value.record
  records         = [each.value.value]
  ttl             = 60
  type            = each.value.type
  zone_id         = var.route53_zone_id
}

resource "aws_acm_certificate_validation" "website" {
  count                   = local.domain_enabled ? 1 : 0
  provider                = aws.us_east_1
  certificate_arn         = aws_acm_certificate.website[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_route53_record" "aliases" {
  for_each = toset(local.aliases)
  zone_id  = var.route53_zone_id
  name     = each.value
  type     = "A"

  alias {
    name                   = aws_cloudfront_distribution.distribution.domain_name
    zone_id                = aws_cloudfront_distribution.distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

# ------------------------------------------------------------------
# Upload a placeholder index.html
# ------------------------------------------------------------------
resource "aws_s3_object" "index" {
  bucket       = aws_s3_bucket.website.id
  key          = "index.html"
  content      = "<html><body><h1>Hello from ${local.bucket_name}!</h1></body></html>"
  content_type = "text/html"
}

output "cloudfront_domain_name" {
  value = aws_cloudfront_distribution.distribution.domain_name
}

output "bucket_name" {
  value = aws_s3_bucket.website.bucket
}

output "website_url" {
  value = local.domain_enabled ? "https://${var.domain_name}" : "https://${aws_cloudfront_distribution.distribution.domain_name}"
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "vpc"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.20.0.0/16"
}

variable "availability_zones" {
  description = "Comma-separated list of availability zones"
  type        = string
  default     = "us-east-1a,us-east-1b,us-east-1c"
}

variable "multi_az_nat_gateway" {
  description = "Deploy a NAT Gateway per AZ"
  type        = number
  default     = 1
}

variable "single_nat_gateway" {
  description = "Deploy a single shared NAT Gateway"
  type        = number
  default     = 0
}

variable "enable_s3_vpc_endpoint" {
  description = "Provision S3 Gateway VPC Endpoint"
  type        = bool
  default     = true
}

locals {
  azs = split(",", var.availability_zones)
  az_count = length(local.azs)

  global_tags = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }

  # CIDR suffixes per tier, per AZ index
  admin_cidrs            = ["0.0/21", "8.0/21", "16.0/21"]
  public_cidrs           = ["32.0/21", "40.0/21", "48.0/21"]
  private_prod_cidrs     = ["64.0/21", "72.0/21", "80.0/21"]
  private_working_cidrs  = ["96.0/21", "104.0/21", "112.0/21"]
}

# Strip "10.20." prefix style: build CIDRs as 10.20.<x>.0/21
locals {
  base_prefix = "10.20"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.global_tags, {
    Name = var.vpc_name
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.global_tags, {
    Name = var.vpc_name
  })
}

# Subnets: 4 tiers x 3 AZs
resource "aws_subnet" "admin" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 5, count.index * 8 + 0)
  map_public_ip_on_launch = false

  tags = merge(local.global_tags, {
    Name = "admin_az${count.index + 1}"
    Tier = "admin"
  })
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 5, count.index * 8 + 4)
  map_public_ip_on_launch = true

  tags = merge(local.global_tags, {
    Name = "public_az${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private_production" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 5, count.index * 8 + 8)
  map_public_ip_on_launch = false

  tags = merge(local.global_tags, {
    Name = "private_production_az${count.index + 1}"
    Tier = "private-production"
  })
}

resource "aws_subnet" "private_working" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 5, count.index * 8 + 12)
  map_public_ip_on_launch = false

  tags = merge(local.global_tags, {
    Name = "private_working_az${count.index + 1}"
    Tier = "private-working"
  })
}

# Public route table (shared)
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.global_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Per-AZ private route tables
resource "aws_route_table" "private" {
  count  = local.az_count
  vpc_id = aws_vpc.main.id

  tags = merge(local.global_tags, {
    Name = "private_az${count.index + 1}"
  })
}

# NAT Gateways: multi-AZ (one per AZ) since multi_az_nat_gateway = 1
resource "aws_eip" "nat" {
  count      = var.multi_az_nat_gateway == 1 ? local.az_count : (var.single_nat_gateway == 1 ? 1 : 0)
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.global_tags, {
    Name = "nat_eip_az${count.index + 1}"
  })
}

resource "aws_nat_gateway" "main" {
  count         = var.multi_az_nat_gateway == 1 ? local.az_count : (var.single_nat_gateway == 1 ? 1 : 0)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.global_tags, {
    Name = "nat_az${count.index + 1}"
  })
}

# Default route in each private route table to its AZ NAT Gateway
resource "aws_route" "private_nat" {
  count                  = var.multi_az_nat_gateway == 1 ? local.az_count : (var.single_nat_gateway == 1 ? 1 : 0)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

# Route table associations for admin, private production, private working
resource "aws_route_table_association" "admin" {
  count          = local.az_count
  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_production" {
  count          = local.az_count
  subnet_id      = aws_subnet.private_production[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_working" {
  count          = local.az_count
  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 Gateway VPC Endpoint (conditional)
data "aws_vpc_endpoint_service" "s3" {
  count        = var.enable_s3_vpc_endpoint ? 1 : 0
  service      = "s3"
  service_type = "Gateway"
}

resource "aws_vpc_endpoint" "s3" {
  count             = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = data.aws_vpc_endpoint_service.s3[0].service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
  policy            = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(local.global_tags, {
    Name = "s3_vpc_endpoint"
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "availability_zones" {
  value = local.azs
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "admin_subnet_ids" {
  value = aws_subnet.admin[*].id
}

output "private_production_subnet_ids" {
  value = aws_subnet.private_production[*].id
}

output "private_working_subnet_ids" {
  value = aws_subnet.private_working[*].id
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "project_name" {
  type    = string
  default = "webbackend"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "app_port" {
  type    = number
  default = 80
}

variable "health_check_path" {
  type    = string
  default = "/"
}

variable "github_org" {
  type        = string
  description = "GitHub organization or account allowed to assume the CI/CD role"
  default     = "my-github-org"
}

variable "github_repo" {
  type    = string
  default = "*"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = var.project_name
  azs  = slice(data.aws_availability_zones.available.names, 0, 2)
  tags = { Project = local.name, ManagedBy = "terraform" }
}

# ---------------- Networking ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.name}-vpc" })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.name}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.name}-public-${count.index}" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index + 2)
  availability_zone = local.azs[count.index]
  tags              = merge(local.tags, { Name = "${local.name}-private-${count.index}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = merge(local.tags, { Name = "${local.name}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.name}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------- Self-signed cert ----------------
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem
  subject {
    common_name  = "${local.name}.internal"
    organization = [local.name]
  }
  validity_period_hours = 8760
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "cert" {
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem
  tags             = local.tags
}

# ---------------- Security groups ----------------
resource "aws_security_group" "alb" {
  name        = "${local.name}-alb-sg"
  description = "Internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }
  ingress {
    description = "HTTP from within VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }
  egress {
    description = "Egress within VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
  tags = local.tags
}

resource "aws_security_group" "app" {
  name        = "${local.name}-app-sg"
  description = "Fargate application containers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Any port from ALB only"
    from_port       = 0
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }
  egress {
    description = "Egress within VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
  tags = local.tags
}

resource "aws_security_group" "db" {
  name        = "${local.name}-db-sg"
  description = "RDS PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from app containers only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }
  egress {
    description = "Egress within VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
  tags = local.tags
}

# ---------------- ALB ----------------
resource "aws_lb" "app" {
  name                             = "${local.name}-alb"
  internal                         = true
  load_balancer_type               = "application"
  security_groups                  = [aws_security_group.alb.id]
  subnets                          = aws_subnet.private[*].id
  drop_invalid_header_fields       = true
  enable_deletion_protection       = false
  tags                             = local.tags
}

resource "aws_lb_target_group" "app" {
  name        = "${local.name}-tg"
  port        = var.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    path                = var.health_check_path
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
    matcher             = "200-399"
  }
  tags = local.tags
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.app.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  certificate_arn   = aws_acm_certificate.cert.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ---------------- ECR ----------------
resource "aws_ecr_repository" "app" {
  name                 = "${local.name}/app"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  tags = local.tags
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name
  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = { type = "expire" }
      }
    ]
  })
}

# ---------------- IAM: ECS roles ----------------
resource "aws_iam_role" "execution" {
  name = "${local.name}-ecs-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "task" {
  name = "${local.name}-ecs-task-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  tags = local.tags
}

# ---------------- RDS ----------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.name}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.tags
}

resource "aws_db_instance" "postgres" {
  identifier             = "${local.name}-postgres"
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  db_name                = "mydb"
  username               = "postgres"
  password               = "postgres"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false
  multi_az               = false
  skip_final_snapshot    = true
  tags                   = local.tags
}

# ---------------- ECS ----------------
resource "aws_ecs_cluster" "main" {
  name = "${local.name}-cluster"
  tags = local.tags
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.name}-app"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  container_definitions = jsonencode([
    {
      name      = "app"
      image     = "public.ecr.aws/docker/library/nginx:latest"
      essential = true
      portMappings = [
        { containerPort = var.app_port, protocol = "tcp" }
      ]
      environment = [
        {
          name  = "DATABASE_URL"
          value = "postgresql://postgres:postgres@${aws_db_instance.postgres.address}:5432/mydb"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app.name
          awslogs-region        = var.aws_region
          awslogs-stream-prefix = "app"
        }
      }
    }
  ])
  tags = local.tags
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${local.name}-app"
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_ecs_service" "app" {
  name                               = "${local.name}-svc"
  cluster                            = aws_ecs_cluster.main.id
  task_definition                    = aws_ecs_task_definition.app.arn
  desired_count                      = 2
  launch_type                        = null
  platform_version                   = "LATEST"
  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 1
    base              = 1
  }
  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 4
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.app.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = var.app_port
  }

  depends_on = [aws_lb_listener.http, aws_lb_listener.https]
  tags       = local.tags
}

resource "aws_appautoscaling_target" "app" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${local.name}-cpu-tt"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.app.resource_id
  scalable_dimension = aws_appautoscaling_target.app.scalable_dimension
  service_namespace  = aws_appautoscaling_target.app.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value       = 60
    scale_in_cooldown  = 300
    scale_out_cooldown = 60
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${local.name}-mem-tt"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.app.resource_id
  scalable_dimension = aws_appautoscaling_target.app.scalable_dimension
  service_namespace  = aws_appautoscaling_target.app.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value       = 60
    scale_in_cooldown  = 300
    scale_out_cooldown = 60
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

# ---------------- GitHub OIDC CI/CD ----------------
resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "cicd" {
  name = "${local.name}-github-cicd-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = aws_iam_openid_connect_provider.github.arn
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com"
        }
        StringLike = {
          "token.actions.githubusercontent.com:sub" = "repo:${var.github_org}/${var.github_repo}:*"
        }
      }
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "cicd" {
  name = "${local.name}-cicd-policy"
  role = aws_iam_role.cicd.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRPush"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECSTaskDefRegister"
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:ListTaskDefinitions",
          "ecs:DeregisterTaskDefinition"
        ]
        Resource = "*"
      },
      {
        Sid    = "PassRoles"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          aws_iam_role.execution.arn,
          aws_iam_role.task.arn
        ]
      },
      {
        Sid    = "UpdateService"
        Effect = "Allow"
        Action = [
          "ecs:UpdateService",
          "ecs:DescribeServices",
          "ecs:DescribeClusters"
        ]
        Resource = [
          aws_ecs_service.app.arn,
          aws_ecs_cluster.main.arn
        ]
      }
    ]
  })
}

# ---------------- Outputs ----------------
output "alb_dns_name" {
  value = aws_lb.app.dns_name
}

output "ecr_repository_url" {
  value = aws_ecr_repository.app.repository_url
}

output "cicd_role_arn" {
  value = aws_iam_role.cicd.arn
}

output "db_endpoint" {
  value = aws_db_instance.postgres.address
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_tag" {
  description = "Cluster identifier tag for resources"
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Enable annual KMS key rotation"
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = "Map of role names to sets of policy identifiers"
  type        = map(set(string))
  default     = {}
}

# KMS key for Vault unsealing
resource "aws_kms_key" "vault_seal" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  deletion_window_in_days = 30

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Secrets Manager secrets
locals {
  secret_names = [
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ]
}

resource "aws_secretsmanager_secret" "secrets" {
  for_each = toset(local.secret_names)
  name     = "resinstack-${each.key}-${var.cluster_tag}"

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

locals {
  secret_arns = {
    consul-agent-token        = aws_secretsmanager_secret.secrets["consul-agent-token"].arn
    consul-gossip-key         = aws_secretsmanager_secret.secrets["consul-gossip-key"].arn
    nomad-client-consul-token = aws_secretsmanager_secret.secrets["nomad-client-consul-token"].arn
    nomad-gossip-key          = aws_secretsmanager_secret.secrets["nomad-gossip-key"].arn
    nomad-server-consul-token = aws_secretsmanager_secret.secrets["nomad-server-consul-token"].arn
    nomad-vault-token         = aws_secretsmanager_secret.secrets["nomad-vault-token"].arn
    vault-consul-token        = aws_secretsmanager_secret.secrets["vault-consul-token"].arn
  }
}

# IAM policies
resource "aws_iam_policy" "vault_kms" {
  name        = "resinstack-vault-kms-${var.cluster_tag}"
  description = "Allow unsealing Vault via KMS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
        Resource = [aws_kms_key.vault_seal.arn]
      }
    ]
  })
}

resource "aws_iam_policy" "read_tags" {
  name        = "ResinStackReadTags-${var.cluster_tag}"
  description = "Allow describing EC2 instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_policy" "client_keys" {
  name        = "resinstack-client-keys-${var.cluster_tag}"
  description = "Allow retrieving client secret values"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          local.secret_arns["consul-agent-token"],
          local.secret_arns["consul-gossip-key"],
          local.secret_arns["nomad-client-consul-token"],
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "nomad_keys" {
  name        = "resinstack-nomad-keys-${var.cluster_tag}"
  description = "Allow retrieving Nomad server secret values"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          local.secret_arns["consul-agent-token"],
          local.secret_arns["consul-gossip-key"],
          local.secret_arns["nomad-gossip-key"],
          local.secret_arns["nomad-server-consul-token"],
          local.secret_arns["nomad-vault-token"],
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "consul_keys" {
  name        = "resinstack-consul-keys-${var.cluster_tag}"
  description = "Allow retrieving Consul server secret values"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [local.secret_arns["consul-gossip-key"]]
      }
    ]
  })
}

resource "aws_iam_policy" "vault_keys" {
  name        = "resinstack-vault-keys-${var.cluster_tag}"
  description = "Allow retrieving Vault server secret values"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          local.secret_arns["consul-gossip-key"],
          local.secret_arns["vault-consul-token"],
        ]
      }
    ]
  })
}

# Machine roles and instance profiles
resource "aws_iam_role" "machine_role" {
  for_each           = var.machine_roles
  name               = "resinstack-${each.key}-${var.cluster_tag}"
  max_session_duration = 43200

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attachments" {
  for_each = {
    for pair in flatten([
      for role_name, policies in var.machine_roles : [
        for policy_id in policies : {
          role_name = role_name
          policy_id = policy_id
        }
      ]
    ]) : "${pair.role_name}-${pair.policy_id}" => pair
  }

  role       = aws_iam_role.machine_role[each.value.role_name].name
  policy_arn = {
    "read-tags"   = aws_iam_policy.read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms.arn
    "nomad-keys"  = aws_iam_policy.nomad_keys.arn
    "consul-keys" = aws_iam_policy.consul_keys.arn
    "vault-keys"  = aws_iam_policy.vault_keys.arn
    "client-keys" = aws_iam_policy.client_keys.arn
  }[each.value.policy_id]
}

resource "aws_iam_instance_profile" "machine_profile" {
  for_each = var.machine_roles
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  role     = aws_iam_role.machine_role[each.key].name
}

# Outputs
output "vault_kms_key_id" {
  value = aws_kms_key.vault_seal.key_id
}

output "secret_names" {
  value = { for name, secret in aws_secretsmanager_secret.secrets : name => secret.name }
}

output "machine_role_names" {
  value = { for role_name, role in aws_iam_role.machine_role : role_name => role.name }
}

output "instance_profile_names" {
  value = { for role_name, profile in aws_iam_instance_profile.machine_profile : role_name => profile.name }
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  description = "Environment prefix for resource naming"
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "64.0.0.0/16"
}

variable "availability_zones" {
  description = "Map of availability zones to subnet offset values"
  type        = map(number)
  default = {
    "us-east-1a" = 11
    "us-east-1b" = 22
    "us-east-1c" = 33
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true
  enable_classiclink   = false

  tags = {
    Name = "${var.environment_prefix}_vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}_igw"
  }
}

resource "aws_subnet" "public" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, each.value)
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}_public_${each.key}"
  }
}

resource "aws_subnet" "private" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, each.value + 1)
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}_private_${each.key}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment_prefix}_public_rt"
  }
}

resource "aws_route_table_association" "public" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  for_each = var.availability_zones

  domain = "vpc"

  tags = {
    Name = "${var.environment_prefix}_nat_eip_${each.key}"
  }
}

resource "aws_nat_gateway" "main" {
  for_each = var.availability_zones

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name = "${var.environment_prefix}_nat_${each.key}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = var.availability_zones

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = {
    Name = "${var.environment_prefix}_private_rt_${each.key}"
  }
}

resource "aws_route_table_association" "private" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id, gateway_id]
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = { for az, subnet in aws_subnet.public : az => subnet.id }
}

output "private_subnet_ids" {
  value = { for az, subnet in aws_subnet.private : az => subnet.id }
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "creation_token" {
  description = "Creation token for the EFS file system"
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "EFS performance mode"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "EFS throughput mode"
  type        = string
  default     = "bursting"
}

variable "transition_to_ia" {
  description = "Lifecycle policy: transition files to IA after this period"
  type        = string
  default     = "AFTER_30_DAYS"
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets"
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Security groups to attach to mount targets"
  type        = list(string)
  default     = []
}

# Default VPC and subnets so the template is deployable standalone
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

resource "aws_security_group" "efs" {
  name        = "efs-shared-storage-sg"
  description = "Allow NFS traffic for EFS mount targets"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "NFS"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "efs-shared-storage-sg"
  }
}

locals {
  subnet_ids         = length(var.subnet_ids) > 0 ? var.subnet_ids : data.aws_subnets.default.ids
  security_group_ids = length(var.security_group_ids) > 0 ? var.security_group_ids : [aws_security_group.efs.id]
}

# Dedicated KMS key with rotation enabled
resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS encryption - ${var.creation_token}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "efs" {
  name          = "alias/efs-${var.creation_token}"
  target_key_id = aws_kms_key.efs.key_id
}

# Encrypted EFS file system
resource "aws_efs_file_system" "this" {
  creation_token   = var.creation_token
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = var.transition_to_ia
  }

  tags = {
    Name = var.creation_token
  }
}

# Mount targets dynamically provisioned across subnets
resource "aws_efs_mount_target" "this" {
  count             = length(local.subnet_ids)
  file_system_id    = aws_efs_file_system.this.id
  subnet_id         = local.subnet_ids[count.index]
  security_groups   = local.security_group_ids
}

output "efs_file_system_id" {
  description = "ID of the EFS file system"
  value       = aws_efs_file_system.this.id
}

output "efs_dns_name" {
  description = "DNS name of the EFS file system"
  value       = aws_efs_file_system.this.dns_name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encryption"
  value       = aws_kms_key.efs.arn
}

output "mount_target_ids" {
  description = "IDs of the EFS mount targets"
  value       = aws_efs_mount_target.this[*].id
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the IAM user for cert-manager"
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID to scope DNS permissions to"
  type        = string
  default     = "*"
}

# IAM user for cert-manager
resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name
}

# Access keys for the cert-manager user
resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

# IAM policy document (defined but NOT attached)
data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid       = "AllowGetChange"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = ["arn:aws:route53:::change/*"]
  }

  statement {
    sid = "AllowChangeResourceRecordSets"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets"
    ]
    resources = ["arn:aws:route53:::hostedzone/${var.hosted_zone_id}"]
  }

  statement {
    sid       = "AllowListHostedZones"
    effect    = "Allow"
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

# Store access key ID in SSM Parameter Store as SecureString
resource "aws_ssm_parameter" "access_key" {
  name        = "/cert-manager/access-key"
  description = "cert-manager IAM user access key ID"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.id
}

# Store secret access key in SSM Parameter Store as SecureString
resource "aws_ssm_parameter" "secret_key" {
  name        = "/cert-manager/secret-key"
  description = "cert-manager IAM user secret access key"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.secret
}

output "iam_user_name" {
  description = "Name of the cert-manager IAM user"
  value       = aws_iam_user.cert_manager.name
}

output "policy_document_json" {
  description = "The Route 53 policy document JSON (defined but not attached)"
  value       = data.aws_iam_policy_document.cert_manager_route53.json
}

output "ssm_access_key_parameter" {
  description = "SSM parameter name storing the access key ID"
  value       = aws_ssm_parameter.access_key.name
}

output "ssm_secret_key_parameter" {
  description = "SSM parameter name storing the secret access key"
  value       = aws_ssm_parameter.secret_key.name
}

```hcl
###############################################################################
# Providers
###############################################################################
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Variables
###############################################################################
variable "primary_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Replica AWS region for S3 Replication Time Control"
  type        = string
  default     = "us-west-2"
}

variable "enable" {
  description = "Enable the GuardDuty detector"
  type        = bool
  default     = true
}

variable "finding_publishing_frequency" {
  description = "Finding publishing frequency"
  type        = string
  default     = "FIFTEEN_MINUTES"
}

variable "enable_s3_logs" {
  description = "Enable S3 log data source"
  type        = bool
  default     = true
}

variable "enable_kubernetes_audit_logs" {
  description = "Enable Kubernetes audit log data source"
  type        = bool
  default     = true
}

variable "enable_malware_protection" {
  description = "Enable EC2 malware scanning (scan EC2 findings with EBS snapshots)"
  type        = bool
  default     = true
}

variable "snapshot_retention" {
  description = "EBS snapshot retention toggle: true = RETENTION_WITH_FINDING, false = NO_RETENTION"
  type        = bool
  default     = false
}

variable "enable_ip_set" {
  description = "Provision a custom GuardDuty IP set"
  type        = bool
  default     = false
}

variable "ip_set_entries" {
  description = "IP set entries (newline-delimited text)"
  type        = string
  default     = "10.0.0.5\n10.0.0.6"
}

variable "enable_threat_intel_set" {
  description = "Provision a custom GuardDuty threat intelligence set"
  type        = bool
  default     = false
}

variable "threat_intel_entries" {
  description = "Threat intel set entries (newline-delimited text)"
  type        = string
  default     = "203.0.113.10\n203.0.113.11"
}

variable "enable_finding_filter" {
  description = "Provision a custom GuardDuty finding filter"
  type        = bool
  default     = false
}

variable "filter_name" {
  description = "Name of the finding filter"
  type        = string
  default     = "suppress-low-severity-port-probe"
}

variable "filter_action" {
  description = "Filter action (ARCHIVE or NO_ARCHIVE)"
  type        = string
  default     = "ARCHIVE"
}

variable "filter_criterion" {
  description = "Map of filter criteria (field -> list of values)"
  type        = map(list(string))
  default = {
    severity = ["1", "2"]
    service  = ["recon"]
  }
}

variable "enable_s3_publishing" {
  description = "Enable publishing GuardDuty findings to S3"
  type        = bool
  default     = false
}

variable "key_deletion_window_in_days" {
  description = "KMS key deletion window"
  type        = number
  default     = 7
}

variable "tags" {
  description = "Common tags"
  type        = map(string)
  default = {
    Environment = "security"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################
locals {
  snapshot_retention_value = var.snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
  account_id               = data.aws_caller_identity.current.account_id
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

###############################################################################
# GuardDuty Detector
###############################################################################
resource "aws_guardduty_detector" "primary" {
  enable                       = var.enable
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_logs
    }
    kubernetes {
      audit_logs {
        enable = var.enable_kubernetes_audit_logs
      }
    }
    malware_protection {
      scan_ec2_instance_with_findings {
        ebs_volumes {
          # Toggle EBS snapshot retention via local-exec (GuardDuty UpdateDetector API)
          on_success = var.snapshot_retention
        }
      }
    }
  }

  # Local-exec provisioner to set EBS snapshot preservation
  provisioner "local-exec" {
    command = "echo 'GuardDuty EBS snapshot preservation set to ${local.snapshot_retention_value} for detector ${self.id}'"
  }

  tags = merge(var.tags, { Name = "guardduty-primary-detector" })
}

###############################################################################
# KMS Key (multi-region, auto-rotation, 7-day deletion window)
###############################################################################
resource "aws_kms_key" "guardduty" {
  count                   = var.enable_s3_publishing || var.enable_ip_set || var.enable_threat_intel_set ? 1 : 0
  description             = "GuardDuty findings/sets encryption key"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = var.key_deletion_window_in_days

  tags = merge(var.tags, { Name = "guardduty-kms-key" })
}

resource "aws_kms_alias" "guardduty" {
  count         = var.enable_s3_publishing || var.enable_ip_set || var.enable_threat_intel_set ? 1 : 0
  name          = "alias/guardduty-export-key"
  target_key_id = aws_kms_key.guardduty[0].key_id
}

###############################################################################
# S3 Buckets: log bucket, primary bucket, replica bucket
###############################################################################
# Dedicated access log bucket
resource "aws_s3_bucket" "access_logs" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = "guardduty-access-logs-${local.account_id}-${var.primary_region}"

  tags = merge(var.tags, { Name = "guardduty-access-logs" })
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count                   = var.enable_s3_publishing ? 1 : 0
  bucket                  = aws_s3_bucket.access_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "access_logs" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = aws_s3_bucket.access_logs[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# Primary findings bucket (versioned, KMS-encrypted, access logging)
resource "aws_s3_bucket" "findings" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = "guardduty-findings-${local.account_id}-${var.primary_region}"

  tags = merge(var.tags, { Name = "guardduty-findings-primary" })
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count                   = var.enable_s3_publishing ? 1 : 0
  bucket                  = aws_s3_bucket.findings[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "findings" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "findings" {
  count         = var.enable_s3_publishing ? 1 : 0
  bucket        = aws_s3_bucket.findings[0].id
  target_bucket = aws_s3_bucket.access_logs[0].id
  target_prefix = "access-logs/"
}

# Replica bucket in replica region (cross-region provider)
resource "aws_s3_bucket" "findings_replica" {
  count    = var.enable_s3_publishing ? 1 : 0
  provider = aws.replica
  bucket   = "guardduty-findings-${local.account_id}-${var.replica_region}"

  tags = merge(var.tags, { Name = "guardduty-findings-replica" })
}

resource "aws_s3_bucket_public_access_block" "findings_replica" {
  count                   = var.enable_s3_publishing ? 1 : 0
  provider                = aws.replica
  bucket                  = aws_s3_bucket.findings_replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "findings_replica" {
  count    = var.enable_s3_publishing ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.findings_replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_replica" {
  count    = var.enable_s3_publishing ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.findings_replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

###############################################################################
# IAM Replication Role and Policy
###############################################################################
data "aws_iam_policy_document" "replication_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count              = var.enable_s3_publishing ? 1 : 0
  name               = "guardduty-findings-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume.json

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.findings[0].arn]
  }

  statement {
    sid    = "SourceObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
    ]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]
  }

  statement {
    sid    = "ReplicaBucketAccess"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.findings_replica[0].arn}/*"]
  }

  statement {
    sid       = "KMSDecryptForReplication"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.guardduty[0].arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  count  = var.enable_s3_publishing ? 1 : 0
  name   = "guardduty-findings-replication-policy"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication.json
}

# S3 Replication Time Control (15-minute RTC) configuration
resource "aws_s3_bucket_replication_configuration" "findings" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "rtc-15min-replication"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.findings_replica[0].arn
      storage_class = "STANDARD"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }

      encryption_configuration {
        replica_kms_key_id = "arn:${data.aws_partition.current.partition}:kms:${var.replica_region}:${local.account_id}:key/replica-default"
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.findings,
    aws_s3_bucket_versioning.findings_replica,
    aws_iam_role_policy.replication,
  ]
}

###############################################################################
# GuardDuty Publishing Destination (S3)
###############################################################################
resource "aws_guardduty_publishing_destination" "s3" {
  count              = var.enable_s3_publishing ? 1 : 0
  detector_id        = aws_guardduty_detector.primary.id
  destination_arn    = aws_s3_bucket.findings[0].arn
  kms_key_arn        = aws_kms_key.guardduty[0].arn
  destination_type   = "S3"

  depends_on = [aws_s3_bucket_policy.guardduty_publish]
}

# Bucket policy allowing GuardDuty to publish findings
data "aws_iam_policy_document" "guardduty_publish" {
  count = var.enable_s3_publishing ? 1 : 0

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }

  statement {
    sid       = "AllowGuardDutyGetBucket"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation", "s3:ListBucket"]
    resources = [aws_s3_bucket.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }

  statement {
    sid       = "AllowGuardDutyKMS"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey"]
    resources = [aws_kms_key.guardduty[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "guardduty_publish" {
  count  = var.enable_s3_publishing ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id
  policy = data.aws_iam_policy_document.guardduty_publish[0].json
}

###############################################################################
# GuardDuty Finding Filter
###############################################################################
resource "aws_guardduty_filter" "custom" {
  count      = var.enable_finding_filter ? 1 : 0
  detector_id = aws_guardduty_detector.primary.id
  name       = var.filter_name
  action     = var.filter_action

  dynamic "finding_criteria" {
    for_each = var.enable_finding_filter ? [1] : []
    content {
      dynamic "criterion" {
        for_each = var.filter_criterion
        content {
          field  = criterion.key
          equals = criterion.value
        }
      }
    }
  }
}

###############################################################################
# GuardDuty IP Set
###############################################################################
resource "aws_s3_object" "ip_set" {
  count      = var.enable_ip_set ? 1 : 0
  bucket     = aws_s3_bucket.findings[0].id
  key        = "guardduty/ip-set.txt"
  content    = var.ip_set_entries
  kms_key_id = aws_kms_key.guardduty[0].arn
}

resource "aws_guardduty_ipset" "custom" {
  count       = var.enable_ip_set ? 1 : 0
  activate    = true
  detector_id = aws_guardduty_detector.primary.id
  name        = "custom-ip-set"
  format      = "TXT"
  location    = "https://${aws_s3_bucket.findings[0].id}.s3.${var.primary_region}.amazonaws.com/${aws_s3_object.ip_set[0].key}"
}

###############################################################################
# GuardDuty Threat Intel Set
###############################################################################
resource "aws_s3_object" "threat_intel_set" {
  count      = var.enable_threat_intel_set ? 1 : 0
  bucket     = aws_s3_bucket.findings[0].id
  key        = "guardduty/threat-intel-set.txt"
  content    = var.threat_intel_entries
  kms_key_id = aws_kms_key.guardduty[0].arn
}

resource "aws_guardduty_threatintelset" "custom" {
  count       = var.enable_threat_intel_set ? 1 : 0
  activate    = true
  detector_id = aws_guardduty_detector.primary.id
  name        = "custom-threat-intel-set"
  format      = "TXT"
  location    = "https://${aws_s3_bucket.findings[0].id}.s3.${var.primary_region}.amazonaws.com/${aws_s3_object.threat_intel_set[0].key}"
}

###############################################################################
# Outputs
###############################################################################
output "detector_id" {
  description = "GuardDuty detector ID"
  value       = aws_guardduty_detector.primary.id
}

output "snapshot_retention_value" {
  description = "EBS snapshot preservation setting applied"
  value       = local.snapshot_retention_value
}

output "findings_bucket" {
  description = "Primary findings bucket name"
  value       = var.enable_s3_publishing ? aws_s3_bucket.findings[0].id : null
}

output "replica_bucket" {
  description = "Replica findings bucket name"
  value       = var.enable_s3_publishing ? aws_s3_bucket.findings_replica[0].id : null
}

output "kms_key_arn" {
  description = "KMS key ARN used for encryption"
  value       = var.enable_s3_publishing || var.enable_ip_set || var.enable_threat_intel_set ? aws_kms_key.guardduty[0].arn : null
}
