provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "imputation-example"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# EMR Service Role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "emr_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_service_role" {
  name               = "${var.name_prefix}-emr-service-role"
  assume_role_policy = data.aws_iam_policy_document.emr_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_service_policy" {
  role       = aws_iam_role.emr_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEMRServicePolicy_v2"
}

# -----------------------------------------------------------------------------
# EC2 Instance Profile Role (for EMR cluster nodes)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_ec2_role" {
  name               = "${var.name_prefix}-emr-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_managed_policy" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforEC2Role"
}

resource "aws_iam_role_policy" "emr_ec2_cloudwatch" {
  name = "${var.name_prefix}-cloudwatch-policy"
  role = aws_iam_role.emr_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "emr_ec2_ssm" {
  name = "${var.name_prefix}-ssm-policy"
  role = aws_iam_role.emr_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:DescribeAssociation",
          "ssm:GetDeployablePatchSnapshotForInstance",
          "ssm:GetDocument",
          "ssm:DescribeDocument",
          "ssm:GetManifest",
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:ListAssociations",
          "ssm:ListInstanceAssociations",
          "ssm:PutInventoryDocument",
          "ssm:PutDocument",
          "ssm:UpdateAssociationStatus",
          "ssm:UpdateInstanceAssociationStatus",
          "ssm:UpdateInstanceInformation"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2messages:SendReply"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "emr_ec2_instance_profile" {
  name = "${var.name_prefix}-emr-ec2-instance-profile"
  role = aws_iam_role.emr_ec2_role.name
  tags = var.tags
}

# -----------------------------------------------------------------------------
# EMR Autoscaling Role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "autoscaling_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_autoscaling_role" {
  name               = "${var.name_prefix}-emr-autoscaling-role"
  assume_role_policy = data.aws_iam_policy_document.autoscaling_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling_policy" {
  role       = aws_iam_role.emr_autoscaling_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEMRAutoscalePolicy"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "emr_service_role_arn" {
  description = "ARN of the EMR service role"
  value       = aws_iam_role.emr_service_role.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role"
  value       = aws_iam_role.emr_service_role.name
}

output "emr_service_role_unique_id" {
  description = "Unique ID of the EMR service role"
  value       = aws_iam_role.emr_service_role.unique_id
}

output "emr_ec2_role_arn" {
  description = "ARN of the EMR EC2 instance profile role"
  value       = aws_iam_role.emr_ec2_role.arn
}

output "emr_ec2_role_name" {
  description = "Name of the EMR EC2 instance profile role"
  value       = aws_iam_role.emr_ec2_role.name
}

output "emr_ec2_role_unique_id" {
  description = "Unique ID of the EMR EC2 instance profile role"
  value       = aws_iam_role.emr_ec2_role.unique_id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling_role.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling_role.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Unique ID of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling_role.unique_id
}

output "emr_instance_profile_id" {
  description = "ID of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.id
}

output "emr_instance_profile_arn" {
  description = "ARN of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.arn
}

output "emr_instance_profile_name" {
  description = "Name of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.name
}

terraform {
