provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the IAM user for API integration testing"
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "Optional ARN of the Cognito user pool to grant AdminInitiateAuth access"
  type        = string
  default     = ""
}

resource "aws_iam_user" "api_test_user" {
  name = var.iam_user_name
  path = "/"
}

resource "aws_iam_access_key" "api_test_user_key" {
  user = aws_iam_user.api_test_user.name
}

resource "aws_iam_user_policy" "readonly_apigw_cloudwatch" {
  name = "${var.iam_user_name}-readonly-apigw-cloudwatch"
  user = aws_iam_user.api_test_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["apigateway:GET"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["cloudwatch:GetMetricData", "cloudwatch:ListMetrics"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "cognito_admin_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  name = "${var.iam_user_name}-cognito-admin-auth"
  user = aws_iam_user.api_test_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cognito-idp:AdminInitiateAuth"]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

output "iam_user_name" {
  description = "Name of the created IAM user"
  value       = aws_iam_user.api_test_user.name
}

output "access_key_id" {
  description = "Access key ID for the IAM user"
  value       = aws_iam_access_key.api_test_user_key.id
}

output "secret_access_key" {
  description = "Secret access key for the IAM user (sensitive)"
  value       = aws_iam_access_key.api_test_user_key.secret
  sensitive   = true
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "legion"
}

# ---------------------------------------------------------------------------
# EKS Master (control plane) IAM role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "master_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.master_assume_role.json
}

resource "aws_iam_role_policy_attachment" "master_cluster_policy" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_service_policy" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# ---------------------------------------------------------------------------
# EKS Worker Node IAM role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_worker_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ---------------------------------------------------------------------------
# Cluster Autoscaler policy for worker nodes
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "worker_autoscaling" {
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchConfigurations",
      "ec2:DescribeLaunchTemplateVersions",
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "worker_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Cluster Autoscaler policy for EKS worker nodes (${var.cluster_name})"
  policy      = data.aws_iam_policy_document.worker_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "node_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

# ---------------------------------------------------------------------------
# Instance profile for worker nodes
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.node.name
}

output "master_role_arn" {
  value = aws_iam_role.master.arn
}

output "node_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_instance_profile_name" {
  value = aws_iam_instance_profile.node.name
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "172.69.2.0/24"
}

variable "webserver_ingress_rules" {
  description = "Dynamic ingress rules for the web server security group"
  type = list(object({
    port     = number
    protocol = string
    cidr     = string
  }))
  default = [
    {
      port     = 80
      protocol = "tcp"
      cidr     = "0.0.0.0/0"
    },
    {
      port     = 22
      protocol = "tcp"
      cidr     = "172.69.0.0/16"
    }
  ]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    vpc_name = "vpc_name"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone       = "us-east-1a"

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = "us-east-1a"

  tags = {
    Name = "private_subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "webserver" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.webserver_ingress_rules
    content {
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = [ingress.value.cidr]
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for databases"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "database_security_group"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}

output "private_subnet_id" {
  value = aws_subnet.private.id
}

output "webserver_security_group_id" {
  value = aws_security_group.webserver.id
}

output "database_security_group_id" {
  value = aws_security_group.database.id
}

