resource "aws_iam_instance_profile" "aws_ccm_k8s_controlplane" {
  name = "aws_ccm_k8s_controlplane"
  role = aws_iam_role.aws_ccm_k8s_controlplane.name
  tags = var.tags
}

data "aws_iam_policy_document" "aws_ccm_k8s_controlplane" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeVpcs",
      "ec2:DescribeSubnets",
      "ec2:DescribeRouteTables",
      "ec2:DescribeInternetGateways",
      "ec2:DescribeNatGateways",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeAddresses",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "ec2:AllocateAddress",
      "ec2:ReleaseAddress",
      "ec2:AssociateAddress",
      "ec2:DisassociateAddress",
      "ec2:CreateNetworkInterface",
      "ec2:DeleteNetworkInterface",
      "ec2:ModifyNetworkInterfaceAttribute",
      "ec2:CreateRoute",
      "ec2:DeleteRoute",
      "ec2:ReplaceRoute",
      "autoscaling:DescribeAutoScalingGroups",
      "elasticloadbalancing:CreateLoadBalancer",
      "elasticloadbalancing:DeleteLoadBalancer",
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:ModifyLoadBalancerAttributes",
      "elasticloadbalancing:ConfigureHealthCheck",
      "elasticloadbalancing:DescribeTags",
      "elasticloadbalancing:AddTags",
      "elasticloadbalancing:RemoveTags",
      "elasticloadbalancing:CreateTargetGroup",
      "elasticloadbalancing:DeleteTargetGroup",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTargetGroupAttributes",
      "elasticloadbalancing:ModifyTargetGroup",
      "elasticloadbalancing:ModifyTargetGroupAttributes",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:CreateListener",
      "elasticloadbalancing:DeleteListener",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:CreateRule",
      "elasticloadbalancing:DeleteRule",
      "elasticloadbalancing:ModifyRule",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
      "kms:DescribeKey",
      "iam:CreateServiceLinkedRole"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "aws_ccm_k8s_controlplane" {
  name        = "aws_ccm_k8s_controlplane"
  description = "Policy for the AWS Cloud Controller Manager on the Kubernetes control plane"
  policy      = data.aws_iam_policy_document.aws_ccm_k8s_controlplane.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "aws_ccm_k8s_controlplane" {
  role       = aws_iam_role.aws_ccm_k8s_controlplane.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_controlplane.arn
}

# -----------------------------------------------------------------------------
# Worker Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "aws_ccm_k8s_worker" {
  name               = "aws_ccm_k8s_worker"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_worker" {
  name = "aws_ccm_k8s_worker"
  role = aws_iam_role.aws_ccm_k8s_worker.name
  tags = var.tags
}

data "aws_iam_policy_document" "aws_ccm_k8s_worker" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetAuthorizationToken",
      "ecr:GetRepositoryPolicy",
      "ecr:ListTagsForResource"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "aws_ccm_k8s_worker" {
  name        = "aws_ccm_k8s_worker"
  description = "Policy for Kubernetes worker nodes to describe EC2 resources and pull images from ECR"
  policy      = data.aws_iam_policy_document.aws_ccm_k8s_worker.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "aws_ccm_k8s_worker" {
  role       = aws_iam_role.aws_ccm_k8s_worker.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_worker.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "controlplane_role_name" {
  description = "Name of the control plane IAM role"
  value       = aws_iam_role.aws_ccm_k8s_controlplane.name
}

output "controlplane_instance_profile_name" {
  description = "Name of the control plane instance profile"
  value       = aws_iam_instance_profile.aws_ccm_k8s_controlplane.name
}

output "worker_role_name" {
  description = "Name of the worker IAM role"
  value       = aws_iam_role.aws_ccm_k8s_worker.name
}

output "worker_instance_profile_name" {
  description = "Name of the worker instance profile"
  value       = aws_iam_instance_profile.aws_ccm_k8s_worker.name
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  description = "Prefix for resource names"
  type        = string
  default     = "awscademo-"
}

variable "tags" {
  description = "Default tags"
  type        = map(string)
  default = {
    Contact          = "cloud-admin@example.com"
    DeploymentMethod = "terraform"
    DeploymentDate   = "2024-01-01"
    TTL              = "infinity"
  }
}

# ------------------------------------------------------------------
# Self-management policy for demo users
# ------------------------------------------------------------------
resource "aws_iam_policy" "demo_self_management" {
  name        = "${var.name}demo-self-management"
  description = "Allow users to manage their own credentials and MFA"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowViewAccountInfo"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:ListAccountAliases"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowManageOwnPasswords"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:UpdatePassword"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnSSHPublicKeys"
        Effect = "Allow"
        Action = [
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:UpdateSSHPublicKey"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid      = "AllowManageOwnVirtualMFADevice"
        Effect   = "Allow"
        Action   = ["iam:CreateVirtualMFADevice"]
        Resource = "arn:aws:iam::*:mfa/*"
      },
      {
        Sid    = "AllowManageOwnMFADevices"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid      = "AllowDeactivateOwnMFAOnlyWhenMFAPresent"
        Effect   = "Allow"
        Action   = ["iam:DeactivateMFADevice"]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "BlockDeactivatingMFADeviceWithoutMFA"
        Effect   = "Deny"
        Action   = ["iam:DeactivateMFADevice"]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })

  tags = var.tags
}

# ------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------
resource "aws_iam_group" "demo_users" {
  name = "${var.name}demo-users"
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.demo_self_management.arn
}

resource "aws_iam_group" "readonly_users" {
  name = "${var.name}readonly-users"
}

resource "aws_iam_group_policy_attachment" "readonly_users_readonly" {
  group      = aws_iam_group.readonly_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name}mfa-superadmin"
}

# ------------------------------------------------------------------
# Admin role assumable by account root
# ------------------------------------------------------------------
data "aws_caller_identity" "current" {}

resource "aws_iam_role" "admin" {
  name                 = substr("${var.name}admin", 0, 31)
  max_session_duration = 43200

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "admin" {
  name = "${var.name}admin-policy"
  role = aws_iam_role.admin.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------
# Allow MFA superadmin group members to assume the admin role
# ------------------------------------------------------------------
resource "aws_iam_group_policy" "mfa_superadmin_assume_role" {
  name  = "${var.name}mfa-superadmin-assume-role"
  group = aws_iam_group.mfa_superadmin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

output "admin_role_arn" {
  value = aws_iam_role.admin.arn
}

output "group_names" {
  value = [
    aws_iam_group.demo_users.name,
    aws_iam_group.readonly_users.name,
    aws_iam_group.mfa_superadmin.name
  ]
}
