```hcl
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type    = string
  default = "acme"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "name" {
  type    = string
  default = "iam"
}

variable "attributes" {
  type    = list(string)
  default = []
}

variable "tags" {
  type = map(string)
  default = {
    Team = "security"
  }
}

variable "admin_users" {
  type    = list(string)
  default = ["alice"]
}

variable "non_admin_users" {
  type    = list(string)
  default = ["bob", "carol"]
}

module "admin_label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admins"])
  tags        = var.tags
}

module "non_admin_label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admins"])
  tags        = var.tags
}

module "admin_role_label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin", "role"])
  tags        = var.tags
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowIndividualUserToManageTheirOwnPassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetAccountPasswordPolicy",
      "iam:GetUser"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowIndividualUserToViewAndManageTheirOwnMFA"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListAccountAliases",
      "iam:ListUsers",
      "iam:ListMFADevices",
      "iam:GetAccountSummary"
    ]
    resources = [
      "arn:aws:iam::*:mfa/$${aws:username}",
      "arn:aws:iam::*:user/$${aws:username}"
    ]
  }

  statement {
    sid       = "AllowIndividualUserToDeactivateTheirOwnMFAOnlyWhenUsingMFA"
    effect    = "Allow"
    actions   = ["iam:DeactivateMFADevice"]
    resources = ["arn:aws:iam::*:mfa/$${aws:username}"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid       = "AllowIndividualUserToListTheirOwnMFA"
    effect    = "Allow"
    actions   = ["iam:ListMFADevices"]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid       = "AllowIndividualUsersToManageTheirOwnAccessKeys"
    effect    = "Allow"
    actions   = ["iam:CreateAccessKey", "iam:DeleteAccessKey", "iam:ListAccessKeys", "iam:UpdateAccessKey"]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid       = "BlockAnyAccessToListAccountMFADevicesExceptWithMFA"
    effect    = "Allow"
    actions   = ["iam:ListVirtualMFADevices", "iam:GetAccountPasswordPolicy"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.non_admin_label.id}-self-management"
  description = "Allow users to self-manage credentials and MFA"
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.non_admin_label.tags
}

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid     = "AllowAssumeAdminRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${module.admin_role_label.id}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${module.admin_label.id}-assume-role"
  description = "Allow admins to assume the admin role with MFA"
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = module.admin_label.tags
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "AllowAccountRootPrincipalToAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = module.admin_role_label.id
  description        = "Admin role requiring MFA"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  tags               = module.admin_role_label.tags
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

resource "aws_iam_user" "admin" {
  count = length(var.admin_users)
  name  = var.admin_users[count.index]
  tags  = module.admin_label.tags
}

resource "aws_iam_user" "non_admin" {
  count = length(var.non_admin_users)
  name  = var.non_admin_users[count.index]
  tags  = module.non_admin_label.tags
}

resource "aws_iam_user_group_membership" "admin" {
  count = length(var.admin_users)
  user  = aws_iam_user.admin[count.index].name
  groups = [
    aws_iam_group.admin.name,
    aws_iam_group.non_admin.name
  ]
}

resource "aws_iam_user_group_membership" "non_admin" {
  count  = length(var.non_admin_users)
  user   = aws_iam_user.non_admin[count.index].name
  groups = [aws_iam_group.non_admin.name]
}

output "admin_group_name" {
  value = aws_iam_group.admin.name
}

output "non_admin_group_name" {
  value = aws_iam_group.non_admin.name
}

output "admin_role_arn" {
  value = aws_iam_role.admin.arn
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones to use"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dev-test-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dev-test-igw"
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "public" {
  count                   = length(var.availability_zones)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "dev-test-public-subnet-${count.index + 1}"
    Tier = "public"
  }
}

# Private subnets (two per AZ)
resource "aws_subnet" "private" {
  count             = length(var.availability_zones) * 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = var.availability_zones[floor(count.index / 2)]

  tags = {
    Name = "dev-test-private-subnet-${count.index + 1}"
    Tier = "private"
  }
}

# Public route table with default route to IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "dev-test-public-rt"
  }
}

# Private route table with no explicit routes
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dev-test-private-rt"
  }
}

# Route table associations
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  gateway_id     = null
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Public security group
resource "aws_security_group" "public" {
  name        = "dev-test-public-sg"
  description = "Public tier security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "dev-test-public-sg"
  }
}

# Private security group
resource "aws_security_group" "private" {
  name        = "dev-test-private-sg"
  description = "Private tier security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "dev-test-private-sg"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "public_security_group_id" {
  description = "ID of the public security group"
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "ID of the private security group"
  value       = aws_security_group.private.id
}
