provider "aws" {
  region = "us-east-1"
}

variable "name_suffix" {
  description = "Suffix appended to all resource names"
  type        = string
  default     = ""
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_iam_role" "prod_ci" {
  name = "prod-ci-role${var.name_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "prod_ci" {
  name = "prod-ci-policy${var.name_suffix}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/prod-ci-role${var.name_suffix}"
      }
    ]
  })
}

resource "aws_iam_group" "prod_ci" {
