# Terraform Template: AWS Config Configuration Aggregator

## Description
This Terraform configuration creates an AWS Config configuration aggregator named "default" that collects configuration and compliance data across all AWS regions for the current AWS account. It uses the `account_aggregation_source` block with `all_regions = true` to aggregate data from every region. Default tags are applied to indicate the stack is managed by Terraform.

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "default_tags" {
  description = "Default tags applied to all resources"
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Stack     = "default"
  }
}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_id  = data.aws_caller_identity.current.account_id
    all_regions = true
  }

  tags = var.default_tags
}

data "aws_caller_identity" "current" {}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "additional_tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "CIDR ranges allowed to SSH into public subnets"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs                = data.aws_availability_zones.available.names
  public_cidrs       = [for i in range(length(local.azs)) : cidrsubnet(var.vpc_cidr, 8, i)]
  private_cidrs      = [for i in range(length(local.azs)) : cidrsubnet(var.vpc_cidr, 8, i + length(local.azs))]
  common_tags        = merge({ VPC = var.vpc_name }, var.additional_tags)
  default_name_tag   = "${var.vpc_name} Default"
}

# ---------------- VPC ----------------
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    local.common_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = merge(
    local.common_tags,
    { Name = local.default_name_tag }
  )
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  tags = merge(
    local.common_tags,
    { Name = local.default_name_tag }
  )
}

# ---------------- Subnets ----------------
resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.this.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.public_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-public-${local.azs[count.index]}" }
  )
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.this.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.private_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-private-${local.azs[count.index]}" }
  )
}

# ---------------- IGW / NAT ----------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-igw" }
  )
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-nat-eip" }
  )
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-nat" }
  )

  depends_on = [aws_internet_gateway.this]
}

# ---------------- Route Tables ----------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-public-rt" }
  )
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-private-rt" }
  )
}

resource "aws_route_table_association" "private" {
  count = length(local.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Security group for public tier"
  vpc_id      = aws_vpc.this.id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-public-sg" }
  )
}

resource "aws_vpc_security_group_ingress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_ingress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh" {
  count = length(var.ssh_inbound)

  security_group_id = aws_security_group.public.id
  cidr_ipv4         = var.ssh_inbound[count.index]
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "public_http_vpc" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_egress_rule" "public_https_vpc" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Security group for private tier"
  vpc_id      = aws_vpc.this.id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-private-sg" }
  )
}

resource "aws_vpc_security_group_ingress_rule" "private_http_from_public" {
  count = length(local.public_cidrs)

  security_group_id            = aws_security_group.private.id
  referenced_security_group_id = aws_security_group.public.id
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80
}

resource "aws_vpc_security_group_ingress_rule" "private_https_from_public" {
  count = length(local.public_cidrs)

  security_group_id            = aws_security_group.private.id
  referenced_security_group_id = aws_security_group.public.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

resource "aws_vpc_security_group_egress_rule" "private_https_vpc" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

# ---------------- Network ACLs ----------------
resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-public-nacl" }
  )
}

# Public NACL ingress
resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 110
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 120
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count = length(var.ssh_inbound)

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + (count.index + 1) * 10
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

# Public NACL egress
resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  egress         = true
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  egress         = true
  rule_number    = 110
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
