  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    { Name = "${var.vpc_name}-private-nacl" }
  )
}

# Private NACL ingress
resource "aws_network_acl_rule" "private_ingress_http_from_public" {
  count = length(local.public_cidrs)

  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index * 10
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = local.public_cidrs[count.index]
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https_from_public" {
  count = length(local.public_cidrs)

  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index * 10
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = local.public_cidrs[count.index]
