data "aws_iam_policy" "imagebuilder_full_access" {
  arn = "arn:aws:iam::aws:policy/AWSImageBuilderFullAccess"
}

resource "aws_iam_role" "imagebuilder" {
  name        = "imagebuilder_role"
  path        = "/"
  description = "IAM role for EC2 Image Builder automation"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = data.aws_iam_policy.imagebuilder_full_access.arn
