# Description
This Terraform template provisions an IAM role named "tamr-instance-role" with an EC2 trust policy, an optional permissions boundary, and an IAM instance profile named "tamr-instance-profile". Resource tags are customizable via a map variable.

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for the Tamr EC2 instance"
  type        = string
  default     = "tamr-instance-role"
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile"
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary" {
  description = "ARN of the permissions boundary to apply to the role (optional)"
  type        = string
  default     = null
}

variable "tags" {
  description = "Map of resource tags"
  type        = map(string)
  default = {
    Environment = "production"
    Application = "tamr"
    ManagedBy   = "terraform"
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance_role" {
  name                 = var.role_name
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  permissions_boundary = var.permissions_boundary
  tags                 = var.tags
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.instance_profile_name
  role = aws_iam_role.tamr_instance_role.name
  tags = var.tags
}

output "role_arn" {
  description = "ARN of the Tamr instance role"
  value       = aws_iam_role.tamr_instance_role.arn
}

output "instance_profile_arn" {
  description = "ARN of the Tamr instance profile"
  value       = aws_iam_instance_profile.tamr_instance_profile.arn
}

output "instance_profile_name" {
  description = "Name of the instance profile to attach to EC2"
  value       = aws_iam_instance_profile.tamr_instance_profile.name
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
