terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  description = "Environment-specific resource name prefix"
  type        = string
  default     = "dev"
}

variable "target_account_id" {
  description = "ID of the target account containing the software installation files role"
  type        = string
  default     = "123456789012"
}

variable "target_role_name" {
  description = "Name of the role in the target account to assume"
  type        = string
  default     = "software-install-files-reader"
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "packer_builder" {
  name               = "${var.environment_prefix}-packer-builder-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

data "aws_iam_policy_document" "packer_builder_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole",
    ]
    resources = ["arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"]
  }
}

resource "aws_iam_role_policy" "packer_builder" {
  name   = "${var.environment_prefix}-packer-builder-policy"
  role   = aws_iam_role.packer_builder.id
  policy = data.aws_iam_policy_document.packer_builder_policy.json
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${var.environment_prefix}-packer-builder-profile"
  role = aws_iam_role.packer_builder.name
}

output "instance_profile_name" {
  value = aws_iam_instance_profile.packer_builder.name
}

output "role_arn" {
  value = aws_iam_role.packer_builder.arn
}
