terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "three-tier-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "presentation" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.0.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.1.0/24"

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.2.0/24"

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "presentation-route-table"
  }
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "subnet_ids" {
  value = {
    presentation = aws_subnet.presentation.id
    application  = aws_subnet.application.id
    data         = aws_subnet.data.id
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "user_name" {
  description = "Name of the IAM user"
  type        = string
  default     = "sc_test_user"
}

variable "group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "sc_test_group"
}

variable "role_name" {
  description = "Name of the service-catalog-assumable role"
  type        = string
  default     = "test_role"
}

# Trust policy allowing the account to assume the role (Service Catalog launch constraint)
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "test_role_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.test_role_trust.json
}

# Scoped launch-constraint policy for Service Catalog testing
data "aws_iam_policy_document" "launch_constraint" {
  statement {
    effect = "Allow"
    actions = [
      "servicecatalog:*",
      "cloudformation:CreateStack",
      "cloudformation:UpdateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DescribeStackEvents",
      "cloudformation:ValidateTemplate",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "sc_launch_constraint_policy"
  description = "Scoped policy for Service Catalog launch constraint testing"
  policy      = data.aws_iam_policy_document.launch_constraint.json
}

resource "aws_iam_role_policy_attachment" "test_role_attach" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# IAM group
resource "aws_iam_group" "test_group" {
  name = var.group_name
}

# IAM user with console access
resource "aws_iam_user" "test_user" {
  name          = var.user_name
  force_destroy = true
}

resource "aws_iam_user_login_profile" "test_user_login" {
  user    = aws_iam_user.test_user.name
  pgp_key = "keybase:terraform_test" # replace with your PGP key or set password_reset_required
}

resource "aws_iam_group_membership" "test_membership" {
  name  = "sc_test_membership"
  users = [aws_iam_user.test_user.name]
  group = aws_iam_group.test_group.name
}

output "role_arn" {
  description = "ARN of the service-catalog-assumable role"
  value       = aws_iam_role.test_role.arn
}

output "user_name" {
  description = "Name of the created IAM user"
  value       = aws_iam_user.test_user.name
}

output "group_name" {
  description = "Name of the created IAM group"
  value       = aws_iam_group.test_group.name
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones to use (max 3)"
  type        = number
  default     = 3
}

variable "enable_ssm_endpoints" {
  description = "Whether to create SSM interface VPC endpoints"
  type        = bool
  default     = false
}

locals {
  default_tags = {
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner"
  })
}

resource "aws_subnet" "public" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.this.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-public-${local.azs[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count             = var.az_count
  vpc_id            = aws_vpc.this.id
  availability_zone = local.azs[count.index]
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 100)

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-private-${local.azs[count.index]}"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-nat-eip"
  })
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = var.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = var.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# S3 Gateway VPC Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-s3-endpoint"
  })
}

data "aws_region" "current" {}

# Security group for interface endpoints
resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "datadog-scanner-vpce-"
  description = "Allow inbound HTTPS from VPC CIDR for interface VPC endpoints"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-vpce-sg"
  })
}

# Interface VPC endpoints for Lambda and EBS
resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-lambda-endpoint"
  })
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-ebs-endpoint"
  })
}

# Optional SSM interface VPC endpoints
resource "aws_vpc_endpoint" "ssm" {
  count               = var.enable_ssm_endpoints ? 1 : 0
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-ssm-endpoint"
  })
}

resource "aws_vpc_endpoint" "ssmmessages" {
  count               = var.enable_ssm_endpoints ? 1 : 0
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-ssmmessages-endpoint"
  })
}

resource "aws_vpc_endpoint" "ec2messages" {
  count               = var.enable_ssm_endpoints ? 1 : 0
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.default_tags, {
    Name = "DatatogAgentlessScanner-ec2messages-endpoint"
  })
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "create_enabled" {
  description = "Main toggle to enable/disable creation of all resources"
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "Toggle between creating a new security group (true) or attaching rules to an existing one (false)"
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to (used when create_new_security_group is false)"
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID for the new security group. If empty, a fallback VPC (10.0.0.0/16) is provisioned"
  type        = string
  default     = ""
}

variable "name" {
  description = "Base name for resources"
  type        = string
  default     = "app-workload"
}

variable "environment" {
  description = "Environment label"
  type        = string
  default     = "dev"
}

variable "application" {
  description = "Application label"
  type        = string
  default     = "core"
}

variable "security_group_description" {
  description = "Description for the new security group"
  type        = string
  default     = "Managed security group for application workloads"
}

variable "create_prefix_list" {
  description = "Whether to create a managed prefix list (only if no existing prefix list IDs supplied)"
  type        = bool
  default     = true
}

variable "existing_prefix_list_ids" {
  description = "Pre-existing prefix list IDs to use instead of creating one"
  type        = list(string)
  default     = []
}

variable "prefix_list_max_entries" {
  description = "Maximum entries in the managed prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list"
  type = list(object({
    cidr        = string
    description = string
  }))
  default = [
    {
      cidr        = "10.0.0.0/8"
      description = "Internal network"
    }
  ]
}

variable "ingress_cidr_rules" {
  description = "Ingress rules based on CIDR blocks"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = string
  }))
  default = [
    {
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
      description = "HTTPS from anywhere"
    }
  ]
}

variable "ingress_self_rules" {
  description = "Ingress rules referencing the security group itself"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = []
}

variable "ingress_sg_rules" {
  description = "Ingress rules based on source security group IDs"
  type = list(object({
    from_port             = number
    to_port               = number
    protocol              = string
    source_security_group_id = string
    description           = string
  }))
  default = []
}

variable "ingress_prefix_list_rules" {
  description = "Ingress rules based on prefix lists (defaults to newly created prefix list when prefix_list_id is empty)"
  type = list(object({
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = string
    description    = string
  }))
  default = []
}

variable "egress_cidr_rules" {
  description = "Egress rules based on CIDR blocks"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = string
  }))
  default = [
    {
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = ["0.0.0.0/0"]
      description = "Allow all egress"
    }
  ]
}

variable "egress_self_rules" {
  description = "Egress rules referencing the security group itself"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = []
}

variable "egress_sg_rules" {
  description = "Egress rules based on destination security group IDs"
  type = list(object({
    from_port             = number
    to_port               = number
    protocol              = string
    source_security_group_id = string
    description           = string
  }))
  default = []
}

variable "egress_prefix_list_rules" {
  description = "Egress rules based on prefix lists (defaults to newly created prefix list when prefix_list_id is empty)"
  type = list(object({
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = string
    description    = string
  }))
  default = []
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  enabled = var.create_enabled

  # Fallback VPC needed when creating a new SG and no VPC ID supplied
  create_fallback_vpc = local.enabled && var.create_new_security_group && var.vpc_id == ""

  vpc_id = local.create_fallback_vpc ? aws_vpc.fallback[0].id : var.vpc_id

  create_prefix_list = local.enabled && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0

  prefix_list_ids = local.create_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : var.existing_prefix_list_ids

  # Label module configuration
  sg_labels = {
    name        = "${var.name}-sg"
    environment = var.environment
    application = var.application
  }

  pl_labels = {
    name        = "${var.name}-prefix-list"
    environment = var.environment
    application = var.application
  }
}

# -----------------------------------------------------------------------------
# Label module
# -----------------------------------------------------------------------------

module "sg_label" {
  source  = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  labels  = local.sg_labels
}

module "pl_label" {
  source  = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  labels  = local.pl_labels
}

# -----------------------------------------------------------------------------
# Fallback VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "fallback" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    module.sg_label.tags,
    {
      Name = "${module.sg_label.id}-vpc"
    }
  )
}

# -----------------------------------------------------------------------------
# Managed Prefix List
# -----------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = module.pl_label.id
  description    = "Managed prefix list for ${var.name}"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = module.pl_label.tags
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------

resource "aws_security_group" "this" {
  count = local.enabled && var.create_new_security_group ? 1 : 0

  name        = module.sg_label.id
  description = var.security_group_description
  vpc_id      = local.vpc_id

  tags = module.sg_label.tags
}

locals {
  security_group_id = var.create_new_security_group ? aws_security_group.this[0].id : var.existing_security_group_id
}

# -----------------------------------------------------------------------------
# Ingress Rules
# -----------------------------------------------------------------------------

resource "aws_vpc_security_group_ingress_rule" "cidr" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.ingress_cidr_rules : "cidr-${idx}" => r } : {}

  security_group_id = local.security_group_id
  cidr_ipv4         = each.value.cidr_blocks[0]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
}

resource "aws_vpc_security_group_ingress_rule" "self" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.ingress_self_rules : "self-${idx}" => r } : {}

  security_group_id = local.security_group_id
  referenced_security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
}

resource "aws_vpc_security_group_ingress_rule" "sg" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.ingress_sg_rules : "sg-${idx}" => r } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.source_security_group_id
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.protocol
  description                  = each.value.description
}

resource "aws_vpc_security_group_ingress_rule" "prefix_list" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.ingress_prefix_list_rules : "pl-${idx}" => r } : {}

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != "" ? each.value.prefix_list_id : local.prefix_list_ids[0]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
}

# -----------------------------------------------------------------------------
# Egress Rules
# -----------------------------------------------------------------------------

resource "aws_vpc_security_group_egress_rule" "cidr" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.egress_cidr_rules : "cidr-${idx}" => r } : {}

  security_group_id = local.security_group_id
  cidr_ipv4         = each.value.cidr_blocks[0]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
}

resource "aws_vpc_security_group_egress_rule" "self" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.egress_self_rules : "self-${idx}" => r } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = local.security_group_id
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.protocol
  description                  = each.value.description
}

resource "aws_vpc_security_group_egress_rule" "sg" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.egress_sg_rules : "sg-${idx}" => r } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.source_security_group_id
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.protocol
  description                  = each.value.description
}

resource "aws_vpc_security_group_egress_rule" "prefix_list" {
  for_each = local.enabled && local.security_group_id != "" ? { for idx, r in var.egress_prefix_list_rules : "pl-${idx}" => r } : {}

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != "" ? each.value.prefix_list_id : local.prefix_list_ids[0]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  description       = each.value.description
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "security_group_id" {
  description = "ID of the managed security group"
  value       = local.enabled ? local.security_group_id : ""
}

output "prefix_list_ids" {
  description = "IDs of prefix lists in use"
  value       = local.enabled ? local.prefix_list_ids : []
}

output "vpc_id" {
  description = "VPC ID hosting the security group"
  value       = local.enabled && var.create_new_security_group ? local.vpc_id : ""
}
