terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  description = "Name of the CloudForecast IAM role"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID required for cross-account assume-role"
  type        = string
  default     = "benchmark-external-id"
}

data "aws_iam_policy_document" "trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::656227328603:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

resource "aws_iam_role" "cloudforecast" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.trust.json
}

resource "aws_iam_role_policy" "metrics_tags" {
  name = "CloudForecastMetricsTags"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["cloudwatch:GetMetricStatistics", "tag:GetResources"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "organizations" {
  name = "CloudForecastOrganizations"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["organizations:ListAccounts"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "elb" {
  name = "CloudForecastELB"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "elasticloadbalancing:DescribeLoadBalancers",
        "elasticloadbalancing:DescribeLoadBalancerAttributes",
        "elasticloadbalancing:DescribeTags",
        "elasticloadbalancing:DescribeListeners",
        "elasticloadbalancing:DescribeTargetGroups",
        "elasticloadbalancing:DescribeTargetHealth"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "ebs" {
  name = "CloudForecastEBS"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "ec2:DescribeSnapshots",
        "ec2:DescribeVolumes"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "ec2" {
  name = "CloudForecastEC2"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "ec2:DescribeInstances",
        "ec2:DescribeInstanceStatus",
        "ec2:DescribeInstanceAttribute",
        "ec2:DescribeTags"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "rds" {
  name = "CloudForecastRDS"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "rds:DescribeDBInstances",
        "rds:DescribeDBSnapshots",
        "rds:ListTagsForResource"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "s3" {
  name = "CloudForecastS3"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:ListAllMyBuckets",
        "s3:ListBucket",
        "s3:GetBucketLocation",
        "s3:GetBucketTagging",
        "s3:GetLifecycleConfiguration"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "logs" {
  name = "CloudForecastLogs"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["logs:DescribeLogGroups"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "support" {
  name = "CloudForecastSupport"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "support:DescribeTrustedAdvisorChecks",
        "support:DescribeTrustedAdvisorCheckSummaries",
        "support:DescribeTrustedAdvisorCheckResult"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "elb_classic" {
  name = "CloudForecastELBClassic"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["elasticloadbalancing:DescribeLoadBalancerPolicies"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "ebs_attributes" {
  name = "CloudForecastEBSAttributes"
