      Action   = ["ec2:DescribeSnapshotAttribute"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "ec2_images" {
  name = "CloudForecastEC2Images"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "ec2:DescribeImages",
        "ec2:DescribeRegions"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "rds_metrics" {
  name = "CloudForecastRDSMetrics"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["rds:DescribeDBEngineVersions"]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy" "s3_inventory" {
  name = "CloudForecastS3Inventory"
  role = aws_iam_role.cloudforecast.id
  policy = jsonencode({
    Version = "2012-10-17"
