}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment suffix for the cost reporting user"
  type        = string
  default     = "dev"
}

variable "enable_database_disaster_recovery_user" {
  description = "Whether to create the database disaster recovery IAM user"
  type        = bool
  default     = false
}

variable "enable_data_exports_user" {
  description = "Whether to create the data exports IAM user"
  type        = bool
  default     = false
}

variable "enable_packer_user" {
  description = "Whether to create the Packer image builder IAM user"
  type        = bool
  default     = false
}

variable "data_exports_bucket_arn" {
  description = "ARN of the S3 bucket used for data exports"
  type        = string
  default     = "arn:aws:s3:::mattermost-data-exports-dev"
}

variable "packer_state_bucket" {
  description = "Name of the S3 bucket used by Packer for monitoring state"
  type        = string
  default     = "mattermost-packer-state-dev"
}

variable "server_role_name" {
  description = "Name of the server IAM role that Packer may pass"
  type        = string
  default     = "mattermost-server-role"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function Packer may configure"
  type        = string
  default     = "bind-server-network-attachment"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Mandatory: Cost reporting user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment}"
}

resource "aws_iam_user_policy" "cost_report" {
  name = "mattermost-cost-report-policy-${var.environment}"
  user = aws_iam_user.cost_report.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional: Database disaster recovery user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "db_dr" {
  count = var.enable_database_disaster_recovery_user ? 1 : 0
  name  = "mattermost-db-disaster-recovery-${var.environment}"
}

resource "aws_iam_user_policy" "db_dr" {
  count = var.enable_database_disaster_recovery_user ? 1 : 0
  name  = "mattermost-db-dr-policy-${var.environment}"
  user  = aws_iam_user.db_dr[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:*"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional: Data exports user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment}"
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-policy-${var.environment}"
  user  = aws_iam_user.data_exports[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = var.data_exports_bucket_arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${var.data_exports_bucket_arn}/*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional: Packer image builder user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-${var.environment}"
}

resource "aws_iam_user_policy" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-policy-${var.environment}"
  user  = aws_iam_user.packer[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Permissions"
        Effect = "Allow"
        Action = [
          "ec2:AttachVolume",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CopyImage",
          "ec2:CreateImage",
          "ec2:CreateKeyPair",
          "ec2:CreateSecurityGroup",
          "ec2:CreateSnapshot",
          "ec2:CreateTags",
          "ec2:CreateVolume",
          "ec2:DeleteKeyPair",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteSnapshot",
          "ec2:DeleteVolume",
          "ec2:DeregisterImage",
          "ec2:DescribeImageAttribute",
          "ec2:DescribeImages",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeRegions",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSnapshots",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVpcs",
          "ec2:DetachVolume",
          "ec2:ModifyImageAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:ModifySnapshotAttribute",
          "ec2:RegisterImage",
          "ec2:RunInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Resource = "*"
      },
      {
        Sid    = "AutoScalingPermissions"
        Effect = "Allow"
        Action = [
          "autoscaling:CreateLaunchConfiguration",
          "autoscaling:DeleteLaunchConfiguration",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeScalingActivities"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchEventsPermissions"
        Effect = "Allow"
        Action = [
          "events:PutRule",
          "events:PutTargets",
          "events:DeleteRule",
          "events:DescribeRule",
          "events:ListTargetsByRule",
          "events:RemoveTargets"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMPermissions"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "ssm:PutParameter",
          "ssm:DeleteParameter",
          "ssm:DescribeParameters"
        ]
        Resource = "*"
      },
      {
        Sid    = "IAMInspectionPermissions"
        Effect = "Allow"
        Action = [
          "iam:GetInstanceProfile",
          "iam:GetRole",
          "iam:GetRolePolicy",
          "iam:ListInstanceProfilesForRole",
          "iam:ListRolePolicies",
          "iam:PassRole"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.server_role_name}"
      },
      {
        Sid    = "S3StateBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "arn:aws:s3:::${var.packer_state_bucket}",
          "arn:aws:s3:::${var.packer_state_bucket}/*"
        ]
      },
      {
        Sid    = "LambdaConfigurationPermissions"
        Effect = "Allow"
        Action = [
          "lambda:GetFunctionConfiguration",
          "lambda:UpdateFunctionConfiguration"
        ]
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:${var.lambda_function_name}"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "cost_report_user_name" {
  value = aws_iam_user.cost_report.name
}

output "db_dr_user_name" {
  value = var.enable_database_disaster_recovery_user ? aws_iam_user.db_dr[0].name : null
}

output "data_exports_user_name" {
  value = var.enable_data_exports_user ? aws_iam_user.data_exports[0].name : null
}

output "packer_user_name" {
  value = var.enable_packer_user ? aws_iam_user.packer[0].name : null
}

provider "aws" {
  region = "us-east-1"
}

variable "ecr_repository_names" {
  description = "Names of ECR repositories for HealthOmics container images"
  type        = list(string)
  default     = ["omics-workflow-container"]
}

variable "external_aws_account_ids" {
  description = "External AWS account IDs to grant cross-account ECR pull access"
  type        = list(string)
  default     = []
}

variable "additional_s3_buckets" {
  description = "Additional S3 bucket ARNs to grant the user read-only access"
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------- KMS ----------------
resource "aws_kms_key" "omics" {
  description             = "KMS key for HealthOmics output bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "omics" {
  name          = "alias/healthomics-output"
  target_key_id = aws_kms_key.omics.key_id
}

# ---------------- S3 output bucket ----------------
resource "aws_s3_bucket" "output" {
  bucket = "tf-benchmark-omics-output-bucket"
}

resource "aws_s3_bucket_public_access_block" "output" {
  bucket                  = aws_s3_bucket.output.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output" {
  bucket = aws_s3_bucket.output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.omics.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "output" {
  bucket = aws_s3_bucket.output.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------- ECR repositories ----------------
resource "aws_ecr_repository" "omics" {
  count = length(var.ecr_repository_names)
  name  = var.ecr_repository_names[count.index]

  image_scanning_configuration {
    scan_on_push = true
  }
}

data "aws_iam_policy_document" "ecr_pull" {
  count = length(var.ecr_repository_names)

  statement {
    sid     = "HealthOmicsPull"
    effect  = "Allow"
    actions = ["ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage", "ecr:BatchCheckLayerAvailability"]

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
  }

  dynamic "statement" {
    for_each = length(var.external_aws_account_ids) > 0 ? [1] : []
    content {
      sid     = "CrossAccountPull"
      effect  = "Allow"
      actions = ["ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage", "ecr:BatchCheckLayerAvailability"]

      principals {
        type        = "AWS"
        identifiers = [for id in var.external_aws_account_ids : "arn:${data.aws_partition.current.partition}:iam::${id}:root"]
      }
    }
  }
}

resource "aws_ecr_repository_policy" "omics" {
  count      = length(var.ecr_repository_names)
  repository = aws_ecr_repository.omics[count.index].name
  policy     = data.aws_iam_policy_document.ecr_pull[count.index].json
}

# ---------------- IAM role for HealthOmics ----------------
resource "aws_iam_role" "omics" {
  name = "HealthOmicsRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "omics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "service" {
  statement {
    sid       = "OmicsActions"
    effect    = "Allow"
    actions   = ["omics:*"]
    resources = ["*"]
  }

  statement {
    sid       = "PassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringEqualsIfExists"
      variable = "iam:PassedToService"
      values   = ["omics.amazonaws.com"]
    }
  }

  statement {
    sid    = "OutputBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.output.arn,
      "${aws_s3_bucket.output.arn}/*"
    ]
  }

  statement {
    sid       = "KmsAccess"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = [aws_kms_key.omics.arn]
  }

  statement {
    sid       = "EcrAccess"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability", "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "service" {
  name   = "HealthOmicsServicePolicy"
  role   = aws_iam_role.omics.id
  policy = data.aws_iam_policy_document.service.json
}

# ---------------- IAM user ----------------
resource "aws_iam_user" "workbench" {
  name = "workbench-health-omics"
}

resource "aws_iam_access_key" "workbench" {
  user = aws_iam_user.workbench.name
}

data "aws_iam_policy_document" "user" {
  statement {
    sid       = "OmicsActions"
    effect    = "Allow"
    actions   = ["omics:*"]
    resources = ["*"]
  }

  statement {
    sid       = "PassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringEqualsIfExists"
      variable = "iam:PassedToService"
      values   = ["omics.amazonaws.com"]
    }
  }

  statement {
    sid    = "OutputBucketReadOnly"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.output.arn,
      "${aws_s3_bucket.output.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = length(var.additional_s3_buckets) > 0 ? [1] : []
    content {
      sid    = "AdditionalBucketsReadOnly"
      effect = "Allow"
      actions = [
        "s3:GetObject",
        "s3:GetObjectVersion",
        "s3:ListBucket",
        "s3:GetBucketLocation"
      ]
      resources = var.additional_s3_buckets
    }
  }

  statement {
    sid       = "EcrAccess"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability", "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage", "ecr:DescribeRepositories", "ecr:ListImages"]
    resources = ["*"]
  }
}

resource "aws_iam_user_policy" "user" {
  name   = "HealthOmicsUserPolicy"
  user   = aws_iam_user.workbench.name
  policy = data.aws_iam_policy_document.user.json
}

output "output_bucket_name" {
  value = aws_s3_bucket.output.bucket
}

output "healthomics_role_arn" {
  value = aws_iam_role.omics.arn
}

output "ecr_repository_urls" {
  value = aws_ecr_repository.omics[*].repository_url
}

output "workbench_user_access_key_id" {
  value = aws_iam_access_key.workbench.id
}

output "workbench_user_secret_access_key" {
  value     = aws_iam_access_key.workbench.secret
  sensitive = true
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type    = string
  default = "10.0"
}

variable "default_tags" {
  type    = map(string)
  default = {}
}

locals {
  cluster_full_name = "dit-paas-${var.cluster_name}-cluster"
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = local.cluster_full_name

  tags = merge(
    var.default_tags,
    {
      Name = local.cluster_full_name
    }
  )
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-vpc"
    }
  )
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-ig"
    }
  )
}

# Public subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = element(["a", "b", "c"], count.index)
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 6, count.index + 3)
  map_public_ip_on_launch = true

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-public-${element(["a", "b", "c"], count.index)}"
    }
  )
}

# Private subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  availability_zone = element(["a", "b", "c"], count.index)
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 6, count.index)

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-private-${element(["a", "b", "c"], count.index)}"
    }
  )
}

# Shared public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs and NAT Gateways
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-nat-eip-${element(["a", "b", "c"], count.index)}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-nat-${element(["a", "b", "c"], count.index)}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# Dedicated private route tables
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(
    var.default_tags,
    {
      Name = "${var.cluster_name}-private-rt-${element(["a", "b", "c"], count.index)}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}
