terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  type        = string
  default     = "benchmark-vpc"
  description = "Name of the VPC"
}

variable "vpc_ipv4_primary_cidr_block" {
  type        = string
  default     = "172.16.0.0/16"
  description = "Primary IPv4 CIDR block for the VPC"
}

variable "availability_zones" {
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
  description = "Availability zones for subnet provisioning"
}

variable "region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region"
}

module "vpc" {
  source  = "cloudposse/vpc/aws"
  version = "2.1.0"

  namespace  = "benchmark"
  stage      = "prod"
  name       = var.vpc_name
  attributes = ["vpc"]

  ipv4_primary_cidr_block = var.vpc_ipv4_primary_cidr_block
  assign_generated_ipv6_cidr_block = false

  enable_dns_hostnames = true
  enable_dns_support   = true

  default_security_group_deny_all = true

  tags = {
    Name = var.vpc_name
  }
}

module "subnets" {
  source  = "cloudposse/dynamic-subnets/aws"
  version = "2.4.0"

  namespace  = "benchmark"
  stage      = "prod"
  name       = var.vpc_name
  attributes = ["subnets"]

  vpc_id                  = module.vpc.vpc_id
  igw_id                  = [module.vpc.igw_id]
  ipv4_cidr_block         = [var.vpc_ipv4_primary_cidr_block]
  availability_zones      = var.availability_zones
  nat_gateway_enabled     = true
  nat_elastic_ips         = true
  max_nats                = length(var.availability_zones)
  public_subnets_enabled  = true
  private_subnets_enabled = true

  tags = {
    Name = "${var.vpc_name}-subnets"
  }
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC interface endpoints - self-referencing HTTPS only"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Self-referencing TCP 443 ingress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Self-referencing TCP 443 egress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  tags = {
    Name = "vpc_endpoint_sg"
  }
}

module "vpc_endpoints" {
  source  = "cloudposse/vpc-endpoints/aws"
  version = "1.0.1"

  namespace = "benchmark"
  stage     = "prod"
  name      = var.vpc_name

  vpc_id             = module.vpc.vpc_id
  subnet_ids         = module.subnets.private_subnet_ids
  security_group_ids = [aws_security_group.vpc_endpoint_sg.id]
  ip_address_type    = "ipv4"
  private_dns_enabled = true

  endpoints = {
    ecr-docker = {
      service             = "ecr.dkr"
      service_type        = "Interface"
      tags                = { Name = "ecr-dkr-endpoint" }
      private_dns_enabled = true
    },
    ecr-api = {
      service             = "ecr.api"
      service_type        = "Interface"
      tags                = { Name = "ecr-api-endpoint" }
      private_dns_enabled = true
    },
    cloudwatch-logs = {
      service             = "logs"
      service_type        = "Interface"
      tags                = { Name = "cloudwatch-logs-endpoint" }
      private_dns_enabled = true
    },
    ssm = {
      service             = "ssm"
      service_type        = "Interface"
      tags                = { Name = "ssm-endpoint" }
      private_dns_enabled = true
    },
    kms = {
      service             = "kms"
      service_type        = "Interface"
      tags                = { Name = "kms-endpoint" }
      private_dns_enabled = true
    }
  }

  tags = {
    Name = "${var.vpc_name}-interface-endpoints"
  }
}

module "s3_vpc_endpoint" {
  source  = "cloudposse/vpc-endpoints-s3/aws"
  version = "1.0.0"

  namespace = "benchmark"
  stage     = "prod"
  name      = var.vpc_name

  vpc_id     = module.vpc.vpc_id
  region     = var.region
  route_table_ids = concat(
    [module.vpc.vpc_default_route_table_id],
    module.subnets.public_route_table_ids,
    module.subnets.private_route_table_ids
  )

  tags = {
    Name = "${var.vpc_name}-s3-gateway-endpoint"
  }
}

output "vpc_id" {
  value = module.vpc.vpc_id
}

output "private_subnet_ids" {
  value = module.subnets.private_subnet_ids
}

output "public_subnet_ids" {
  value = module.subnets.public_subnet_ids
}

output "vpc_endpoint_sg_id" {
  value = aws_security_group.vpc_endpoint_sg.id
}

output "s3_endpoint_id" {
  value = module.s3_vpc_endpoint.endpoint_id
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  type    = string
  default = "benchmark-vpc"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "instance_tenancy" {
  type    = string
  default = "default"
}

variable "enable_dns_hostnames" {
  type    = bool
  default = true
}

variable "flow_logs_traffic_type" {
  type    = string
  default = "ALL"
}

variable "flow_logs_retention_days" {
  type    = number
  default = 180
}

variable "route_table_ids" {
  description = "Route table IDs for gateway endpoints"
  type        = list(string)
  default     = []
}

variable "aws_interface_services" {
  description = "Standard AWS services for interface endpoints (private DNS enabled)"
  type        = set(string)
  default     = ["logs"]
}

variable "custom_endpoint_services" {
  description = "Custom endpoint services: key -> {service_name, port, source_security_group_id}"
  type = map(object({
    service_name            = string
    port                    = number
    source_security_group_id = string
  }))
  default = {}
}

variable "endpoint_source_security_group_ids" {
  description = "Source security group IDs for standard AWS interface endpoint SG rules"
  type        = list(string)
  default     = []
}

locals {
  flow_logs_role_name = "vpc_flow_logs_${var.vpc_name}"
  log_group_name      = "/aws/vpc-flow-logs/${var.vpc_name}"
}

# ---------------- VPC ----------------
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = true

  tags = { Name = var.vpc_name }
}

# ---------------- Flow Logs ----------------
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.log_group_name
  retention_in_days = var.flow_logs_retention_days
}

data "aws_iam_policy_document" "flow_logs_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = local.flow_logs_role_name
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume.json
}

data "aws_iam_policy_document" "flow_logs_policy" {
  statement {
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]
    resources = ["${aws_cloudwatch_log_group.flow_logs.arn}:*"]
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name   = "${local.flow_logs_role_name}_policy"
  role   = aws_iam_role.flow_logs.id
  policy = data.aws_iam_policy_document.flow_logs_policy.json
}

resource "aws_flow_log" "this" {
  vpc_id               = aws_vpc.this.id
  traffic_type         = var.flow_logs_traffic_type
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn
}

# ---------------- Default SG management ----------------
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = { Name = "default-${var.vpc_name}" }
}

# ---------------- Security groups ----------------
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for standard AWS interface endpoints"
  vpc_id      = aws_vpc.this.id

  dynamic "ingress" {
    for_each = var.endpoint_source_security_group_ids
    content {
      description     = "HTTPS from source SG"
      protocol        = "tcp"
      from_port       = 443
      to_port         = 443
      security_groups = [ingress.value]
    }
  }

  dynamic "egress" {
    for_each = var.endpoint_source_security_group_ids
    content {
      description     = "HTTPS to source SG"
      protocol        = "tcp"
      from_port       = 443
      to_port         = 443
      security_groups = [egress.value]
    }
  }

  tags = { Name = "vpc-endpoints-${var.vpc_name}" }
}

resource "aws_security_group" "custom_endpoints" {
  name        = "custom-endpoints-${var.vpc_name}"
  description = "Security group for custom endpoint services"
  vpc_id      = aws_vpc.this.id

  dynamic "ingress" {
    for_each = var.custom_endpoint_services
    content {
      description     = "Ingress for ${ingress.key}"
      protocol        = "tcp"
      from_port       = ingress.value.port
      to_port         = ingress.value.port
      security_groups = [ingress.value.source_security_group_id]
    }
  }

  dynamic "egress" {
    for_each = var.custom_endpoint_services
    content {
      description     = "Egress for ${egress.key}"
      protocol        = "tcp"
      from_port       = egress.value.port
      to_port         = egress.value.port
      security_groups = [egress.value.source_security_group_id]
    }
  }

  tags = { Name = "custom-endpoints-${var.vpc_name}" }
}

# ---------------- VPC Endpoints ----------------
resource "aws_vpc_endpoint" "gateway" {
  for_each = toset(["dynamodb", "s3"])

  vpc_id          = aws_vpc.this.id
  service_name    = "com.amazonaws.us-east-1.${each.key}"
  route_table_ids = var.route_table_ids
  vpc_endpoint_type = "Gateway"

  tags = { Name = "${each.key}-gateway-${var.vpc_name}" }
}

resource "aws_vpc_endpoint" "aws_interface" {
  for_each = var.aws_interface_services

  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.us-east-1.${each.key}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = { Name = "${each.key}-interface-${var.vpc_name}" }
}

resource "aws_vpc_endpoint" "custom_interface" {
  for_each = var.custom_endpoint_services

  vpc_id              = aws_vpc.this.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  security_group_ids  = [aws_security_group.custom_endpoints.id]

  tags = { Name = "${each.key}-custom-${var.vpc_name}" }
}

# ---------------- SSM role (conditional) ----------------
data "aws_iam_policy_document" "ssm_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm" {
  count  = contains(toset(var.aws_interface_services), "ssm") ? 1 : 0
  name   = "ssm_${var.vpc_name}"
  assume_role_policy = data.aws_iam_policy_document.ssm_assume.json
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count      = contains(toset(var.aws_interface_services), "ssm") ? 1 : 0
  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = contains(toset(var.aws_interface_services), "ssm") ? 1 : 0
  name  = "ssm_${var.vpc_name}"
  role  = aws_iam_role.ssm[0].name
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for KMS key aliases"
  type        = string
  default     = "baseline"
}

variable "key_rotation_days" {
  description = "KMS key rotation period in days"
  type        = number
  default     = 90
}

variable "deletion_window_days" {
  description = "KMS key deletion window in days"
  type        = number
  default     = 30
}

variable "external_default_ebs_key_arn" {
  description = "Optional external KMS key ARN for default EBS encryption. If blank, the internal compute key is used."
  type        = string
  default     = ""
}

variable "enable_instance_metadata_defaults" {
  description = "Enable account-level EC2 instance metadata defaults (IMDSv2 required)"
  type        = bool
  default     = true
}

variable "metadata_hop_limit" {
  description = "IMDS hop limit for account-level defaults"
  type        = number
  default     = 1
}

variable "disable_ec2_serial_console" {
  description = "Disable EC2 Serial Console access at account level"
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Enable EMR block public access configuration"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# Compute KMS key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "compute_key" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEC2ServiceOperations"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["ec2.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:ec2:ebs"
      values   = ["*"]
    }
  }

  statement {
    sid    = "AllowAutoScalingServiceRoleUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant"
    ]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:ec2:ebs"
      values   = ["*"]
    }
  }
}

resource "aws_kms_key" "compute" {
  description             = "${var.project_name}-compute KMS key"
  deletion_window_in_days = var.deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_days
  policy                  = data.aws_iam_policy_document.compute_key.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

# -----------------------------------------------------------------------------
# Observability KMS key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "observability_key" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["logs.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:*:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrailUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarmsUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }

  statement {
    sid    = "AllowSNSUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["sns.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }

  statement {
    sid    = "AllowSQSUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["sqs.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }

  statement {
    sid    = "AllowEventBridgeUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["events.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }
}

resource "aws_kms_key" "observability" {
  description             = "${var.project_name}-observability KMS key"
  deletion_window_in_days = var.deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_days
  policy                  = data.aws_iam_policy_document.observability_key.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

# -----------------------------------------------------------------------------
# Storage KMS key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "storage_key" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["s3.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }

  statement {
    sid    = "AllowAWSConfigSnapshotDelivery"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["config.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:config:arn"
      values   = ["arn:${local.partition}:config:*:${local.account_id}:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrailLogEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.${local.partition == "aws" ? "amazonaws.com" : "${local.partition}.amazonaws.com"}"]
    }
  }
}

resource "aws_kms_key" "storage" {
  description             = "${var.project_name}-storage KMS key"
  deletion_window_in_days = var.deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_days
  policy                  = data.aws_iam_policy_document.storage_key.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# -----------------------------------------------------------------------------
# Account-level default EBS encryption
# -----------------------------------------------------------------------------
resource "aws_ebs_default_kms_key" "default" {
  key_arn = var.external_default_ebs_key_arn != "" ? var.external_default_ebs_key_arn : aws_kms_key.compute.arn
}

resource "aws_ebs_encryption_by_default" "default" {
  enabled = true
}

# -----------------------------------------------------------------------------
# Account-level public access restrictions
# -----------------------------------------------------------------------------
resource "aws_ec2_image_block_public_access" "default" {
  state = "block-new-sharing"
}

resource "aws_ebs_snapshot_block_public_access" "default" {
  state = "block-all-sharing"
}

resource "aws_ec2_instance_metadata_defaults" "default" {
  count = var.enable_instance_metadata_defaults ? 1 : 0

  http_tokens = "required"
  hop_limit   = var.metadata_hop_limit
}

resource "aws_ec2_serial_console_access" "default" {
  count = var.disable_ec2_serial_console ? 1 : 0

  serial_console_access_enabled = false
}

resource "aws_emr_block_public_access_rule" "default" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_access_groups = true
}

output "compute_key_arn" {
  value = aws_kms_key.compute.arn
}

output "observability_key_arn" {
  value = aws_kms_key.observability.arn
}

output "storage_key_arn" {
  value = aws_kms_key.storage.arn
}

output "default_ebs_key_arn" {
  value = aws_ebs_default_kms_key.default.key_arn
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------- Variables ----------------

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_private_subnets" {
  description = "If true, create 2 public + 2 private subnets; if false, create 4 public subnets"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Deploy NAT Gateways in each public subnet"
  type        = bool
  default     = false
}

variable "enable_nat_instance" {
  description = "Deploy NAT EC2 instances in each public subnet"
  type        = bool
  default     = false
}

variable "enable_egress_only_igw" {
  description = "Deploy an Egress-Only Internet Gateway with IPv6 egress"
  type        = bool
  default     = false
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

# ---------------- Data ----------------

data "aws_ami" "amazon_linux_nat" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------- VPC Core ----------------

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = { Name = var.vpc_name }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = { Name = "${var.vpc_name}-igw" }
}

# ---------------- Security Groups ----------------

resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.this.id

  ingress {
    protocol  = "-1"
    from_port = 0
    to_port   = 0
    self      = true
  }

  egress {
    protocol  = "-1"
    from_port = 0
    to_port   = 0
    self      = true
  }

  tags = { Name = "${var.vpc_name}-default-sg" }
}

resource "aws_security_group" "tls_443" {
  name        = "${var.vpc_name}-tls-443"
  description = "Allow inbound TLS on port 443"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "TLS from anywhere"
    protocol    = "tcp"
    from_port   = 443
    to_port     = 443
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${var.vpc_name}-tls-443" }
}

# ---------------- Subnets ----------------

locals {
  az_count = var.enable_private_subnets ? 2 : 4
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "${var.vpc_name}-public-${count.index + 1}" }
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? 2 : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.public_subnet_cidrs[count.index + 2]
  availability_zone = local.azs[count.index]

  tags = { Name = "${var.vpc_name}-private-${count.index + 1}" }
}

# ---------------- Public Routing ----------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = { Name = "${var.vpc_name}-public-rt" }
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- Strategy 1: NAT Gateways ----------------

resource "aws_eip" "nat" {
  count = var.enable_nat_gateway ? local.az_count : 0

  domain = "vpc"

  tags = { Name = "${var.vpc_name}-nat-eip-${count.index + 1}" }
}

resource "aws_nat_gateway" "this" {
  count = var.enable_nat_gateway ? local.az_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = { Name = "${var.vpc_name}-nat-gw-${count.index + 1}" }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private_nat_gw" {
  count = var.enable_nat_gateway ? local.az_count : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = { Name = "${var.vpc_name}-private-rt-natgw-${count.index + 1}" }
}

resource "aws_route_table_association" "private_nat_gw" {
  count = var.enable_nat_gateway ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_gw[count.index].id
}

# ---------------- Strategy 2: NAT Instances ----------------

resource "aws_security_group" "nat_instance" {
  count = var.enable_nat_instance ? 1 : 0

  name        = "${var.vpc_name}-nat-instance-sg"
  description = "NAT instance security group"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "HTTP from VPC"
    protocol    = "tcp"
    from_port   = 80
    to_port     = 80
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTPS from VPC"
    protocol    = "tcp"
    from_port   = 443
    to_port     = 443
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "ICMP from VPC"
    protocol    = "icmp"
    from_port   = -1
    to_port     = -1
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All outbound"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${var.vpc_name}-nat-instance-sg" }
}

resource "aws_instance" "nat" {
  count = var.enable_nat_instance ? local.az_count : 0

  ami                         = data.aws_ami.amazon_linux_nat.id
  instance_type               = "m1.small"
  subnet_id                   = aws_subnet.public[count.index].id
  associate_public_ip_address = true
  security_groups             = [aws_security_group.nat_instance[0].id]
  source_dest_check           = false

  tags = { Name = "${var.vpc_name}-nat-instance-${count.index + 1}" }
}

resource "aws_route_table" "private_nat_instance" {
  count = var.enable_nat_instance ? local.az_count : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat[count.index].primary_network_interface_id
  }

  tags = { Name = "${var.vpc_name}-private-rt-natinst-${count.index + 1}" }
}

resource "aws_route_table_association" "private_nat_instance" {
  count = var.enable_nat_instance ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# ---------------- Strategy 3: Egress-Only IGW ----------------

resource "aws_egress_only_internet_gateway" "this" {
  count = var.enable_egress_only_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = { Name = "${var.vpc_name}-eigw" }
}

resource "aws_route" "private_egress_only_igw" {
  count = var.enable_egress_only_igw ? local.az_count : 0

  route_table_id              = aws_route_table.private_nat_gw[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}
```

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "benchmark"
}

variable "glacier_transition_days" {
  description = "Days before transitioning to Glacier"
  type        = number
  default     = 7
}

variable "glacier_expiration_days" {
  description = "Days before expiration"
  type        = number
  default     = 30
}

data "aws_caller_identity" "current" {}

# ---------------- KMS keys ----------------
resource "aws_kms_key" "primary" {
  description             = "KMS key for primary state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "replica" {
  provider                = aws.secondary
  description             = "KMS key for replica state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------- Primary buckets ----------------
resource "aws_s3_bucket" "state" {
  bucket = "tfstate-${var.environment}-${data.aws_caller_identity.current.account_id}-primary"
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "state" {
  bucket        = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.logs.id
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RestrictToAccountAndACL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "RequireBucketOwnerFullControl"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "logs" {
  bucket = "tflogs-${var.environment}-${data.aws_caller_identity.current.account_id}-primary"
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  depends_on = [aws_s3_bucket_ownership_controls.logs]
  bucket     = aws_s3_bucket.logs.id
  acl        = "log-delivery-write"
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "glacier-archive"
    status = "Enabled"
    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }
    expiration {
      days = var.glacier_expiration_days
    }
  }
}

# ---------------- Replica buckets ----------------
resource "aws_s3_bucket" "state_replica" {
  provider = aws.secondary
  bucket   = "tfstate-${var.environment}-${data.aws_caller_identity.current.account_id}-replica"
}

resource "aws_s3_bucket_versioning" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state_replica" {
  provider                = aws.secondary
  bucket                  = aws_s3_bucket.state_replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }
  }
}

resource "aws_s3_bucket_policy" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id
  policy   = aws_s3_bucket_policy.state.policy
}

resource "aws_s3_bucket" "logs_replica" {
  provider = aws.secondary
  bucket   = "tflogs-${var.environment}-${data.aws_caller_identity.current.account_id}-replica"
}

resource "aws_s3_bucket_versioning" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs_replica" {
  provider                = aws.secondary
  bucket                  = aws_s3_bucket.logs_replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id
  rule {
    id     = "glacier-archive"
    status = "Enabled"
    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }
    expiration {
      days = var.glacier_expiration_days
    }
  }
}

# ---------------- Replication IAM ----------------
resource "aws_iam_role" "replication" {
  name = "s3-replication-${var.environment}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name = "s3-replication-${var.environment}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.state.arn, aws_s3_bucket.logs.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.state.arn}/*", "${aws_s3_bucket.logs.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${aws_s3_bucket.state_replica.arn}/*", "${aws_s3_bucket.logs_replica.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.primary.arn, aws_kms_key.replica.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------- Replication configurations ----------------
resource "aws_s3_bucket_replication_configuration" "state" {
  depends_on = [aws_s3_bucket_versioning.state, aws_s3_bucket_versioning.state_replica]
  bucket     = aws_s3_bucket.state.id
  role       = aws_iam_role.replication.arn

  rule {
    id     = "replicate-state"
    status = "Enabled"
    delete_marker_replication {
      status = "Enabled"
    }
    destination {
      bucket        = aws_s3_bucket.state_replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "logs" {
  depends_on = [aws_s3_bucket_versioning.logs, aws_s3_bucket_versioning.logs_replica]
  bucket     = aws_s3_bucket.logs.id
  role       = aws_iam_role.replication.arn

  rule {
    id     = "replicate-logs"
    status = "Enabled"
    delete_marker_replication {
      status = "Enabled"
    }
    destination {
      bucket        = aws_s3_bucket.logs_replica.arn
      storage_class = "STANDARD"
    }
  }
}

output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "logs_bucket" {
  value = aws_s3_bucket.logs.id
}

output "state_replica_bucket" {
  value = aws_s3_bucket.state_replica.id
}

output "logs_replica_bucket" {
  value = aws_s3_bucket.logs_replica.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones to use"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.0.0/20"
    "us-east-1b" = "10.0.16.0/20"
  }
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.32.0/20"
    "us-east-1b" = "10.0.48.0/20"
  }
}

variable "database_subnet_cidrs" {
  description = "CIDR blocks for database subnets"
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.64.0/20"
    "us-east-1b" = "10.0.80.0/20"
  }
}

variable "map_public_ip_on_launch" {
  description = "Map public IPs on launch in public subnets"
  type        = bool
  default     = false
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC to use instead of creating one"
  type        = string
  default     = null
}

variable "existing_public_subnet_ids" {
  description = "Map of AZ to existing public subnet IDs"
  type        = map(string)
  default     = {}
}

variable "existing_private_subnet_ids" {
  description = "Map of AZ to existing private subnet IDs"
  type        = map(string)
  default     = {}
}

variable "existing_database_subnet_ids" {
  description = "Map of AZ to existing database subnet IDs"
  type        = map(string)
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT Gateway"
  type        = string
  default     = null
}

variable "existing_security_group_id" {
  description = "ID of an existing security group for VPC endpoints"
  type        = string
  default     = null
}

variable "vpc_endpoint_services" {
  description = "List of AWS services for interface VPC endpoints"
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

locals {
  vpc_id = var.existing_vpc_id != null ? var.existing_vpc_id : aws_vpc.this[0].id

  public_subnet_ids   = length(var.existing_public_subnet_ids) > 0 ? var.existing_public_subnet_ids : { for az, s in aws_subnet.public : az => s.id }
  private_subnet_ids  = length(var.existing_private_subnet_ids) > 0 ? var.existing_private_subnet_ids : { for az, s in aws_subnet.private : az => s.id }
  database_subnet_ids = length(var.existing_database_subnet_ids) > 0 ? var.existing_database_subnet_ids : { for az, s in aws_subnet.database : az => s.id }

  all_private_subnet_ids = values(local.private_subnet_ids)

  endpoint_security_group_id = var.existing_security_group_id != null ? var.existing_security_group_id : aws_security_group.vpc_endpoints[0].id

  vpc_cidr = var.existing_vpc_id != null ? data.aws_vpc.existing[0].cidr_block : var.vpc_cidr

  db_subnet_group_name = lower(var.vpc_name)
}

data "aws_vpc" "existing" {
  count  = var.existing_vpc_id != null ? 1 : 0
  id     = var.existing_vpc_id
}

# VPC
resource "aws_vpc" "this" {
  count                         = var.existing_vpc_id != null ? 0 : 1
  cidr_block                    = var.vpc_cidr
  enable_dns_hostnames          = true
  enable_dns_support            = true
  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id
  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  for_each                = var.existing_vpc_id != null ? {} : var.public_subnet_cidrs
  vpc_id                  = local.vpc_id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = var.map_public_ip_on_launch
  tags = {
    Name = "${var.vpc_name}-public-${each.key}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  for_each          = var.existing_vpc_id != null ? {} : var.private_subnet_cidrs
  vpc_id            = local.vpc_id
  cidr_block        = each.value
  availability_zone = each.key
  tags = {
    Name = "${var.vpc_name}-private-${each.key}"
  }
}

# Database subnets
resource "aws_subnet" "database" {
  for_each          = var.existing_vpc_id != null ? {} : var.database_subnet_cidrs
  vpc_id            = local.vpc_id
  cidr_block        = each.value
  availability_zone = each.key
  tags = {
    Name = "${var.vpc_name}-db-${each.key}"
  }
}

# Public route table
resource "aws_route_table" "public" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id
  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route" "public_internet" {
  count                  = var.existing_vpc_id != null ? 0 : 1
  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each       = aws_subnet.public
  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[0].id
}

# Private route table
resource "aws_route_table" "private" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id
  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  for_each       = aws_subnet.private
  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[0].id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count  = (var.existing_vpc_id == null && var.existing_nat_id == null) ? 1 : 0
  domain = "vpc"
  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

# NAT Gateway in first public subnet
resource "aws_nat_gateway" "this" {
  count         = (var.existing_vpc_id == null && var.existing_nat_id == null) ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = values(aws_subnet.public)[0].id
  tags = {
    Name = "${var.vpc_name}-nat"
  }
  depends_on = [aws_internet_gateway.this]
}

# Route private traffic through NAT (or existing NAT)
resource "aws_route" "private_nat" {
  count                  = var.existing_nat_id != null ? 1 : 0
  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = var.existing_nat_id
}

resource "aws_route" "private_nat_new" {
  count                  = (var.existing_vpc_id == null && var.existing_nat_id == null) ? 1 : 0
  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[0].id
}

# RDS DB subnet group
resource "aws_db_subnet_group" "this" {
  name       = local.db_subnet_group_name
  subnet_ids = values(local.database_subnet_ids)
  tags = {
    Name = local.db_subnet_group_name
  }
}

# Security group for VPC endpoints
resource "aws_security_group" "vpc_endpoints" {
  count       = var.existing_security_group_id != null ? 0 : 1
  name        = "${var.vpc_name}-vpc-endpoints"
  description = "Security group for VPC interface endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound within VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-vpc-endpoints"
  }
}

# Interface VPC endpoints
data "aws_vpc_endpoint_service" "this" {
  for_each = toset(var.vpc_endpoint_services)
  service  = each.key
}

resource "aws_vpc_endpoint" "this" {
  for_each            = toset(var.vpc_endpoint_services)
  vpc_id              = local.vpc_id
  service_name        = data.aws_vpc_endpoint_service.this[each.key].service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.all_private_subnet_ids
  security_group_ids  = [local.endpoint_security_group_id]
  private_dns_enabled = true
  tags = {
    Name = "${var.vpc_name}-${each.key}"
  }
}

output "vpc_id" {
  value = local.vpc_id
}

output "public_subnet_ids" {
  value = local.public_subnet_ids
}

output "private_subnet_ids" {
  value = local.private_subnet_ids
}

output "database_subnet_ids" {
  value = local.database_subnet_ids
}

output "db_subnet_group_name" {
  value = aws_db_subnet_group.this.name
}

output "nat_gateway_id" {
  value = var.existing_nat_id != null ? var.existing_nat_id : (var.existing_vpc_id == null ? aws_nat_gateway.this[0].id : null)
}

output "vpc_endpoint_security_group_id" {
  value = local.endpoint_security_group_id
}

output "vpc_endpoint_ids" {
  value = { for k, v in aws_vpc_endpoint.this : k => v.id }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_shortcode" {
  description = "Application shortcode used for resource name prefixes"
  type        = string
  default     = "bmk"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.8.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.8.1.0/24"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------- VPC ----------------
resource "aws_vpc" "test_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.app_shortcode}-ssm-test-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.test_vpc.id
  cidr_block        = var.subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.app_shortcode}-ssm-test-private-subnet"
  }
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "service_endpoints" {
  name        = "${var.app_shortcode}-ssm-test-endpoint-sg"
  description = "Allows inbound HTTPS from VPC CIDR for interface endpoints"
  vpc_id      = aws_vpc.test_vpc.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-endpoint-sg"
  }
}

resource "aws_security_group" "instance" {
  name        = "${var.app_shortcode}-ssm-test-instance-sg"
  description = "Allows egress HTTPS to VPC CIDR for the test instance"
  vpc_id      = aws_vpc.test_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  egress {
    description = "HTTPS to VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance-sg"
  }
}

# ---------------- VPC Endpoints ----------------
resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.test_vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.service_endpoints.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "${var.app_shortcode}-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.test_vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.service_endpoints.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "${var.app_shortcode}-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.test_vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.service_endpoints.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "${var.app_shortcode}-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.test_vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.service_endpoints.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "${var.app_shortcode}-logs-endpoint"
  }
}

data "aws_region" "current" {}

# ---------------- IAM ----------------
data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_test_role" {
  name               = "${var.app_shortcode}-ssm-test-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Name = "${var.app_shortcode}-ssm-test-role"
  }
}

data "aws_iam_policy_document" "ssm_test_policy" {
  statement {
    sid       = "SSMActions"
    effect    = "Allow"
    actions   = ["ssm:*"]
    resources = ["*"]
  }

  statement {
    sid       = "SSMMessages"
    effect    = "Allow"
    actions   = ["ssmmessages:*"]
    resources = ["*"]
  }

  statement {
    sid       = "EC2Messages"
    effect    = "Allow"
    actions   = ["ec2messages:*"]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchLogs"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:DescribeLogGroups", "logs:DescribeLogStreams", "logs:PutLogEvents", "logs:GetLogEvents"]
    resources = ["*"]
  }

  statement {
    sid       = "KMSGenerateDataKey"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
  }

  statement {
    sid       = "S3ObjectActions"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ssm_test_policy" {
  name   = "${var.app_shortcode}-ssm-test-policy"
  role   = aws_iam_role.ssm_test_role.id
  policy = data.aws_iam_policy_document.ssm_test_policy.json
}

resource "aws_iam_instance_profile" "ssm_test_profile" {
  name = "${var.app_shortcode}-ssm-test-instance-profile"
  role = aws_iam_role.ssm_test_role.name
}

# ---------------- EC2 Instance ----------------
resource "aws_instance" "test_instance" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.small"
  subnet_id                   = aws_subnet.private.id
  iam_instance_profile        = aws_iam_instance_profile.ssm_test_profile.name
  vpc_security_group_ids      = [aws_security_group.instance.id]
  source_dest_check           = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance"
  }
}

output "vpc_id" {
  value = aws_vpc.test_vpc.id
}

output "subnet_id" {
  value = aws_subnet.private.id
}

output "instance_id" {
  value = aws_instance.test_instance.id
}

output "instance_private_ip" {
  value = aws_instance.test_instance.private_ip
}

output "iam_role_name" {
  value = aws_iam_role.ssm_test_role.name
}

output "iam_instance_profile_name" {
  value = aws_iam_instance_profile.ssm_test_profile.name
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

data "aws_ami" "al2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

data "aws_region" "current" {}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = { Name = "private-fargate-vpc" }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "public-${count.index}" }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = local.azs[count.index]

  tags = { Name = "private-${count.index}" }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count      = 3
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  depends_on    = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------- VPC Endpoints ----------------
resource "aws_security_group" "endpoints" {
  name_prefix = "vpc-endpoints-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset([
    "com.amazonaws.${data.aws_region.current.name}.ecr.dkr",
    "com.amazonaws.${data.aws_region.current.name}.ecr.api",
    "com.amazonaws.${data.aws_region.current.name}.logs",
    "com.amazonaws.${data.aws_region.current.name}.secretsmanager",
    "com.amazonaws.${data.aws_region.current.name}.ssm",
    "com.amazonaws.${data.aws_region.current.name}.kms",
  ])

  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true
}

# ---------------- Cloud Map ----------------
resource "aws_service_discovery_private_dns_namespace" "ns" {
  name        = "private-fargate-crowdnews.hands-on.cloud.local"
  description = "Private namespace for Fargate service discovery"
  vpc         = aws_vpc.main.id
}

# ---------------- ECR / Logs / ECS ----------------
resource "aws_ecr_repository" "nginx" {
  name                 = "private-fargate-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_cloudwatch_log_group" "nginx" {
  name              = "/ecs/private-fargate-nginx"
  retention_in_days = 7
}

resource "aws_ecs_cluster" "main" {
  name = "private-fargate-cluster"
}

# ---------------- IAM ----------------
resource "aws_iam_role" "execution" {
  name = "ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "execution" {
  name = "execution-policy"
  role = aws_iam_role.execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability", "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "${aws_cloudwatch_log_group.nginx.arn}:*"
      },
      {
        Effect   = "Allow"
        Action   = ["ssm:GetParameters", "secretsmanager:GetSecretValue", "kms:Decrypt"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "task" {
  name = "ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "task" {
  name = "task-policy"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssm:GetParameters", "ssm:GetParameter"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["servicediscovery:*"]
        Resource = "*"
      }
    ]
  })
}

# ---------------- Task Definition ----------------
resource "aws_ecs_task_definition" "nginx" {
  family                   = "private-fargate-nginx"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "public.ecr.aws/nginx/nginx:latest"
      essential = true
      portMappings = [
        { containerPort = 80, protocol = "tcp" }
      ]
      environment = [
        { name = "SERVICE_DISCOVERY_NAMESPACE_ID", value = aws_service_discovery_private_dns_namespace.ns.id }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.nginx.name
          awslogs-region        = data.aws_region.current.name
          awslogs-stream-prefix = "nginx"
        }
      }
    }
  ])
}

# ---------------- Security Groups ----------------
resource "aws_security_group" "task" {
  name_prefix = "fargate-task-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "jumphost" {
  name_prefix = "jumphost-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# ---------------- ECS Service ----------------
resource "aws_ecs_service" "nginx" {
  name            = "private-fargate-nginx"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = 80
  }

  depends_on = [aws_service_discovery_service.nginx]
}

resource "aws_service_discovery_service" "nginx" {
  name          = "nginx"
  namespace_id  = aws_service_discovery_private_dns_namespace.ns.id
  description   = "NGINX service discovery"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.ns.id

    dns_records {
      type = "A"
      ttl  = 10
    }

    dns_records {
      type = "SRV"
      ttl  = 10
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

# ---------------- Jumphost ----------------
resource "aws_iam_role" "jumphost" {
  name = "jumphost-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_core" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "jumphost-instance-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [cidrhost(aws_subnet.public[0].cidr_block, 10)]
  security_groups = [aws_security_group.jumphost.id]

  tags = { Name = "jumphost-eni" }
}

resource "aws_instance" "jumphost" {
  ami                    = data.aws_ami.al2.id
  instance_type          = "t3.micro"
  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  tags = { Name = "ssm-jumphost" }
}

# ---------------- Output ----------------
output "curl_command" {
  value = "curl http://nginx.private-fargate-crowdnews.hands-on.cloud.local"
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

variable "cluster_name" {
  default = "demo-eks"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------- VPC ----------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/20"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_name}-public"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.cluster_name}-private-${count.index}"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${var.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------- KMS ----------------
resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key for ${var.cluster_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------- Cluster IAM ----------------
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "kms" {
  name = "eks-kms-usage"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey", "kms:CreateGrant"]
      Resource = aws_kms_key.eks.arn
    }]
  })
}

# ---------------- EKS Control Plane ----------------
resource "aws_security_group" "cluster" {
  name        = "${var.cluster_name}-cluster-sg"
  description = "EKS control plane security group"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.cluster_name}-cluster-sg"
  }
}

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.29"

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    endpoint_public_access = false
    endpoint_private_access = true
    security_group_ids = [aws_security_group.cluster.id]
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller
  ]
}

# ---------------- Key Pair ----------------
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_pem" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

# ---------------- Node IAM ----------------
resource "aws_iam_role" "node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node.name
}

# ---------------- Node Security Group ----------------
resource "aws_security_group" "node" {
  name        = "${var.cluster_name}-node-sg"
  description = "EKS worker node security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Outbound within VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Node to node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  ingress {
    description     = "TCP 443 from control plane"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.cluster.id]
  }

  ingress {
    description     = "TCP 1025-65535 from control plane"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_security_group.cluster.id]
  }

  egress {
    description     = "TCP 443 to control plane"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.cluster.id]
  }

  egress {
    description     = "TCP 1025-65535 to control plane"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_security_group.cluster.id]
  }

  tags = {
    Name = "${var.cluster_name}-node-sg"
  }
}

# ---------------- Launch Template ----------------
data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.29/amazon-linux-2/recommended/image_id"
}

locals {
  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -ex
    /etc/eks/bootstrap.sh ${var.cluster_name} \
      --b64-cluster-ca ${aws_eks_cluster.main.certificate_authority_data} \
      --apiserver-endpoint ${aws_eks_cluster.main.endpoint} \
      --use-max-pods false
    /opt/aws/bin/cfn-signal -e $? --stack eks-cluster-stack --resource NodeGroup --region us-east-1
  EOF
  )
}

resource "aws_launch_template" "node" {
  name        = "${var.cluster_name}-node-lt"
  description = "EKS worker node launch template"

  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  iam_instance_profile {
    name = aws_iam_instance_profile.node.name
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  metadata_options {
    http_tokens                 = "required"
    http_endpoint               = "enabled"
    http_put_response_hop_limit = 2
  }

  user_data = local.user_data
}

resource "time_sleep" "launch_template_settle" {
  create_duration = "30s"
  depends_on      = [aws_launch_template.node]
}

# ---------------- CloudFormation ASG ----------------
resource "aws_cloudformation_stack" "node_asg" {
  name = "eks-cluster-stack"

  parameters = {
    ClusterName   = var.cluster_name
    LaunchTemplateId = aws_launch_template.node.id
    LaunchTemplateVersion = aws_launch_template.node.latest_version
    SubnetIds     = join(",", aws_subnet.private[*].id)
    NodeSecurityGroupId = aws_security_group.node.id
  }

  template_body = <<YAML
AWSTemplateFormatVersion: "2010-09-09"
Description: EKS worker node Auto Scaling Group
Parameters:
  ClusterName:
    Type: String
  LaunchTemplateId:
    Type: String
  LaunchTemplateVersion:
    Type: String
  SubnetIds:
    Type: String
  NodeSecurityGroupId:
    Type: String
Resources:
  NodeGroup:
    Type: AWS::AutoScaling::AutoScalingGroup
    UpdatePolicy:
      AutoScalingRollingUpdate:
        MaxBatchSize: 1
        MinInstancesInService: 3
        PauseTime: PT5M
    Properties:
      MinSize: "1"
      DesiredCapacity: "3"
      MaxSize: "4"
      VPCZoneIdentifier: !Split [",", !Ref SubnetIds]
      LaunchTemplate:
        LaunchTemplateId: !Ref LaunchTemplateId
        Version: !Ref LaunchTemplateVersion
      Tags:
        - Key: Name
          Value: !Sub "\${ClusterName}-node"
          PropagateAtLaunch: true
        - Key: kubernetes.io/cluster/\${ClusterName}
          Value: owned
          PropagateAtLaunch: true
Outputs:
  NodeInstanceRoleArn:
    Value: ${aws_iam_role.node.arn}
  NodeSecurityGroupId:
    Value: !Ref NodeSecurityGroupId
  AutoScalingGroupId:
    Value: !Ref NodeGroup
YAML

  depends_on = [time_sleep.launch_template_settle]
}

# ---------------- Outputs ----------------
output "node_instance_role_arn" {
  value = aws_cloudformation_stack.node_asg.outputs["NodeInstanceRoleArn"]
}

output "node_security_group_id" {
  value = aws_cloudformation_stack.node_asg.outputs["NodeSecurityGroupId"]
}

output "autoscaling_group_id" {
  value = aws_cloudformation_stack.node_asg.outputs["AutoScalingGroupId"]
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      Project     = "eks-state-management"
      ManagedBy   = "terraform"
      Environment = "production"
      Component   = "remote-state"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
  default_tags {
    tags = {
      Project     = "eks-state-management"
      ManagedBy   = "terraform"
      Environment = "production"
      Component   = "remote-state-replica"
    }
  }
}

variable "stacks" {
  description = "Map of EKS stack names to their regions"
  type = map(object({
    region = string
  }))
  default = {
    "dev-stack" = {
      region = "us-east-1"
    }
    "prod-stack" = {
      region = "us-east-1"
    }
  }
}

data "aws_caller_identity" "current" {}

# ---------------- KMS Keys ----------------

resource "aws_kms_key" "primary" {
  description             = "Primary KMS key for Terraform state encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "primary" {
  name          = "alias/terraform-state-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Replica KMS key for Terraform state encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/terraform-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

# ---------------- Primary S3 Bucket ----------------

resource "aws_s3_bucket" "primary" {
  bucket = "terraform-state-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "primary_ssl_deny" {
  statement {
    sid       = "DenyInsecureRequests"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.primary.arn, "${aws_s3_bucket.primary.arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_ssl_deny.json
}

# ---------------- Replica S3 Bucket ----------------

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = "terraform-state-replica-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica_ssl_deny" {
  statement {
    sid       = "DenyInsecureRequests"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.replica.arn, "${aws_s3_bucket.replica.arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_ssl_deny.json
}

# ---------------- Replication IAM Role ----------------

resource "aws_iam_role" "replication" {
  name = "terraform-state-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  name = "terraform-state-replication-policy"
  role = aws_iam_role.replication.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.primary.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = ["${aws_s3_bucket.replica.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.replica.arn]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_s3_bucket_versioning.replica]
  bucket     = aws_s3_bucket.primary.id
  role       = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-to-replica"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

# ---------------- DynamoDB Lock Tables & Stack Policies ----------------

resource "aws_dynamodb_table" "state_lock" {
  for_each     = var.stacks
  name         = "terraform-state-lock-${each.key}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

resource "aws_iam_policy" "stack_access" {
  for_each = var.stacks
  name     = "terraform-state-access-${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/${each.key}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [aws_dynamodb_table.state_lock[each.key].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.primary.arn]
      }
    ]
  })
}

# ---------------- Generated backend.tf per stack ----------------

resource "local_file" "backend_config" {
  for_each = var.stacks

  content = templatefile("${path.module}/backend.tpl", {
    bucket_name     = aws_s3_bucket.primary.bucket
    key_prefix      = each.key
    region          = each.value.region
    dynamodb_table  = aws_dynamodb_table.state_lock[each.key].name
    kms_key_arn     = aws_kms_key.primary.arn
  })
  filename        = "${path.module}/eks-stacks/${each.key}/backend.tf"
  file_permission = "0644"
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
