```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_users" {
  description = "Map of IAM users with their Owner tags"
  type = map(object({
    owner = string
  }))
  default = {
    "dev1"  = { owner = "Devel" }
    "dev2"  = { owner = "Devel" }
    "guest" = { owner = "Guest" }
  }
}

resource "aws_iam_group" "devel_group" {
  name = "Ersia_Devel_Group"
}

resource "aws_iam_group" "guest_group" {
  name = "Ersia_Guest_Group"
}

resource "aws_iam_group_policy_attachment" "devel_readonly" {
  group      = aws_iam_group.devel_group.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guest_iamreadonly" {
  group      = aws_iam_group.guest_group.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user" "users" {
  for_each = var.iam_users
  name     = each.key

  tags = {
    Owner = each.value.owner
  }
}

resource "aws_iam_user_group_membership" "membership" {
  for_each = var.iam_users

  user = aws_iam_user.users[each.key].name

  groups = each.value.owner == "Devel" ? [aws_iam_group.devel_group.name] : [aws_iam_group.guest_group.name]
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_pet" "name" {
  length = 2
}

# ---------------- KMS ----------------
resource "aws_kms_key" "sqs" {
  description             = "KMS key for SQS queue ${random_pet.name.id}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/sqs-${random_pet.name.id}"
  target_key_id = aws_kms_key.sqs.key_id
}

# ---------------- SQS ----------------
resource "aws_sqs_queue" "messages" {
  name                              = "${random_pet.name.id}-messages"
  kms_master_key_id                 = aws_kms_key.sqs.key_id
  kms_data_key_reuse_period_seconds = 300
  sqs_managed_sse_enabled           = false
  visibility_timeout_seconds        = 300
}

# ---------------- IAM ----------------
data "aws_iam_policy_document" "apigw_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_sqs" {
  name               = "apigw-sqs-${random_pet.name.id}"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume.json
}

data "aws_iam_policy_document" "apigw_sqs" {
  statement {
    actions = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.messages.arn]
  }
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "apigw_sqs" {
  name   = "apigw-sqs-policy"
  role   = aws_iam_role.apigw_sqs.id
  policy = data.aws_iam_policy_document.apigw_sqs.json
}

# ---------------- CloudWatch Logs ----------------
resource "aws_cloudwatch_log_group" "api_access" {
  name              = "/aws/apigateway/${random_pet.name.id}"
  retention_in_days = 1
}

# ---------------- API Gateway v2 WebSocket ----------------
resource "aws_apigatewayv2_api" "ws" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# Mock integration for connect route
resource "aws_apigatewayv2_integration" "connect_mock" {
  api_id                 = aws_apigatewayv2_api.ws.id
  integration_type       = "AWS"
  integration_uri        = "arn:aws:apigateway:${data.aws_region.current.name}:apigateway:mock"
  integration_method     = "GET"
  payload_format_version = "1.0"
}

resource "aws_apigatewayv2_route" "connect" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_key          = "$connect"
  target             = "integrations/${aws_apigatewayv2_integration.connect_mock.id}"
}

# SQS integration for default route
resource "aws_apigatewayv2_integration" "default_sqs" {
  api_id                 = aws_apigatewayv2_api.ws.id
  integration_type       = "AWS"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${aws_sqs_queue.messages.name}"
  credentials_arn        = aws_iam_role.apigw_sqs.arn
  payload_format_version = "1.0"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "$default" = "Action=SendMessage&MessageBody=$util.urlEncode($input.body)"
  }
  response_templates = {
    "$default" = <<EOF
{
  "statusCode": 200,
  "body": $input.json('$.body')
}
EOF
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_key          = "$default"
  target             = "integrations/${aws_apigatewayv2_integration.default_sqs.id}"
}

# SQS integration for disconnect route
resource "aws_apigatewayv2_integration" "disconnect_sqs" {
  api_id                 = aws_apigatewayv2_api.ws.id
  integration_type       = "AWS"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${aws_sqs_queue.messages.name}"
  credentials_arn        = aws_iam_role.apigw_sqs.arn
  payload_format_version = "1.0"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "$disconnect" = "Action=SendMessage&MessageBody=Client%20disconnected"
  }
  response_templates = {
    "$default" = "{}"
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_key          = "$disconnect"
  target             = "integrations/${aws_apigatewayv2_integration.disconnect_sqs.id}"
}

# Stage
resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.ws.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access.arn
    format          = jsonencode({
      requestId        = "$context.requestId"
      routeKey         = "$context.routeKey"
      connectionId     = "$context.connectionId"
      status           = "$context.status"
      integrationError = "$context.integration.error"
    })
  }
}

data "aws_region" "current" {}

# ---------------- Output ----------------
output "websocket_endpoint" {
  value = "wss://${aws_apigatewayv2_api.ws.api_id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_apigatewayv2_stage.dev.name}"
}

output "sqs_queue_url" {
  value = aws_sqs_queue.messages.url
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --- Variables ---

variable "vpc1_name" {
  description = "Name tag for the first test VPC"
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc1_cidr" {
  description = "CIDR block for the first test VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc2_name" {
  description = "Name tag for the Default VPC"
  type        = string
  default     = "Default"
}

variable "vpc2_cidr" {
  description = "CIDR block for the Default VPC"
  type        = string
  default     = "172.31.0.0/16"
}

variable "vpc2_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the Default VPC"
  type        = bool
  default     = true
}

variable "vpc3_name" {
  description = "Name tag for the eksctl VPC"
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "vpc3_cidr" {
  description = "CIDR block for the eksctl VPC"
  type        = string
  default     = "192.168.0.0/16"
}

variable "vpc3_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the eksctl VPC"
  type        = bool
  default     = true
}

variable "vpc3_eksctl_cluster_name" {
  description = "eksctl cluster name tag value"
  type        = string
  default     = "eks-cluster-px"
}

variable "vpc3_eksctl_version" {
  description = "eksctl version tag value"
  type        = string
  default     = "0.94.0"
}

variable "vpc4_cidr" {
  description = "CIDR block for the untagged VPC"
  type        = string
  default     = "10.0.0.0/24"
}

variable "vpc5_cidr" {
  description = "CIDR block for the fifth VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc5_name" {
  description = "Name tag for the fifth VPC (empty by default)"
  type        = string
  default     = ""
}

# --- VPCs ---

# VPC 1: XXXX-vpc-test
resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc1_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = {
    Name = var.vpc1_name
  }
}

# VPC 2: Default
resource "aws_vpc" "default" {
  cidr_block           = var.vpc2_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc2_enable_dns_hostnames

  tags = {
    Name = var.vpc2_name
  }
}

# VPC 3: eksctl VPC
resource "aws_vpc" "eksctl_vpc" {
  cidr_block           = var.vpc3_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc3_enable_dns_hostnames

  tags = {
    Name                             = var.vpc3_name
    "alpha.eksctl.io/cluster-name"   = var.vpc3_eksctl_cluster_name
    "eksctl.io/v1alpha2/cluster-name" = var.vpc3_eksctl_cluster_name
    "eksctl.io/v1alpha2/nodegroup-0" = "0.94.0"
    "eksctl.io/v1alpha2/version"     = var.vpc3_eksctl_version
  }
}

# VPC 4: Untagged
resource "aws_vpc" "untagged" {
  cidr_block           = var.vpc4_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = {}
}

# VPC 5: Empty Name tag
resource "aws_vpc" "empty_name" {
  cidr_block           = var.vpc5_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = {
    Name = var.vpc5_name
  }
}

# --- Outputs ---

output "vpc_ids" {
  description = "IDs of all created VPCs"
  value = {
    vpc_test   = aws_vpc.vpc_test.id
    default    = aws_vpc.default.id
    eksctl_vpc = aws_vpc.eksctl_vpc.id
    untagged   = aws_vpc.untagged.id
    empty_name = aws_vpc.empty_name.id
  }
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = "production"
      ManagedBy   = "terraform"
    }
  }
}

variable "additional_tags" {
  description = "Optional tags to apply to IAM roles. Tags already set identically in provider default_tags are skipped."
  type        = map(string)
  default     = {}
}

locals {
  # Skip any tag already set identically in the provider default_tags
  role_tags = {
    for k, v in var.additional_tags : k => v
    if lookup({
      Environment = "production"
      ManagedBy   = "terraform"
    }, k, null) != v
  }
}

# -----------------------------------------------------------------------------
# ECS service role: ecs-role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name                 = "ecs-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = data.aws_iam_policy_document.ecs_assume_role.json
  tags                 = local.role_tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_service" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# -----------------------------------------------------------------------------
# ECS task execution role: ecs-tasks-role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                 = "ecs-tasks-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags                 = local.role_tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_execution" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# -----------------------------------------------------------------------------
# EventBridge role: events-role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "events_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events_role" {
  name                 = "events-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = data.aws_iam_policy_document.events_assume_role.json
  tags                 = local.role_tags
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    sid       = "AllowRunTask"
    effect    = "Allow"
    actions   = ["ecs:RunTask"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowPassTaskExecutionRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Allows EventBridge to run ECS tasks and pass only the ECS task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy.json
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_logs" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "ecs_role_arn" {
  value = aws_iam_role.ecs_role.arn
}

output "ecs_tasks_role_arn" {
  value = aws_iam_role.ecs_tasks_role.arn
}

output "events_role_arn" {
  value = aws_iam_role.events_role.arn
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  alias  = "primary"
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

variable "primary_bucket_name" {
  type    = string
  default = "example1"
}

variable "secondary_bucket_name" {
  type    = string
  default = "example2"
}

variable "mrap_name" {
  type    = string
  default = "example-mrap"
}

data "aws_caller_identity" "current" {
  provider = aws.primary
}

data "aws_partition" "current" {
  provider = aws.primary
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  primary_bucket_name   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${local.account_id}"
}

# ---------------- KMS Keys ----------------

resource "aws_kms_key" "primary" {
  provider                = aws.primary
  description             = "KMS key for primary bucket ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key for secondary bucket ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

# ---------------- Buckets ----------------

resource "aws_s3_bucket" "primary" {
  provider = aws.primary
  bucket   = local.primary_bucket_name
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary
  bucket   = local.secondary_bucket_name
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
    bucket_key_enabled = true
  }
}

# ---------------- Replication IAM Role ----------------

resource "aws_iam_role" "replication" {
  provider = aws.primary
  name     = "${var.primary_bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  provider = aws.primary
  name     = "${var.primary_bucket_name}-replication-policy"
  role     = aws_iam_role.replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.primary.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = ["${aws_s3_bucket.secondary.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = [aws_kms_key.secondary.arn]
      }
    ]
  })
}

# ---------------- Replication Configuration ----------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary
  ]

  role = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ---------------- Multi-Region Access Point ----------------

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.primary
  name     = var.mrap_name

  region {
    bucket = aws_s3_bucket.primary.arn
  }

  region {
    bucket = aws_s3_bucket.secondary.arn
  }
}

resource "aws_s3control_access_point_policy" "mrap_policy" {
  provider     = aws.primary
  access_point_arn = aws_s3control_multi_region_access_point.mrap.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowOwnerGetObject"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
      },
      {
        Sid       = "AllowOwnerPutObject"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
      }
    ]
  })
}

output "mrap_alias" {
  value = aws_s3control_multi_region_access_point.mrap.alias
}

output "primary_bucket" {
  value = aws_s3_bucket.primary.id
}

output "secondary_bucket" {
  value = aws_s3_bucket.secondary.id
}
```

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  context = {
    namespace  = var.namespace
    environment = var.environment
    stage      = var.stage
    name       = var.name
    delimiter  = "-"
    attributes = ["patch"]
    tags       = var.tags
  }
}

variable "namespace" {
  type    = string
  default = "cp"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "stage" {
  type    = string
  default = "app"
}

variable "name" {
  type    = string
  default = "patching"
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "scan_schedule" {
  type    = string
  default = "cron(0 0 18 ? * WED *)"
}

variable "install_schedule" {
  type    = string
  default = "cron(0 0 21 ? * WED *)"
}

variable "duration_hours" {
  type    = number
  default = 3
}

variable "cutoff_hours" {
  type    = number
  default = 1
}

variable "scan_patch_group" {
  type    = string
  default = "TOSCAN"
}

variable "install_patch_group" {
  type    = string
  default = "TOPATCH"
}

variable "scan_tag_targets" {
  description = "Optional explicit tag targets for scan window"
  type = list(object({
    key    = string
    values = list(string)
  }))
  default = null
}

variable "install_tag_targets" {
  description = "Optional explicit tag targets for install window"
  type = list(object({
    key    = string
    values = list(string)
  }))
  default = null
}

variable "max_concurrency" {
  type    = number
  default = 20
}

variable "max_errors" {
  type    = number
  default = 50
}

variable "reboot_option" {
  type    = string
  default = "RebootIfNeeded"
}

variable "log_prefix" {
  type    = string
  default = "scanning"
}

variable "enable_sns_notifications" {
  type    = bool
  default = false
}

variable "sns_topic_arn" {
  type    = string
  default = ""
}

variable "enable_cloudwatch_logs" {
  type    = bool
  default = false
}

variable "create_log_bucket" {
  type    = bool
  default = true
}

# ---------- S3 log bucket ----------

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "logs" {
  count = var.create_log_bucket ? 1 : 0

  tags = module.this.tags
}

resource "aws_s3_bucket_versioning" "logs" {
  count = var.create_log_bucket ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = var.create_log_bucket ? 1 : 0

  bucket                  = aws_s3_bucket.logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "logs" {
  count = var.create_log_bucket ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AccountReadWrite"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Resource = [
          aws_s3_bucket.logs[0].arn,
          "${aws_s3_bucket.logs[0].arn}/*"
        ]
      }
    ]
  })
}

# ---------- IAM role for SSM Run Command ----------

data "aws_iam_policy_document" "ssm_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm" {
  name               = module.this.id
  assume_role_policy = data.aws_iam_policy_document.ssm_assume.json

  tags = module.this.tags
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "ssm_logs" {
  statement {
    actions   = ["s3:PutObject"]
    resources = var.create_log_bucket ? ["${aws_s3_bucket.logs[0].arn}/${var.log_prefix}/*"] : ["arn:aws:s3:::none/none/*"]
  }

  dynamic "statement" {
    for_each = var.enable_cloudwatch_logs ? [1] : []
    content {
      actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
      resources = ["arn:aws:logs:*:*:*"]
    }
  }

  dynamic "statement" {
    for_each = var.enable_sns_notifications ? [1] : []
    content {
      actions   = ["sns:Publish"]
      resources = [var.sns_topic_arn]
    }
  }
}

resource "aws_iam_role_policy" "ssm_logs" {
  name   = "${module.this.id}-logs"
  role   = aws_iam_role.ssm.id
  policy = data.aws_iam_policy_document.ssm_logs.json
}

# ---------- Maintenance windows ----------

module "scan_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context = merge(local.context, { attributes = ["patch", "scan"] })
}

module "install_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context = merge(local.context, { attributes = ["patch", "install"] })
}

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context = local.context
}

resource "aws_ssm_maintenance_window" "scan" {
  name        = module.scan_label.id
  description = "Weekly patch scan maintenance window"
  schedule    = var.scan_schedule
  duration    = var.duration_hours
  cutoff      = var.cutoff_hours

  tags = module.scan_label.tags
}

resource "aws_ssm_maintenance_window" "install" {
  name        = module.install_label.id
  description = "Weekly patch install maintenance window"
  schedule    = var.install_schedule
  duration    = var.duration_hours
  cutoff      = var.cutoff_hours

  tags = module.install_label.tags
}

# ---------- Targets ----------

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  resource_type = "INSTANCE"

  targets {
    key    = var.scan_tag_targets != null ? "TagList" : "Tag"
    values = var.scan_tag_targets != null ? [for t in var.scan_tag_targets : "${t.key},${join(",", t.values)}"] : ["Patch Group,${var.scan_patch_group}"]
  }
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  resource_type = "INSTANCE"

  targets {
    key    = var.install_tag_targets != null ? "TagList" : "Tag"
    values = var.install_tag_targets != null ? [for t in var.install_tag_targets : "${t.key},${join(",", t.values)}"] : ["Patch Group,${var.install_patch_group}"]
  }
}

# ---------- Tasks ----------

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  service_role_arn = aws_iam_role.ssm.arn

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      timeout_seconds = 3600

      parameter {
        name = "Operation"
        value = "Scan"
      }

      parameter {
        name = "RebootOption"
        value = "NoReboot"
      }

      dynamic "parameter" {
        for_each = var.create_log_bucket ? [1] : []
        content {
          name  = "BaselineOverride"
          value = ""
        }
      }
    }
  }

  logging_info {
    s3_bucket_name = var.create_log_bucket ? aws_s3_bucket.logs[0].id : ""
    s3_key_prefix  = var.log_prefix

    cloudwatch_log_group_name = var.enable_cloudwatch_logs ? "${module.scan_label.id}-logs" : ""
    cloudwatch_encryption_enabled = false
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  service_role_arn = aws_iam_role.ssm.arn

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      timeout_seconds = 3600

      parameter {
        name = "Operation"
        value = "Install"
      }

      parameter {
        name = "RebootOption"
        value = var.reboot_option
      }
    }
  }

  logging_info {
    s3_bucket_name = var.create_log_bucket ? aws_s3_bucket.logs[0].id : ""
    s3_key_prefix  = var.log_prefix

    cloudwatch_log_group_name = var.enable_cloudwatch_logs ? "${module.install_label.id}-logs" : ""
    cloudwatch_encryption_enabled = false
  }
}

# ---------- Patch baseline ----------

resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = module.this.id
  description      = "Amazon Linux 2 patch baseline"
  operating_system = "AMAZON_LINUX_2"

  approved_patches_compliance_level = "HIGH"
  approved_patches_enable_non_security = true

  approval_rule {
    approve_after_days  = 7
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = module.this.tags
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "alarm_email_recipients" {
  description = "List of email addresses to subscribe to the management-updates SNS topic"
  type        = list(string)
  default     = ["placeholder@example.com"]
}

# ---------------- KMS ----------------

resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  name          = "alias/cloudtrail-monitor-key"
  target_key_id = aws_kms_key.cloudtrail_key.key_id
}

resource "aws_kms_key" "sns_key" {
  description             = "KMS key for management-updates SNS topic"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_key_policy" "sns_key_policy" {
  key_id = aws_kms_key.sns_key.key_id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudWatchAlarmsToUseKey"
        Effect    = "Allow"
        Principal = { Service = "cloudwatch.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------- S3 bucket ----------------

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailAclCheck"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = "arn:aws:cloudtrail:${data.aws_caller_identity.current.account_id}:trail/monitor_account_activities"
          }
        }
      },
      {
        Sid       = "AWSCloudTrailWrite"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"                 = "bucket-owner-full-control"
            "AWS:SourceArn"                = "arn:aws:cloudtrail:${data.aws_caller_identity.current.account_id}:trail/monitor_account_activities"
            "aws:SourceAccount"            = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# ---------------- CloudWatch Logs ----------------

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "cloudtrail-to-cloudwatch-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-logs-policy"
  role = aws_iam_role.cloudtrail_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "cloudtrail_to_cloudwatch_logs"
  retention_in_days = 90
}

# ---------------- CloudTrail ----------------

resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = "monitor_account_activities"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_kms_key_id                 = aws_kms_key.cloudtrail_key.arn
  is_multi_region_trail         = true
  include_global_service_events = true
  enable_log_file_validation    = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true

    exclude_management_event_source {
      type = "AWS::KMS::Key"
    }
    exclude_management_event_source {
      type = "AWS::RDS::DBInstance"
    }
  }

  depends_on = [aws_s3_bucket_policy.cloudtrail_logs]
}

# ---------------- Metric filters ----------------

locals {
  metric_namespace = "management_activities"

  metric_filters = {
    security_group_changes = {
      pattern        = "{ ($.eventName = AuthorizeSecurityGroupIngress) || ($.eventName = AuthorizeSecurityGroupEgress) || ($.eventName = RevokeSecurityGroupIngress) || ($.eventName = RevokeSecurityGroupEgress) || ($.eventName = CreateSecurityGroup) || ($.eventName = DeleteSecurityGroup) }"
      metric_name    = "SecurityGroupChanges"
      filter_name    = "security-group-changes"
      alarm_desc     = "Alarm when security group changes occur"
    }
    iam_user_creation_deletion = {
      pattern        = "{ ($.eventName = CreateUser) || ($.eventName = DeleteUser) }"
      metric_name    = "IAMUserCreationDeletion"
      filter_name    = "iam-user-creation-deletion"
      alarm_desc     = "Alarm when IAM users are created or deleted"
    }
    failed_console_logins = {
      pattern        = "{ ($.eventName = ConsoleLogin) && ($.errorMessage = \"Failed authentication\") }"
      metric_name    = "FailedConsoleLogins"
      filter_name    = "failed-console-logins"
      alarm_desc     = "Alarm when failed console logins occur"
    }
    iam_group_role_user_policy_changes = {
      pattern        = "{ ($.eventName = PutGroupPolicy) || ($.eventName = DeleteGroupPolicy) || ($.eventName = PutRolePolicy) || ($.eventName = DeleteRolePolicy) || ($.eventName = PutUserPolicy) || ($.eventName = DeleteUserPolicy) }"
      metric_name    = "IAMGroupRoleUserPolicyChanges"
      filter_name    = "iam-group-role-user-policy-changes"
      alarm_desc     = "Alarm when IAM group, role, or user policy changes occur"
    }
    iam_policy_changes = {
      pattern        = "{ ($.eventName = CreatePolicy) || ($.eventName = DeletePolicy) || ($.eventName = CreatePolicyVersion) || ($.eventName = DeletePolicyVersion) || ($.eventName = AttachRolePolicy) || ($.eventName = DetachRolePolicy) || ($.eventName = AttachUserPolicy) || ($.eventName = DetachUserPolicy) || ($.eventName = AttachGroupPolicy) || ($.eventName = DetachGroupPolicy) }"
      metric_name    = "IAMPolicyChanges"
      filter_name    = "iam-policy-changes"
      alarm_desc     = "Alarm when IAM policy changes occur"
    }
    users_added_to_groups = {
      pattern        = "{ ($.eventName = AddUserToGroup) }"
      metric_name    = "UsersAddedToGroups"
      filter_name    = "users-added-to-groups"
      alarm_desc     = "Alarm when users are added to IAM groups"
    }
    iam_role_creation_deletion = {
      pattern        = "{ ($.eventName = CreateRole) || ($.eventName = DeleteRole) }"
      metric_name    = "IAMRoleCreationDeletion"
      filter_name    = "iam-role-creation-deletion"
      alarm_desc     = "Alarm when IAM roles are created or deleted"
    }
  }
}

resource "aws_cloudwatch_log_metric_filter" "filters" {
  for_each       = local.metric_filters
  name           = each.value.filter_name
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name          = each.value.metric_name
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "alarms" {
  for_each            = local.metric_filters
  alarm_name          = "${each.value.filter_name}-alarm"
  alarm_description   = each.value.alarm_desc
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = each.value.metric_name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.management_updates.arn]
  ok_actions    = [aws_sns_topic.management_updates.arn]

  depends_on = [aws_cloudwatch_log_metric_filter.filters]
}

# ---------------- SNS ----------------

resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns_key.arn
}

resource "aws_sns_topic_policy" "management_updates" {
  arn = aws_sns_topic.management_updates.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudWatchAlarmsToPublish"
        Effect    = "Allow"
        Principal = { Service = "cloudwatch.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.management_updates.arn
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "email" {
  count     = length(var.alarm_email_recipients)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = var.alarm_email_recipients[count.index]
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "config_rule_name_prefix" {
  description = "Optional name prefix for the AWS Config rule"
  type        = string
  default     = ""
}

variable "config_rule_enabled" {
  description = "Whether the AWS Config rule is enabled"
  type        = bool
  default     = true
}

variable "max_cert_days_to_expiration" {
  description = "Maximum number of days before an ACM certificate expiration to flag"
  type        = string
  default     = "14"
}

variable "config_delivery_bucket" {
  description = "Name of the S3 bucket for Config delivery"
  type        = string
  default     = "aws-config-delivery-acm-check-example"
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_recorder" "main" {
  name     = "acm-expiration-recorder"
  role_arn = aws_iam_role.config_role.arn
}

resource "aws_iam_role" "config_role" {
  name = "aws-config-recorder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_s3_bucket" "config_delivery" {
  bucket        = var.config_delivery_bucket
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "config_delivery" {
  bucket                  = aws_s3_bucket.config_delivery.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = ["s3:GetBucketAcl", "s3:ListBucket"]
        Resource = aws_s3_bucket.config_delivery.arn
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.config_delivery.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_config_delivery_channel" "main" {
  name           = "acm-expiration-delivery"
  s3_bucket_name = aws_s3_bucket.config_delivery.bucket

  depends_on = [aws_s3_bucket_policy.config_delivery]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.main]
}

resource "aws_config_config_rule" "acm_expiration" {
  name        = trimsuffix("${var.config_rule_name_prefix}acm-certificate-expiration-check", "-")
  description = "Checks whether ACM certificates are close to expiring"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = var.max_cert_days_to_expiration
  })

  enabled = var.config_rule_enabled

  depends_on = [aws_config_configuration_recorder_status.main]
}

output "config_rule_arn" {
  value = aws_config_config_rule.acm_expiration.arn
}

output "config_rule_name" {
  value = aws_config_config_rule.acm_expiration.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "pool" {
  name = "fiap-hackathon-cognito-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_uppercase = true
    require_numbers   = true
    require_symbols   = false
  }

  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name         = "cognito-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

output "user_pool_id" {
  value = aws_cognito_user_pool.pool.id
}

output "user_pool_client_id" {
  value = aws_cognito_user_pool_client.client.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "azure_tenant_id" {
  description = "Azure AD tenant ID"
  type        = string
  default     = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
}

variable "azure_client_id" {
  description = "Azure AD client ID (audience)"
  type        = string
  default     = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
}

variable "oidc_thumbprint" {
  description = "Thumbprint of the issuer TLS certificate"
  type        = string
  default     = "69a4d4c9e2b1f3a8c7d5e6f0b1a2c3d4e5f60718"
}

data "aws_iam_policy" "organizations_readonly" {
  name = "AWSOrganizationsReadOnlyAccess"
}

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = "https://sts.windows.net/${var.azure_tenant_id}/"
  client_id_list  = [var.azure_client_id]
  thumbprint_list = [var.oidc_thumbprint]

  tags = {
    Name = "AzureAD-OIDC-${var.azure_tenant_id}"
  }
}

data "aws_iam_policy_document" "sentinel_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.azure_ad.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.azure_tenant_id}:aud"
      values   = [var.azure_client_id]
    }
  }
}

resource "aws_iam_role" "sentinel_oidc_readonly" {
  name               = "Sentinel-OIDC-Organizations-ReadOnly"
  assume_role_policy = data.aws_iam_policy_document.sentinel_trust.json

  tags = {
    Name = "Sentinel-OIDC-Organizations-ReadOnly"
  }
}

resource "aws_iam_role_policy_attachment" "organizations_readonly" {
  role       = aws_iam_role.sentinel_oidc_readonly.name
  policy_arn = data.aws_iam_policy.organizations_readonly.arn
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "wildcard_test_role" {
  name               = "rds-wildcard-test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_role_policy" "allow_specific_cluster" {
  name = "allow-addrole-specific-cluster"
  role = aws_iam_role.wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
        Resource = "arn:aws:rds:*:*:cluster:foo_cluster"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_wildcard" {
  name = "allow-add-wildcard"
  role = aws_iam_role.wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "deny_wildcard" {
  name = "deny-add-wildcard"
  role = aws_iam_role.wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

output "role_arn" {
  value = aws_iam_role.wildcard_test_role.arn
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used in the state bucket"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  account_id      = data.aws_caller_identity.current.account_id
  frontend_bucket = "s3-frontend-nft-maker-v2-${local.account_id}"
  state_bucket    = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
}

# ---------------- KMS keys ----------------

resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_key_alias" "frontend" {
  name          = "alias/frontend-nft-maker-v2"
  target_key_id = aws_kms_key.frontend.key_id
}

resource "aws_kms_key" "state" {
  description             = "KMS key for terraform state bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_key_alias" "state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# ---------------- Frontend S3 bucket ----------------

resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket                  = aws_s3_bucket.frontend.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.frontend.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  index_document {
    suffix = "index.html"
  }
  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_cloudfront_origin_access_identity" "oai" {
  comment = "OAI for ${local.frontend_bucket}"
}

data "aws_iam_policy_document" "frontend" {
  statement {
    sid       = "AllowCloudFrontOAIRead"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:ListBucket"]
    resources = [aws_s3_bucket.frontend.arn, "${aws_s3_bucket.frontend.arn}/*"]
    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.oai.iam_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = data.aws_iam_policy_document.frontend.json
  depends_on = [aws_s3_bucket_public_access_block.frontend]
}

# ---------------- WAF ----------------

resource "aws_wafv2_web_acl" "cloudfront" {
  name  = "frontend-nft-maker-v2-acl"
  scope = "CLOUDFRONT"
  default_action {
    allow {}
  }
  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "frontendNftMakerV2Acl"
    sampled_requests_enabled   = true
  }
  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1
    override_action {
      none {}
    }
    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }
}

# ---------------- CloudFront ----------------

resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Frontend distribution for nft-maker-v2"
  price_class         = "PriceClass_200"
  default_root_object = "index.html"

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "s3-frontend-origin"
    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-frontend-origin"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-frontend-origin"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 86400
    default_ttl            = 2592000
    max_ttl                = 31536000
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/*"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-frontend-origin"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 604800
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  web_acl_id = aws_wafv2_web_acl.cloudfront.arn

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# ---------------- Terraform state backend ----------------

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_dynamodb_table" "state_lock" {
  name         = "near-frontend-terraform-state"
  billing_mode = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

# ---------------- Outputs ----------------

output "frontend_bucket" {
  value = aws_s3_bucket.frontend.bucket
}

output "cloudfront_domain" {
  value = aws_cloudfront_distribution.frontend.domain_name
}

output "state_bucket" {
  value = aws_s3_bucket.state.bucket
}

output "dynamodb_lock_table" {
  value = aws_dynamodb_table.state_lock.name
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "EKS cluster name used for tagging"
  type        = string
  default     = "stackx"
}

variable "base_name" {
  description = "Base name for all resources"
  type        = string
  default     = "stackx-network"
}

variable "vpc_cidr" {
  type    = string
  default = "10.1.0.0/16"
}

variable "azs" {
  type    = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "private_subnets" {
  type    = list(string)
  default = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]
}

variable "public_subnets" {
  type    = list(string)
  default = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
}

variable "enable_database_subnets" {
  type    = bool
  default = false
}

variable "database_subnets" {
  type    = list(string)
  default = ["10.1.204.0/22", "10.1.208.0/22", "10.1.212.0/22"]
}

variable "enable_cache_subnets" {
  type    = bool
  default = false
}

variable "cache_subnets" {
  type    = list(string)
  default = ["10.1.216.0/22", "10.1.220.0/22", "10.1.224.0/22"]
}

variable "enable_internal_subnets" {
  type    = bool
  default = false
}

variable "internal_subnets" {
  type    = list(string)
  default = ["10.1.228.0/22", "10.1.232.0/22", "10.1.236.0/22"]
}

locals {
  tags = {
    Name                                     = var.base_name
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

# ---------------- VPC ----------------
resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = local.tags
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags   = local.tags
}

resource "aws_egress_only_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags   = local.tags
}

# ---------------- Public subnets ----------------
resource "aws_subnet" "public" {
  count = length(var.azs)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = var.azs[count.index]
  map_public_ip_on_launch = false
  ipv6_cidr_block         = cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index)
  assign_ipv6_address_on_creation = true

  tags = merge(local.tags, {
    Name = "${var.base_name}-public-${var.azs[count.index]}"
    "kubernetes.io/role/elb"                    = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "karpenter.sh/discovery"                    = var.cluster_name
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id
  tags = merge(local.tags, {
    Name = "${var.base_name}-public"
  })
}

resource "aws_route" "public_internet_v4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route" "public_internet_v6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = length(var.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- NAT gateways ----------------
resource "aws_eip" "nat" {
  count = length(var.azs)

  domain = "vpc"
  tags = merge(local.tags, {
    Name = "${var.base_name}-nat-eip-${var.azs[count.index]}"
  })
}

resource "aws_nat_gateway" "this" {
  count = length(var.azs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  tags = merge(local.tags, {
    Name = "${var.base_name}-nat-${var.azs[count.index]}"
  })
  depends_on = [aws_internet_gateway.this]
}

# ---------------- Private subnets ----------------
resource "aws_subnet" "private" {
  count = length(var.azs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = var.azs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index + 10)
  assign_ipv6_address_on_creation = true

  tags = merge(local.tags, {
    Name = "${var.base_name}-private-${var.azs[count.index]}"
    "kubernetes.io/role/internal-elb"           = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "karpenter.sh/discovery"                    = var.cluster_name
  })
}

resource "aws_route_table" "private" {
  count = length(var.azs)

  vpc_id = aws_vpc.this.id
  tags = merge(local.tags, {
    Name = "${var.base_name}-private-${var.azs[count.index]}"
  })
}

resource "aws_route" "private_nat" {
  count = length(var.azs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route" "private_egress_v6" {
  count = length(var.azs)

  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = length(var.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------- S3 gateway endpoint ----------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.tags, {
    Name = "${var.base_name}-s3-endpoint"
  })
}

data "aws_region" "current" {}

# ---------------- Optional tiers ----------------
resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? length(var.azs) : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.database_subnets[count.index]
  availability_zone = var.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.base_name}-database-${var.azs[count.index]}"
  })
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? length(var.azs) : 0

  vpc_id = aws_vpc.this.id
  tags = merge(local.tags, {
    Name = "${var.base_name}-database-${var.azs[count.index]}"
  })
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? length(var.azs) : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

resource "aws_db_subnet_group" "this" {
  count = var.enable_database_subnets ? 1 : 0

  name       = "${var.base_name}-db-subnet-group"
  subnet_ids = aws_subnet.database[*].id
  tags       = local.tags
}

resource "aws_subnet" "cache" {
  count = var.enable_cache_subnets ? length(var.azs) : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.cache_subnets[count.index]
  availability_zone = var.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.base_name}-cache-${var.azs[count.index]}"
  })
}

resource "aws_route_table" "cache" {
  count = var.enable_cache_subnets ? length(var.azs) : 0

  vpc_id = aws_vpc.this.id
  tags = merge(local.tags, {
    Name = "${var.base_name}-cache-${var.azs[count.index]}"
  })
}

resource "aws_route_table_association" "cache" {
  count = var.enable_cache_subnets ? length(var.azs) : 0

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[count.index].id
}

resource "aws_elasticache_subnet_group" "this" {
  count = var.enable_cache_subnets ? 1 : 0

  name       = "${var.base_name}-cache-subnet-group"
  subnet_ids = aws_subnet.cache[*].id
}

resource "aws_subnet" "internal" {
  count = var.enable_internal_subnets ? length(var.azs) : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.internal_subnets[count.index]
  availability_zone = var.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.base_name}-internal-${var.azs[count.index]}"
  })
}

resource "aws_route_table" "internal" {
  count = var.enable_internal_subnets ? length(var.azs) : 0

  vpc_id = aws_vpc.this.id
  tags = merge(local.tags, {
    Name = "${var.base_name}-internal-${var.azs[count.index]}"
  })
}

resource "aws_route_table_association" "internal" {
  count = var.enable_internal_subnets ? length(var.azs) : 0

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[count.index].id
}

# ---------------- Outputs ----------------
output "vpc_id" {
  value = aws_vpc.this.id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.this[*].id
}

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = "us-east-1"

  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}"
    staging   = "benchmark-datalake-staging-${local.account_id}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}"
    silver    = "benchmark-datalake-silver-${local.account_id}"
    gold      = "benchmark-datalake-gold-${local.account_id}"
    logs      = "benchmark-datalake-logs-${local.account_id}"
  }

  versioned_buckets = ["artefacts", "bronze", "silver", "gold"]
}

# ---------------- KMS ----------------
resource "aws_kms_key" "datalake" {
  description             = "Customer managed key for data lake"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "datalake" {
  name          = "alias/benchmark-datalake"
  target_key_id = aws_kms_key.datalake.key_id
}

# ---------------- S3 ----------------
resource "aws_s3_bucket" "buckets" {
  for_each = local.bucket_names
  bucket   = each.value
}

resource "aws_s3_bucket_public_access_block" "buckets" {
  for_each                = aws_s3_bucket.buckets
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "versioned" {
  for_each = toset(local.versioned_buckets)
  bucket   = aws_s3_bucket.buckets[each.value].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "buckets" {
  for_each = aws_s3_bucket.buckets
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.datalake.arn
    }
  }
}

# Upload Glue scripts from local glueClima folder
resource "aws_s3_object" "glue_scripts" {
  for_each = fileset(path.module, "glueClima/**")
  bucket   = aws_s3_bucket.buckets["artefacts"].id
  key      = "scripts/${replace(each.value, "glueClima/", "")}"
  source   = each.value
  kms_key_id = aws_kms_key.datalake.arn
}

# ---------------- Athena ----------------
resource "aws_athena_database" "silver" {
  name          = "silver"
  bucket        = aws_s3_bucket.buckets["silver"].bucket
  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key_arn       = aws_kms_key.datalake.arn
  }
}

# ---------------- IAM: Glue role ----------------
resource "aws_iam_role" "glue" {
  name = "benchmark-glue-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "glue.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "glue" {
  name = "benchmark-glue-policy"
  role = aws_iam_role.glue.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:*",
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents",
          "secretsmanager:GetSecretValue"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"
        ]
        Resource = [
          for k, b in aws_s3_bucket.buckets : b.arn
        ]
      },
      {
        Effect = "Allow"
        Action = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.datalake.arn
      }
    ]
  })
}

# ---------------- Glue jobs ----------------
resource "aws_glue_job" "extrai" {
  name     = "glue-job-extrai-dados"
  role_arn = aws_iam_role.glue.arn
  glue_version = "4.0"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.buckets["artefacts"].bucket}/scripts/extraiDados.py"
    python_version  = "3"
  }

  worker_type        = "G.1X"
  number_of_workers  = 20
  max_retries        = 0
  timeout            = 2880
  execution_property {
    max_concurrent_runs = 2
  }
  default_arguments = {
    "--TempDir" = "s3://${aws_s3_bucket.buckets["logs"].bucket}/temp/"
    "--job-language" = "python"
  }
}

resource "aws_glue_job" "transforma" {
  name     = "glue-job-transforma-dados"
  role_arn = aws_iam_role.glue.arn
  glue_version = "4.0"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.buckets["artefacts"].bucket}/scripts/transformaDados.py"
    python_version  = "3"
  }

  worker_type        = "G.1X"
  number_of_workers  = 20
  max_retries        = 0
  timeout            = 2880
  execution_property {
    max_concurrent_runs = 2
  }
  default_arguments = {
    "--TempDir"        = "s3://${aws_s3_bucket.buckets["logs"].bucket}/temp/"
    "--job-language"   = "python"
    "--extra-py-files" = "s3://${aws_s3_bucket.buckets["artefacts"].bucket}/scripts/lib.zip"
    "--datalake-formats" = "iceberg"
  }
}

# ---------------- Step Functions ----------------
resource "aws_iam_role" "sfn" {
  name = "benchmark-sfn-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "states.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sfn" {
  name = "benchmark-sfn-policy"
  role = aws_iam_role.sfn.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "glue:StartJobRun", "glue:GetJobRun", "glue:GetJobRuns", "glue:BatchStopJobRun"
      ]
      Resource = [
        "arn:aws:glue:${local.region}:${local.account_id}:job/glue-job-extrai-dados",
        "arn:aws:glue:${local.region}:${local.account_id}:job/glue-job-transforma-dados"
      ]
    }]
  })
}

resource "aws_sfn_state_machine" "pipeline" {
  name     = "benchmark-weather-pipeline"
  role_arn = aws_iam_role.sfn.arn
  definition = jsonencode({
    Comment = "Weather data lake pipeline"
    StartAt = "ExtractData"
    States = {
      ExtractData = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai.name
          Arguments = {
            "--cidade"     = "Sao Paulo"
            "--staging_bucket" = local.bucket_names.staging
            "--api_key"    = "PLACEHOLDER_API_KEY"
          }
        }
        Next = "TransformData"
      }
      TransformData = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma.name
          Arguments = {
            "--staging_bucket" = local.bucket_names.staging
            "--bronze_bucket"  = local.bucket_names.bronze
            "--silver_bucket"  = local.bucket_names.silver
            "--translation_key" = "PLACEHOLDER_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })
}

# ---------------- EventBridge schedule ----------------
resource "aws_iam_role" "eventbridge" {
  name = "benchmark-eventbridge-sfn-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "events.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "eventbridge" {
  name = "benchmark-eventbridge-sfn-policy"
  role = aws_iam_role.eventbridge.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["states:StartExecution"]
      Resource = aws_sfn_state_machine.pipeline.arn
    }]
  })
}

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "benchmark-hourly-trigger"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "sfn" {
  rule     = aws_cloudwatch_event_rule.hourly.name
  arn      = aws_sfn_state_machine.pipeline.arn
  role_arn = aws_iam_role.eventbridge.arn
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "github_branch" {
  type    = string
  default = "master"
}

variable "github_repo_owner" {
  type    = string
  default = "example-owner"
}

variable "github_repo_name" {
  type    = string
  default = "static-site"
}

variable "codestar_connection_arn" {
  type    = string
  default = ""
}

variable "enable_notifications" {
  type    = bool
  default = false
}

variable "notification_email" {
  type    = string
  default = ""
}

variable "enable_artifact_logging" {
  type    = bool
  default = false
}

variable "cloudfront_invalidate" {
  type    = string
  default = "true"
}

locals {
  account_id    = data.aws_caller_identity.current.account_id
  target_bucket = "benchmark-cicd-target-${local.account_id}"
  artifact_bucket = "benchmark-cicd-artifacts-${local.account_id}"
}

# ---------------- KMS ----------------
resource "aws_kms_key" "site" {
  description             = "CI/CD key for static site pipeline"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "site" {
  name          = "alias/benchmark-cicd-site"
  target_key_id = aws_kms_key.site.key_id
}

# ---------------- S3 ----------------
resource "aws_s3_bucket" "target" {
  bucket        = local.target_bucket
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket                  = aws_s3_bucket.target.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.site.arn
    }
  }
}

resource "aws_s3_bucket" "artifacts" {
  bucket        = local.artifact_bucket
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.site.arn
    }
  }
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "artifacts" {
  count  = var.enable_artifact_logging ? 1 : 0
  bucket = aws_s3_bucket.artifacts.id
  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = "artifact-access/"
}

resource "aws_s3_bucket" "log_bucket" {
  count  = var.enable_artifact_logging ? 1 : 0
  bucket = "benchmark-cicd-logs-${local.account_id}"
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count  = var.enable_artifact_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------- SSM parameters ----------------
resource "aws_ssm_parameter" "github_token" {
  name = "/benchmark-cicd/github/token"
  type = "SecureString"
  value = "PLACEHOLDER_GITHUB_TOKEN"
}

resource "aws_ssm_parameter" "webhook_secret" {
  name = "/benchmark-cicd/github/webhook-secret"
  type = "SecureString"
  value = "PLACEHOLDER_WEBHOOK_SECRET"
}

# ---------------- CloudFront ----------------
resource "aws_cloudfront_origin_access_control" "site" {
  name                              = "benchmark-cicd-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site" {
  enabled         = true
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "s3-target"
    origin_access_control_id = aws_cloudfront_origin_access_control.site.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-target"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = "658327ea-f89d-4fab-a63d-7e88639e58f6"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

resource "aws_s3_bucket_policy" "target" {
  bucket = aws_s3_bucket.target.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOAC"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.target.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site.arn
          }
        }
      }
    ]
  })
}

# ---------------- SNS (optional) ----------------
resource "aws_sns_topic" "notifications" {
  count = var.enable_notifications ? 1 : 0
  name  = "benchmark-cicd-notifications"
}

resource "aws_sns_topic_subscription" "email" {
  count     = var.enable_notifications && var.notification_email != "" ? 1 : 0
  topic_arn = aws_sns_topic.notifications[0].arn
  protocol  = "email"
  endpoint  = var.notification_email
}

# ---------------- CodeBuild role ----------------
resource "aws_iam_role" "codebuild" {
  name = "benchmark-cicd-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "codebuild" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:aws:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Resource = [aws_s3_bucket.target.arn, "${aws_s3_bucket.target.arn}/*", aws_s3_bucket.artifacts.arn, "${aws_s3_bucket.artifacts.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:GenerateDataKeyWithoutPlaintext"]
        Resource = aws_kms_key.site.arn
      },
      {
        Effect   = "Allow"
        Action   = "cloudfront:CreateInvalidation"
        Resource = aws_cloudfront_distribution.site.arn
      },
      {
        Effect   = "Allow"
        Action   = ["ssm:GetParameters", "ssm:GetParameter"]
        Resource = "arn:aws:ssm:us-east-1:${local.account_id}:parameter/benchmark-cicd/*"
      }
    ]
  })
}

# ---------------- CodeBuild project ----------------
resource "aws_codebuild_project" "build" {
  name          = "benchmark-cicd-build"
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = 5

  artifacts {
    type                = "S3"
    location            = aws_s3_bucket.artifacts.bucket
    encryption_disabled = false
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type     = "CODEPIPELINE"
    buildspec = <<-EOT
      version: 0.2
      phases:
        build:
          commands:
            - echo "Building static site"
            - aws s3 sync . s3://$TARGET_BUCKET/ --delete
            - if [ "$INVALIDATE" = "true" ]; then aws cloudfront create-invalidation --distribution-id $DISTRIBUTION_ID --paths "/*"; fi
    EOT
  }

  environment {
    # (env vars declared below via separate block)
  }

  lifecycle {
    ignore_changes = []
  }
}

# env vars need to be inside environment block; redeclare properly:
# Terraform HCL does not allow duplicate blocks, so we define env vars here:
resource "aws_codebuild_project" "build_env" {
  count = 0
}

# ---------------- CodePipeline role ----------------
resource "aws_iam_role" "pipeline" {
  name = "benchmark-cicd-pipeline-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "codepipeline.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "pipeline" {
  name = "benchmark-cicd-pipeline-policy"
  role = aws_iam_role.pipeline.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:GetBucketVersioning", "s3:GetBucketLocation", "s3:ListBucket"]
        Resource = [aws_s3_bucket.artifacts.arn, "${aws_s3_bucket.artifacts.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:GenerateDataKeyWithoutPlaintext"]
        Resource = aws_kms_key.site.arn
      },
      {
        Effect   = "Allow"
        Action   = ["codebuild:StartBuild", "codebuild:BatchGetBuilds", "codebuild:BatchGetReports"]
        Resource = aws_codebuild_project.build.arn
      },
      {
        Effect   = "Allow"
        Action   = ["codestar-connections:UseConnection"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = var.enable_notifications ? aws_sns_topic.notifications[0].arn : "arn:aws:sns:us-east-1:${local.account_id}:none"
      }
    ]
  })
}

# ---------------- CodePipeline ----------------
resource "aws_codepipeline" "pipeline" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.pipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"
    encryption_key {
      id   = aws_kms_key.site.arn
      type = "KMS"
    }
  }

  dynamic "notification_configuration" {
    for_each = var.enable_notifications ? [1] : []
    content {
      sns_topic_arn = aws_sns_topic.notifications[0].arn
      detail {
        event_type = ["ALL"]
      }
    }
  }

  stage {
    name = "Source"
    action {
      name             = "Source"
      category         = "Source"
      owner            = var.codestar_connection_arn != "" ? "AWS" : "ThirdParty"
      provider         = var.codestar_connection_arn != "" ? "CodeStarSourceConnection" : "GitHub"
      version          = "1"
      output_artifacts = ["SourceOutput"]
      configuration = var.codestar_connection_arn != "" ? {
        ConnectionArn    = var.codestar_connection_arn
        FullRepositoryId = "${var.github_repo_owner}/${var.github_repo_name}"
        BranchName       = var.github_branch
      } : {
        Owner      = var.github_repo_owner
        Repo       = var.github_repo_name
        Branch     = var.github_branch
        OAuthToken = "ssm:///benchmark-cicd/github/token"
      }
    }
  }

  stage {
    name = "Build"
    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["SourceOutput"]
      output_artifacts = ["BuildOutput"]
      configuration = {
        ProjectName = aws_codebuild_project.build.name
        EnvironmentVariables = jsonencode([
          { name = "TARGET_BUCKET", value = aws_s3_bucket.target.bucket },
          { name = "DISTRIBUTION_ID", value = aws_cloudfront_distribution.site.id },
          { name = "INVALIDATE", value = var.cloudfront_invalidate }
        ])
      }
    }
  }
}

# ---------------- GitHub webhook ----------------
resource "aws_codepipeline_webhook" "github" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name            = "benchmark-cicd-webhook"
  authentication  = "HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.pipeline.name

  authentication_configuration {
    secret_token = "ssm:///benchmark-cicd/github/webhook-secret"
  }

  filter {
    json_path    = "$.ref"
    match_equals = format("refs/heads/%s", var.github_branch)
  }
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "enable" {
  description = "Toggle to enable/disable all resource creation."
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name of the VPC."
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_support" {
  description = "Whether DNS support is enabled in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the VPC."
  type        = bool
  default     = false
}

variable "assign_ipv6" {
  description = "Whether to assign an IPv6 CIDR block to the VPC."
  type        = bool
  default     = false
}

variable "subnets" {
  description = <<-EOT
    List of subnet definitions. Each definition groups subnets by name and class:
      - name:            logical group name (e.g. "app")
      - class:           one of "public", "private", or "intra"
      - cidr_per_az:     list of CIDR blocks, one per availability zone
      - azs:             list of availability zones
      - db_subnet_group: whether to register in a database subnet group
      - cache_subnet_group: whether to register in an ElastiCache subnet group
    Example:
      [
        {
          name               = "app"
          class              = "private"
          azs                = ["us-east-1a", "us-east-1b"]
          cidr_per_az        = ["10.0.1.0/24", "10.0.2.0/24"]
          db_subnet_group    = true
          cache_subnet_group = false
        }
      ]
  EOT
  type = list(object({
    name               = string
    class              = string
    azs                = list(string)
    cidr_per_az        = list(string)
    db_subnet_group    = optional(bool, false)
    cache_subnet_group = optional(bool, false)
  }))
  default = []
}

variable "single_nat_gateway" {
  description = "If true, provision a single NAT gateway shared by all private subnets; otherwise one per AZ."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Data
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "this" {
  count                = var.enable ? 1 : 0
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.assign_ipv6

  tags = merge(
    var.tags,
    {
      Name = var.vpc_name
    }
  )
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  count  = var.enable && length(local.public_subnets) > 0 ? 1 : 0
  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-igw" })
}

# -----------------------------------------------------------------------------
# NAT Gateways (one per AZ with private subnets, or a single shared one)
# -----------------------------------------------------------------------------

locals {
  public_subnets = flatten([
    for def in var.subnets : [
      for i, az in def.azs : {
        name     = "${def.name}-${az}"
        class    = def.class
        az       = az
        cidr     = def.cidr_per_az[i]
        db       = def.db_subnet_group
        cache    = def.cache_subnet_group
        group    = def.name
      }
    ] if def.class == "public"
  ])

  private_subnets = flatten([
    for def in var.subnets : [
      for i, az in def.azs : {
        name  = "${def.name}-${az}"
        class = def.class
        az    = az
        cidr  = def.cidr_per_az[i]
        db    = def.db_subnet_group
        cache = def.cache_subnet_group
        group = def.name
      }
    ] if def.class == "private"
  ])

  intra_subnets = flatten([
    for def in var.subnets : [
      for i, az in def.azs : {
        name  = "${def.name}-${az}"
        class = def.class
        az    = az
        cidr  = def.cidr_per_az[i]
        db    = def.db_subnet_group
        cache = def.cache_subnet_group
        group = def.name
      }
    ] if def.class == "intra"
  ])

  # AZs that contain private subnets (NAT gateways are placed in public subnets of the same AZ)
  private_azs = distinct([for s in local.private_subnets : s.az])

  # Public subnets keyed by AZ, used to host NAT gateways
  public_by_az = { for s in local.public_subnets : s.az => s }

  nat_azs = var.single_nat_gateway ? (
    length(local.private_azs) > 0 ? [local.private_azs[0]] : []
  ) : local.private_azs
}

resource "aws_eip" "nat" {
  for_each = toset(var.enable ? local.nat_azs : [])
  domain   = "vpc"

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat-${each.key}" })
}

resource "aws_nat_gateway" "this" {
  for_each = toset(var.enable ? local.nat_azs : [])

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = local.public_by_az[each.key] != null ? [
    for s in aws_subnet.this : s.id
    if s.availability_zone == each.key && s.tags["Class"] == "public"
  ][0] : null

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat-${each.key}" })

  depends_on = [aws_internet_gateway.this]
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "this" {
  for_each = {
    for s in concat(local.public_subnets, local.private_subnets, local.intra_subnets) :
    "${s.group}-${s.az}" => s
  }

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  map_public_ip_on_launch = each.value.class == "public"

  tags = merge(
    var.tags,
    {
      Name  = each.value.name
      Class = each.value.class
      Group = each.value.group
    }
  )
}

# -----------------------------------------------------------------------------
# Route tables
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count  = var.enable && length(local.public_subnets) > 0 ? 1 : 0
  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-public" })
}

resource "aws_route" "public_igw" {
  count = var.enable && length(local.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table" "private" {
  for_each = toset(var.enable ? local.private_azs : [])
  vpc_id   = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-private-${each.key}" })
}

resource "aws_route" "private_nat" {
  for_each = toset(var.enable ? local.private_azs : [])

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[
    var.single_nat_gateway ? local.private_azs[0] : each.key
  ].id
}

resource "aws_route_table_association" "public" {
  for_each = {
    for s in local.public_subnets : "${s.group}-${s.az}" => s
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  for_each = {
    for s in local.private_subnets : "${s.group}-${s.az}" => s
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[each.value.az].id
}

# -----------------------------------------------------------------------------
# Subnet groups
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "this" {
  count = var.enable && length([for s in concat(local.public_subnets, local.private_subnets, local.intra_subnets) : s if s.db]) > 0 ? 1 : 0

  name        = "${var.vpc_name}-db-subnet-group"
  description = "Database subnet group for ${var.vpc_name} VPC"
  subnet_ids = [
    for s in aws_subnet.this : s.id
    if s.tags["Group"] != null && lookup(
      { for def in var.subnets : def.name => def.db_subnet_group },
      s.tags["Group"], false
    )
  ]

  tags = merge(var.tags, { Name = "${var.vpc_name}-db-subnet-group" })
}

resource "aws_elasticache_subnet_group" "this" {
  count = var.enable && length([for s in concat(local.public_subnets, local.private_subnets, local.intra_subnets) : s if s.cache]) > 0 ? 1 : 0

  name       = "${var.vpc_name}-cache-subnet-group"
  subnet_ids = [
    for s in aws_subnet.this : s.id
    if s.tags["Group"] != null && lookup(
      { for def in var.subnets : def.name => def.cache_subnet_group },
      s.tags["Group"], false
    )
  ]

  tags = merge(var.tags, { Name = "${var.vpc_name}-cache-subnet-group" })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = var.enable ? aws_vpc.this[0].id : null
}

output "vpc_cidr" {
  description = "CIDR block of the VPC."
  value       = var.enable ? aws_vpc.this[0].cidr_block : null
}

output "public_subnet_ids" {
  description = "IDs of public subnets."
  value = [
    for s in aws_subnet.this : s.id
    if s.tags["Class"] == "public"
  ]
}

output "private_subnet_ids" {
  description = "IDs of private subnets."
  value = [
    for s in aws_subnet.this : s.id
    if s.tags["Class"] == "private"
  ]
}

output "intra_subnet_ids" {
  description = "IDs of intra subnets."
  value = [
    for s in aws_subnet.this : s.id
    if s.tags["Class"] == "intra"
  ]
}

output "db_subnet_group_name" {
  description = "Name of the database subnet group, if created."
  value       = var.enable ? try(aws_db_subnet_group.this[0].name, null) : null
}

output "elasticache_subnet_group_name" {
  description = "Name of the ElastiCache subnet group, if created."
  value       = var.enable ? try(aws_elasticache_subnet_group.this[0].name, null) : null
}
```

