```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "queue_name" {
  description = "Name of the dead-letter queue"
  type        = string
  default     = "aggregation-lambda-dead-letter-queue"
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (14 days)"
  type        = number
  default     = 1209600
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_kms_key" "sqs_key" {
  description             = "KMS key for SQS dead-letter queue encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "Allow SQS to use the key"
        Effect    = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "sqs-dlq-encryption-key"
  }
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/${var.queue_name}-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

resource "aws_sqs_queue" "dlq" {
  name                      = var.queue_name
  message_retention_seconds = var.message_retention_seconds
  kms_master_key_id         = aws_kms_key.sqs_key.key_id
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Name        = var.queue_name
    Environment = "production"
    Purpose     = "dead-letter-queue"
  }
}

output "queue_url" {
  description = "URL of the dead-letter queue"
  value       = aws_sqs_queue.dlq.url
}

output "queue_arn" {
  description = "ARN of the dead-letter queue"
  value       = aws_sqs_queue.dlq.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encryption"
  value       = aws_kms_key.sqs_key.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which the SQS queue will be created."
  type        = string
  default     = "us-east-1"
}

resource "aws_sqs_queue" "standard_queue" {
  # The 'name' attribute is intentionally omitted so that Terraform
  # auto-generates a unique queue name (standard, non-FIFO queue).

  # Visibility timeout: message is hidden from other consumers for 30 seconds after retrieval.
  visibility_timeout_seconds = 30

  # Message retention period: messages are retained for 345600 seconds (4 days).
  message_retention_seconds = 345600

  # Maximum message size: 262144 bytes (256 KB).
  max_message_size = 262144

  # Delivery delay: 0 seconds, messages are available immediately.
  delay_seconds = 0

  # Long-polling wait time: 0 seconds, ReceiveMessage returns immediately (short polling).
  receive_wait_time_seconds = 0

  # Server-side encryption using the SQS-managed key.
  sqs_managed_sse_enabled = true

  tags = {
    Name      = "standard-sqs-queue"
    ManagedBy = "terraform"
  }
}

output "queue_name" {
  description = "The auto-generated name of the SQS queue."
  value       = aws_sqs_queue.standard_queue.name
}

output "queue_url" {
  description = "The URL of the SQS queue."
  value       = aws_sqs_queue.standard_queue.url
}

output "queue_arn" {
  description = "The ARN of the SQS queue."
  value       = aws_sqs_queue.standard_queue.arn
}

