provider "aws" {
  region = "us-east-1"
}

variable "default_sms_type" {
  description = "The default SMS type (Transactional or Promotional)"
  type        = string
  default     = "Transactional"
}

variable "default_sender_id" {
  description = "Default sender ID (leave empty to unset)"
  type        = string
  default     = ""
}

variable "monthly_spend_limit" {
  description = "Monthly SMS spend limit in USD (leave empty to unset)"
  type        = string
  default     = ""
}

variable "delivery_status_iam_role_arn" {
  description = "IAM role ARN for delivery status reporting (leave empty to unset)"
  type        = string
  default     = ""
}

variable "delivery_status_success_sampling_rate" {
  description = "Percentage of successful deliveries for which stats are sampled (0-100)"
  type        = number
  default     = 0
}

variable "usage_report_s3_bucket" {
  description = "S3 bucket for usage reports (leave empty to unset)"
  type        = string
  default     = ""
}

resource "aws_sns_sms_preferences" "this" {
  default_sms_type                        = var.default_sms_type
  default_sender_id                       = var.default_sender_id != "" ? var.default_sender_id : null
  monthly_spend_limit                     = var.monthly_spend_limit != "" ? var.monthly_spend_limit : null
  delivery_status_iam_role_arn            = var.delivery_status_iam_role_arn != "" ? var.delivery_status_iam_role_arn : null
  delivery_status_success_sampling_rate   = var.delivery_status_success_sampling_rate
  usage_report_s3_bucket                  = var.usage_report_s3_bucket != "" ? var.usage_report_s3_bucket : null
}

output "default_sms_type" {
  description = "Configured default SMS type"
  value       = aws_sns_sms_preferences.this.default_sms_type
}

output "delivery_status_success_sampling_rate" {
  description = "Configured delivery status success sampling rate"
  value       = aws_sns_sms_preferences.this.delivery_status_success_sampling_rate
}

output "default_sender_id" {
  description = "Configured default sender ID (empty if unset)"
  value       = var.default_sender_id
}

output "monthly_spend_limit" {
  description = "Configured monthly spend limit (empty if unset)"
  value       = var.monthly_spend_limit
}

output "delivery_status_iam_role_arn" {
  description = "Configured delivery status IAM role ARN (empty if unset)"
  value       = var.delivery_status_iam_role_arn
}

output "usage_report_s3_bucket" {
  description = "Configured usage report S3 bucket (empty if unset)"
  value       = var.usage_report_s3_bucket
}
