# Enable SSM Automation to deliver script output to CloudWatch Logs
resource "aws_ssm_service_setting" "automation_cloudwatch_logging" {
  count       = var.enable ? 1 : 0
  setting_id  = "arn:aws:ssm:us-east-1:${data.aws_caller_identity.current.account_id}:servicesetting/ssm/automation/customer-execute-script-log-group"
  setting_value = var.log_group_name
}

# Disable public sharing of Systems Manager documents
resource "aws_ssm_service_setting" "disable_public_sharing" {
  count         = var.enable ? 1 : 0
  setting_id    = "arn:aws:ssm:us-east-1:${data.aws_caller_identity.current.account_id}:servicesetting/ssm/documents/public-sharing-permission"
  setting_value = "Disable"
