terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Fetch the TLS certificate chain of the GitHub OIDC issuer to derive CA thumbprints
data "tls_certificate" "github_oidc" {
  url = "https://token.actions.githubusercontent.com"
}

# GitHub's two published thumbprints
locals {
  github_published_thumbprints = [
    "6938fd4d98bab03faadb97c347354a6eb8db0d40",
    "6938fd4d98bab03faadb97c347354a6eb8db0d41",
  ]

  # CA fingerprints from the fetched certificate chain
  fetched_thumbprints = [
    for cert in data.tls_certificate.github_oidc.certificates :
    cert.sha1_fingerprint
  ]

  # Combined, de-duplicated thumbprint list
  combined_thumbprints = toset(concat(local.fetched_thumbprints, local.github_published_thumbprints))
}

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = tolist(local.combined_thumbprints)

  tags = {
    Name        = "github-actions-oidc"
    Environment = "shared"
  }
}

# ---------------------------------------------------------------------------
# Optional GitHub-federated IAM roles.
# Disabled by default: github_federated_roles defaults to an empty map,
# so no roles are created unless explicitly configured.
# ---------------------------------------------------------------------------
variable "github_federated_roles" {
  description = "Map of role names to role configuration for GitHub-federated IAM roles. Empty by default (no roles created)."
  type = map(object({
    github_organization = string
    github_repository   = optional(string)
    allowed_branches    = optional(list(string), ["main"])
    managed_policy_arns = optional(list(string), [])
    max_session_duration = optional(number, 3600)
  }))
  default = {}
}

data "aws_iam_policy_document" "github_federated_trust" {
  for_each = var.github_federated_roles

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values = concat(
        [
          for branch in each.value.allowed_branches :
          "repo:${each.value.github_organization}/${coalesce(each.value.github_repository, "*")}:ref:refs/heads/${branch}"
        ],
        [
          "repo:${each.value.github_organization}/${coalesce(each.value.github_repository, "*")}:environment:*"
        ]
      )
    }
  }
}

resource "aws_iam_role" "github_federated" {
  for_each = var.github_federated_roles

  name                 = each.key
  max_session_duration = each.value.max_session_duration
  assume_role_policy   = data.aws_iam_policy_document.github_federated_trust[each.key].json

  tags = {
    Name        = each.key
    FederatedBy = "github-actions-oidc"
  }
}

resource "aws_iam_role_policy_attachment" "github_federated" {
  for_each = var.github_federated_roles

  role       = aws_iam_role.github_federated[each.key].name
  policy_arn = each.value.managed_policy_arns[0]
}

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github_actions.arn
}

output "federated_role_arns" {
  description = "ARNs of any created GitHub-federated IAM roles (empty by default)."
  value       = { for k, r in aws_iam_role.github_federated : k => r.arn }
}

