terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "github_repository_patterns" {
  description = "List of GitHub repository subject patterns allowed to assume the role (e.g. 'org/repo:ref:refs/heads/main'). Empty means no subject condition is applied."
  type        = list(string)
  default     = []
}

variable "role_name" {
  description = "Name of the IAM role for GitHub Actions."
  type        = string
  default     = "github-actions-role"
}

variable "managed_policy_arns" {
  description = "List of managed policy ARNs to attach to the role."
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "oidc_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/token.actions.githubusercontent.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    dynamic "condition" {
      for_each = length(var.github_repository_patterns) > 0 ? [1] : []
      content {
        test     = "StringLike"
        variable = "token.actions.githubusercontent.com:sub"
        values   = var.github_repository_patterns
      }
    }
  }
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

resource "aws_iam_role" "github_actions" {
  name                 = var.role_name
  path                 = "/"
  description          = "IAM role assumed by GitHub Actions via OIDC"
  assume_role_policy   = data.aws_iam_policy_document.oidc_trust.json
  managed_policy_arns  = var.managed_policy_arns
  force_detach_policies = true
}

output "role_arn" {
  description = "ARN of the GitHub Actions IAM role"
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions IAM role"
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions IAM role"
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Unique ID of the GitHub Actions IAM role"
  value       = aws_iam_role.github_actions.unique_id
}

```hcl
provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "managed_force_mfa" {
  statement {
    sid = "AllowViewAccountInfo"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
    ]
    resources = ["*"]
  }

  statement {
    sid = "AllowManageOwnPasswords"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = ["arn:aws:iam::*:user/${aws_iam_user.example.user_name}"]
  }

  statement {
    sid = "AllowManageOwnVirtualMFA"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableVirtualMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [
      "arn:aws:iam::*:mfa/*",
      "arn:aws:iam::*:user/${aws_iam_user.example.user_name}",
    ]
  }

  statement {
    sid = "AllowManageOwnMFAWhenSignedInWithMFA"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [
      "arn:aws:iam::*:mfa/*",
      "arn:aws:iam::*:user/${aws_iam_user.example.user_name}",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid = "AllowSelfInspectionWhenSignedInWithMFA"
    actions = [
      "iam:GetLoginProfile",
      "iam:ListGroupsForUser",
      "iam:ListMFADevices",
      "iam:ListAttachedUserPolicies",
      "iam:ListUserPolicies",
      "iam:ListAccessKeys",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
    ]
    resources = ["arn:aws:iam::*:user/${aws_iam_user.example.user_name}"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_user" "example" {
  name = "example-user"
  path = "/"
}

resource "aws_iam_policy" "managed_force_mfa" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows self-service password and MFA management; MFA deactivation and self-inspection require MFA"
  policy      = data.aws_iam_policy_document.managed_force_mfa.json
}

resource "aws_iam_user_policy_attachment" "example" {
  user       = aws_iam_user.example.name
  policy_arn = aws_iam_policy.managed_force_mfa.arn
}

output "policy_arn" {
  value = aws_iam_policy.managed_force_mfa.arn
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "password_length" {
  description = "Length of generated console passwords"
  type        = number
  default     = 8
}

# ---------------- Groups ----------------

resource "aws_iam_group" "billing" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport" {
  name = "SuportGroup"
}

# ---------------- Policies ----------------

resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost report, and pricing visibility"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingReadOnly"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "budgets:ViewBudget",
          "cur:DescribeReportDefinitions",
          "cur:GetReportDefinitions",
          "cur:ListReportDefinitions",
          "pricing:GetProducts",
          "pricing:GetAttributeValues",
          "pricing:DescribeServices"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only describe, get, and list access to EC2, S3, CloudWatch, and RDS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SupportReadOnly"
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "rds:Describe*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------- Group policy attachments ----------------

resource "aws_iam_group_policy_attachment" "billing" {
  group      = aws_iam_group.billing.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin" {
  group      = aws_iam_group.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport" {
  group      = aws_iam_group.suport.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# ---------------- Users ----------------

resource "aws_iam_user" "billing" {
  name = "Billing"
}

resource "aws_iam_user" "admin" {
  name = "Admin"
}

resource "aws_iam_user" "suport" {
  name = "Suport"
}

# ---------------- Group memberships ----------------

resource "aws_iam_user_group_membership" "billing" {
  user  = aws_iam_user.billing.name
  groups = [aws_iam_group.billing.name]
}

resource "aws_iam_user_group_membership" "admin" {
  user  = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "suport" {
  user  = aws_iam_user.suport.name
  groups = [aws_iam_group.suport.name]
}

# ---------------- Login profiles ----------------

resource "aws_iam_user_login_profile" "billing" {
  user                    = aws_iam_user.billing.name
  password_length         = var.password_length
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "admin" {
  user                    = aws_iam_user.admin.name
  password_length         = var.password_length
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "suport" {
  user                    = aws_iam_user.suport.name
  password_length         = var.password_length
  password_reset_required = true
}

# ---------------- Outputs ----------------

output "billing_username" {
  value = aws_iam_user.billing.name
}

output "billing_password" {
  value     = aws_iam_user_login_profile.billing.password
  sensitive = true
}

output "admin_username" {
  value = aws_iam_user.admin.name
}

output "admin_password" {
  value     = aws_iam_user_login_profile.admin.password
  sensitive = true
}

output "suport_username" {
  value = aws_iam_user.suport.name
}

output "suport_password" {
  value     = aws_iam_user_login_profile.suport.password
  sensitive = true
}
