  role = aws_iam_role.comprehend_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::nlp-pipeline-bucket/*"
