```hcl
###############################################################################
# Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "organizational_units" {
  description = <<-EOT
    Optional list of slash-delimited organizational unit paths to create beneath
    the organization root, up to five levels deep.
    Example: ["Workloads/Production/App1", "Workloads/Sdlc", "Security", "Sandbox"]
    Defaults to an empty list, which creates no organizational units.
  EOT
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for path in var.organizational_units :
      length([for segment in split("/", trimspace(path)) : trimspace(segment) if trimspace(segment) != ""]) <= 5
    ])
    error_message = "Each organizational unit path may contain at most 5 slash-delimited levels."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Normalize every requested path: trim whitespace and drop empty segments.
  path_segments = [
    for path in var.organizational_units :
    [for segment in split("/", trimspace(path)) : trimspace(segment) if trimspace(segment) != ""]
  ]

  # Distinct, fully-joined normalized paths (empty/invalid paths are ignored).
  normalized_paths = distinct([
    for segments in local.path_segments : join("/", segments) if length(segments) > 0
  ])

  # Unique path prefixes per hierarchy level (level N = first N segments of a path).
  level_1_paths = distinct([for path in local.normalized_paths : split("/", path)[0]])
  level_2_paths = distinct([for path in local.normalized_paths : join("/", slice(split("/", path), 0, 2)) if length(split("/", path)) >= 2])
  level_3_paths = distinct([for path in local.normalized_paths : join("/", slice(split("/", path), 0, 3)) if length(split("/", path)) >= 3])
  level_4_paths = distinct([for path in local.normalized_paths : join("/", slice(split("/", path), 0, 4)) if length(split("/", path)) >= 4])
  level_5_paths = distinct([for path in local.normalized_paths : join("/", slice(split("/", path), 0, 5)) if length(split("/", path)) >= 5])

  root_id = aws_organizations_organization.this.roots[0].id
}

###############################################################################
# AWS Organization (all features, policy types enabled on the root)
###############################################################################

resource "aws_organizations_organization" "this" {
  feature_set = "ALL"

  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]

  aws_service_access_principals = [
    "backup.amazonaws.com",
  ]
}

###############################################################################
# Organizational units (optionally up to five nested levels)
###############################################################################

# Level 1: direct children of the organization root.
resource "aws_organizations_organizational_unit" "level_1" {
  for_each  = toset(local.level_1_paths)
  name      = each.value
  parent_id = local.root_id
}

# Level 2: children of level 1 OUs.
resource "aws_organizations_organizational_unit" "level_2" {
  for_each  = toset(local.level_2_paths)
  name      = split("/", each.value)[1]
  parent_id = aws_organizations_organizational_unit.level_1[split("/", each.value)[0]].id
}

# Level 3: children of level 2 OUs.
resource "aws_organizations_organizational_unit" "level_3" {
  for_each  = toset(local.level_3_paths)
  name      = split("/", each.value)[2]
  parent_id = aws_organizations_organizational_unit.level_2[join("/", slice(split("/", each.value), 0, 2))].id
}

# Level 4: children of level 3 OUs.
resource "aws_organizations_organizational_unit" "level_4" {
  for_each  = toset(local.level_4_paths)
  name      = split("/", each.value)[3]
  parent_id = aws_organizations_organizational_unit.level_3[join("/", slice(split("/", each.value), 0, 3))].id
}

# Level 5: children of level 4 OUs (deepest supported level).
resource "aws_organizations_organizational_unit" "level_5" {
  for_each  = toset(local.level_5_paths)
  name      = split("/", each.value)[4]
  parent_id = aws_organizations_organizational_unit.level_4[join("/", slice(split("/", each.value), 0, 4))].id
}

###############################################################################
# Outputs
###############################################################################

output "organization_id" {
  description = "Identifier of the AWS Organization."
  value       = aws_organizations_organization.this.id
}

output "organization_arn" {
  description = "ARN of the AWS Organization."
  value       = aws_organizations_organization.this.arn
}

output "root_id" {
  description = "Identifier of the organization root."
  value       = local.root_id
}

output "organizational_unit_ids" {
  description = "Map of organizational unit full path to organizational unit id (empty if no paths were supplied)."
  value = merge(
    { for path, ou in aws_organizations_organizational_unit.level_1 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_2 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_3 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_4 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_5 : path => ou.id },
  )
}
```

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name         = "swe-vpc"
    ResourceGroup = "default"
  }
}

resource "aws_default_network_acl" "default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = "10.0.0.0/16"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 200
    action     = "deny"
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 300
    action     = "deny"
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = "10.0.0.0/16"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "swe-vpc-default_acl"
  }
}

resource "aws_default_security_group" "default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  ingress {
    description = "Allow ICMP echo (ping) from anywhere"
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 8
    to_port     = 0
  }

  ingress {
    description = "Allow HTTP from anywhere"
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 80
    to_port     = 80
  }

  egress {
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 0
    to_port     = 0
  }

  tags = {
    Name = "swe-vpc-default_sg"
  }
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpcs" {
  description = "VPC definitions for dev and rec environments"
  type = map(object({
    cidr = string
  }))
  default = {
    dev = { cidr = "10.16.0.0/16" }
    rec = { cidr = "10.32.0.0/16" }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "vpc" {
  for_each             = var.vpcs
  cidr_block           = each.value.cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_${each.key}"
  }
}

resource "aws_internet_gateway" "gw" {
  for_each = var.vpcs
  vpc_id   = aws_vpc.vpc[each.key].id

  tags = {
    Name = "gatway_${each.key}"
  }
}

resource "aws_route" "default_internet_ipv4" {
  for_each               = var.vpcs
  route_table_id         = aws_vpc.vpc[each.key].main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw[each.key].id
}

resource "aws_route" "default_internet_ipv6" {
  for_each                        = var.vpcs
  route_table_id                  = aws_vpc.vpc[each.key].main_route_table_id
  destination_ipv6_cidr_block     = "::/0"
  gateway_id                      = aws_internet_gateway.gw[each.key].id
}

locals {
  subnet_specs = {
    public_a   = { offset = 12, az_index = 0, type = "public" }
    public_b   = { offset = 11, az_index = 1, type = "public" }
    internal_a = { offset = 1, az_index = 0, type = "internal" }
    internal_b = { offset = 2, az_index = 1, type = "internal" }
    external_a = { offset = 5, az_index = 0, type = "external" }
    external_b = { offset = 6, az_index = 1, type = "external" }
  }
}

resource "aws_subnet" "subnet" {
  for_each = {
    for pair in setproduct(keys(var.vpcs), keys(local.subnet_specs)) :
    "${pair[0]}_${pair[1]}" => {
      env    = pair[0]
      spec   = local.subnet_specs[pair[1]]
      vpc    = var.vpcs[pair[0]]
    }
  }

  vpc_id            = aws_vpc.vpc[each.value.env].id
  cidr_block        = cidrsubnet(each.value.vpc.cidr, 8, each.value.spec.offset)
  availability_zone = data.aws_availability_zones.available.names[each.value.spec.az_index]
  map_public_ip_on_launch = each.value.spec.type == "public"

  tags = {
    Name = "subnet_${each.value.env}_${each.value.spec.type}_${each.value.spec.az_index == 0 ? "a" : "b"}"
  }
}

output "vpc_dev_id" {
  description = "ID of the development VPC"
  value       = aws_vpc.vpc["dev"].id
}

output "vpc_rec_id" {
  description = "ID of the recette (staging) VPC"
  value       = aws_vpc.vpc["rec"].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  description = "Namespace for Cloud Posse label conventions"
  type        = string
  default     = "security"
}

variable "environment" {
  description = "Environment for Cloud Posse label conventions"
  type        = string
  default     = "prod"
}

variable "stage" {
  description = "Stage for Cloud Posse label conventions"
  type        = string
  default     = "guardduty"
}

variable "name" {
  description = "Name for Cloud Posse label conventions"
  type        = string
  default     = "detector"
}

variable "attributes" {
  description = "Additional attributes for Cloud Posse label conventions"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "enable_s3_protection" {
  description = "Enable S3 protection feature (disabled per business requirement)"
  type        = bool
  default     = false
}

variable "finding_publishing_frequency" {
  description = "Finding publishing frequency; null uses the service default"
  type        = string
  default     = null
}

variable "enable_eventbridge_notifications" {
  description = "Whether to create EventBridge rule and SNS topic for GuardDuty findings (disabled by default)"
  type        = bool
  default     = false
}

variable "sns_topic_subscribers" {
  description = "List of email addresses to subscribe to the SNS topic when notifications are enabled"
  type        = list(string)
  default     = []
}

module "label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"

  namespace  = var.namespace
  environment = var.environment
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_protection
    }
  }

  tags = module.label.tags
}

# ---------------------------------------------------------------------------
# Optional EventBridge rule and SNS topic notifications for GuardDuty findings.
# All resources below are disabled by default (count = 0), so no topic,
# topic policy, or event rule is created unless explicitly enabled.
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "findings" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  name   = "${module.label.id}-findings"
  tags   = module.label.tags
}

resource "aws_sns_topic_policy" "findings" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  arn    = aws_sns_topic.findings[0].arn
  policy = data.aws_iam_policy_document.findings_sns[count.index].json
}

data "aws_iam_policy_document" "findings_sns" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  statement {
    sid       = "AllowEventBridgePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_subscription" "findings" {
  count = var.enable_eventbridge_notifications ? length(var.sns_topic_subscribers) : 0

  topic_arn = aws_sns_topic.findings[0].arn
  protocol  = "email"
  endpoint  = var.sns_topic_subscribers[count.index]
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  name        = "${module.label.id}-findings"
  description = "Capture GuardDuty findings"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = module.label.tags
}

resource "aws_cloudwatch_event_target" "guardduty_findings" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  rule = aws_cloudwatch_event_rule.guardduty_findings[0].name
  arn  = aws_sns_topic.findings[0].arn
}

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector"
  value       = aws_guardduty_detector.this.id
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic for findings (null when notifications are disabled)"
  value       = var.enable_eventbridge_notifications ? aws_sns_topic.findings[0].arn : null
}

output "eventbridge_rule_arn" {
  description = "ARN of the EventBridge rule for findings (null when notifications are disabled)"
  value       = var.enable_eventbridge_notifications ? aws_cloudwatch_event_rule.guardduty_findings[0].arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

# KMS key with rotation enabled
resource "aws_kms_key" "backup_key" {
  description             = "KMS key for ${local.prefix}-backup-vault"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "${local.prefix}-backup-key"
  }
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/${local.prefix}-backup-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

# Backup vault encrypted with the KMS key
resource "aws_backup_vault" "backup_vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

# Backup plan
resource "aws_backup_plan" "backup_plan" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 12 * * ? *)"

    lifecycle {
      delete_after = 90
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

# IAM role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "${local.prefix}-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup selection
resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.backup_plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

output "backup_vault_name" {
  value = aws_backup_vault.backup_vault.name
}

output "backup_plan_name" {
  value = aws_backup_plan.backup_plan.name
}

output "backup_role_name" {
  value = aws_iam_role.backup_role.name
}

output "kms_key_arn" {
  value = aws_kms_key.backup_key.arn
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "pool" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
    require_lowercase = false
  }
}

resource "aws_cognito_user_pool_domain" "domain" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.pool.id
}

resource "aws_iam_role" "auth_role" {
  name = "coop-tweets_cognito_auth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "unauth_role" {
  name = "coop-tweets_cognito_unauth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "auth_policy" {
  name = "cognito_kibana_auth_coop-tweets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "unauth_policy" {
  name = "cognito_kibana_unauth_coop-tweets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "auth_attach" {
  role       = aws_iam_role.auth_role.name
  policy_arn = aws_iam_policy.auth_policy.arn
}

resource "aws_iam_role_policy_attachment" "unauth_attach" {
  role       = aws_iam_role.unauth_role.name
  policy_arn = aws_iam_policy.unauth_policy.arn
}

resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }

  roles = {
    authenticated   = aws_iam_role.auth_role.arn
    unauthenticated = aws_iam_role.unauth_role.arn
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name         = "coop-tweets-client"
  user_pool_id = aws_cognito_user_pool.pool.id
}

resource "aws_cognito_identity_pool_roles_attachment" "roles_attachment" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    authenticated   = aws_iam_role.auth_role.arn
    unauthenticated = aws_iam_role.unauth_role.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_findings_export" {
  description = "Whether to export GuardDuty findings to S3"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# GuardDuty Detector
resource "aws_guardduty_detector" "main" {
  enable = true

  datasources {
    s3_logs {
      enable = true
    }
    malware_protection {
      scan_ec2_instance {
        ebs_volumes {
          enable = true
        }
      }
    }
  }

  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

# KMS Key for GuardDuty findings export encryption
resource "aws_kms_key" "guardduty" {
  description             = "KMS key for GuardDuty findings export encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowGuardDutyToEncryptFindings"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

# EventBridge rule for GuardDuty Finding events
resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name        = "guardduty-finding-events"
  description = "Matches GuardDuty Finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

# Optional S3 findings export (disabled by default)
resource "aws_s3_bucket" "findings" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = "guardduty-findings-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count                   = var.enable_findings_export ? 1 : 0
  bucket                  = aws_s3_bucket.findings[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "findings" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGuardDutyPutObject"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "AllowGuardDutyGetBucket"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = "s3:GetBucketLocation"
        Resource  = aws_s3_bucket.findings[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_guardduty_publishing_destination" "findings" {
  count         = var.enable_findings_export ? 1 : 0
  detector_id   = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.findings[0].arn
  kms_key_arn   = aws_kms_key.guardduty.arn

  depends_on = [aws_s3_bucket_policy.findings]
}

output "detector_id" {
  value = aws_guardduty_detector.main.id
}

output "kms_key_arn" {
  value = aws_kms_key.guardduty.arn
}

output "event_rule_arn" {
  value = aws_cloudwatch_event_rule.guardduty_findings.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "private_bucket" {
  bucket_prefix = "private-bucket-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "private_bucket" {
  depends_on = [
    aws_s3_bucket_ownership_controls.private_bucket,
    aws_s3_bucket_public_access_block.private_bucket
  ]

  bucket = aws_s3_bucket.private_bucket.id
  acl    = "private"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# Trust policy: current account principals only, MFA required
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "role_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# -----------------------------------------------------------------------------
# Customer-managed policy: billing full access
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "billing_full_access" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:*Billing",
      "aws-portal:*Usage",
      "aws-portal:*PaymentMethod",
      "budgets:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Full access to billing, usage, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

# -----------------------------------------------------------------------------
# Customer-managed policy: billing view access
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "billing_view_access" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "aws-portal:ViewPaymentMethods",
      "budgets:ViewBudget",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "View-only access to billing, usage, account, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

# -----------------------------------------------------------------------------
# Roles
# -----------------------------------------------------------------------------
resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.role_trust.json
}

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.role_trust.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# -----------------------------------------------------------------------------
# Assume-role policies for groups
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role${aws_iam_role.billing_full_access.path}${aws_iam_role.billing_full_access.name}",
    ]
  }
}

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  path        = "/"
  description = "Allows members of the billing-full-access group to assume the billing-full-access role"
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role${aws_iam_role.billing_view_access.path}${aws_iam_role.billing_view_access.name}",
    ]
  }
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  path        = "/"
  description = "Allows members of the billing-view-access group to assume the billing-view-access role"
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

# -----------------------------------------------------------------------------
# Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_full_access" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_view_access" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

# -----------------------------------------------------------------------------
# Optional group memberships (empty by default)
# -----------------------------------------------------------------------------
variable "billing_full_access_group_users" {
  description = "List of IAM user names to add to the billing-full-access group"
  type        = list(string)
  default     = []
}

variable "billing_view_access_group_users" {
  description = "List of IAM user names to add to the billing-view-access group"
  type        = list(string)
  default     = []
}

resource "aws_iam_user_group_membership" "billing_full_access" {
  for_each = toset(var.billing_full_access_group_users)
  user     = each.value
  groups   = [aws_iam_group.billing_full_access.name]
}

resource "aws_iam_user_group_membership" "billing_view_access" {
  for_each = toset(var.billing_view_access_group_users)
  user     = each.value
  groups   = [aws_iam_group.billing_view_access.name]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access role"
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access role"
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access group"
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access group"
  value       = aws_iam_group.billing_view_access.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Helper lookups: current partition, region, and account
data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  base_name = "cognito"
  pet_name  = random_pet.suffix.id
  name      = "${local.base_name}-${local.pet_name}"
  pool_name = replace(local.name, "-", "_")
}

resource "random_pet" "suffix" {
  length = 2
}

resource "random_string" "external_id" {
  length  = 16
  upper   = true
  lower   = false
  special = false
}

# IAM role that Cognito can assume to send SMS via SNS
resource "aws_iam_role" "sms_role" {
  name = "${local.name}-sms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "sms_policy" {
  name = "${local.name}-sms-policy"
  role = aws_iam_role.sms_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:publish"
        Resource = "*"
      }
    ]
  })
}

# Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name = local.pool_name

  mfa_configuration = "OFF"

  auto_verified_attributes = ["email"]

  sms_authentication_message = "Your code is {####}"

  sms_configuration {
    external_id    = random_string.external_id.result
    sns_caller_arn = aws_iam_role.sms_role.arn
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = false

    string_attribute_constraints {
      min_length = 5
      max_length = 2048
    }
  }

  schema {
    name                = "phone_number"
    attribute_data_type = "String"
    required            = false
    mutable             = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "profile_user_id"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "profile_email"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "first_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "last_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "gender"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "age"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "persona"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }
}

# App client without a client secret
resource "aws_cognito_user_pool_client" "client" {
  name                                 = local.name
  user_pool_id                         = aws_cognito_user_pool.pool.id
  generate_secret                      = false
  explicit_auth_flows                  = ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  prevent_user_existence_errors        = "ENABLED"
  supported_identity_providers         = ["COGNITO"]
}

# Identity Pool
resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = local.name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }
}

# Authenticated (signed-in) users role
resource "aws_iam_role" "signed_users" {
  name = "${local.name}-signed-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

# Unauthenticated (anonymous) users role
resource "aws_iam_role" "anonymous_users" {
  name = "${local.name}-anonymous-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "signed_users_policy" {
  name = "${local.name}-signed-users-policy"
  role = aws_iam_role.signed_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:*",
          "cognito-sync:*"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "anonymous_users_policy" {
  name = "${local.name}-anonymous-users-policy"
  role = aws_iam_role.anonymous_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:*"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
        ]
      }
    ]
  })
}

resource "aws_cognito_identity_pool_roles_attachment" "roles" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    authenticated   = aws_iam_role.signed_users.arn
    unauthenticated = aws_iam_role.anonymous_users.arn
  }
}

output "user_pool_id" {
  value = aws_cognito_user_pool.pool.id
}

output "app_client_id" {
  value = aws_cognito_user_pool_client.client.id
}

output "identity_pool_id" {
  value = aws_cognito_identity_pool.identity_pool.id
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name_prefix = "${terraform.workspace}-batch"
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
}

# ---------------- Networking ----------------

resource "aws_vpc" "batch_vpc" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.batch_vpc.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-subnet"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.batch_vpc.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-subnet"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.batch_vpc.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_eip" "nat_eip" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.batch_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.batch_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# ---------------- Security ----------------

resource "aws_security_group" "batch_sg" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for AWS Batch compute environment"
  vpc_id      = aws_vpc.batch_vpc.id

  egress {
    description = "HTTPS to VPC CIDR only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.batch_vpc.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

# ---------------- KMS & S3 ----------------

resource "aws_kms_key" "results_key" {
  description             = "KMS key for benchmark batch results"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = "${local.name_prefix}-results-key"
  }
}

resource "aws_s3_bucket" "results" {
  bucket = "benchmark-batch-results-${local.account_id}"

  tags = {
    Name = "benchmark-batch-results-${local.account_id}"
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket                  = aws_s3_bucket.results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.results_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------- IAM ----------------

resource "aws_iam_role" "ecs_instance_role" {
  name = "${local.name_prefix}-ecs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance_managed" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "ecs_s3_policy"
  description = "S3 and KMS access for Batch ECS instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetObject"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.results.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.results_key.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_s3" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

resource "aws_iam_instance_profile" "ecs_instance_profile" {
  name = "${local.name_prefix}-ecs-profile"
  role = aws_iam_role.ecs_instance_role.name
}

resource "aws_iam_role" "batch_service_role" {
  name = "${local.name_prefix}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# ---------------- AWS Batch ----------------

data "aws_ssm_parameter" "ecs_optimized_ami" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2023/recommended"
}

resource "aws_batch_compute_environment" "compute_env" {
  compute_environment_name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT_ALLOCATION"
    instance_type       = ["optimal"]
    min_vcpus           = 0
    max_vcpus           = 4
    desired_vcpus       = 0
    security_group_ids  = [aws_security_group.batch_sg.id]
    subnets             = [aws_subnet.private.id]
    instance_role       = aws_iam_instance_profile.ecs_instance_profile.arn

    launch_template {
      launch_template_id = aws_launch_template.ecs_lt.id
      version            = "$Latest"
    }

    tags = {
      Name = local.name_prefix
    }
  }

  service_role_arn = aws_iam_role.batch_service_role.arn

  depends_on = [aws_iam_role_policy_attachment.batch_service]

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_launch_template" "ecs_lt" {
  name          = "${local.name_prefix}-lt"
  image_id      = jsondecode(data.aws_ssm_parameter.ecs_optimized_ami.insecure_value == "" ? data.aws_ssm_parameter.ecs_optimized_ami.value : data.aws_ssm_parameter.ecs_optimized_ami.value)["image_id"]

  tags = {
    Name = "${local.name_prefix}-lt"
  }
}

resource "aws_batch_job_queue" "job_queue" {
  name                 = "${terraform.workspace}-batch-queue"
  state                = "ENABLED"
  priority             = 1
  compute_environments = [aws_batch_compute_environment.compute_env.arn]

  tags = {
    Name = "${terraform.workspace}-batch-queue"
  }
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables (all have defaults so the configuration is deployable as-is)
# ------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region into which the infrastructure will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "max_compliance_retention_days" {
  description = "Maximum number of days an object may be placed in COMPLIANCE-mode object lock before the bucket policy denies the request."
  type        = number
  default     = 90
}

# ------------------------------------------------------------------------------
# Provider
# ------------------------------------------------------------------------------

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# The AWS-managed S3 KMS key (alias/aws/s3)
data "aws_kms_key" "s3" {
  key_id = "alias/aws/s3"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  # Latest allowed COMPLIANCE-mode retain-until date: now + 90 days.
  # 90 days * 24 hours = 2160 hours.
  max_compliance_retention_date = timeadd(timestamp(), "${var.max_compliance_retention_days * 24}h")
}

# ------------------------------------------------------------------------------
# S3 bucket: endpoint-backup-<account-id>
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  # Object lock disabled, per requirements.
  object_lock_enabled = false

  tags = {
    Name        = "endpoint-backup"
    Description = "Secure bucket for endpoint backups"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Transfer acceleration suspended
resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

# Default server-side encryption with S3-managed keys (AES256)
resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ------------------------------------------------------------------------------
# Bucket policy
#   1. Deny any request not made over TLS 1.2 or higher.
#   2. Deny uploads / retention changes that would place an object in
#      COMPLIANCE-mode lock for more than 90 days.
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "endpoint_backup_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceModeLockMoreThan90Days"
    effect = "Deny"
    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "DateGreaterThan"
      variable = "s3:object-lock-retain-until-date"
      values   = [local.max_compliance_retention_date]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.endpoint_backup,
  ]
}

# ------------------------------------------------------------------------------
# IAM user: endpoint-backup (no access keys are created)
# ------------------------------------------------------------------------------

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

# ------------------------------------------------------------------------------
# Customer-managed IAM policy: endpoint-backup-bucket-read-write-access
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "endpoint_backup_access" {
  statement {
    sid    = "BucketListReadVersion"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:PutBucketVersioning",
    ]
    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ObjectReadWriteDeleteVersionRetentionRestore"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObject",
      "s3:PutObjectRetention",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "KmsDecryptAndGenerateDataKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [data.aws_kms_key.s3.arn]
  }
}

resource "aws_iam_policy" "endpoint_backup_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "List, read, write, delete, version, retention and restore access to the endpoint-backup bucket, plus decrypt/data-key access on the AWS-managed S3 KMS key."
  policy      = data.aws_iam_policy_document.endpoint_backup_access.json
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_access.arn
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "bucket_name" {
  description = "Name of the endpoint backup S3 bucket."
  value       = aws_s3_bucket.endpoint_backup.id
}

output "bucket_arn" {
  description = "ARN of the endpoint backup S3 bucket."
  value       = aws_s3_bucket.endpoint_backup.arn
}

output "iam_user_name" {
  description = "Name of the endpoint backup IAM user."
  value       = aws_iam_user.endpoint_backup.name
}

output "iam_policy_arn" {
  description = "ARN of the endpoint-backup-bucket-read-write-access policy."
  value       = aws_iam_policy.endpoint_backup_access.arn
}

terraform {
