  value = aws_cognito_user_pool.shared_services.id
}

output "hosted_ui_domain" {
  value = aws_cognito_user_pool_domain.hosted_ui.domain
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_name" {
  type    = string
  default = "terraform"
}

variable "environment" {
  type    = string
  default = "testing"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "azs" {
  type    = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnets" {
  type    = list(string)
  default = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnets" {
  type    = list(string)
  default = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "enable_dns_hostnames" {
  type    = bool
  default = false
}

variable "enable_ipv6" {
  type    = bool
  default = false
}

variable "enable_transit_gateway_attachment" {
  type    = bool
  default = false
}

variable "transit_gateway_id" {
  type    = string
  default = ""
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = {
    Name        = "vpc-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name        = "igw-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnets)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = var.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "public-${var.azs[count.index]}-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
    Tier        = "public"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = var.azs[count.index]

  tags = {
    Name        = "private-${var.azs[count.index]}-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
    Tier        = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name        = "rt-public-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name        = "eip-nat-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "nat-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name        = "rt-private-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this.id
}

resource "aws_route" "private_tgw" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  transit_gateway_id     = var.transit_gateway_id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.this.id
  subnet_ids         = aws_subnet.private[*].id

  tags = {
    Name        = "tgw-attach-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

resource "aws_db_subnet_group" "this" {
  name        = "db-subnet-${var.app_name}-${var.environment}"
  description = "DB subnet group for ${var.app_name}-${var.environment}"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name        = "db-subnet-${var.app_name}-${var.environment}"
    app         = var.app_name
    environment = var.environment
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "vpc_cidr" {
  value = aws_vpc.this.cidr_block
}

output "default_security_group_id" {
  value = aws_vpc.this.default_security_group_id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  value = aws_nat_gateway.this.id
}

output "nat_eip" {
  value = aws_eip.nat.public_ip
}

output "db_subnet_group_name" {
  value = aws_db_subnet_group.this.name
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "repositories" {
  description = "List of CodeCommit repository names for the GitOps bridge"
  type        = list(string)
  default     = ["gitops-apps", "gitops-platform", "gitops-addons"]
}

variable "iam_user_name" {
  description = "IAM user name for the GitOps bridge"
  type        = string
  default     = "gitops-bridge-gitops"
}

variable "ssh_directory" {
  description = "Local SSH directory where the private key and config are written"
  type        = string
  default     = "~/.ssh"
}

# Three CodeCommit repositories
resource "aws_codecommit_repository" "gitops" {
  count         = length(var.repositories)
  repository_name = var.repositories[count.index]
  description     = "GitOps bridge repository: ${var.repositories[count.index]}"
}

# TLS key pair (4096-bit RSA)
resource "tls_private_key" "gitops_ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# Random five-character suffix for the secret name
resource "random_string" "suffix" {
  length  = 5
  special = false
  upper   = false
}

# IAM user
resource "aws_iam_user" "gitops" {
  name = var.iam_user_name
}

# Upload SSH public key to IAM
resource "aws_iam_ssh_public_key" "gitops" {
  user_name       = aws_iam_user.gitops.name
  encoding        = "SSH"
  public_key      = tls_private_key.gitops_ssh.public_key_openssh
}

# Customer-managed policy granting pull/push to only the three repos
resource "aws_iam_policy" "gitops" {
  name        = var.iam_user_name
  description = "Git pull and push access to GitOps bridge CodeCommit repositories"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitGitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GitPush"
        ]
        Resource = [
          for repo in aws_codecommit_repository.gitops : repo.arn
        ]
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "gitops" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.gitops.arn
}

# Store private key in Secrets Manager
resource "aws_secretsmanager_secret" "gitops_key" {
  name        = "codecommit-key-${random_string.suffix.result}"
  description = "SSH private key for IAM user ${var.iam_user_name} to access CodeCommit"
}

resource "aws_secretsmanager_secret_version" "gitops_key" {
  secret_id     = aws_secretsmanager_secret.gitops_key.id
  secret_string = tls_private_key.gitops_ssh.private_key_pem
}

# Write private key locally
resource "local_file" "private_key" {
  content         = tls_private_key.gitops_ssh.private_key_pem
  filename        = pathexpand("${var.ssh_directory}/gitops_ssh.pem")
  file_permission = "0600"
}

# SSH config entry for CodeCommit endpoints
resource "local_file" "ssh_config" {
  content = join("\n", [
    for repo in var.repositories : <<EOF
Host git-codecommit.*.amazonaws.com
  IdentityFile ${pathexpand("${var.ssh_directory}/gitops_ssh.pem")}
  IdentitiesOnly yes
EOF
  ])
  filename        = pathexpand("${var.ssh_directory}/config")
  file_permission = "0600"
}

output "repository_clone_urls_ssh" {
  description = "SSH clone URLs for the GitOps repositories"
  value       = [for repo in aws_codecommit_repository.gitops : repo.clone_url_ssh]
}

output "secret_name" {
  description = "Name of the Secrets Manager secret holding the private key"
  value       = aws_secretsmanager_secret.gitops_key.name
}

output "iam_user_name" {
  description = "IAM user with Git access"
  value       = aws_iam_user.gitops.name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "key_public_key" {
  description = "Public key material for the benchmark SSH key pair"
  type        = string
  default     = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQDExampleReplaceMe user@example"
}

variable "extra_ebs_volumes" {
  description = "Optional extra EBS volumes to attach"
  type = map(object({
    size = number
    type = string
  }))
  default = {}
}

variable "extra_network_interfaces" {
  description = "Optional additional ENIs (each gets an Elastic IP)"
  type = map(object({
    subnet_id              = optional(string)
    private_ip             = optional(string)
    source_dest_check      = optional(bool, true)
    secondary_private_ips  = optional(list(string), [])
  }))
  default = {}
}

module "benchmark_instance" {
  source = "./modules/ec2-instance"

  name                = "benchmark-instance"
  instance_type       = "t2.micro"
  key_name            = "benchmark-d8bc612be4e0-key"
  key_public_key      = var.key_public_key

  create_network      = true
  vpc_cidr            = "10.70.0.0/16"
  subnet_cidr         = "10.70.0.0/24"
  subnet_az           = null

  root_volume_size    = 10
  root_volume_type    = "gp2"
  root_volume_encrypted = true

  detailed_monitoring = true
  associate_public_ip = true
  imdsv2_required     = true

  extra_ebs_volumes       = var.extra_ebs_volumes
  extra_network_interfaces = var.extra_network_interfaces
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "source1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "eu-central-1"
}

data "aws_caller_identity" "current" {
  provider = aws.source1
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  source1_names = ["log1a.veerum", "log1b.veerum"]
  source2_names = ["log2a.veerum", "log2b.veerum"]

  source1_full = [for n in local.source1_names : "${n}-${local.account_id}"]
  source2_full = [for n in local.source2_names : "${n}-${local.account_id}"]

  replica1_full = concat(
    [for n in local.source1_full : "${n}-replica1"],
    [for n in local.source2_full : "${n}-replica1"]
  )
  replica2_full = concat(
    [for n in local.source1_full : "${n}-replica2"],
    [for n in local.source2_full : "${n}-replica2"]
  )
}

# ---------------- KMS keys ----------------

resource "aws_kms_key" "source1" {
  provider                = aws.source1
  description             = "KMS key for source buckets in us-east-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "source1" {
  provider      = aws.source1
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "KMS key for source buckets in us-west-2"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "KMS key for replica buckets in eu-west-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "KMS key for replica buckets in eu-central-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# ---------------- Source buckets (us-east-1) ----------------

resource "aws_s3_bucket" "source1" {
  provider = aws.source1
  count    = length(local.source1_full)
  bucket   = local.source1_full[count.index]

  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket_versioning" "source1" {
  provider = aws.source1
  count    = length(aws_s3_bucket.source1)
  bucket   = aws_s3_bucket.source1[count.index].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  provider                  = aws.source1
  count                     = length(aws_s3_bucket.source1)
  bucket                    = aws_s3_bucket.source1[count.index].id
  block_public_acls         = true
  block_public_policy       = true
  ignore_public_acls        = true
  restrict_public_buckets   = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  provider = aws.source1
  count    = length(aws_s3_bucket.source1)
  bucket   = aws_s3_bucket.source1[count.index].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

# ---------------- Source buckets (us-west-2) ----------------

resource "aws_s3_bucket" "source2" {
