# ---------------- Replica buckets (eu-central-1) ----------------

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  count    = length(local.replica2_full)
  bucket   = local.replica2_full[count.index]

  tags = {
    Env = "dev"
