# ---------------- IAM role for replication ----------------

data "aws_iam_policy_document" "replication_assume" {
  provider = aws.source1
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringLike"
      variable = "aws:PrincipalArn"
      values = concat(
        [for b in aws_s3_bucket.source1 : b.arn],
        [for b in aws_s3_bucket.source2 : b.arn]
      )
    }
  }
}

resource "aws_iam_role" "replication" {
  provider           = aws.source1
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume.json
}

data "aws_iam_policy_document" "replication_policy" {
  provider = aws.source1

  statement {
    sid    = "ReadSource"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = concat(
      [for b in aws_s3_bucket.source1 : b.arn],
      [for b in aws_s3_bucket.source2 : b.arn]
    )
  }

  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold"
    ]
    resources = concat(
      [for b in aws_s3_bucket.source1 : "${b.arn}/*"],
      [for b in aws_s3_bucket.source2 : "${b.arn}/*"]
    )
  }

  statement {
    sid    = "ReplicateToDestinations"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner"
    ]
    resources = concat(
      [for b in aws_s3_bucket.replica1 : "${b.arn}/*"],
      [for b in aws_s3_bucket.replica2 : "${b.arn}/*"]
    )
  }

  statement {
    sid       = "DecryptSource"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.source1.arn, aws_kms_key.source2.arn]
  }

  statement {
    sid       = "EncryptReplica"
    effect    = "Allow"
    actions   = ["kms:Encrypt"]
    resources = [aws_kms_key.replica1.arn, aws_kms_key.replica2.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  provider = aws.source1
  name     = "s3-cross-region-replication-policy"
  role     = aws_iam_role.replication.id
  policy   = data.aws_iam_policy_document.replication_policy.json
}

# ---------------- Replication configurations ----------------

resource "aws_s3_bucket_replication_configuration" "source1" {
  provider = aws.source1
  count    = length(aws_s3_bucket.source1)
  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2
  ]

  bucket = aws_s3_bucket.source1[count.index].id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-replica1"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica1[count.index].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  rule {
    id     = "replicate-to-replica2"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica2[count.index].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "source2" {
  provider = aws.source2
  count    = length(aws_s3_bucket.source2)
  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2
  ]

  bucket = aws_s3_bucket.source2[count.index].id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-replica1"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica1[length(local.source1_full) + count.index].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  rule {
    id     = "replicate-to-replica2"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica2[length(local.source1_full) + count.index].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy GuardDuty resources"
  type        = string
  default     = "us-east-1"
}

variable "repository_url" {
  description = "Repository URL used for tagging the detector"
  type        = string
  default     = "https://github.com/example/terraform-guardduty-module"
}

variable "enable_findings_filter" {
  description = "Whether to create a GuardDuty findings filter"
  type        = bool
  default     = false
}

variable "findings_filter_name" {
  description = "Name of the optional findings filter"
  type        = string
  default     = "example-filter"
}

variable "findings_filter_criteria" {
  description = "Criteria for the optional findings filter"
  type        = map(list(string))
  default = {
    severity = ["HIGH"]
  }
}

variable "findings_filter_action" {
  description = "Action for the optional findings filter (ARCHIVE or NOOP)"
  type        = string
  default     = "NOOP"
}

variable "enable_trusted_ip_set" {
  description = "Whether to create a trusted IP set"
  type        = bool
  default     = false
}

variable "trusted_ip_set_name" {
  description = "Name of the optional trusted IP set"
  type        = string
  default     = "trusted-ips"
}

variable "trusted_ip_set_locations" {
  description = "IP locations for the optional trusted IP set"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "enable_threat_intel_set" {
  description = "Whether to create a threat intelligence set"
  type        = bool
  default     = false
}

variable "threat_intel_set_name" {
  description = "Name of the optional threat intelligence set"
  type        = string
  default     = "threat-intel"
}

variable "threat_intel_set_locations" {
  description = "Object locations (S3 URLs) for the optional threat intelligence set"
  type        = list(string)
  default     = ["https://s3.amazonaws.com/example-bucket/threatlist.txt"]
}

variable "enable_s3_malware_protection_plan" {
  description = "Whether to create an S3 malware protection plan"
  type        = bool
  default     = false
}

variable "s3_malware_protection_bucket_arn" {
  description = "S3 bucket ARN for the optional malware protection plan"
  type        = string
  default     = "arn:aws:s3:::example-bucket"
}

variable "enable_findings_export" {
  description = "Whether to create the findings export bucket and publishing destination"
  type        = bool
  default     = false
}

variable "findings_export_bucket_name" {
  description = "Name of the optional findings export bucket"
  type        = string
  default     = "guardduty-findings-export-example"
}

variable "findings_export_replication_region" {
  description = "Destination region for cross-region replication of the findings export bucket"
  type        = string
  default     = "us-west-2"
}

# GuardDuty detector
resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  datasources {
    s3_logs {
      enable = true
    }
    malware_protection {
      scan_ec2_instance_with_findings {
        ebs_volumes {
          enable = true
        }
      }
    }
  }

  features {
    name = "RDS_LOGIN_EVENTS"
    status = "ENABLED"
  }

  features {
    name = "LAMBDA_NETWORK_LOGS"
    status = "ENABLED"
  }

  features {
    name = "EKS_AUDIT_LOGS"
    status = "ENABLED"
  }

  features {
    name = "EBS_MALWARE_PROTECTION"
    status = "ENABLED"
  }

  features {
    name = "EKS_RUNTIME_MONITORING"
    status = "ENABLED"

    additional_configuration {
      name   = "EKS_ADDON_MANAGEMENT"
      status = "DISABLED"
    }
  }

  features {
    name = "ECS_FARGATE_RUNTIME_MONITORING"
    status = "ENABLED"

    additional_configuration {
      name   = "ECS_AGENT_MANAGEMENT"
      status = "DISABLED"
    }
  }

  features {
    name = "RUNTIME_MONITORING"
    status = "ENABLED"

    additional_configuration {
      name   = "EC2_AGENT_MANAGEMENT"
      status = "DISABLED"
    }
  }

  tags = {
    RepositoryURL = var.repository_url
  }
}

# Post-deployment AWS CLI command to configure malware scan settings (no snapshot retention)
resource "null_resource" "malware_scan_settings" {
  depends_on = [aws_guardduty_detector.main]

  provisioner "local-exec" {
    command = "aws guardduty update-malware-protection-settings --detector-id ${aws_guardduty_detector.main.id} --scan-resource-metadata 'EbsVolume={SnapshotRetention=DISABLED}' --region ${var.aws_region}"
  }

  triggers = {
    detector_id = aws_guardduty_detector.main.id
  }
}

# Optional: findings filter
resource "aws_guardduty_filter" "optional" {
  count       = var.enable_findings_filter ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.findings_filter_name
  action      = var.findings_filter_action
  description = "Optional findings filter"

  criterion {
    field  = "severity"
    equals = var.findings_filter_criteria["severity"]
  }
}

# Optional: trusted IP set
resource "aws_guardduty_ipset" "trusted" {
  count       = var.enable_trusted_ip_set ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.trusted_ip_set_name
  format      = "TXT"
  location    = var.trusted_ip_set_locations[0]
  activate    = true
}

# Optional: threat intelligence set
resource "aws_guardduty_threatintelset" "optional" {
  count       = var.enable_threat_intel_set ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.threat_intel_set_name
  format      = "TXT"
  location    = var.threat_intel_set_locations[0]
  activate    = true
}

# Optional: S3 malware protection plan
resource "aws_guardduty_malware_protection_plan" "s3" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0
  role  = aws_iam_role.malware_protection_plan[0].arn

  protected_resource {
    s3_bucket {
      bucket_name = var.s3_malware_protection_bucket_arn
    }
  }

  actions {
    tagging {
      status = "ENABLED"
    }
  }
}

resource "aws_iam_role" "malware_protection_plan" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0
  name  = "guardduty-malware-protection-plan-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "malware-protection-plan.guardduty.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "malware_protection_plan" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0
  name  = "guardduty-malware-protection-plan-policy"
  role  = aws_iam_role.malware_protection_plan[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObjectTagging",
          "s3:GetBucketLocation"
        ]
        Resource = [
          var.s3_malware_protection_bucket_arn,
          "${var.s3_malware_protection_bucket_arn}/*"
        ]
      }
    ]
  })
}

# Optional: findings export infrastructure
resource "aws_kms_key" "findings_export" {
  count                   = var.enable_findings_export ? 1 : 0
  description             = "KMS key for GuardDuty findings export bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "findings_export" {
  count         = var.enable_findings_export ? 1 : 0
  bucket        = var.findings_export_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.findings_export[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    id     = "abort-incomplete-multipart"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# Access logging bucket
resource "aws_s3_bucket" "findings_export_logs" {
  count         = var.enable_findings_export ? 1 : 0
  bucket        = "${var.findings_export_bucket_name}-access-logs"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "findings_export_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "findings_export_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.findings_export_logs[0].arn}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.findings_export[0].arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  target_bucket = aws_s3_bucket.findings_export_logs[0].id
  target_prefix = "access-logs/"
}

# Cross-region replication
resource "aws_s3_bucket" "findings_export_replica" {
  count         = var.enable_findings_export ? 1 : 0
  bucket        = "${var.findings_export_bucket_name}-replica"
  force_destroy = true

  provider = aws.replica
}

resource "aws_s3_bucket_versioning" "findings_export_replica" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export_replica" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-export-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-export-replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.findings_export[0].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.findings_export[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = ["${aws_s3_bucket.findings_export_replica[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.findings_export[0].arn]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id
  role   = aws_iam_role.replication[0].arn

  depends_on = [
    aws_s3_bucket_versioning.findings_export,
    aws_s3_bucket_versioning.findings_export_replica
  ]

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.findings_export_replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.findings_export[0].arn
      }
    }
  }
}

resource "aws_guardduty_publishing_destination" "findings_export" {
  count          = var.enable_findings_export ? 1 : 0
  detector_id    = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.findings_export[0].arn
  kms_key_arn    = aws_kms_key.findings_export[0].arn
}

# Provider for the replication destination region
provider "aws" {
  alias  = "replica"
  region = var.findings_export_replication_region
}

output "detector_id" {
  description = "ID of the GuardDuty detector"
  value       = aws_guardduty_detector.main.id
}

output "detector_arn" {
  description = "ARN of the GuardDuty detector"
  value       = aws_guardduty_detector.main.arn
}
